[32783] = { ["id"] = 32783, ["name"] = "Ga'nar's Vengeance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32783, 32791, 32792, 32794, 32795, 32796 }, ["series"] = { 32791, 32792, 32794, 32795, 32796, 33468, 33469, 33470, 33473, 33807 }, ["description"] = "My brother's head is as thick as his axe and he is as stubborn as a gronn. When Ga'nar left he took with him some of the finest warriors in the clan and headed north to the Daggermaw Ravine. If they are still out there, you must find them. Ga'nar will not listen to me. Help him see his vengeance through if you must but please bring him back to us.", ["objectivesText"] = "Find Ga'nar near Daggermaw Ravine.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 70909, ["x"] = 0.308, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.225333, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 20, ["name"] = "Ga'nar's Vengeance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[32791] = { ["id"] = 32791, ["name"] = "Let the Hunt Begin!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32783, 32791, 32792, 32794, 32795, 32796 }, ["series"] = { 32783, 32792, 32794, 32795, 32796, 33468, 33469, 33470, 33473, 33807 }, ["description"] = "I have no time for my brother's whimpering. We hunt for vengeance or death. The Thunderlord chieftain slew my father and left me for dead, so I shall take his three sons, the first of which is this runt in my hand. This filth has revealed the number and positions of the Thunderlords in the ravine beyond. Join us, if you dare, and you will witness how real warriors of the Frostwolf clan fight. Get in my way, and I will end you.", ["objectivesText"] = "Confront Grotan the Herald.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70909, ["x"] = 0.308, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74000, ["x"] = 0.36, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 20, ["name"] = "Ga'nar's Vengeance", ["orderIndex"] = 1, ["flags"] = 0 } } },
