[32794] = { ["id"] = 32794, ["name"] = "Wrath of Gronn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32783, 32791, 32792, 32794, 32795, 32796 }, ["series"] = { 32783, 32791, 32792, 32795, 32796, 33468, 33469, 33470, 33473, 33807 }, ["description"] = "The Thunderlord are capturing gronn for the Iron Horde. Show these fools why gronn are NOT pets. Follow us into Grulloc's Grotto and sunder the chains of the captive gronn . Let the beasts seek to gain their own vengeance against the Thunderlord. Meet us at Grulloc's Lair beneath the grotto when you are done.", ["objectivesText"] = "Release 3 Captive Gronn .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70910, ["x"] = 0.464, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 20, ["name"] = "Ga'nar's Vengeance", ["orderIndex"] = 3, ["flags"] = 0 } } },
