[32796] = { ["id"] = 32796, ["name"] = "To the Garrison", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32783, 32791, 32792, 32794, 32795, 32796 }, ["series"] = { 32783, 32791, 32792, 32794, 32795, 33468, 33469, 33470, 33473, 33807 }, ["description"] = "My father is avenged. The sons of the Iron Wolf are all slain. Go to the garrison your people are constructing in the south. There, herald my return to my laggard brother. The time has come for the \"chieftain\" to be reminded of what it means to be a Frostwolf.", ["objectivesText"] = "Meet with Durotan in front of your garrison in Frostfire Ridge .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 20, ["name"] = "Ga'nar's Vengeance", ["orderIndex"] = 5, ["flags"] = 0 } } },
[32804] = { ["id"] = 32804, ["name"] = "Articles of the Fallen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32804 }, ["series"] = { 32929 }, ["description"] = "Even when on a mission of vengeance we must remember to uphold the honor that is required of a member of the Frostwolves. In the grotto below are the fallen corpses of many good Frostwolf orcs. They must be remembered. While you carry out Ga'nar's task, look for articles of our fallen brethren. Bring these articles to me so that I might pass them to a shaman for final burial as is our tradition.", ["objectivesText"] = "Recover 10 Fallen Frostwolf Artifacts . Progress: Have you found the articles?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 100899 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74223, ["x"] = 0.464, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74223, ["x"] = 0.464, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[32929] = { ["id"] = 32929, ["name"] = "They Rely on Numbers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32929 }, ["series"] = { 32804 }, ["description"] = "Thunderlord spend their days training to hunt as a team, but as individuals they are weak. Their only strength is in numbers. So... to win, we must cull their numbers. As we move up through the Daggermaw Ravine, slay any Thunderlord who stand in your way, and their clan will be made the weaker for it.", ["objectivesText"] = "Slay 15 Thunderlord at Daggermaw Ravine in Frostfire Ridge . Progress: My axe bears the blood of a dozen Thunderlord. How many have you slain this day?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74222, ["x"] = 0.435333, ["y"] = 0.304667 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74223, ["x"] = 0.464, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.304667 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[32989] = { ["id"] = 32989, ["name"] = "Securing the South", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32989, 32990, 32991, 32992, 32993, 32994, 33493, 33785, 33826, 33828 }, ["series"] = { 32990, 32991, 32992, 32993, 33014, 33512, 33938 }, ["description"] = "We have an outpost to the southeast that was boxed in by Thunderlord forces as they marched through the canyons to Wor'gol. I have sent reinforcements to secure the outpost and press east to Grom'gar. We will push the Thunderlords out of our lands completely, and pursue them all the way back to that reeking corpse they call home. Draka's sister, Lokra , was among the orcs who volunteered to clean up Stonefang Outpost.", ["objectivesText"] = "Speak with Lokra at Stonefang Outpost.", ["rewardXP"] = 175, ["rewardItems"] = { 110560 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72274, ["x"] = 0.47225, ["y"] = 0.49975 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.225333, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 21, ["name"] = "Thunder's Fall", ["orderIndex"] = 0, ["flags"] = 0 } } },
[32990] = { ["id"] = 32990, ["name"] = "They Who Held Fast", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32989, 32990, 32991, 32992, 32993, 32994, 33493, 33785, 33826, 33828 }, ["series"] = { 32989, 32991, 32992, 32993, 33014, 33512, 33938 }, ["description"] = "The siege has been broken - they underestimated the resilience of Stonefang, and our reinforcement wave from Bladespire caught them completely off-guard. Once we finish cleaning up here, we rally anyone who can still fight and prepare to march for Grom'gar. The outpost captain, Karg Bloodfury, should have come out to meet us by now. Can you get him out here? Tell him Lokra is waiting. He knows how much I hate to be kept waiting.", ["objectivesText"] = "Speak with Karg Bloodfury in Stonefang Outpost. Progress: You go ahead - Asha and I will hold here for now.", ["rewardXP"] = 1415, ["rewardItems"] = { 110560 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72274, ["x"] = 0.47225, ["y"] = 0.49975 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72274, ["x"] = 0.47225, ["y"] = 0.49975 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.47225, ["y"] = 0.49975 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 21, ["name"] = "Thunder's Fall", ["orderIndex"] = 1, ["flags"] = 0 } } },
[32991] = { ["id"] = 32991, ["name"] = "Into the Boneslag", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32989, 32990, 32991, 32992, 32993, 32994, 33493, 33785, 33826, 33828 }, ["series"] = { 32989, 32990, 32992, 32993, 33014, 33512, 33938 }, ["description"] = "The Thunderlords took prisoners into the Boneslag? Well what are we waiting for?! We have to go after them! You look for the missing villagers - Asha and I will track Karg.", ["objectivesText"] = "Search the Boneslag for the missing Frostwolf orcs.", ["rewardXP"] = 1415, ["rewardItems"] = { 110560 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72274, ["x"] = 0.47225, ["y"] = 0.49975 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72274, ["x"] = 0.47225, ["y"] = 0.49975 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.47225, ["y"] = 0.49975 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 21, ["name"] = "Thunder's Fall", ["orderIndex"] = 2, ["flags"] = 0 } } },
[32992] = { ["id"] = 32992, ["name"] = "Moving Target", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32989, 32990, 32991, 32992, 32993, 32994, 33493, 33785, 33826, 33828 }, ["series"] = { 32989, 32990, 32991, 32993, 33014, 33512, 33938 }, ["description"] = "Karg's captors are moving east - probably retreating to Grom'gar with their tails between their legs! They think they outrun me, but Asha here is the fastest thing on four legs. We'll run them down in the Icewind Drifts.", ["objectivesText"] = "Catch up with Lokra in the Icewind Drifts.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 110560 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72274, ["x"] = 0.47225, ["y"] = 0.49975 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72274, ["x"] = 0.47225, ["y"] = 0.49975 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.47225, ["y"] = 0.49975 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 21, ["name"] = "Thunder's Fall", ["orderIndex"] = 3, ["flags"] = 0 } } },
[32993] = { ["id"] = 32993, ["name"] = "The Strength of Our Bonds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32989, 32990, 32991, 32992, 32993, 32994, 33493, 33785, 33826, 33828 }, ["series"] = { 32989, 32990, 32991, 32992, 33014, 33512, 33938 }, ["description"] = "Asha has passed, but we share a bond that cannot be severed by death. Even now, her spirit urges me onward to Grom'gar. The Iron Wolf claims our attachments make us weak... that love makes us vulnerable. He is wrong. Karg is my strength, and I his. I will free him from his chains, and together we will show the Thunderlord clan the strength of our bonds.", ["objectivesText"] = "Find Karg Bloodfury in Grom'gar.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 113253, 113254, 113255 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72274, ["x"] = 0.47225, ["y"] = 0.49975 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72373, ["x"] = 0.632, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.47225, ["y"] = 0.49975 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 21, ["name"] = "Thunder's Fall", ["orderIndex"] = 4, ["flags"] = 0 } } },
[32994] = { ["id"] = 32994, ["name"] = "Enfilade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32989, 32990, 32991, 32992, 32993, 32994, 33493, 33785, 33826, 33828 }, ["series"] = { 33826 }, ["description"] = "If we leave now, my clan's final assault on Grom'gar will be a disaster. Though our warriors are unmatched in melee, the Thunderlords have new ranged weapons - our forces would be decimated as they cross the Icewind Drifts. But WE are already here. We can overtake those weapons before they ever fire. Blackrock orcs help our enemies forge these \"cannons\" in the workshops on the south side. If we use their own tools to sabotage the weapons, we leave Grom'gar wide open to a Frostwolf raid.", ["objectivesText"] = "Use Blackrock Blasting Powder to destroy 5 Iron Horde Cannons in Grom'gar. Progress: If we leave those cannons intact, my brothers and sisters will die. What more is there to say?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 104039, 110560 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 21, ["name"] = "Thunder's Fall", ["orderIndex"] = 7, ["flags"] = 0 } } },
[33010] = { ["id"] = 33010, ["name"] = "The Iron Wolf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33010, 34123, 34124, 37291 }, ["series"] = { 33543, 33544, 34123, 34124, 34867, 35557, 49546 }, ["description"] = "My brother Ga'nar stands beside me. Wor'gol, Stonefang, and your garrison hold strong. Our clan is united, and the Thunderlord are already on the run. We are ready. The time has come to face this \"Iron Wolf.\"", ["objectivesText"] = "Enter the Hunter's Hall in Grom'gar and defeat the Iron Wolf .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 111909, 111911, 111912, 111913, 111914, 111915, 111916 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 22, ["name"] = "The Battle of Thunder Pass", ["orderIndex"] = 1, ["flags"] = 0 } } },
[33013] = { ["id"] = 33013, ["name"] = "Of Fire and Thunder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33013 }, ["description"] = "The Iron Wolf... brought weapons... <cough> ...weapons of fire and thunder. Our warriors have never seen such weapons. We were not ready. <wheeze> We must learn... to overcome...", ["objectivesText"] = "Examine the Siege Munitions and Heavy Plating in The Boneslag.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74358, ["x"] = 0.415, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[33059] = { ["id"] = 33059, ["name"] = "The Fate of Karabor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33059, 33072, 33076, 33080, 33081, 33082, 33586 }, ["series"] = { 33070, 33072, 33075, 33076, 33080, 33081, 33765, 33814, 33905, 34019, 36592 }, ["description"] = "Threads of the future weave together, winding and unwinding, creating tapestries that change in form and color from one moment to the next. I must have clarity. I must focus on the ONE strand that will become reality. When you are ready to share in my vision, drink the elixir. When the vision begins, be on your guard. The events of the vision are as deadly as anything we experience in this reality.", ["objectivesText"] = "Drink the Clarity Elixir and witness the fate of Karabor. Progress: <The Prophet is deep in thought. He looks troubled.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 111591 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 79043, ["x"] = 0.387333, ["y"] = 0.530667 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 79043, ["x"] = 0.387333, ["y"] = 0.530667 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.387333, ["y"] = 0.530667 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 43, ["name"] = "The Dark Side of the Moon", ["orderIndex"] = 4, ["flags"] = 0 } } },
[33070] = { ["id"] = 33070, ["name"] = "Think of the Children!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33070, 33075, 33765, 33813, 33905, 34019 }, ["series"] = { 33059, 33072, 33075, 33076, 33080, 33081, 33765, 33814, 33905, 34019, 36592 }, ["description"] = "When the Shadowmoon attacked Arbor Glen, everything was thrown into chaos. Many of us escaped, but there are still three children missing. I believe they are still back in the village. Please save them!", ["objectivesText"] = "Save Rastaak , Ariaana , and Hakaam .", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80196, ["x"] = 0.466, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 74043, ["x"] = 0.490667, ["y"] = 0.381333 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 40, ["name"] = "Shadows Awaken", ["orderIndex"] = 0, ["flags"] = 0 } } },
[33072] = { ["id"] = 33072, ["name"] = "Into Twilight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33059, 33072, 33076, 33080, 33081, 33082, 33586 }, ["series"] = { 33059, 33070, 33075, 33076, 33080, 33081, 33765, 33814, 33905, 34019, 36592 }, ["description"] = "The safety of my people is of the utmost priority. It is likely that Ner'zhul has taken the prisoners to Shaz'gul, his stronghold to the southwest. I do not wish to use aggression against him, but he may force my hand. Meet me at Twilight Glade, <name>. Then, we shall try our best to recover the prisoners.", ["objectivesText"] = "Speak to Prophet Velen at Twilight Glade.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 74043, ["x"] = 0.490667, ["y"] = 0.381333 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 79043, ["x"] = 0.387333, ["y"] = 0.530667 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.490667, ["y"] = 0.381333 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 43, ["name"] = "The Dark Side of the Moon", ["orderIndex"] = 0, ["flags"] = 0 } } },
[33075] = { ["id"] = 33075, ["name"] = "A Hero's Welcome", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33070, 33075, 33765, 33813, 33905, 34019 }, ["series"] = { 33059, 33070, 33072, 33076, 33080, 33081, 33765, 33814, 33905, 34019, 36592 }, ["description"] = "Prophet Velen has asked me to show you around Shadowmoon Valley . We will go first to Embaari Village, where my sister Samaara is waiting for us. I have not seen her since the Iron Horde took me to Tanaan. The village is just one of many trading villages between the Temple of Karabor and Shattrath. Follow the road east and make your way to Embaari Village. I will accompany you, my friend.", ["objectivesText"] = "Speak to Samaara at Embaari Village.", ["rewardGold"] = 208560, ["rewardXP"] = 1415, ["rewardItems"] = { 104350, 105716, 108481, 110560, 110723, 111024, 111591, 111908 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 73395, ["x"] = 0.584, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 75005, ["x"] = 0.422, ["y"] = 0.397333 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 40, ["name"] = "Shadows Awaken", ["orderIndex"] = 1, ["flags"] = 0 } } },
[33076] = { ["id"] = 33076, ["name"] = "The Clarity Elixir", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33059, 33072, 33076, 33080, 33081, 33082, 33586 }, ["series"] = { 33059, 33070, 33072, 33075, 33080, 33081, 33765, 33814, 33905, 34019, 36592 }, ["description"] = "I see a thousand glimpses of the future, swimming in a chaotic blur. It is possible to focus my energies to see the true eventuality - the future most likely to come to pass. I will need an oracle stone to focus my power, and a special elixir to still my mind. To make the elixir, I will need the following ingredients: wing dust from Swamplighters along the river, fresh hearts from a monstrously-sized hydra, and a rare star lily. Meet me at Moonwillow Peak when this task is done.", ["objectivesText"] = "Collect 6 Swamplighter Dust , 3 Engorged Hearts , and 1 Starflower. Progress: Yes?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 104350, 105716, 111024 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 79043, ["x"] = 0.387333, ["y"] = 0.530667 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 79043, ["x"] = 0.387333, ["y"] = 0.530667 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.387333, ["y"] = 0.530667 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 43, ["name"] = "The Dark Side of the Moon", ["orderIndex"] = 3, ["flags"] = 0 } } },
[33077] = { ["id"] = 33077, ["name"] = "A Grandmother's Remedy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33077 }, ["description"] = "Oh my, such a vigorous young <lad/lass>! Such a spring in your step, and such a sparkle in your eye! When you get to my age, it's all aches and pains. Luckily, I have a recipe for an unguent that would soothe my joints. I just need the ooze from the skin of belly toads in the swamp. Would you be a dear and help an old woman out?", ["objectivesText"] = "Collect 6 Vials of Toad Juice . Progress: It's all downhill from here, dearie.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 110723 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 71641, ["x"] = 0.412, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 71641, ["x"] = 0.412, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[33080] = { ["id"] = 33080, ["name"] = "Going Undercover", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33059, 33072, 33076, 33080, 33081, 33082, 33586 }, ["series"] = { 33059, 33070, 33072, 33075, 33076, 33081, 33765, 33814, 33905, 34019, 36592 }, ["description"] = "Yrel leads my rangers on a search for the prisoners at the Shadowmoon village. Their work is extremely dangerous, so I need you to carry out a contingency mission. Sylene has mastered an illusion spell which will allow you to infiltrate Shaz'gul safely. Speak to her to disguise yourself. Then, plant explosives at the quartermaster's depot, the main lodge, and the ritual altar. In case anything goes wrong, set them off to create a distraction.", ["objectivesText"] = "Speak to Sylene at Twilight Glade to gain an orc illusion, then plant explosives at key locations in Shaz'gul. If you lose your disguise, use Sylene's Amulet of Illusion to regain an orc appearance.", ["rewardGold"] = 442560, ["rewardXP"] = 1770, ["rewardItems"] = { 107076 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 73425, ["x"] = 0.405, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 74877, ["x"] = 0.342, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 43, ["name"] = "The Dark Side of the Moon", ["orderIndex"] = 1, ["flags"] = 0 } } },
[33081] = { ["id"] = 33081, ["name"] = "Escape From Shaz'gul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33059, 33072, 33076, 33080, 33081, 33082, 33586 }, ["series"] = { 33059, 33070, 33072, 33075, 33076, 33080, 33765, 33814, 33905, 34019, 36592 }, ["description"] = "I've failed, <name>... My squadron was caught by a wandering patrol. We fought fiercely, but the alarm had been raised. The rangari forced me into hiding before surrendering themselves to the enemy. They were under MY command, and they gave their lives... for what? I... I'm not sure what to do, <name>. We need to get out of here, but how?", ["objectivesText"] = "Help Yrel escape from Shaz'gul.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 106174, 107304, 107309, 107315 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 74877, ["x"] = 0.342, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 76067, ["x"] = 0.406, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 43, ["name"] = "The Dark Side of the Moon", ["orderIndex"] = 2, ["flags"] = 0 } } },
[33082] = { ["id"] = 33082, ["name"] = "Ancestor's Memory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33059, 33072, 33076, 33080, 33081, 33082, 33586 }, ["series"] = { 33586, 34043 }, ["description"] = "I believe that you should know the price of the lives you take. So before I will help you find Ner'zhul, you must understand why he joined the Iron Horde. In a cave beneath this village is an artifact that we call the Ancestral Totem. On it is carved the names of every Shadowmoon clan member since its founding. The opening of the cave lies directly south. I will meet you there.", ["objectivesText"] = "Find the Ancestor's Totem in the cave beneath Exile's Rise. Progress: You must understand a man's life before taking it.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 106151, 107301, 107306, 107316 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 75884, ["x"] = 0.457, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 75884, ["x"] = 0.457, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.457, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 43, ["name"] = "The Dark Side of the Moon", ["orderIndex"] = 6, ["flags"] = 0 } } },
[33083] = { ["id"] = 33083, ["name"] = "On the Offensive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["description"] = "We cannot enter these gates, but you can, <class>. Your mission is critical, and the Shadowmoon will kill you on sight. Do not hesitate to return the favor.", ["objectivesText"] = "Kill 15 Shadowmoon Darkcasters or Shadowmoon Voidclaws .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 31726, 31727, 59542, 59543, 59544, 94222, 131224, 155246, 155247, 155248, 155249, 155263, 155264, 155265, 155266, 193676, 193677, 193679, 193685, 193686, 193692, 193697, 197359, 197889, 197891, 197897, 197899, 200251, 211279, 212757, 223907, 237812 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 81176, ["x"] = 0.358, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 77282, ["x"] = 0.409, ["y"] = 0.377 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[33255] = { ["id"] = 33255, ["name"] = "The Righteous March", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["series"] = { 33256, 33533, 35033, 35050, 35065, 35556, 36632, 49564 }, ["description"] = "The Iron Horde have overtaken Karabor. If we don't act now, we will lose the city. Exarch Akama and the last of our forces are trapped within the city, but your garrison forces are still outside the temple, awaiting your orders. Come and fly with me. We will meet your forces on the field. With the naaru by our side, we will make one last charge to retake the city!", ["objectivesText"] = "Escort your garrison forces to the Temple of Karabor by slaying all the orcs in the Path of Light.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 75145, ["x"] = 0.482, ["y"] = 0.41 }, { ["mapID"] = 539, ["npcID"] = 77312, ["x"] = 0.522, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 72413, ["x"] = 0.751333, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[33256] = { ["id"] = 33256, ["name"] = "The Defense of Karabor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["series"] = { 33255, 33533, 35033, 35050, 35065, 35556, 36632, 49564 }, ["description"] = "Defend Karabor from the Iron Horde. At the end of the northern courtyard is Arnokk the Burner. He guards the entrance to the harbor behind Karabor, where the main Iron Horde army is waiting. Once we've taken care of him, we'll need to deal with the Iron Horde leader, Commander Vorka.", ["objectivesText"] = "Destroy the Iron Horde in Karabor.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 106139, 106150, 106156, 106160, 245425, 251330, 251477, 251548, 251549, 251640, 251653, 251654 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 72413, ["x"] = 0.751333, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 73395, ["x"] = 0.584, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.751333, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 2, ["flags"] = 0 } } },
