[33408] = { ["id"] = 33408, ["name"] = "Great Balls of Fire!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 34379, 34380 }, ["series"] = { 33344, 33410, 33526, 33527, 33546, 33622, 33657, 33784, 33816, 34379, 34380 }, ["description"] = "Ga'nar led Ligra and the others to the second level of the fortress. Your friend, Thrall , also went to lend his skills. Follow the ramp on the south end of the ramparts outside to join them. Help them bring victory to the Frostwolf Clan!", ["objectivesText"] = "Speak to Thrall in Bladespire Citadel. Progress: Yes, traveler?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 107279, 107361 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 75177, ["x"] = 0.27, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 527, ["questLines"] = { { ["id"] = 18, ["name"] = "Siege of Bladespire Citadel", ["orderIndex"] = 5, ["flags"] = 0 } } },
[33410] = { ["id"] = 33410, ["name"] = "The Butcher of Bladespire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 527, ["storyline"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 34379, 34380 }, ["series"] = { 33344, 33408, 33526, 33527, 33546, 33622, 33657, 33784, 33816, 34379, 34380 }, ["description"] = "After Ga'nar advanced into the fortress, the Bladespire unleashed a giant creature on our forces. I am still weak after using my magic, but at least I can help this orc in her recovery. Help take Dorogg down, <name>.", ["objectivesText"] = "Slay Dorogg the Ruthless . Progress: Have Dorogg fallen?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 106138, 106148, 106159, 106170, 107279, 107361, 112566, 114973, 115008, 116438 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 527, ["questLines"] = { { ["id"] = 18, ["name"] = "Siege of Bladespire Citadel", ["orderIndex"] = 6, ["flags"] = 0 } } },
