[33468] = { ["id"] = 33468, ["name"] = "Save Wolf Home", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33468, 33469, 33470, 33807 }, ["series"] = { 32783, 32791, 32792, 32794, 32795, 32796, 33469, 33470, 33473, 33807 }, ["description"] = "Cowardly Thunderlords... During the battle for the citadel, runners informed me that the Iron Wolf is striking at our home. He'll find no easy footing there, Draka will make them pay tenfold for any of ours that they slay, but we must return quickly and chase the mongrels off. You and your forces have proven valuable allies of the Frostwolves. We'd welcome your aid in securing our Wor'gol. I'll see you on the battlefield if you choose to come.", ["objectivesText"] = "Save Wor'gol from the Thunderlord clan. Progress: There are more Thunderlord to be killed.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74651, ["x"] = 0.208, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.225333, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 19, ["name"] = "Defense of Wor'gol", ["orderIndex"] = 0, ["flags"] = 0 } } },
[33469] = { ["id"] = 33469, ["name"] = "The Farseer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33468, 33469, 33470, 33807 }, ["series"] = { 32783, 32791, 32792, 32794, 32795, 32796, 33468, 33470, 33473, 33807 }, ["description"] = "The Thunderlord warleader... <name>, you have to stop him. He went to attack Drek'Thar at the Pool of Visions to the northwest!", ["objectivesText"] = "Get to the Pool of Visions and kill Warleader Gargrak . Progress: Wolf Home will not be safe until this coward is dead!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74651, ["x"] = 0.208, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74272, ["x"] = 0.168, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.208, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 19, ["name"] = "Defense of Wor'gol", ["orderIndex"] = 2, ["flags"] = 0 } } },
[33470] = { ["id"] = 33470, ["name"] = "Pool of Visions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33468, 33469, 33470, 33807 }, ["series"] = { 32783, 32791, 32792, 32794, 32795, 32796, 33468, 33469, 33473, 33807 }, ["description"] = "A terrible storm gathers on the horizon, <class>. I have prepared a ritual. You must consult the pool to see what destiny holds for us all.", ["objectivesText"] = "Speak with Farseer Drek'Thar at the Pool of Visions to begin the ritual of vision.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 106141, 106152, 106162, 106173, 244320 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74272, ["x"] = 0.168, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74272, ["x"] = 0.168, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 19, ["name"] = "Defense of Wor'gol", ["orderIndex"] = 3, ["flags"] = 0 } } },
[33473] = { ["id"] = 33473, ["name"] = "Back to Bladespire Citadel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33473 }, ["series"] = { 32783, 32791, 32792, 32794, 32795, 32796, 33468, 33469, 33470, 33807 }, ["description"] = "Durotan must be told of your vision. Pul Windcarver will offer you a flight back. The fate of the Frostwolf... of Draenor, depends upon you, <name>.", ["objectivesText"] = "Return to Durotan at Bladespire Citadel.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74272, ["x"] = 0.168, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[33493] = { ["id"] = 33493, ["name"] = "Return to the Pack", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 590, ["storyline"] = { 32989, 32990, 32991, 32992, 32993, 32994, 33493, 33785, 33826, 33828 }, ["series"] = { 33828, 37291 }, ["description"] = "Part of me agrees with Karg - we COULD challenge the Iron Wolf right now. My fists clench at the mention of his name. My muscles scream for vengeance. But then, in my heart, I feel Asha. Calming me. Guiding me. I do not deserve her wisdom, but it is a gift I will not waste. <Lokra squints at the sky.> Durotan and the others will be gathering at your garrison about now. We should meet them.", ["objectivesText"] = "Speak with Durotan at your garrison.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 110560 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 21, ["name"] = "Thunder's Fall", ["orderIndex"] = 9, ["flags"] = 0 } } },
[33526] = { ["id"] = 33526, ["name"] = "These Colors Don't Run", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 34379, 34380 }, ["series"] = { 33344, 33408, 33410, 33527, 33546, 33622, 33657, 33784, 33816, 34379, 34380 }, ["description"] = "Bladespire has been a plague on my people for many years. That ends today! Now to explain it to the ogres in a way they will understand. If you still wish to help us, place our banner in the corpses of our adversaries. Their courage will falter as they behold a field of Frostwolf trophies! This is our way. I will meet with you ahead when you have completed this deed.", ["objectivesText"] = "Use 8 Frostwolf Banners on Bladespire Ogre corpses. Progress: Yes?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 107279, 107361 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 }, { ["mapID"] = 525, ["npcID"] = 76240, ["x"] = 0.201333, ["y"] = 0.441333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.225333, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 526, ["questLines"] = { { ["id"] = 18, ["name"] = "Siege of Bladespire Citadel", ["orderIndex"] = 3, ["flags"] = 0 } } },
[33527] = { ["id"] = 33527, ["name"] = "Last Steps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 34379, 34380 }, ["series"] = { 33344, 33408, 33410, 33526, 33546, 33622, 33657, 33784, 33816, 34379, 34380 }, ["description"] = "In a rage, Ga'nar ascended to fight Gorr'thog, the ogre king. He is alone, and the ramp to the throne room is now blocked. You've proven resourceful. Perhaps you could find another way up? I sustained wounds on my way here, but I will work to cut my way through and up the ramp so we may rejoin. Hurry traveler, ensure that the Frostwolf clan wins our assault on the citadel.", ["objectivesText"] = "Climb the chain and kill Gorr'thog.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 106135, 106149, 106157, 107279, 107302, 107361, 245438 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 75177, ["x"] = 0.27, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 528, ["questLines"] = { { ["id"] = 18, ["name"] = "Siege of Bladespire Citadel", ["orderIndex"] = 9, ["flags"] = 0 } } },
[33530] = { ["id"] = 33530, ["name"] = "Nightmare in the Tomb", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "Down there... horrible... bodies everywhere... Dark ritual... please... you must stop it...", ["objectivesText"] = "Investigate the ritual in the Tomb of Souls.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 110253, 110271, 112512, 112513, 112514, 112515 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75119, ["x"] = 0.556, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 4, ["flags"] = 0 } } },
[33543] = { ["id"] = 33543, ["name"] = "The Laughing Skull", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 33543, 33544, 33548, 33563, 33593, 35151, 36434, 36460 }, ["series"] = { 33010, 33544, 34123, 34124, 34867, 35557, 49546 }, ["description"] = "Ah, $p, good. I need someone who is not of my clan to negotiate with the Laughing Skull. We could use their help navigating this land, but they are dangerous and unpredictable, much like Gorgrond itself. Follow this road and seek out someone willing to speak with you. Perhaps they will see you as something new and be willing to talk first and stab later.", ["objectivesText"] = "Find a Laughing Skull clansman.", ["rewardGold"] = 254700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 84176, ["x"] = 0.387, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.737333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 57, ["name"] = "Establish a Foothold", ["orderIndex"] = 0, ["flags"] = 0 } } },
[33544] = { ["id"] = 33544, ["name"] = "Goren, Goren, Gone!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 33543, 33544, 33548, 33563, 33593, 35151, 36434, 36460 }, ["series"] = { 33010, 33543, 34123, 34124, 34867, 35557, 49546 }, ["description"] = "We... we left the goren alone for too long. They have grown bold and forgotten who we are. Kill them! Kill them all. Rip them apart until they scream. Remind them what happens to anyone who tries to attack a Laughing Skull village. Oh, and welcome to Gorgrond .", ["objectivesText"] = "Slay 8 Acidtooth Devourers .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 84176, ["x"] = 0.387, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 84176, ["x"] = 0.387, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.387, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 57, ["name"] = "Establish a Foothold", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 111478 } },
[33546] = { ["id"] = 33546, ["name"] = "Deeds Left Undone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 34379, 34380 }, ["series"] = { 33344, 33408, 33410, 33526, 33527, 33622, 33657, 33784, 33816, 34379, 34380 }, ["description"] = "In his haste, Ga'nar advanced before this area was secured. He is a matchless warrior, mind you, but his tactics are sometimes costly. Gol'kosh and his troops were ordered to destroy enemy supplies, but ogres have stolen the oil he needs. Retrieve the oil and see that their mission is carried out, traveler. Then, if they still live, direct them to rejoin me at the citadel's entrance. I must see my wounded brothers to safety.", ["objectivesText"] = "Collect barrels of Frostwolf Oil and deliver it to Gol'kosh in the supply room. Progress: Lok'tar, traveler.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 107279, 107361 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 75177, ["x"] = 0.27, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 526, ["questLines"] = { { ["id"] = 18, ["name"] = "Siege of Bladespire Citadel", ["orderIndex"] = 4, ["flags"] = 0 } } },
[33548] = { ["id"] = 33548, ["name"] = "We Die Laughing!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 33543, 33544, 33548, 33563, 33593, 35151, 36434, 36460 }, ["description"] = "Are you here to help or hinder? This village is being eaten, and we must move quickly to salvage what we can. Gather the masks of our fallen Laughing Skull brothers and sisters and meet me on the western side of the village. I will need them if our clan is to rebuild.", ["objectivesText"] = "Collect 5 Laughing Skull Masks . Progress: We are the Laughing Skull! We do not flinch in the face of death. We laugh at it.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 107338, 112608, 112609, 112610, 112611 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 76987, ["x"] = 0.392, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74606, ["x"] = 0.448667, ["y"] = 0.723333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 57, ["name"] = "Establish a Foothold", ["orderIndex"] = 2, ["flags"] = 0 } } },
[33563] = { ["id"] = 33563, ["name"] = "Eye Candy", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 33543, 33544, 33548, 33563, 33593, 35151, 36434, 36460 }, ["description"] = "You! Get in the fight or get out of our way. This is no ordinary goren attack. Look over there, a gronnling is sacking our grubhall. That hunchbacked gorebucket bit a chunk out of my lovely Marrow! Rip the eye out of its forehead and bring it to me. That should buy me enough time to get her clear of this goren hole.", ["objectivesText"] = "Collect Skothwa's Eye . Progress: Did you make that thing scream? Did it beg for mercy? Did you kill it before taking its eye? Tell me everything.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 114229, 118030, 118031, 118032, 118033 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74611, ["x"] = 0.409, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74611, ["x"] = 0.409, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 57, ["name"] = "Establish a Foothold", ["orderIndex"] = 3, ["flags"] = 0 } } },
[33586] = { ["id"] = 33586, ["name"] = "Chasing Shadows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33059, 33072, 33076, 33080, 33081, 33082, 33586 }, ["series"] = { 33082, 34043 }, ["description"] = "Not all of the Shadowmoon orcs followed Ner'zhul's alliance with the Iron Horde. Among them, there is one orc whom I befriended many years ago. She may be able to tell us more about Ner'zhul's plans for this \"Dark Star.\" She can be found at Exile's Rise to the northeast. I will send word ahead so she expects your arrival.", ["objectivesText"] = "Speak to Rulkan at Exile's Rise.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 79043, ["x"] = 0.387333, ["y"] = 0.530667 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 75884, ["x"] = 0.457, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.387333, ["y"] = 0.530667 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 43, ["name"] = "The Dark Side of the Moon", ["orderIndex"] = 5, ["flags"] = 0 } } },
[33593] = { ["id"] = 33593, ["name"] = "A Flare for the Dramatic", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 33543, 33544, 33548, 33563, 33593, 35151, 36434, 36460 }, ["series"] = { 35151, 36434, 36460 }, ["description"] = "I received a strange object with a note attached. Here, it seems to be written in your tongue, commander. <Dear Mister Durotan , I'm Penny... you know, from Azeroth? We met briefly back at $p's garrison. Anyway, like I told you, I have a fifth degree black hammer in engineering and I'm eager to serve. The more danger the better! You just fire this old flare whenever you're in trouble and I'll be there, quick as a quark! Hopefully, Penny>", ["objectivesText"] = "Shoot Penny's Flare Gun while in Deadgrin. Progress: Hey there, commander!", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 115534 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.737333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 57, ["name"] = "Establish a Foothold", ["orderIndex"] = 4, ["flags"] = 0 } } },
[33622] = { ["id"] = 33622, ["name"] = "To the Slaughter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 34379, 34380 }, ["series"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33657, 33784, 33816, 34379, 34380 }, ["description"] = "This entrance to the fortress is clear again, thanks to your help. Inside is another story. Find your way inside and leave no ogre standing as you go.", ["objectivesText"] = "Kill 10 ogres in Bladespire Citadel. Progress: Yes?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 38670, 59685, 59686, 59687, 59688, 59689, 59690, 59691, 59692, 107279, 107361, 175184, 175185, 175186, 175187, 175216, 175217, 175218, 175219 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 75177, ["x"] = 0.27, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 527, ["questLines"] = { { ["id"] = 18, ["name"] = "Siege of Bladespire Citadel", ["orderIndex"] = 8, ["flags"] = 0 } } },
[33657] = { ["id"] = 33657, ["name"] = "Moving In", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33657 }, ["series"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 33816, 34379, 34380 }, ["description"] = "Gorr'thog is now dead. It is time now to secure our hold on Bladespire Citadel. Meet me below and we can begin strengthening our presence.", ["objectivesText"] = "Meet Durotan at Bladespire Citadel.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 107279, 107361, 195213 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.225333, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[33720] = { ["id"] = 33720, ["name"] = "Decommissioned Mission", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33721, 33724, 33728, 33729, 33730, 33731, 34948, 34962 }, ["description"] = "Ketya Shrediron, Your new Iron Shredders are a menace to our own soldiers. Decommission the prototype and store it in the cave on Talador beach until you've worked out the kinks. I will send Engineer Draxen to work on it in the meantime. - Orgrim Doomhammer", ["objectivesText"] = "Find the Decommissioned Iron Shredder in the nearby cave and take it from Engineer Draxen .", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75924, ["x"] = 0.59, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 5, ["flags"] = 0 } } },
[33721] = { ["id"] = 33721, ["name"] = "Gazlowe's Solution", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33720, 33724, 33728, 33729, 33730, 33731, 34948, 34962 }, ["description"] = "I've identified some high value targets down in the forest below. When you get near one, you can deploy my solution. Deploy it and the objectives will be neutralized with great ceremony.", ["objectivesText"] = "Destroy the Thunderlord Cache, Blackrock Forge, and Munitions Landing.", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 107899, 113023, 113024, 113025 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75873, ["x"] = 0.62, ["y"] = 0.104 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75924, ["x"] = 0.59, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.104 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 3, ["flags"] = 0 } } },
[33722] = { ["id"] = 33722, ["name"] = "Too Many Irons in the Fire", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33754, 34683, 34950, 35226 }, ["description"] = "We must not head into battle prematurely. Before we go after Orgrim, we must first deal with his troops. If we are to succeed in our mission of wiping out the Iron Horde from Talador , we need to start on these shores.", ["objectivesText"] = "Kill 15 Iron Horde on Orunai Coast.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75806, ["x"] = 0.615, ["y"] = 0.109 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75958, ["x"] = 0.59, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.109 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 1, ["flags"] = 0 } } },
[33724] = { ["id"] = 33724, ["name"] = "Vol. X Pages ?", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33720, 33721, 33728, 33729, 33730, 33731, 34948, 34962 }, ["description"] = "The manual for the shredder was wedged in there, but it's missing lots of pages. We need to find as many pages of that manual as possible and I might--MIGHT--be able to get this shredder operational. Based on the direction of the wind, I bet the pages flew toward Archenon Siegeyard.", ["objectivesText"] = "Find 20 Manual Pages at Archenon Siegeyard. Progress: I don't know why those idiots don't just collect all the pages in one place.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 107843 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75924, ["x"] = 0.59, ["y"] = 0.206 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75941, ["x"] = 0.556, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 7, ["flags"] = 0 } } },
[33728] = { ["id"] = 33728, ["name"] = "An Eye for a Spy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33720, 33721, 33724, 33729, 33730, 33731, 34948, 34962 }, ["description"] = "Excellent, excellent! I'll make sense of these manual pages and will get the Iron Shredder operational immediately! While I do that, take a look through my Eye 'n' Ear. That's where you'll be headed soon!", ["objectivesText"] = "Look through Gazlowe 's Eye 'n' Ear. Progress: Lots of orcs ready to be shredded!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 63793, 63794, 63796, 63797, 246427 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75941, ["x"] = 0.556, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75941, ["x"] = 0.556, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 10, ["flags"] = 0 } } },
[33729] = { ["id"] = 33729, ["name"] = "Born to Shred", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33720, 33721, 33724, 33728, 33730, 33731, 34948, 34962 }, ["description"] = "The Iron Shredder is operational! It should be primed and ready for you to shred our enemies in Tuurem! Head inside and see what damage you can do. Can't say I'm not jealous.", ["objectivesText"] = "Kill 100 Iron Horde in Tuurem using the Iron Shredder. Progress: What's up, boss?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75941, ["x"] = 0.556, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75941, ["x"] = 0.556, ["y"] = 0.41 }, { ["mapID"] = 535, ["npcID"] = 75968, ["x"] = 0.606, ["y"] = 0.387368 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 11, ["flags"] = 0 } } },
[33730] = { ["id"] = 33730, ["name"] = "Engineering Her Demise", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33720, 33721, 33724, 33728, 33729, 33731, 34948, 34962 }, ["description"] = "-- THE MOTHER HAS BEEN DETECTED. WARNING! WARNING! --", ["objectivesText"] = "Defeat Ketya Shrediron at Tuurem.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 113050, 113051, 113052, 113053, 113054, 113055, 113056, 113057 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75941, ["x"] = 0.556, ["y"] = 0.41 }, { ["mapID"] = 535, ["npcID"] = 75968, ["x"] = 0.606, ["y"] = 0.387368 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75959, ["x"] = 0.5485, ["y"] = 0.3875 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 12, ["flags"] = 0 } } },
[33731] = { ["id"] = 33731, ["name"] = "The Battle for Shattrath", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33720, 33721, 33724, 33728, 33729, 33730, 34948, 34962 }, ["description"] = "To stop the Iron Horde, we must overcome prejudice and work together, if only for this purpose. Horde, Alliance, past, present... all meaningless in the face of this enemy. We will retake Shattrath together... or die trying.", ["objectivesText"] = "Repel the Iron Horde from Shattrath.", ["rewardGold"] = 1239200, ["rewardXP"] = 5530, ["rewardItems"] = { 112516, 112517, 112518, 112519 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75805, ["x"] = 0.542, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79604, ["x"] = 0.714, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 14, ["flags"] = 0 } } },
[33735] = { ["id"] = 33735, ["name"] = "In Short Supply", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33736 }, ["description"] = "The enemy has explosive devices stored on the beach below. We must recover them so they are not used against us. Reports indicate that crates of explosives are scattered along the shoreline. While you search, Durotan and I will carve deeper into Iron Horde territory.", ["objectivesText"] = "Collect 6 Iron Horde Explosives . Progress: Have you found the Iron Horde Explosives yet?", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 69903, 90818, 103533, 107855, 120334, 128803, 140591, 141701, 160054, 184522, 201326, 224573, 259086 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75808, ["x"] = 0.5724, ["y"] = 0.2984 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75808, ["x"] = 0.5724, ["y"] = 0.2984 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.5724, ["y"] = 0.2984 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 2, ["flags"] = 0 } } },
[33736] = { ["id"] = 33736, ["name"] = "Iron Them Out", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33735 }, ["description"] = "The orcs themselves are not the only threat. We may have weakened them considerably, but they still have siege weapons of significant power. Sabotage siege weapons you find with the explosives you collected from the beach.", ["objectivesText"] = "Destroy 6 Iron Horde Siege Engines.", ["rewardGold"] = 58650, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75808, ["x"] = 0.5724, ["y"] = 0.2984 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75808, ["x"] = 0.5724, ["y"] = 0.2984 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.5724, ["y"] = 0.2984 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 9, ["flags"] = 0 } } },
[33754] = { ["id"] = 33754, ["name"] = "Through the Looking Glass", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33722, 34683, 34950, 35226 }, ["description"] = "Your allies sent along a goblin, Gazlowe, to advise us against the Iron Horde. Thus far, he has proven a valuable asset. He has a looking glass set up that can see a great distance and, he claims, even hear. Use this looking glass and report back what you've seen. I will stick to my standard spyglass.", ["objectivesText"] = "Look through Gazlowe's Eye 'n' Ear. Progress: Take a look through Gazlowe's Eye 'n' Ear.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75806, ["x"] = 0.615, ["y"] = 0.109 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75806, ["x"] = 0.615, ["y"] = 0.109 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.109 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 0, ["flags"] = 0 } } },
[33765] = { ["id"] = 33765, ["name"] = "Dark Enemies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33070, 33075, 33765, 33813, 33905, 34019 }, ["series"] = { 33059, 33070, 33072, 33075, 33076, 33080, 33081, 33814, 33905, 34019, 36592 }, ["description"] = "Your arrival should be cause for celebration, hero, but I fear our troubles are just beginning. Warlord Ner'zhul and his Shadowmoon clan have launched a surprise attack on a draenei settlement to the north. Prophet Velen has gone to aid the wounded at Teluuna Observatory, but we need more defenders. I must go to assist the others. If you wish to help us, go to Arbor Glen and kill any Shadowmoon enemies that you see.", ["objectivesText"] = "Kill 8 Shadowmoon Voidmancers .", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 113145, 113146, 113147 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 75005, ["x"] = 0.422, ["y"] = 0.397333 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 74043, ["x"] = 0.490667, ["y"] = 0.381333 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.397333 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 40, ["name"] = "Shadows Awaken", ["orderIndex"] = 2, ["flags"] = 0 } } },
[33784] = { ["id"] = 33784, ["name"] = "Gormaul Tower", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 34379, 34380 }, ["series"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33657, 33816, 34379, 34380 }, ["description"] = "It is time for us to strike out against those who would enslave us! We travel to Gormaul Tower to wrest it from the Bladespire ogres. I would welcome your company. Mount up, and together we will ride to battle!", ["objectivesText"] = "Take Gormaul Tower from the Bladespire ogres. Progress: You may ride with us and fight with our pack.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 106136, 106154, 106164, 106168, 107279, 107361 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 76557, ["x"] = 0.218667, ["y"] = 0.519333 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 76240, ["x"] = 0.201333, ["y"] = 0.441333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.218667, ["y"] = 0.519333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 18, ["name"] = "Siege of Bladespire Citadel", ["orderIndex"] = 2, ["flags"] = 0 } } },
[33785] = { ["id"] = 33785, ["name"] = "Karg Unchained", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32989, 32990, 32991, 32992, 32993, 32994, 33493, 33785, 33826, 33828 }, ["description"] = "They took my brothers and sisters. They took my wolf. <Karg lifts his axe and fixes his gaze upon its edge.> Now we take their heads.", ["objectivesText"] = "Slay 25 Thunderlord orcs in Grom'gar. Progress: By killing them - we take their heads by killing them. We don't actually need to pick up the heads.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 21, ["name"] = "Thunder's Fall", ["orderIndex"] = 6, ["flags"] = 0 } } },
[33786] = { ["id"] = 33786, ["name"] = "Crippled Caravan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33786 }, ["series"] = { 33787, 33788, 33808, 34077 }, ["description"] = "I'm getting reports that the botani have started leaving their bloom and attacking wandering travelers. This is most unusual. We already dispatched a number of rangari to try and resolve this issue. A caravan from Azeroth passed through here recently, you should probably check on your people to ensure their safety.", ["objectivesText"] = "Find Fiona 's Caravan in Shadowmoon Valley .", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 76200, ["x"] = 0.57, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 76204, ["x"] = 0.536, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[33787] = { ["id"] = 33787, ["name"] = "Fiona's Solution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33787 }, ["series"] = { 33786, 33788, 33808, 34077 }, ["description"] = "Gidwin was attacked by one of those plant creatures. From the looks of it, he is suffering from some kind of paralysis. I can make a cure, but I'll need some local ingredients.", ["objectivesText"] = "Collect 1 Riverbeast Heart , 2 Swamplighter Venom , 4 Riotvine , and 3 Moonlit Herbs . Progress: Do you have the ingredients?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 108394, 108395, 108396, 108409 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 76204, ["x"] = 0.536, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 76204, ["x"] = 0.536, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[33788] = { ["id"] = 33788, ["name"] = "Cooking With Unstable Herbs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33788, 34994, 34995, 35006, 35014, 35015 }, ["series"] = { 33786, 33787, 33808, 34077 }, ["description"] = "The base is boiling and ready for those ingredients. Add each of the ingredients, one at a time, and I will handle the mixing and frothing. Speak to me when you are ready.", ["objectivesText"] = "Help Fiona brew a curative elixir. Progress: Are you ready to begin?", ["rewardGold"] = 7150, ["rewardXP"] = 1415, ["rewardItems"] = { 113130 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 76204, ["x"] = 0.536, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 76204, ["x"] = 0.536, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 42, ["name"] = "Botani In Bloom", ["orderIndex"] = 0, ["flags"] = 0 } } },
[33793] = { ["id"] = 33793, ["name"] = "Harbingers of the Void", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["description"] = "Our scouts have made a horrifying discovery, <name>. The souls of the prisoners are being used to summon creatures from the void. Inside, three beings of darkness already await - the Essence of Shadow , the Essence of Darkness , and the Essence of Anguish . They must be destroyed immediately, before their power can be unleashed.", ["objectivesText"] = "Destroy the Essence of Shadow , Essence of Darkness , and Essence of Anguish . Progress: The souls of innocents were used to birth the foul creatures. All that is depraved, and sick, and twisted in this world, are embodied within them.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 81176, ["x"] = 0.358, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 77282, ["x"] = 0.409, ["y"] = 0.377 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 8, ["flags"] = 0 } } },
[33794] = { ["id"] = 33794, ["name"] = "The Great Salvation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["description"] = "We've located the prisoners. They are being held in captivity here, inside the Shadowmoon fortress. Please rescue as many of them as you can. And hurry. We can hear their screams out here.", ["objectivesText"] = "Free 8 Draenei Prisoners from their cages.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 211279 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 81176, ["x"] = 0.358, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 73395, ["x"] = 0.584, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 9, ["flags"] = 0 } } },
[33795] = { ["id"] = 33795, ["name"] = "Across the Stars", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["description"] = "A key source of the Shadowmoon clan's power comes from their understanding of the stars and their omens. For centuries, they have recorded the patterns of the stars and their interpretations. While you are in the fortress, collect some of these documents for me. We will take their own knowledge and use it against them.", ["objectivesText"] = "Collect 5 Star Readings . Progress: Your aid is appreciated, <class>.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 112385 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 81173, ["x"] = 0.354, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 77282, ["x"] = 0.409, ["y"] = 0.377 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 10, ["flags"] = 0 } } },
[33807] = { ["id"] = 33807, ["name"] = "Free Our Brothers and Sisters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33468, 33469, 33470, 33807 }, ["series"] = { 32783, 32791, 32792, 32794, 32795, 32796, 33468, 33469, 33470, 33473 }, ["description"] = "These Thunderlord curs use coward's weapons like nets and chains. Many of our villagers and wolf-brothers and sisters have been trapped. If you free them, they will fight at your side with honor. We must quell this attack with haste so I may return to Bladespire Citadel and continue my preparations.", ["objectivesText"] = "Free 6 Frost Wolves or Wor'gol Villagers.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74507, ["x"] = 0.1985, ["y"] = 0.58725 }, { ["mapID"] = 525, ["npcID"] = 79415, ["x"] = 0.218, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74651, ["x"] = 0.208, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.1985, ["y"] = 0.58725 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 19, ["name"] = "Defense of Wor'gol", ["orderIndex"] = 1, ["flags"] = 0 } } },
[33808] = { ["id"] = 33808, ["name"] = "Swamplighter Queen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33808 }, ["series"] = { 33786, 33787, 33788, 34077 }, ["description"] = "It looks like those plant creatures used some kind of poison when they attacked Gidwin. It's a powerful concoction to say the least. If we are going to cure Gidwin we need one more special ingredient. This one might be a bit harder to obtain than the others. You up to the challenge, <name>?", ["objectivesText"] = "Obtain The Swamplighter Queen's Tail for Fiona in Shadowmoon Valley . Progress: I just wanted to pick some herbs and relax with my boys... I should have stayed in Azeroth.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 106143, 106153, 106176, 107314, 108410 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 76204, ["x"] = 0.536, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 76204, ["x"] = 0.536, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[33813] = { ["id"] = 33813, ["name"] = "In Need of a Hero", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33070, 33075, 33765, 33813, 33905, 34019 }, ["description"] = "I...<sob>... I can't leave...<gulp>... without... Squiggy...! He... he's... trapped! You need... to put out... the fire! < Ariaana points across the room and bursts into tears.>", ["objectivesText"] = "Save Squiggy by dousing fires with buckets of water. Progress: Squiggy... is... my... best... friend!", ["rewardGold"] = 143200, ["rewardXP"] = 710, ["rewardItems"] = { 111908 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 71502, ["x"] = 0.52, ["y"] = 0.326 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 71502, ["x"] = 0.52, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 40, ["name"] = "Shadows Awaken", ["orderIndex"] = 3, ["flags"] = 0 } } },
[33815] = { ["id"] = 33815, ["name"] = "A Song of Frost and Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33868, 34364, 34375, 34377, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "You have rescued many of my clan from the slave pens of Tanaan. Their liberation and the destruction of the Dark Portal are more than enough for me to consider you one of us. However, you are still a stranger to our leader, Durotan . I would like to introduce you to him.", ["objectivesText"] = "Meet Durotan . Progress: What a strange creature you are.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 111907 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 76411, ["x"] = 0.447, ["y"] = 0.661 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78272, ["x"] = 0.453, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.447, ["y"] = 0.661 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 0, ["flags"] = 0 } } },
[33816] = { ["id"] = 33816, ["name"] = "Honor Has Its Rewards", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33816 }, ["series"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33657, 33784, 34379, 34380 }, ["description"] = "You have honored my people. Now, we wish to honor you. We have a rite of initiation in my clan. When one comes of age, they cover themselves in the blood of their first hunt, and rest their hands upon a shamanstone to honor the ancestors who came before them. In our brief time together you have already slain many foes more fierce than our hunters have ever had to face. Go, touch the shamanstone here in Wor'gol, and join our pack as an equal.", ["objectivesText"] = "Go to the Shamanstone in Wor'gol and receive a blessing. Progress: Thank you for saving my clan.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 107279, 107361 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 80456, ["x"] = 0.21, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74272, ["x"] = 0.168, ["y"] = 0.578 }, { ["mapID"] = 525, ["npcID"] = 76616, ["x"] = 0.176, ["y"] = 0.566 }, { ["mapID"] = 525, ["npcID"] = 80456, ["x"] = 0.21, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.21, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[33826] = { ["id"] = 33826, ["name"] = "Where's My Wolf?!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32989, 32990, 32991, 32992, 32993, 32994, 33493, 33785, 33826, 33828 }, ["series"] = { 32994 }, ["description"] = "My frost wolf, Nerok , was captured with me and the others. I do not know where they are keeping him, but I'll bet the so-called \"beastmaster\" who dragged us here does. He is at the beast pens nearby, boasting about his catch to the younger hunters. We'll see how he boasts with my axe in his skull.", ["objectivesText"] = "Slay Beastmaster Torash and free Nerok in Grom'gar. Progress: I will not leave my frost wolf behind. Dead or alive, Nerok leaves this place with me.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 110560 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 21, ["name"] = "Thunder's Fall", ["orderIndex"] = 5, ["flags"] = 0 } } },
[33828] = { ["id"] = 33828, ["name"] = "The Master Siegesmith", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32989, 32990, 32991, 32992, 32993, 32994, 33493, 33785, 33826, 33828 }, ["series"] = { 33493, 37291 }, ["description"] = "Not long ago, the most advanced weapon a Thunderlord could make was a really, really big spear. The Blackrock orcs must have shipped in a fearsome master to have them producing cannons so rapidly. We need to find that master.", ["objectivesText"] = "Slay Master Siegesmith Uratok in Grom'gar. Progress: Karg is right - this is our best opportunity to cripple Grom'gar's defenses. We do this, then we return to the clan, heads high with pride.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 113249, 113250, 113251, 113252 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 21, ["name"] = "Thunder's Fall", ["orderIndex"] = 8, ["flags"] = 0 } } },
[33837] = { ["id"] = 33837, ["name"] = "Darkness Falls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["description"] = "It is already beginning, over the hills to the southeast. Ner'zhul has everything he needs to summon the Dark Star. The Iron Horde attack on Karabor is imminent. This is where everything ends. Champion, I must ask you to ride ahead and delay Ner'zhul . I will join you as quickly as I can.", ["objectivesText"] = "Find Ner'zhul . Progress: Today is the day that everything ends. But something new rises from the ashes.", ["rewardGold"] = 509400, ["rewardXP"] = 2125, ["rewardItems"] = { 113169, 113170, 113171, 113172, 113173, 113174, 113175, 113176 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 77282, ["x"] = 0.409, ["y"] = 0.377 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 73395, ["x"] = 0.584, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.377 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[33905] = { ["id"] = 33905, ["name"] = "Closing the Door", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33070, 33075, 33765, 33813, 33905, 34019 }, ["series"] = { 33059, 33070, 33072, 33075, 33076, 33080, 33081, 33765, 33814, 34019, 36592 }, ["description"] = "The Shadowmoon orcs are using portals to bring in reinforcements and smuggle away draenei captives. If we are to have any hope of retaking the village, we must destroy the portals at once. The only way to do this is to kill the portalmasters who keep the rifts open.", ["objectivesText"] = "Close 3 Void Portals by killing Shadowmoon Portalmasters . Progress: Breaking the fabric of space is extremely costly magic. It must rend their very souls.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 74343, ["x"] = 0.464, ["y"] = 0.379 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 74043, ["x"] = 0.490667, ["y"] = 0.381333 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.379 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 40, ["name"] = "Shadows Awaken", ["orderIndex"] = 4, ["flags"] = 0 } } },
[33917] = { ["id"] = 33917, ["name"] = "Disrupting the Flow", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "You there, we need to stop the flow of demon reinforcements! Do you see the floating fel crystals spread throughout the front? Those resonators are powering the portals unleashing hell on our forces. I need you to take them out!", ["objectivesText"] = "Destroy 4 Burning Resonators in the Burning Front. Progress: We can't hold out forever!", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 108733, 177698, 177699, 178874, 178877, 178880, 178881, 178882, 178883 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78482, ["x"] = 0.566, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78482, ["x"] = 0.566, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 1, ["flags"] = 0 } } },
[33920] = { ["id"] = 33920, ["name"] = "The Heart of Auchindoun", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "A band of Shadow Council orcs stole the Heart of Auchindoun! The Heart powers all of Auchindoun's defenses. Thankfully we were able to save its core and one of its four pieces. The warlock O'mogg Blackheart is using Karab'uun , one of the stolen pieces, to power the largest portal in the Burning Front. Return Karab'uun to me.", ["objectivesText"] = "Defeat O'mogg Blackheart and retrieve Karab'uun in the Burning Front. Progress: I trust you have Karab'uun . I am not known for my patience when the countless souls inside Auchindoun are in danger.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 108733, 113029, 113030, 113031, 119078, 119087 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78519, ["x"] = 0.565, ["y"] = 0.67 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78519, ["x"] = 0.565, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 2, ["flags"] = 0 } } },
[33958] = { ["id"] = 33958, ["name"] = "Into the Hollow", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 33976, 34092, 34240, 34242, 34326, 34508 }, ["description"] = "I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front. One of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari , one of the remaining pieces of the Heart of Auchindoun. I need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.", ["objectivesText"] = "Kill Xanatos the Defiler in Deathweb Hollow and retrieve Sha'tari . Progress: Did the demon have Sha'tari as we thought?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 109744, 110683, 112509, 112510, 112511, 112528 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75256, ["x"] = 0.596, ["y"] = 0.739333 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75256, ["x"] = 0.596, ["y"] = 0.739333 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.739333 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 8, ["flags"] = 0 } } },
[33967] = { ["id"] = 33967, ["name"] = "Antivenin", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else. I'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention! Please, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.", ["objectivesText"] = "Collect 9 Deathweb Fangs in Deathweb Hollow. Progress: Do you have the fangs? We don't have much time!", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 109744 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78028, ["x"] = 0.596, ["y"] = 0.739333 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78028, ["x"] = 0.596, ["y"] = 0.739333 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.739333 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 9, ["flags"] = 0 } } },
[33969] = { ["id"] = 33969, ["name"] = "Vile Defilers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "The spiders in the nearby overrun mine are feared by many, for their venom twists the very form of their victims. Many of the locals stay far away from their hollow, but I fear the Shadow Council has become privy to this information. Our scouts report that their warlocks are infusing these spiders with fel energy so that their venom turns their victims into demonic minions! We must destroy the defiling crystals so this madness does not spread.", ["objectivesText"] = "Destroy 5 Defiling Crystals in Deathweb Hollow.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 109744, 110683 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78102, ["x"] = 0.575, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78102, ["x"] = 0.575, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 7, ["flags"] = 0 } } },
[33970] = { ["id"] = 33970, ["name"] = "Into the Hollow", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["description"] = "I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front. One of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari , one of the remaining pieces of the Heart of Auchindoun. I need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.", ["objectivesText"] = "Kill Xanatos the Defiler in Deathweb Hollow and retrieve Sha'tari . Progress: Did the foul demon have Sha'tari as we thought?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 110683, 112509, 112510, 112511, 112528 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75256, ["x"] = 0.596, ["y"] = 0.739333 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75256, ["x"] = 0.596, ["y"] = 0.739333 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.739333 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 8, ["flags"] = 0 } } },
[33971] = { ["id"] = 33971, ["name"] = "Antivenin", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["description"] = "I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else. I'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention! Please, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.", ["objectivesText"] = "Collect 9 Deathweb Fangs in Deathweb Hollow. Progress: Do you have the fangs? We don't have much time!", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 109744, 110683, 116125, 117569 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78028, ["x"] = 0.596, ["y"] = 0.739333 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78028, ["x"] = 0.596, ["y"] = 0.739333 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.739333 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 9, ["flags"] = 0 } } },
[33972] = { ["id"] = 33972, ["name"] = "Vile Defilers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["description"] = "The deathweb spiders are remarkable creatures. Their venom twists the very form of their victims. We are not the only ones privy to this information. The Shadow Council has already dispatched its warlocks to Deathweb Hollow to infuse the spiders with fel energy so that their venom turns creatures into demonic minions! We must destroy the defiling crystals to prevent all of Talador from bending to Teron'gor's will!", ["objectivesText"] = "Destroy 5 Defiling Crystals in Deathweb Hollow. Progress: The last thing we need is the monstrous creatures of this land joining the Legion's fold.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75249, ["x"] = 0.605, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75249, ["x"] = 0.605, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 7, ["flags"] = 0 } } },
[33976] = { ["id"] = 33976, ["name"] = "The Final Piece", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 33958, 34092, 34240, 34242, 34326, 34508 }, ["description"] = "I am too injured to fight, <class>. I have failed my city and its people. This battle is yours. Vorpil waits just ahead. He's trying to use Auch'naaru 's powers for some sort of dark ritual. You must do what I could not. Cut Vorpil down and retrieve Auch'naaru so the Heart of Auchindoun can be whole once more!", ["objectivesText"] = "Take Auch'naaru from Vorpil Ribcleaver in Telmor. Progress: We need the final piece of the Heart!", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 108886, 108896, 108897, 109162, 109163, 109197, 109622, 113042, 113043, 113044, 113045, 113046, 113047, 113048, 113049 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 77082, ["x"] = 0.448, ["y"] = 0.905 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77082, ["x"] = 0.448, ["y"] = 0.905 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.905 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 15, ["flags"] = 0 } } },
[33988] = { ["id"] = 33988, ["name"] = "Invasion of the Soul Eaters", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "<The note is scrawled hurriedly across the parchment.> Telmor is lost. The Shadow Council is dragging our fallen into piles and feeding the souls to their leader. There is blood on my hands... Please, if anyone reads this message, burn the bodies of our fallen so our enemy cannot use them. - Restalaan, Captain of the Guard", ["objectivesText"] = "Use torches from a forge to burn 4 body piles in Telmor.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 24421, 108886, 108896, 108897, 109162, 109163, 109197, 109622 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 12, ["flags"] = 0 } } },
[34012] = { ["id"] = 34012, ["name"] = "Need More Teeth", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["description"] = "< Prowler Sasha silently holds out his hand to reveal a necklace crafted of stained leather and putrid brown ogre teeth. All have a matching tone of rot to them.> <It has several knots that appear to be missing additional teeth.>", ["objectivesText"] = "Collect 30 Putrid Brown Ogre Teeth. Progress: < Prowler Sasha stares at you with cold, merciless eyes.>", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 108898 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75008, ["x"] = 0.414, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75008, ["x"] = 0.414, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34013] = { ["id"] = 34013, ["name"] = "Never Forget", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "We had to escape Telmor with what few we could save. Someone disabled Leafshadow 's cloaking field; I know not who, but I suspect it had to have been one of our own. We will retrieve our livelihoods in time, but we cannot risk losing our sacred artifacts. If you are able, bring Leafshadow , our town registry, and our prayerbook to safety.", ["objectivesText"] = "Recover the Telmor Registry , the Auchenai Prayerbook , and Leafshadow in Telmor. Progress: Some things are worth fighting for, <race>. These are such things.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 108886, 108896, 108897, 109162, 109163, 109197, 109622 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78083, ["x"] = 0.504667, ["y"] = 0.874667 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78083, ["x"] = 0.504667, ["y"] = 0.874667 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.504667, ["y"] = 0.874667 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 13, ["flags"] = 0 } }, ["startItems"] = { 108951 } },
[34019] = { ["id"] = 34019, ["name"] = "Shadows Awaken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33070, 33075, 33765, 33813, 33905, 34019 }, ["series"] = { 33059, 33070, 33072, 33075, 33076, 33080, 33081, 33765, 33814, 33905, 36592 }, ["description"] = "We've managed to pin Ner'zhul inside the Observatory, but he's taken many down with him. He has taken Yrel's sister, Samaara. I am needed to hold the line here. Please, do whatever you can to save her, hero.", ["objectivesText"] = "Confront Ner'zhul. Progress: The Shadowmoon clan's aggression began when the Iron Horde arrived on Draenor.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 106167, 107308, 107313, 107318, 113103, 114877, 114972, 114984, 115278, 115281, 115343, 115507 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 74043, ["x"] = 0.490667, ["y"] = 0.381333 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 74043, ["x"] = 0.490667, ["y"] = 0.381333 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.490667, ["y"] = 0.381333 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 40, ["name"] = "Shadows Awaken", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34043] = { ["id"] = 34043, ["name"] = "Darkest Night", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["series"] = { 33082, 33586 }, ["description"] = "This keystone will grant its bearer entry into Anguish Fortress. Take it and meet Prophet Velen outside the Shadowmoon fortress. He intends to face Ner'zhul head-on.", ["objectivesText"] = "Speak to Prophet Velen at Anguish Fortress. Provided item:", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 112372 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 75884, ["x"] = 0.457, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 77282, ["x"] = 0.409, ["y"] = 0.377 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.457, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34054] = { ["id"] = 34054, ["name"] = "The Dark Side of the Moon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["series"] = { 35032 }, ["description"] = "< Prophet Velen 's voice continues.> Yrel and I have located Warlord Ner'zhul. He is meeting with Grommash Hellscream atop the highest altar overlooking Anguish Fortress. Meet us there. We must stop him.", ["objectivesText"] = "Find Ner'zhul. Progress: Ner'zhul will pay for what he has done.", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 106175, 107307, 107312, 107317, 110560, 237812 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 77282, ["x"] = 0.409, ["y"] = 0.377 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 73395, ["x"] = 0.584, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.377 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34087] = { ["id"] = 34087, ["name"] = "Through the Looking Glass", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34088, 34959, 36801 }, ["description"] = "An ally of yours, Thaelin, is helping us counter the Iron Horde. He claims this device can be used to spy on the enemy, even so far as hearing what they are saying at great distance. I do not trust such devices. Use it and let me know what you see.", ["objectivesText"] = "Look through Thaelin's Observicopter. Progress: Take a look through Thaelin's Observicopter. I don't trust that machine.", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34088] = { ["id"] = 34088, ["name"] = "Too Many Irons in the Fire", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34087, 34959, 36801 }, ["description"] = "We must slay the Iron Horde troops who infest our lands. Find those who would sully our great forest and show them the hand of justice.", ["objectivesText"] = "Kill 15 Iron Horde at Mor'gran Logworks.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34089] = { ["id"] = 34089, ["name"] = "In Short Supply", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34095 }, ["description"] = "The Iron Horde has explosive devices stored throughout the heart of their logging camp. We must recover them so they are not used against us. I will keep an eye on Maraad... I worry for him in his anger.", ["objectivesText"] = "Collect 6 Iron Horde Explosives . Progress: Have you found the Iron Horde Explosives yet?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 69903, 90818, 103533, 107843, 107855, 108825, 109161, 110560, 120334, 128803, 140591, 141701, 160054, 184522, 201326, 224573, 259086 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75804, ["x"] = 0.586, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75804, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34090] = { ["id"] = 34090, ["name"] = "Thaelin's Quick Fix", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34091, 34094, 34096, 34097, 34098, 34099, 34947, 34963 }, ["description"] = "Those orcs sure like to pile things up in one place. That gave me an idea... I've built this ingenious device for ya! When you get near a target, it'll let you know, and you can deploy it for a big, satisfying, kerBOOM!", ["objectivesText"] = "Destroy the Thunderlord Cache, Blackrock Forge, and Log Storage. Progress: BOOM! Ahahahahaaa!", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560, 113023, 113024, 113025 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34091] = { ["id"] = 34091, ["name"] = "Decommissioned Mission", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34094, 34096, 34097, 34098, 34099, 34947, 34963 }, ["description"] = "Ketya Shrediron, Your new Iron Shredders are a menace to our own soldiers. Decommission the prototype and store it out of the way until you've worked out the kinks. I will send Engineer Trak to work on it in the meantime. - Orgrim Doomhammer", ["objectivesText"] = "Kill Engineer Trak and recover the Decommissioned Iron Shredder .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34092] = { ["id"] = 34092, ["name"] = "Desperate Measures", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 33958, 33976, 34240, 34242, 34326, 34508 }, ["description"] = "We've identified the location of Teron'gor's compound, but his forces are already far stronger than anything we've ever faced. We need to gain an edge, and quickly. The cursed spirits of the Ango'rosh ogres, our ancient enemies, linger in nearby ruins. Go there and gather the Ango'rosh Spellbook and the Grimoire of Binding . Perform the ritual described within at their altar to lift their curse and seek their aid. It's a long shot, but we don't have any other options.", ["objectivesText"] = "Gather the Ango'rosh Spellbook and the Grimoire of Binding , then perform the ritual at the Altar of Ango'rosh in the Ango'rosh Ruins. Progress: Were you able to acquire the aid of the Ango'rosh?", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 108886, 108896, 108897, 109162, 109163, 109197, 109622 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 77799, ["x"] = 0.434, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77799, ["x"] = 0.434, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 17, ["flags"] = 0 } } },
[34094] = { ["id"] = 34094, ["name"] = "Vol. X Pages ?", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34096, 34097, 34098, 34099, 34947, 34963 }, ["description"] = "That shredder had a manual jammed in the cockpit, but it's missing a lot o' pages. If we can find those manual pages, I'd bet my third toe I can get the prototype shredder working again. I coulda swore I saw a few of those pages floatin' about in Archenon Siegeyard. Maybe the orcs there carry them.", ["objectivesText"] = "Find 20 Manual Pages on orcs at Archenon Siegeyard. Progress: Have you found those pages? These manuals are ridiculous.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 107843 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34095] = { ["id"] = 34095, ["name"] = "Iron Them Out", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34089 }, ["description"] = "The orcs themselves are not the only threat. They still have siege weapons of significant power. They've already been used against Tuurem, and we must not allow for their continued operation. Sabotage siege weapons using the explosives you collected from the logging camp.", ["objectivesText"] = "Destroy 6 Iron Horde Siege Engines.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75804, ["x"] = 0.586, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75804, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 8, ["flags"] = 0 } } },
[34096] = { ["id"] = 34096, ["name"] = "An Eye for a Spy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34094, 34097, 34098, 34099, 34947, 34963 }, ["description"] = "I'll get the prototype shredder working right now! Take a look through my Observicopter. You'll see what you're about to head into...", ["objectivesText"] = "Look through Thaelin's Observicopter. Progress: Take a look!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 63793, 63794, 63796, 63797, 246427 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 9, ["flags"] = 0 } } },
[34097] = { ["id"] = 34097, ["name"] = "Born to Shred", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34094, 34096, 34098, 34099, 34947, 34963 }, ["description"] = "I've got this prototype shredder operating on most cylinders. Boy, will they be surprised when you stomp them with their own machine! Can't wait to watch you from the safety of the Observicopter.", ["objectivesText"] = "Kill 100 Iron Horde in Tuurem using the Iron Shredder.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 }, { ["mapID"] = 535, ["npcID"] = 75968, ["x"] = 0.606, ["y"] = 0.387368 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 10, ["flags"] = 0 } } },
[34098] = { ["id"] = 34098, ["name"] = "Engineering Her Demise", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34094, 34096, 34097, 34099, 34947, 34963 }, ["description"] = "-- THE MOTHER HAS BEEN DETECTED. WARNING! WARNING! --", ["objectivesText"] = "Defeat Ketya Shrediron .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 113050, 113051, 113052, 113053, 113054, 113055, 113056, 113057 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 }, { ["mapID"] = 535, ["npcID"] = 75968, ["x"] = 0.606, ["y"] = 0.387368 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 11, ["flags"] = 0 } } },
[34099] = { ["id"] = 34099, ["name"] = "The Battle for Shattrath", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34094, 34096, 34097, 34098, 34947, 34963 }, ["description"] = "To stop the Iron Horde, we must overcome prejudice and work together, if only for this purpose. Horde, Alliance, past, present... all meaningless in the face of this enemy. We will retake Shattrath together... or die trying.", ["objectivesText"] = "Repel the Iron Horde from Shattrath.", ["rewardGold"] = 1239200, ["rewardXP"] = 5530, ["rewardItems"] = { 112516, 112517, 112518, 112519, 245425, 251330, 251477, 251548, 251549, 251640, 251653, 251654 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75805, ["x"] = 0.542, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79608, ["x"] = 0.696, ["y"] = 0.21 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 13, ["flags"] = 0 } } },
[34122] = { ["id"] = 34122, ["name"] = "Ogre Diplomacy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34122 }, ["description"] = "They may be spirits, but the Ango'rosh are still ogres. Even with their books in hand, they won't respect you until you prove yourself, and there's only one way to earn that. By killing them. You should take out as many of the Ango'rosh spirits and their pets as you can while in the ruins.", ["objectivesText"] = "Kill 10 Ango'rosh in the Ango'rosh Ruins. Progress: How goes your diplomatic mission?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75389, ["x"] = 0.43, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75389, ["x"] = 0.43, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34123] = { ["id"] = 34123, ["name"] = "To Thunder Pass", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33010, 34123, 34124, 37291 }, ["series"] = { 33010, 33543, 33544, 34124, 34867, 35557, 49546 }, ["description"] = "There is no time to mourn our fallen or lick our wounds. Your scouts have already reported sighting a massive Iron Horde army making its way through Thunder Pass. I advise you let your garrison forces secure this area while you and I make for the pass east of here with the rest of the Frostwolves. It is time to show this Iron Horde what a united Frostwolf clan can do.", ["objectivesText"] = "Speak with Lokra at Wolf's Stand.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 106137, 106146, 106169, 107397 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 76487, ["x"] = 0.749, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 22, ["name"] = "The Battle of Thunder Pass", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34124] = { ["id"] = 34124, ["name"] = "The Battle of Thunder Pass", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33010, 34123, 34124, 37291 }, ["series"] = { 33010, 33543, 33544, 34123, 34867, 35557, 49546 }, ["description"] = "The Iron Horde has an army tenfold our number marching down the Thunder Pass as we speak. Durotan is amassing our forces at the mouth of the pass. He is doing what he can to mount a defense but war on this scale is not what we Frostwolves are masters of. He will need your expertise. Please, go to him.", ["objectivesText"] = "Defend Frostfire Ridge from the Iron Horde.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 106137, 106146, 106169, 107397, 118474 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 76487, ["x"] = 0.749, ["y"] = 0.569 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 76484, ["x"] = 0.756, ["y"] = 0.554 }, { ["mapID"] = 525, ["npcID"] = 77485, ["x"] = 0.75, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 22, ["name"] = "The Battle of Thunder Pass", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34144] = { ["id"] = 34144, ["name"] = "Retribution for the Light", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["description"] = "There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale. You have the power needed to destroy Teron'gor's demonic minions once and for all. Send them to the Twisting Nether in pieces!", ["objectivesText"] = "Kill 15 demons in Gul'rok.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75389, ["x"] = 0.43, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75389, ["x"] = 0.43, ["y"] = 0.762 }, { ["mapID"] = 535, ["npcID"] = 77580, ["x"] = 0.456, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 19, ["flags"] = 0 } } },
[34154] = { ["id"] = 34154, ["name"] = "Destination: Unknown", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 34157 }, ["description"] = "Teron'gor and Gul'dan were just leaving through the portal as I arrived... and I... I know I won't be able to defeat them. I'll hold open the portal as long as I can. It will be up to you to strike the killing blow. Our fate is in your hands, <name>.", ["objectivesText"] = "Destroy Mongrethod in the Remains of Xandros.", ["rewardGold"] = 339600, ["rewardXP"] = 3455, ["rewardItems"] = { 113014, 113015, 113016, 119061, 119069 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 77582, ["x"] = 0.312, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79434, ["x"] = 0.462, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 22, ["flags"] = 0 } } },
[34157] = { ["id"] = 34157, ["name"] = "Into the Heart of Madness", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 34154 }, ["description"] = "<name>, Nyami ran off to 'take down Teron'gor herself.' You need to find her. She has no chance against him on her own. I must remain here and organize our ranks should another attack fall upon us. I'm counting on you.", ["objectivesText"] = "Speak to Soulbinder Nyami at the Seat of Depravity in Gul'rok.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75392, ["x"] = 0.43, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77582, ["x"] = 0.312, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 18, ["flags"] = 0 } } },
[34163] = { ["id"] = 34163, ["name"] = "Hiding in the Shadows", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "<The voice of Teron'gor enters your mind.> Our final move must remain concealed from the Auchenai, my minions. Use the shadow orbs Gul'dan provided for us to veil Gul'rok in darkness. Prepare our forces, we march on Auchindoun on my order. We will feast on the souls of the draenei and usher our demonic allies into this world! <Destroying these shadow orbs would help the defenders at Auchindoun greatly.>", ["objectivesText"] = "Destroy the three Shadow Orbs in Gul'rok.", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 20, ["flags"] = 0 } } },
[34164] = { ["id"] = 34164, ["name"] = "Book Burning", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "Please, <name>... I don't have much time. The Shadow Council have allowed themselves to be turned into demons by Teron'gor and his warlocks! I have reason to believe that the shadowborne dementors are using spells given to them by Gul'dan to empower the demonic orcs. Take their spellbooks and cast them into the fire by me... it will be a pleasant sight to die to.", ["objectivesText"] = "Obtain 3 Shadow Council Spellbooks and burn them in the fire by Kor'thos Dawnfury in Gul'rok. Progress: Yes?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 109259 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 77629, ["x"] = 0.34, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77629, ["x"] = 0.34, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 21, ["flags"] = 0 } } },
[34234] = { ["id"] = 34234, ["name"] = "Payback", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "We thought we were safe behind Leafshadow's cloaking veil. < Vindicator Kaluud wipes the blood from his face.> Someone told the Shadow Council's forces how to disable it. We were able to hold them off at first... Most of the town was slaughtered in the attack. Please, you must avenge our fallen. Rout these invaders out from Telmor forever!", ["objectivesText"] = "Rout 12 Shadow Council forces in Telmor.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 63574, 63575, 63576, 63577, 63578, 63579, 63580, 63581, 108886, 108896, 108897, 109162, 109163, 109197, 109622, 155374, 155375, 155378, 198048, 198059, 200453, 204075, 204673, 204732, 204737, 204738, 204739, 204740, 204741, 204742, 204743, 204744, 204750, 204752, 204753, 204758, 204759, 204760, 204761, 204763, 204764, 204766, 204767, 204769, 204771, 204772, 204773, 204774, 204775, 204776, 204777, 204778, 204780, 204781, 204783, 204784, 204785, 204787, 204788, 204896, 204897 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78082, ["x"] = 0.504, ["y"] = 0.874 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78082, ["x"] = 0.504, ["y"] = 0.874 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.874 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 11, ["flags"] = 