[34240] = { ["id"] = 34240, ["name"] = "Scheduled Pickup", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 33958, 33976, 34092, 34242, 34326, 34508 }, ["description"] = "You've proven yourself more than capable in battle, <name>. As you know, there may be Shadow Council forces anywhere around Auchindoun, including near Telmor. Tuulani's powers as a soulpriest have not yet fully manifested; she isn't capable of protecting the shard alone. I need you to join her at Telmor to make sure the crystal makes it to Auchindoun safely.", ["objectivesText"] = "Speak to Soulbinder Tuulani outside Telmor.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 108886, 108896, 108897, 109162, 109163, 109197, 109622 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75250, ["x"] = 0.572, ["y"] = 0.77 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77869, ["x"] = 0.504, ["y"] = 0.875 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 10, ["flags"] = 0 } } },
[34242] = { ["id"] = 34242, ["name"] = "Scheduled Pickup", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["series"] = { 33958, 33976, 34092, 34240, 34326, 34508 }, ["description"] = "You've proven yourself more than capable in battle, <name>. There may be Shadow Council forces all around Auchindoun, including near Telmor. I want you to join Soulbinder Tuulani at Telmor to make sure the crystal makes it safely to Auchindoun. I know I can trust you to get it done.", ["objectivesText"] = "Speak to Soulbinder Tuulani outside Telmor.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75246, ["x"] = 0.61, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77869, ["x"] = 0.504, ["y"] = 0.875 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 10, ["flags"] = 0 } } },
[34271] = { ["id"] = 34271, ["name"] = "The Fate of Gordawg", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34271, 34891, 34894, 34932, 34941, 34943, 34964, 34965, 35144, 35145, 35232, 35265, 35317 }, ["description"] = "Looming monstrously between us and the inner chamber is the great fury we have sought to return to the Throne of Elements. Gordawg stands before us enthralled; a slave to the pale and their mysterious master. My heart is heavy with grief to see such a great creature mindless and enslaved by evil. There is no going back, in order to push forward you must go through Gordawg. It pains me, but Gordawg must be slain. When the deed is done, we will return the fury's heart to the Throne of Elements.", ["objectivesText"] = "Retrieve the Heart of the Fury . Progress: What of Gordawg? Has the great fury been brought to rest?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 113077 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80595, ["x"] = 0.726, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 11, ["flags"] = 0 } } },
[34326] = { ["id"] = 34326, ["name"] = "Changing the Tide", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 33958, 33976, 34092, 34240, 34242, 34508 }, ["description"] = "It is time to retaliate against this foe. Meet me at Retribution Point and we will take this fight to the Shadow Council. Teron'gor shall not feast on another soul so long as we stand in his way! His reign of terror ends today.", ["objectivesText"] = "Speak to Restalaan at Retribution Point.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 108886, 108896, 108897, 109162, 109163, 109197, 109622 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 77082, ["x"] = 0.448, ["y"] = 0.905 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77799, ["x"] = 0.434, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.905 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 16, ["flags"] = 0 } } },
[34351] = { ["id"] = 34351, ["name"] = "We Must Construct Additional Pylons", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 34458, 35249 }, ["description"] = "We came here to retrieve a reserve pylon to power Auchindoun's defenses, but we've been pinned to this position by the Shadow Council for hours! I need to get these injured back to Exarch's Refuge, but we still need the backup system! Please, gather Arkonite crystals and an Arkonite pylon from the tomb and meet me at the refuge as quickly as you can!", ["objectivesText"] = "Collect 6 Arkonite Crystals and an Arkonite Pylon from the Tomb of Lights. Progress: Do you have the arkonite pylon and the crystals?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 110253, 110271 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 78520, ["x"] = 0.552, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34364] = { ["id"] = 34364, ["name"] = "For the Horde!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34375, 34377, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "Without you, none of us would have made it to the shores of my homeland. You will be the one to lead our forces here on Draenor. This is your garrison to found. I leave it to you to plant the banner and claim this territory. When you are ready, I will have Khadgar open a portal to bring through a few necessary reinforcements.", ["objectivesText"] = "Plant the Horde Banner to Claim the Land.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 23002, 23007, 23015, 23022, 29928, 29930, 29931, 29934, 29938, 29941, 29943, 29945, 37956, 37964, 37998, 38006, 38041, 38048, 38081, 38102, 38110, 57509, 57510, 57511, 57512, 65680, 65701, 65719, 65728, 66073, 94220, 111535, 111536, 111537, 111538, 111539, 111540, 111541, 111542, 111907, 116202, 118761, 118762, 118763, 118764, 118765, 131486, 131696, 131697, 151557, 155662, 157028, 157757, 157759, 161328, 165001, 165871, 166883, 167169, 168615, 168850, 169765, 174069, 174508, 211279, 223907, 237812, 241215 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70859, ["x"] = 0.388, ["y"] = 0.560667 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.560667 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34375] = { ["id"] = 34375, ["name"] = "Back to Work", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34377, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "Alright, boss. We're gonna need some lumber if we're gonna get this garrison started off right. If you mark some trees to be cut down, your peons will do the rest.", ["objectivesText"] = "Mark 6 Trees. Progress: There aren't a lot of trees around. Go mark 'em!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 111907 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34378] = { ["id"] = 34378, ["name"] = "Establish Your Garrison", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "It's time for the main event! We've got the materials, we've got the manpower, we've got another thing that starts with \"m.\" Let's build this thing! I got a gaggle of assistants up on that ridge to the west. They should have your personal surveying stand set up by now. Head on over there and you should be able to watch our progress from it.", ["objectivesText"] = "Watch the construction of your garrison by using the Master Surveyor Progress: I'm almost as excited about building this as you are. I want to see if it falls apart!", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 111907 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34379] = { ["id"] = 34379, ["name"] = "Den of Wolves", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 34379, 34380 }, ["series"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33657, 33784, 33816, 34380 }, ["description"] = "Durotan wishes for us to join him now that you have established your foothold. I hope he will accept your help.", ["objectivesText"] = "Ride the Frostwolf Rylak to Wor'gol.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 107279, 107361 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 76411, ["x"] = 0.447, ["y"] = 0.661 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.447, ["y"] = 0.661 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 18, ["name"] = "Siege of Bladespire Citadel", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34380] = { ["id"] = 34380, ["name"] = "Rally the Frostwolves", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33784, 34379, 34380 }, ["series"] = { 33344, 33408, 33410, 33526, 33527, 33546, 33622, 33657, 33784, 33816, 34379 }, ["description"] = "My brother, in his haste, has already taken some of my clan with him and has begun an assault on Bladespire Citadel before we were ready. Draka awaits by our war horn. Please let her know that it is time to rally the clan! With the aid of you and your forces, we might actually stand a chance at victory against the ogres.", ["objectivesText"] = "Ask Draka to sound the war horn. Progress: Draka will know what to do.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 107279, 107361 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 70860, ["x"] = 0.225333, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 76557, ["x"] = 0.218667, ["y"] = 0.519333 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.225333, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 18, ["name"] = "Siege of Bladespire Citadel", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34392] = { ["id"] = 34392, ["name"] = "Onslaught's End", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34392, 34393, 34398, 34420, 35933, 36881 }, ["series"] = { 34393, 34398, 34420, 35933, 36881 }, ["description"] = "\"Guard Gul'dan and his Shadow Council with your lives! The portal cannot function without our prisoners' fel magic. Fail me and watch all that you hold dear turn to ash. -Grommash Hellscream.\" The Iron Horde appear to be holding prisoners that are crucial to keeping the portal open. Search the nearby spires!", ["objectivesText"] = "Disable the two fel spires of the Dark Portal. Progress: See the drifting energy from the tips of those spires? They clearly have some effect upon the portal. With any hope, the portal falls along with them.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 60, ["name"] = "The Dark Portal", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34393] = { ["id"] = 34393, ["name"] = "The Portal's Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34392, 34393, 34398, 34420, 35933, 36881 }, ["series"] = { 34392, 34398, 34420, 35933, 36881 }, ["description"] = "This portal is fueled by powers neither mechanical nor arcane. Look to either side of us, <name>. The screaming souls of slain prisoners are being channeled into the heart of the portal itself. And they are channeling these souls through the body of Gul'dan . Find a way into the chamber beneath us, and do whatever it takes to get Gul'dan to stop his channeling. Our last hope rests on you, <name>.", ["objectivesText"] = "Enter the Soul Engine beneath the Dark Portal, then shut the Dark Portal down. Progress: Go now, hero! Lives hang in the balance!", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 112387, 112388, 112389, 112391, 112392, 112393, 112395, 113579, 120304, 143742, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 60, ["name"] = "The Dark Portal", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34398] = { ["id"] = 34398, ["name"] = "Warlords of Draenor: The Dark Portal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 1519, ["mapID"] = 577, ["storyline"] = { 34392, 34393, 34398, 34420, 35933, 36881 }, ["series"] = { 34392, 34393, 34420, 35933, 36881 }, ["description"] = "ATTENTION HEROES ADVENTURERS DEFENDERS OF AZEROTH Archmage Khadgar , hero of the Second War, is assembling a coalition of Azeroth's strongest to bravely step through the Dark Portal and stop the Iron Horde's invasion of Azeroth. Champions who are interested in glory can meet Khadgar at the base of the Dark Portal in Blasted Lands. Safety not guaranteed.", ["objectivesText"] = "Speak with Archmage Khadgar at the foot of the Dark Portal in Blasted Lands.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 60, ["name"] = "The Dark Portal", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34402] = { ["id"] = 34402, ["name"] = "Of Wolves and Warriors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34378, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "The return of many of my people is a boon to us, and I thank you for your part in their survival. Come, ride with me. We have much to discuss.", ["objectivesText"] = "Ride with Durotan .", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 111907 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78272, ["x"] = 0.453, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 70859, ["x"] = 0.388, ["y"] = 0.560667 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.453, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34407] = { ["id"] = 34407, ["name"] = "Holding the Line", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "It is good to see you again, champion. Demons are assaulting Auchindoun and we are barely standing our ground against them. We need to push our front lines forward lest our losses reach critical mass. If your blade is with us, shove it into these foul creatures' throats.", ["objectivesText"] = "Slay 15 demons in the Burning Front.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 108733, 142450, 237812 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75119, ["x"] = 0.556, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75119, ["x"] = 0.556, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34418] = { ["id"] = 34418, ["name"] = "Holding the Line", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["series"] = { 34696 }, ["description"] = "Auchindoun is under attack! The Auchenai are valiant warriors in their own right, but they cannot hold against these endless demon hordes alone. We came here to stop the Legion from engulfing Draenor... working together is our best shot. I need you to thin out the demons' numbers so we can regroup our forces safely and push forward into the Burning Front. We will stop their march here and now!", ["objectivesText"] = "Slay 15 demons in the Burning Front.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 142450, 237812 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75121, ["x"] = 0.555, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75121, ["x"] = 0.555, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34420] = { ["id"] = 34420, ["name"] = "The Cost of War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34392, 34393, 34398, 34420, 35933, 36881 }, ["series"] = { 34392, 34393, 34398, 35933, 36881 }, ["description"] = "They called this operation a suicide mission, but I don't plan on throwing away any lives meaninglessly. Everybody, with me!", ["objectivesText"] = "Follow Archmage Khadgar .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 110799, 113579, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 60, ["name"] = "The Dark Portal", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34421] = { ["id"] = 34421, ["name"] = "Bled Dry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34421, 34422, 34423, 35241 }, ["description"] = "<The orc spits out his last words.> They kept us in cages. They... drain our blood, for... rituals... <The Frostwolf coughs violently.> ...many left -- -- my... people... <The orc dies.>", ["objectivesText"] = "Free the slaves from the 2 Bleeding Hollow Cages in Heartblood.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 61, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34422] = { ["id"] = 34422, ["name"] = "Blaze of Glory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34421, 34422, 34423, 35240, 35241, 35242 }, ["description"] = "We can't stay here forever. We NEED to keep moving. But first - we need a distraction. <Khadgar conjures a small gem.> This bead should burn anything flammable that you get close to. With your skill, and a bit of luck, you might be able to take the attention of the Bleeding Hollow orcs off our group.", ["objectivesText"] = "Use the Lucifrium Bead to destroy 8 Bleeding Hollow huts. Progress: We cannot hold out here forever, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 112431, 112432, 112433, 112434, 113191, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 61, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34423] = { ["id"] = 34423, ["name"] = "Altar Altercation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34421, 34422, 34423, 35240, 35241, 35242 }, ["series"] = { 34425 }, ["description"] = "You see that altar down there? There's a magical eye settled at its peak, and I fear our group will not survive if it sees us. Distract the eye, <name>. Cause a commotion, kill some ritualists, whatever you have to do - just occupy that thing long enough for me to guide the rest of our group past its gaze. <Khadgar looks over his shoulder.> Bring that strapping orc with you. The one that's not Thrall.", ["objectivesText"] = "Speak with Ariok , then help him distract the Eye of Kilrogg.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 61, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34425] = { ["id"] = 34425, ["name"] = "The Kargathar Proving Grounds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34425, 34427, 34429, 34478 }, ["series"] = { 34423 }, ["description"] = "The orcs in this area look like members of the Shattered Hand clan. You can tell by looking at their hands. Let's join up with the others. We must find a way out of here.", ["objectivesText"] = "Follow Khadgar. Progress: Yes?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 62, ["name"] = "The Shattered Hand", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34427] = { ["id"] = 34427, ["name"] = "A Potential Ally", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34425, 34427, 34429 }, ["description"] = "One of the captured orcs is receiving some... preferential treatment, if you can call it that. While others are tied down and tortured, this one is tied to a stake and burned for the amusement of his captors. Use this runestone. It should handily deal with the ring of fire that surrounds him.", ["objectivesText"] = "Use the Frostflurry Focus near the ring of fire in Kargathar Proving Grounds to free Farseer Drek'Thar .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 112440, 112441, 112442, 112443 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 62, ["name"] = "The Shattered Hand", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34429] = { ["id"] = 34429, ["name"] = "Kill Your Hundred", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34425, 34427, 34429, 34478 }, ["description"] = "I see only one way out of this trap, <name>, and it's right through the middle of that arena. This might be the end of us.", ["objectivesText"] = "Survive Kargath's Arena.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 86594, 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 62, ["name"] = "The Shattered Hand", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34431] = { ["id"] = 34431, ["name"] = "Masters of Shadow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34431, 34432, 34434, 34436 }, ["description"] = "The bad orcs tried to catch me, but I snuck away. I'm good at hiding. All of the bad orcs are bad, but I've remembered the names of the meanest ones, just in case anybody came to save me. < Luuka takes a deep breath.> Ungra , Gurran, and... umm... oh! Ankova. Will you protect me from them?", ["objectivesText"] = "Slay Ungra , Taskmaster Gurran , and Ankova the Fallen . Progress: How goes your mission?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34432] = { ["id"] = 34432, ["name"] = "The Shadowmoon Clan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 17, ["storyline"] = { 34431, 34432, 34434, 34436 }, ["description"] = "We will protect the wounded prisoners and make sure Kargath doesn't get through the rubble. You go ahead and clear the cave, <name>.", ["objectivesText"] = "Slay 10 Shadowmoon Orcs or Void Wolves within the Umbral Halls.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 112663, 112664, 112665, 112666 }, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 78554, ["x"] = 0.549, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34434] = { ["id"] = 34434, ["name"] = "Yrel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34431, 34432, 34434, 34436 }, ["description"] = "Forgive me if I'm a bit flustered - I've never killed anyone before. My name is Yrel , and I am a student of Karabor. You say you have an ARMY with you? The Light must truly be watching over me today. I will follow you, then. Lead the way, <name>.", ["objectivesText"] = "Escort Yrel to safety.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34436] = { ["id"] = 34436, ["name"] = "Keli'dan the Breaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34431, 34432, 34434, 34436 }, ["description"] = "One of Ner'zhul's lieutenants remains, up ahead. The exit to the cave isn't much farther past him. I will go back and tell Khadgar that the cave is clear. We will rendezvous once you've taken care of Keli'dan!", ["objectivesText"] = "Slay Keli'dan the Breaker .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34437] = { ["id"] = 34437, ["name"] = "The Prodigal Frostwolf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34437, 34439, 34442, 34925, 34958, 34987, 35005, 35019 }, ["series"] = { 34442, 34925 }, ["description"] = "I can get back to Drek'Thar myself... after I run this stinking shovel through a few Blackrock stomachs.", ["objectivesText"] = "Report to Farseer Drek'Thar at the Blackrock Quarry in Tanaan Jungle.", ["rewardGold"] = 29325, ["rewardXP"] = 710, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 64, ["name"] = "The Blackrock", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34439] = { ["id"] = 34439, ["name"] = "The Battle of the Forge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34437, 34439, 34442, 34925, 34958, 34987, 35005, 35019 }, ["description"] = "Our troops are armed - the time to strike is now! Strike swift and true, <name>!", ["objectivesText"] = "Slay 15 Blackrock Orcs and 3 Ogron Warcrushers . Progress: This dam thing is tougher than it looks.", ["rewardGold"] = 509400, ["rewardXP"] = 2125, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 64, ["name"] = "The Blackrock", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34442] = { ["id"] = 34442, ["name"] = "Ga'nar of the Frostwolf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34437, 34439, 34442, 34925, 34958, 34987, 35005, 35019 }, ["series"] = { 34437, 34925 }, ["description"] = "We must move on, there isn't time to waste! One of the elders of my clan, Ga'nar , is out there somewhere. I can sense him, but I cannot find him. Keep an eye out for Ga'nar . He is a strong-willed orc, and will languish in captivity.", ["objectivesText"] = "Find Ga'nar .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 64, ["name"] = "The Blackrock", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34445] = { ["id"] = 34445, ["name"] = "A Taste of Iron", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34445, 34446, 35747, 35884 }, ["series"] = { 35747 }, ["description"] = "The way I see it, there's two ways to keep this tank from going through the portal: break the tank, or USE the dang tank ta' BLOW UP the dang portal. I can get 'er workin', I just need time. Hop in that turret off the starboard bow and keep 'em off my back.", ["objectivesText"] = "Enter the Worldbreaker Side Turret and destroy 200 Iron Horde troops. Progress: Almost there, <name>.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 65, ["name"] = "Escape From Tanaan", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34446] = { ["id"] = 34446, ["name"] = "The Home Stretch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34445, 34446, 35747 }, ["description"] = "If they weren't angry before, they sure are now. We won't survive a minute up on top o' this tank! Let's join up with the rest and get out of here!!", ["objectivesText"] = "Get to the docks.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 65, ["name"] = "Escape From Tanaan", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34451] = { ["id"] = 34451, ["name"] = "Sunsworn Camp", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["description"] = "We no longer have a need to work alongside the Auchenai, champion. I have arranged for their lead soulbinders to continue to advise us, but I believe any action is best left to us at this point. Meet me at Sunsworn Camp, southeast of here. I can sense more demonic taint in the area, and we may be able to track down the remaining power crystal shards at its source.", ["objectivesText"] = "Meet Lady Liadrin at Sunsworn Camp in Talador .", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75121, ["x"] = 0.555, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75246, ["x"] = 0.61, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34452] = { ["id"] = 34452, ["name"] = "Light's Rest", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "With the brute force of our enemy neutralized, we must turn our sights on quelling the aftermath and preparing for any future assaults. We still need Auchindoun's defenses reinvigorated. Meet me at Light's Rest, not far south of here. We have reports coming in of demonic taint in the area, and we may be able to track down the remaining power crystal shards at its source.", ["objectivesText"] = "Meet Exarch Maladaar at Light's Rest in Talador .", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 109744, 110683 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75119, ["x"] = 0.556, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75250, ["x"] = 0.572, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34458] = { ["id"] = 34458, ["name"] = "Powering the Defenses", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 34351, 35249 }, ["description"] = "What few soulpriests we don't have on the front lines are working fervently to maintain Auchindoun's defenses. They aren't going to be able to keep it up much longer alone. Soulbinder Tuulani went inside the nearby Tomb of Lights to retrieve a backup power pylon and hasn't returned. I need you to find her and get her and the pylon back here safely.", ["objectivesText"] = "Find Soulbinder Tuulani in the Tomb of Lights.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 110253, 110271 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 81789, ["x"] = 0.556, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34462] = { ["id"] = 34462, ["name"] = "Winds of Change", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 590, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34378, 34402, 34461, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "Commander, I have bad news. Olin Umberhide , the tauren who escaped with you from Tanaan, was ambushed when near the eastern perimeter of the Garrison. He was seen being dragged off by the pale. These are dangerous, disturbing creatures that some believe were once orcs. Now they are husks of barely living flesh bent by dark magics. Olin is resourceful, but outnumbered. I would advise travelling east to effect a rescue as soon as possible, before they eat him alive... slowly.", ["objectivesText"] = "Rescue Olin Umberhide . Progress: Have you found Olin? Was he alive or dead?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 111907 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 12, ["flags"] = 0 } } },
[34478] = { ["id"] = 34478, ["name"] = "A Potential Ally", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34425, 34429, 34478 }, ["description"] = "One of the captured draenei is receiving some... preferential treatment, if you can call it that. While others are tied down and tortured, this one is tied to a stake and burned for the orcs' amusement. Use this runestone. It should handily deal with the ring of fire that surrounds this draenei.", ["objectivesText"] = "Use the Frostflurry Focus near the ring of fire in Kargathar Proving Grounds to free Exarch Maladaar .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 112440, 112441, 112442, 112443, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 62, ["name"] = "The Shattered Hand", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34508] = { ["id"] = 34508, ["name"] = "Restalaan, Captain of the Guard", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["series"] = { 33958, 33976, 34092, 34240, 34242, 34326 }, ["description"] = "They killed Aedraa and took the crystal from her! The captain of the guard, Restalaan , tried to stop them and they took him into the cathedral! If we can just get this crystal, we can reunite the Heart of Auchindoun and turn its defenses on fully! We can't afford to fail now. <name>, you're the only one left that can do it. You have to find Restalaan ! He'll know where they took it.", ["objectivesText"] = "Find Restalaan in Telmor.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 108886, 108896, 108897, 109162, 109163, 109197, 109622 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 77869, ["x"] = 0.504, ["y"] = 0.875 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77082, ["x"] = 0.448, ["y"] = 0.905 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.875 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 14, ["flags"] = 0 } } },
[34558] = { ["id"] = 34558, ["name"] = "At Your Command", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34558 }, ["series"] = { 34676, 35702, 36495, 36576, 37183, 49565, 92692 }, ["description"] = "I'm glad you're here! Fort Wrynn is nearly complete. We only need to fill this last plot. Baros provided us with blueprints for two different structures that would fit this space - an Artillery Tower or an Arcane Sanctum. It's your call, commander. The plans are on the drafting table for your perusal.", ["objectivesText"] = "Choose which outpost structure to construct. Progress: At your command.", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79133, ["x"] = 0.698, ["y"] = 0.208 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79133, ["x"] = 0.698, ["y"] = 0.208 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.208 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34563] = { ["id"] = 34563, ["name"] = "The Quarry Quandary", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34571, 34573, 34578, 34624, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["description"] = "Now that we have the artillery tower built, we're going to need some skilled hands to run it. I've heard that Ared, one of the best smiths in Shattrath, managed to escape the city's fall. He should be just outside the north wall with the rest of the refugees. See if you can convince him to work for us.", ["objectivesText"] = "Speak to Apprentice Miall just outside of Fort Wrynn in Talador . Progress: We need to find someone to run this place or we're not going to be producing much of anything.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 6948, 110898, 111910 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79133, ["x"] = 0.698, ["y"] = 0.208 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79159, ["x"] = 0.692, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.208 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34564] = { ["id"] = 34564, ["name"] = "Destination: Unknown", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["description"] = "Teron'gor and Gul'dan were just leaving through the portal as I arrived... and I... I know I won't be able to defeat them. I'll hold open the portal as long as I can. It will be up to you to strike the killing blow. Our fate is in your hands, <name>.", ["objectivesText"] = "Destroy Mongrethod in the Remains of Xandros.", ["rewardGold"] = 14300, ["rewardXP"] = 3455, ["rewardItems"] = { 113014, 113015, 113016, 119061, 119069 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 77582, ["x"] = 0.312, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79434, ["x"] = 0.462, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 22, ["flags"] = 0 } } },
[34566] = { ["id"] = 34566, ["name"] = "At Your Command", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34566 }, ["series"] = { 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "Commander, the outpost is nearly fully operational. Gazlowe provided us with two different blueprints to fill this final plot - an Arsenal or an Arcane Sanctum. Either one would provide us with the additional firepower we need to stop the Iron Horde's advance. The plans are on the drafting table . It's your call.", ["objectivesText"] = "Inspect the Drafting Table and choose which outpost structure to construct. Progress: What is your will, commander?", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79176, ["x"] = 0.71, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79176, ["x"] = 0.71, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34569] = { ["id"] = 34569, ["name"] = "The Quarry Quandary", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34576, 34577, 35102 }, ["description"] = "Now that our arsenal is built we need a skilled smith to operate it. We recently caught an Iron Horde deserter who claims he used to be one of the Blackrock's best iron workers. Normally I'd ignore the ravings of a captive, but the weapons we took out of his pack had the finest workmanship I've ever seen. Commander, I think we should see if he's as good as he claims.", ["objectivesText"] = "Obtain Morketh Bladehowl 's assistance.", ["rewardGold"] = 70225, ["rewardXP"] = 1385, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79176, ["x"] = 0.71, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79210, ["x"] = 0.718, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34571] = { ["id"] = 34571, ["name"] = "Out of Jovite", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34563, 34573, 34578, 34624, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["description"] = "Ared and I came this way because we needed a good supply of metal to build his designs and some of the best metal is the jovite that comes from the mine in Kuuro's Claim. In order to supply the artillery tower I'm going to need this metal. Unfortunately that place was recently overwhelmed by a pack of goren, so you're going to have to fight your way in to get the ore before they manage to devour it. Nothing that should be too much of a problem for you.", ["objectivesText"] = "Obtain 12 chunks of Jovite Ore from within Kuuro's Claim. Progress: We need to get that ore before those goren eat it all.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 6948, 110898, 111906, 111910 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79329, ["x"] = 0.7, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79329, ["x"] = 0.7, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34572] = { ["id"] = 34572, ["name"] = "Obliterating Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34572 }, ["description"] = "With actual ogre mages present, the Highmaul have been increasing patrols and aggression. Thinning their ranks will go a long way to deterring the Highmaul from making a comeback in Nagrand . Head up to my sister Mirana afterwards, she should have more news.", ["objectivesText"] = "Kill 15 ogres at Mar'gok's Overwatch.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 114683, 114684, 114685, 114686 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79282, ["x"] = 0.788, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81144, ["x"] = 0.84, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.788, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34573] = { ["id"] = 34573, ["name"] = "Iridium Recovery", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34563, 34571, 34578, 34624, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["description"] = "Ared used to always teach me that the purity of the metal is key. If the metal isn't pure it will crack under stress and be of no use to anyone. For the artillery tower to function I'll need to make metal as pure as my master would, and for that I need a strong flux. The dust from crushed iridium geodes would work in a pinch, but we need to find some first. They tend to congregate underground, so check out the mine in Kuuro's Claim nearby.", ["objectivesText"] = "Gather 8 Iridium Dust from Iridium Geodes in Kuuro's Claim. Progress: I'm going to need a lot of iridium dust to purify the metal to anywhere near my masters standards.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 6948, 110898, 111910 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79329, ["x"] = 0.7, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79329, ["x"] = 0.7, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34575] = { ["id"] = 34575, ["name"] = "Step Three: Prophet!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34575 }, ["series"] = { 34582, 34583, 49562 }, ["description"] = "You have arrived in Shadowmoon Valley . It is time to speak with the prophet.", ["objectivesText"] = "Speak with Prophet Velen near the crashed Iron Horde Ship in Shadowmoon Valley .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 79206, ["x"] = 0.27, ["y"] = 0.08 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.08 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[34576] = { ["id"] = 34576, ["name"] = "Iridium Recovery", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34569, 34577, 35102 }, ["description"] = "My goods used to be for the very best, now the Iron Horde make copies out of poor metal and give them to everyone. I'm going to show them what a real smith can do in your arsenal, but first I'm going to need a powerful flux to make the metal as pure as it can get. The dust from crushed iridium geodes would work in a pinch but we need to find some first. They tend to congregate underground, so check out the mine in Kuuro's Claim nearby.", ["objectivesText"] = "Gather 8 Iridium Dust from Iridium Geodes in Kuuro's Claim. Progress: I'm going to need a lot of iridium dust to purify the metal to anywhere near my standards.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 110898 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79356, ["x"] = 0.708, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79356, ["x"] = 0.708, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34577] = { ["id"] = 34577, ["name"] = "Out of Jovite", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34569, 34576, 35102 }, ["description"] = "Crafting good equipment requires the best metal and some of the best metal is the jovite that comes from the mine in Kuuro's Claim, just east of here. In order to supply the arsenal I'm going to need this metal. Unfortunately the place was recently overwhelmed by a pack of goren so you're going to have to fight your way in to get the ore before they manage to devour it. Nothing that should be too much of a problem for you, <sir/ma'am>.", ["objectivesText"] = "Obtain 12 chunks of Jovite Ore from within Kuuro's Claim. Progress: We need to get that ore before those damned goren eat it all.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 111906 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79356, ["x"] = 0.708, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79356, ["x"] = 0.708, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34578] = { ["id"] = 34578, ["name"] = "Going to the Gordunni", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34563, 34571, 34573, 34624, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["description"] = "We have a good supply of jovite now but there just isn't enough of the material in the mine to keep the artillery tower in stock for long. Down south of here there's a mountain that's just full of the stuff but there's one problem; Ogres! The Gordunni live on top of that mountain and they have begun trading the jovite to the Iron Horde. We need to go down there and secure the minerals for ourselves. I'll pack some supplies and meet you near their fortress down south.", ["objectivesText"] = "Travel to Gordal Fortress and meet up with Miall .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 112091, 112307, 112504 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79329, ["x"] = 0.7, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80627, ["x"] = 0.625, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34579] = { ["id"] = 34579, ["name"] = "Gas Guzzlers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34837, 34840, 34855, 34858, 34860, 34870, 34971, 34972 }, ["description"] = "<Sir/Ma'am>, to make the best equipment for your arsenal I need not only the best materials, but to use the best techniques. Over the years I've developed a method to greatly strengthen my metal, but it does require an exotic resource: goren gut gas! The nearby mine at Kuuro's Claim just came down with an infestation of the things. Could you collect a few samples for the arsenal supplies? Just kill a few goren and give their bodies a good prod with this gas extractor.", ["objectivesText"] = "Obtain 6 samples of Goren Gas from Glowgullet Shardshedders and Glowgullet Devourers within Kuuro's Claim.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 111910 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79356, ["x"] = 0.708, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79356, ["x"] = 0.708, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34582] = { ["id"] = 34582, ["name"] = "Finding a Foothold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["series"] = { 34575, 34583, 49562 }, ["description"] = "So, you are the one that has led my children home? I have been waiting for you. The Iron Horde grows stronger every day. I have foreseen a great battle, but my visions are clouded. It's as if time is sitting on top of itself. One thing is certain, your presence here is of great importance.", ["objectivesText"] = "Follow Prophet Velen .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 79206, ["x"] = 0.27, ["y"] = 0.08 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 79470, ["x"] = 0.288, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.08 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34583] = { ["id"] = 34583, ["name"] = "For the Alliance!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["series"] = { 34575, 34582, 49562 }, ["description"] = "We wouldn't have survived Tanaan without your strength, <name>. Many draenei and Alliance alike owe you a great debt. Before we departed for the Dark Portal, King Wrynn personally recommended that I place you in charge of our operations here in Draenor. After seeing you in action, I'm inclined to agree. This is your garrison to found. Plant the banner and we'll begin construction immediately, commander.", ["objectivesText"] = "Plant the Alliance banner.", ["rewardGold"] = 127350, ["rewardXP"] = 1060, ["rewardItems"] = { 23002, 23007, 23015, 23022, 37500, 42792, 42805, 42817, 42830, 65618, 65625, 65639, 65642, 66073, 94219, 108908, 108909, 108910, 108912, 108913, 108914, 108918, 108919, 116202, 151557, 157022, 157756, 157758, 161329, 165010, 165872, 166883, 168615, 168850, 169764, 174068, 174507, 204616, 204617, 204618, 204619, 211279, 223907, 237812, 241215 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 79470, ["x"] = 0.288, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 79243, ["x"] = 0.29, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34584] = { ["id"] = 34584, ["name"] = "Looking for Lumber", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["description"] = "Some of the trees around here look small enough that the workers should be able to down them in no time. We can leave the hard labor to Shelly's men, but if you'd be willing to mark the trees for them to start with, we should be able to get this operation rolling much faster.", ["objectivesText"] = "Mark 8 trees. Progress: How goes the lumber hunt?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 79243, ["x"] = 0.29, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 79243, ["x"] = 0.29, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34585] = { ["id"] = 34585, ["name"] = "Quakefist", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["description"] = "I'm getting reports of a giant in the forest. A few of the Karabor peacekeepers have followed it to a cave. In all honesty I don't think any of our troops are willing to engage the beast. Maybe you could investigate? I'm sure the peacekeepers would appreciate the help.", ["objectivesText"] = "Kill Quakefist . Progress: Did you kill the giant in the cave?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 79567, ["x"] = 0.288, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 79567, ["x"] = 0.288, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34586] = { ["id"] = 34586, ["name"] = "Establish Your Garrison", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["series"] = { 34616 }, ["description"] = "I'm impressed with how quickly you have pulled this group together, commander. I think it's time we start putting up some walls and establishing a firm perimeter around our base.", ["objectivesText"] = "Build your garrison.", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 110560, 112696, 248799 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 79243, ["x"] = 0.29, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34587] = { ["id"] = 34587, ["name"] = "Build Your Barracks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 582, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["description"] = "I must say, commander, this garrison has really come along. We have enough materials, all we need now are the blueprints I drafted up and I can begin construction on your barracks. Hmm... now where did I put those blueprints?", ["objectivesText"] = "Find the blueprints, learn the blueprints, and use the Architect Table to build your barracks. Progress: The troops will sleep a lot better tonight.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 110560, 111956, 112696 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34592] = { ["id"] = 34592, ["name"] = "A Gronnling Problem", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34378, 34402, 34461, 34462, 34765, 34775, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "It's gonna be quite a task to build you a fortress if there's gronnlings rampaging around. I don't think anyone else here can handle taking those big beasts out, so you might need to take care of it yourself.", ["objectivesText"] = "Kill 8 Frostfire Gronnlings . Progress: If you can't find gronnlings, you ain't lookin' hard enough.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 111907 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34593] = { ["id"] = 34593, ["name"] = "Obtaining Ogre Offensive Orders", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34596, 34951, 34954, 34955, 34956, 34957, 35061, 35062, 35148, 35169 }, ["description"] = "My sister, Mirana, is scouting the upper bluff while I've checked out the lower area. There are two particular ogre mages that do a lot of bossing around in the lower area. They seem to have some orders or scrolls on them that would help us figure out what's really going on. Collect that information and meet with my sister on the long stairway up there.", ["objectivesText"] = "Collect Crulgorosh's Orders and Thulgork's Orders at Mar'gok's Overwatch. Progress: Those orders would be really useful in piecing this whole thing together.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 111065, 111066 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79282, ["x"] = 0.788, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81144, ["x"] = 0.84, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.788, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 10, ["flags"] = 0 } } },
[34596] = { ["id"] = 34596, ["name"] = "Reglakk's Research", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34593, 34951, 34954, 34955, 34956, 34957, 35061, 35062, 35148, 35169 }, ["description"] = "These ogres have been using ancient Titan artifacts to empower a small cadre of specialized units called the Breakers. This Magister Reglakk is here studying ways to improve the process. Let's put a stop to whatever rituals he has going up on the bluff.", ["objectivesText"] = "Stop Grand Magister Reglakk.", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["rewardItems"] = { 114911, 114912, 114913, 114914, 114915, 114916, 114917, 114918, 120430 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81144, ["x"] = 0.84, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.84, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 13, ["flags"] = 0 } } },
[34597] = { ["id"] = 34597, ["name"] = "Removing the Paper Trail", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34597 }, ["description"] = "This box is filled with writings and diagrams that oddly resemble research into the nullification of magic. It would be best to ruin these efforts by destroying any research found.", ["objectivesText"] = "Destroy 8 Boxes of Ogre Research at Mar'gok's Overwatch.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81144, ["x"] = 0.84, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.84, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34609] = { ["id"] = 34609, ["name"] = "Creating the Ink", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34612, 34619, 34875, 34908, 34913 }, ["description"] = "We need a way to create an artificial nexus at your tower. I know where we can get the conduit to do that, but it's well-guarded. We need to keep our cool and do this the right way. I have a plan - a scroll of mass teleportation. The fungal giants and shamblers down below are covered with pustules full of an oily substance. We can use the oil to craft a makeshift ink substitute for the scroll.", ["objectivesText"] = "Gather 30 Pulsating Pustules from Sporebats and Fungal Giants in Zangarra. Progress: The giants are harder to take down, but they will yield more pustules!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 111322, 116395 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79392, ["x"] = 0.848, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 14, ["flags"] = 0 } } },
[34612] = { ["id"] = 34612, ["name"] = "Forming the Scroll", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34609, 34619, 34875, 34908, 34913 }, ["description"] = "We'll need arcane parchment to make the scroll. The arcane energy everywhere at this nexus froze the ancients in place and settled in their bark. If we take pieces from the few that haven't been destroyed by the fungal creatures, I can mold them into parchment.", ["objectivesText"] = "Rip 3 Pieces of Bark off of Slumbering Ancients in Zangarra.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 116395 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79392, ["x"] = 0.848, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 15, ["flags"] = 0 } } },
[34616] = { ["id"] = 34616, ["name"] = "Ravenous Ravens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["series"] = { 34586 }, ["description"] = "Do you see that? There is a gigantic raven just past the tree line. I'm not getting anywhere near that. In fact, I'm not sure any of the men are sufficiently equipped to deal with a threat like that. Do you want to handle this one yourself, commander? Once those ravens are gone we can start sending more troops into the woods. So we will be killing two birds with one stone... or should I say kill five birds with... <Confused by his own analogy, Baros scratches his head.> You get the point.", ["objectivesText"] = "Kill 6 Lunarfall Ravens . Progress: Did you kill those ravens?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 79243, ["x"] = 0.29, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 79243, ["x"] = 0.29, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34619] = { ["id"] = 34619, ["name"] = "Gathering the Spark", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34609, 34612, 34875, 34908, 34913 }, ["description"] = "We need arcane energy to complete our scroll. It needs that to coalesce the scroll together. I have an artifact that can capture energy vortexes in the caldera below, so let's get moving.", ["objectivesText"] = "Harvest 3 Arcane Vortexes in Zangarra. Progress: This is why I love magic. It's so... refreshing.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 116395 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79392, ["x"] = 0.848, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 16, ["flags"] = 0 } } },
[34624] = { ["id"] = 34624, ["name"] = "Gas Guzzlers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34563, 34571, 34573, 34578, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["description"] = "To complete my master's designs and to stock up the artillery tower we need to use an exotic resource, namely goren gut gas. The nearby mine at Kuuro's Claim just came down with an infestation of the things. Could you collect a few samples for me? The stuff is concentrated, so only a few are needed. Just kill one and give its body a good prod with this gas extractor.", ["objectivesText"] = "Obtain 6 samples of Goren Gas from Glowgullet Shardshedders and Glowgullet Devourers within Kuuro's Claim.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 6948, 110898, 111910 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79329, ["x"] = 0.7, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79329, ["x"] = 0.7, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34631] = { ["id"] = 34631, ["name"] = "An Audience With The Archmage", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34815 }, ["description"] = "I'm pleased to report that your Arcane Sanctum is up and running, commander! Everything is exactly as the blueprint says... except for this note Baros scrawled on the bottom. \"Don't forget to connect the sanctum to the ley line network!\" Commander, I'm a foreman, not a mage. I... have absolutely no idea how to do that. We've found Archmage Khadgar and some other Kirin Tor not far from here. To the east, near the mountains. Perhaps we should ask them for a hand?", ["objectivesText"] = "Speak to Archmage Khadgar in Talador .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 116395 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79133, ["x"] = 0.698, ["y"] = 0.208 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80142, ["x"] = 0.75, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.208 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 12, ["flags"] = 0 } } },
[34632] = { ["id"] = 34632, ["name"] = "An Audience With The Archmage", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34814 }, ["description"] = "Your Arcane Sanctum is coming along nicely, commander. Everything's built to spec... except for one detail Gazlowe scrawled in at the bottom of the blueprint. \"Don't forget to connect the sanctum to the ley line network!\" I, uh... I have no idea how to do that. I'm sorry commander, but magic just isn't my thing. We did spot Archmage Khadgar and some Kirin Tor not far from here. To the east, up near the mountains. Maybe we should ask them for help?", ["objectivesText"] = "Speak to Archmage Khadgar in Talador .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79176, ["x"] = 0.71, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80142, ["x"] = 0.75, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 13, ["flags"] = 0 } } },
[34634] = { ["id"] = 34634, ["name"] = "Creating the Ink", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34635, 34636, 34874, 34878, 34879 }, ["description"] = "We're going to need a way to create an artificial nexus at your tower. I know where we can get what we need, but it's heavily protected. We don't have the firepower to just waltz in the front door. I have a plan - a scroll of mass teleportation. The fungal giants and spore creatures down below are covered in pustules filled with an oily substance. If we gather enough of the oil I can craft a makeshift ink substitute for the scroll.", ["objectivesText"] = "Gather 30 Pulsating Pustules from Sporebats and Fungal Giants in Zangarra. Progress: The giants have many more pustules than the sporebats, but are much tougher.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 111322 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79393, ["x"] = 0.842, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.842, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 15, ["flags"] = 0 } } },
[34635] = { ["id"] = 34635, ["name"] = "Forming the Scroll", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34634, 34636, 34874, 34878, 34879 }, ["description"] = "For this plan to work, we'll need infused parchment. The latent arcane energy at this nexus quickly froze the ancients in place and settled in their bark. If we rip off strips from the few that haven't been destroyed by the fungal creatures, I can form them into parchment.", ["objectivesText"] = "Rip 3 Pieces of Bark off of Slumbering Ancients in Zangarra.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79393, ["x"] = 0.842, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.842, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 16, ["flags"] = 0 } } },
[34636] = { ["id"] = 34636, ["name"] = "Gathering the Spark", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34634, 34635, 34874, 34878, 34879 }, ["description"] = "We need to get our hands on arcane energy to complete our scroll. It needs that fiery kick. I have a device capable of capturing energy in the space below, so let's get moving. The infused creatures shouldn't be an issue for the two of us.", ["objectivesText"] = "Harvest 3 Arcane Vortexes in Zangarra. Progress: There's so much untapped power... think of the potential!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79393, ["x"] = 0.842, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.842, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 17, ["flags"] = 0 } } },
[34646] = { ["id"] = 34646, ["name"] = "Qiana Moonshadow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 582, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["description"] = "If we are to win this war we are going to need more than foot soldiers. We need champions. Qiana Moonshadow 's performance in Tanaan and Eventide Landing was quite impressive. Perhaps you should speak with her about taking on a greater role in the battle against the Iron Horde.", ["objectivesText"] = "Speak with Qiana Moonshadow .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 112696 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34655] = { ["id"] = 34655, ["name"] = "The Shadows of Skettis", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35636, 35668, 35671 }, ["series"] = { 34653, 34656, 34657, 34658, 34659, 34756, 34805, 35537, 35554, 35636, 35668, 35671, 36951, 49548, 49566 }, ["description"] = "My people flee our homeland in droves. I sell trinkets to ease the journey. But I see that you are not interested in trinkets... No, what you seek are answers. Skettis lies just ahead. Once a great city built by Terokk as a refuge for the unwanted. Now a ruined slum. An old storyteller lives there - a scrollkeeper named Reshad . Find him and speak these words: \"Shadows gather.\" He will know you are a friend. Now go. Your presence is bad for business.", ["objectivesText"] = "Speak the password to Reshad in Skettis. Progress: If you're here for some kind of legendary tome of unthinkable power, I'm sorry to disappoint you. I am merely a keeper of history. I am also very busy at the moment.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 111485, 111524, 111575, 111850, 111892, 113282 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 79539, ["x"] = 0.378, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 79519, ["x"] = 0.48, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 34, ["name"] = "Shadows Gather", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34656] = { ["id"] = 34656, ["name"] = "Hidden in Plain Sight", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35636, 35668, 35671 }, ["series"] = { 34653, 34655, 34657, 34658, 34659, 34756, 34805, 35537, 35554, 35636, 35668, 35671, 36951, 49548, 49566 }, ["description"] = "< Reshad begins hastily stuffing scrolls into his robes.> I thought I would have more time to prepare! There are powerful relics hidden out there in Skettis - if I leave without them, I may as well have died. The first is a pair of wingblades being held by an effigy near the front gate. You likely walked right past them on your way in. Another effigy on the east side of the ruins bears a white mask over its face. Bring those relics to me, and their secrets shall be yours.", ["objectivesText"] = "Retrieve the Weathered Wingblades and Ragged Mask . Progress: Wingblades forged in the name of a sun god to bring freedom and glory to her children. A mask worn by a great king who would walk among his people in disguise to know their true nature.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 111485, 111524, 111575, 111850, 111892, 113282, 114732, 114733, 114734, 114735 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 79519, ["x"] = 0.48, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 79519, ["x"] = 0.48, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 34, ["name"] = "Shadows Gather", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34657] = { ["id"] = 34657, ["name"] = "Adherents of the Sun God", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35636, 35668, 35671 }, ["series"] = { 34653, 34655, 34656, 34658, 34659, 34756, 34805, 35537, 35554, 35636, 35668, 35671, 36951, 49548, 49566 }, ["description"] = "The arakkoa from Skyreach are all ruled by the Adherents of Rukhmar. They revile those of us who bear the Curse of Sethe, and decree that we must be purged in the name of their sun god. Soon their gaze will turn to lands beyond Arak. Challenge their warriors. Buy me time to prepare my escape, and help me set into motion their downfall.", ["objectivesText"] = "Slay 8 Adherent Bladewings . Progress: Skettis will fall today. Neither of us can change that. We need only to send them a message: we will not die quietly.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 111485, 111524, 111575, 111850, 111892, 113282 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 79519, ["x"] = 0.48, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 79519, ["x"] = 0.48, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 34, ["name"] = "Shadows Gather", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34658] = { ["id"] = 34658, ["name"] = "Orders From On High", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35636, 35668, 35671 }, ["series"] = { 34653, 34655, 34656, 34657, 34659, 34756, 34805, 35537, 35554, 35636, 35668, 35671, 36951, 49548, 49566 }, ["description"] = "The Adherents of Rukhmar are the ruling body atop the spires. Their influence is absolute. Their proclamations taken as the will of Rukhmar Herself. The herald leading this purge is surely carrying out such orders - likely no more than a list of names and places they plan to erase. That list would prove invaluable in the days to come. Acquire it for me, and shut that herald up!", ["objectivesText"] = "Loot the Adherent Proclamation from Sun-Sage Rathyx. Progress: < Reshad fastens another scroll to Percy, who squawks meekly in protest.> Oh, stop whining.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 111485, 111524, 111575, 111850, 111892, 113282 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 79519, ["x"] = 0.48, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 79519, ["x"] = 0.48, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 34, ["name"] = "Shadows Gather", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34659] = { ["id"] = 34659, ["name"] = "The Crone", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35636, 35668, 35671 }, ["series"] = { 34653, 34655, 34656, 34657, 34658, 34756, 34805, 35537, 35554, 35636, 35668, 35671, 36951, 49548, 49566 }, ["description"] = "Do you remember our greeting, $p? \"Shadows gather when the raven swallows the day.\" It is more than an old verse - it is a call to action. Followers of the old ways are gathering, and I must join them. You are needed, too, I should think Follow this road down to Crow's Crook. There you will find the home of an old crone. Greet her as you greeted me, and she will guide the way. You will not see me, but I will be close behind.", ["objectivesText"] = "Speak the password to Ornekka at Crow's Crook. Progress: You would be wise to turn back, traveler.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 111485, 111524, 111575, 111850, 111892, 113282, 237812 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 79519, ["x"] = 0.48, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 79890, ["x"] = 0.516, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 34, ["name"] = "Shadows Gather", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34662] = { ["id"] = 34662, ["name"] = "Ring of Trials: Crushmaul", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34662 }, ["series"] = { 35921, 35922 }, ["description"] = "So you want to fight in the Ring of Trials do you? It's your funeral, bub! Your first fight is against an exceptionally large and angry ogre named Crushmaul . That's not all though, you'll have to take out his armored boar companion too; Crushmaul never goes into the ring without him! I hope your affairs are in order, because the last gladiator that fought Crushmaul went home in a body bag... I'm counting on you! Get your ass inside the arena and speak with my associate Guzrug to start the fight!", ["objectivesText"] = "Defeat Crushmaul in the Ring of Trials. Progress: What are you waiting for? Get in the ring and start spilling blood!", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79188, ["x"] = 0.795, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79188, ["x"] = 0.795, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.795, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34663] = { ["id"] = 34663, ["name"] = "Ring of Trials: Raketalon", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34663 }, ["description"] = "You may have defeated Crushmaul, but the party's over now...you've got another fight! The Highmaul take gladiatin' seriously; so when they built the Ring of Trials, they searched far and wide for the most brutal creatures they could find! You're up against a dread raven the ogres are calling Raketalon ! I'm telling you, <name>, something about that bird just ain't right...I think it truly enjoys the act of killing! Raketalon toyed with the last gladiator for hours before eating him. Try not to die!", ["objectivesText"] = "Defeat Raketalon in the Ring of Trials. Progress: What are you waiting for? Get in the arena and start spilling blood!", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79188, ["x"] = 0.795, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79188, ["x"] = 0.795, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.795, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34664] = { ["id"] = 34664, ["name"] = "Ring of Trials: Hol'yelaa", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34664 }, ["description"] = "You won your first two fights, but it's only going to get tougher from here! Your next fight is against Hol'yelaa , a former rangari who is as crazy as they come. No, really... Hol'yelaa is bonkers! Years ago, while on a scouting mission, he single handedly saved his entire rangari unit from a pack of Garn. But something inside of him snapped.... It wasn't long before Hol'yelaa went completely marbles and turned on his own unit! Alright, the pep talk is over! Get in there and kick some ass!", ["objectivesText"] = "Defeat Hol'yelaa in the Ring of Trials. Progress: What are you doing standing around? Get in the arena and spill some blood!", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79188, ["x"] = 0.795, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79188, ["x"] = 0.795, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.795, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34665] = { ["id"] = 34665, ["name"] = "Ring of Trials: Captain Boomspark", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34665 }, ["description"] = "You've been making a name for yourself in the arena, <name>! Don't get too excited though...fame has its consequences! You've been challenged by an up-and-coming gladiator who is looking to make a name for himself, sound familiar? Your next fight is against Captain Boomspark, a mercenary who came here to fight for the Iron Horde. The Iron Horde ain't exactly throwing piles of gold around, so now he's here! He's got a shredder, so watch out for the blades... and the fire too... especially the fire!", ["objectivesText"] = "Defeat Captain Boomspark in the Ring of Trials. Progress: What are you doing standing around? Get in the arena and spill some blood!", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79188, ["x"] = 0.795, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79188, ["x"] = 0.795, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.795, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34666] = { ["id"] = 34666, ["name"] = "Ring of Trials: Roakk the Zealot", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34666 }, ["description"] = "The final match is at hand, <name>! You've decimated all of the best challengers! There's nowhere to go from here but the very top...the reigning champion of the Ring of Trials! The current champ is an arakkoa named Roakk the Zealot . Roakk is a lunatic! He says he's on some divine crusade for the sun or something. Crazy or not, he's one of the most dangerous fighters I've ever seen and has even fought in the Highmaul Coliseum! I'm not going to lie, you're probably going to die in there...good luck!", ["objectivesText"] = "Defeat Roakk in the Ring of Trials. Progress: What are you doing standing around? Don't you hear the crowd screaming? There's a championship waiting on you!", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 114708, 114709, 114710, 114711 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79188, ["x"] = 0.795, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79188, ["x"] = 0.795, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.795, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34675] = { ["id"] = 34675, ["name"] = "The Might of the Warsong", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34674, 34678, 34682, 37184, 49567 }, ["description"] = "<The officer is in a great deal of pain. It's clear that he's not long for this world.> The Warsong. Surprise attack. Headed... west. <He takes a moment, before continuing.> They took the... blueprints.... <These are his last words.>", ["objectivesText"] = "Speak with Rangari D'kaan at Telaari Station.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79263, ["x"] = 0.864, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.864, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34678] = { ["id"] = 34678, ["name"] = "Up and Running", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34674, 34675, 34682, 37184, 49567 }, ["description"] = "The Warsong struck us hard. We lost Telaar, but we have a rare opportunity to strike at the heart of the Warsong. We need your wisdom and leadership to pull it off, <name>. First though, we're going to get our survivors out of Telaar. My rangari are ready to strike. We just need to get you to them. Thaelin has a copter that can get you to them. Unfortunately, his hands are full just trying to keep the infernal thing running. Help him get it up and running?", ["objectivesText"] = "Collect the Assorted Engineering Parts , Prop Rotor , and Transmission Flywheel . Progress: <name>, I can't tell you how great it is to see you.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 112524, 112525, 112526, 112527, 112957, 112962, 112963, 177653, 177654, 177655, 177656, 195207, 195209, 211279 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79674, ["x"] = 0.63, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34682] = { ["id"] = 34682, ["name"] = "Operation: Surprise Party", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34674, 34675, 34678, 37184, 49567 }, ["description"] = "There weren't many survivors of the Warsong attack. The few remaining rangari have gone up to one of the bluffs overlooking Telaar. The rangari are waiting for you. They're planning a surprise counter-attack. My copter's taken a beating. The auto-pilot's set to take you up there. I think she's got one last trip in her. Maybe.", ["objectivesText"] = "Use Thaelin's Copter to get up to the Rangari Overlook.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79674, ["x"] = 0.63, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79722, ["x"] = 0.658, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34692] = { ["id"] = 34692, ["name"] = "Delegating on Draenor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 582, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["description"] = "There is more work to do on Draenor than we can possibly handle by ourselves. We need to start delegating. A group of night elves need a champion at Starfall Outpost. Qiana is a perfect fit for this mission.", ["objectivesText"] = "Use the Command Table to send Qiana Moonshadow on a mission. Progress: You can use the Command Table to assign missions to your followers.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 112696 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 8, ["flags"] = 0 } } },
[34696] = { ["id"] = 34696, ["name"] = "The Lady of Light", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34696 }, ["series"] = { 34418 }, ["description"] = "<name>, yes? You are the one in charge here? I am Knight-Lord Dranarus , at your service. Lady Liadrin has responded to a suspected demon presence near Auchindoun, southwest of here. She has asked specifically for your assistance in ensuring Auchindoun does not fall into Gul'dan's hands. If you could set forth at your nearest convenience, I am sure the Lady would be most grateful.", ["objectivesText"] = "Speak to Lady Liadrin at the Burning Front in Talador .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79612, ["x"] = 0.718, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75121, ["x"] = 0.555, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34697] = { ["id"] = 34697, ["name"] = "A Rediscovered Legend", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34697, 34698, 34699, 34700, 34702, 34703, 35152, 35505, 35506, 35508, 35524, 35527, 35707 }, ["series"] = { 34698 }, ["description"] = "If your troops are going to learn to fight people you better get people to fight! And they better be good. Ever hear of Kash'drakor ? He's a big famous Frostwolf orc warrior type that tried to kill us Skulls. He would have won too, if the ogres hadn't snatched him. To the north is the Stonemaul Arena where they took him and a bunch of other big bad mean fighter gladiators. If you can find a way to free them, they could be the best trainers you could hope for.", ["objectivesText"] = "Find Kash'drakor near the Stonemaul Arena in Gorgrond .", ["rewardGold"] = 42135, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 76688, ["x"] = 0.462, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 79320, ["x"] = 0.428, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34698] = { ["id"] = 34698, ["name"] = "Slave Hunters", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["series"] = { 34697 }, ["description"] = "Anytime a gladiator escapes Stonemaul, they send their hardened slave hunters after us. I consider myself a capable warrior, years of surviving in an arena have taught me that. But these slave hunters keep pendants magically tethered to the slaves. With these pendants they can track us down anywhere we go, and kill us in our sleep or when our guard is down. I have no right to ask this, but can you enter Stonemaul and retrieve these pendants?", ["objectivesText"] = "Collect the Pendants of Brol, Krag, and Mol. Progress: Have you the pendants?", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 108899, 111527, 111528 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 79320, ["x"] = 0.428, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 79320, ["x"] = 0.428, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34699] = { ["id"] = 34699, ["name"] = "Getting Gladiators", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["series"] = { 34703, 34704, 35137 }, ["description"] = "When we fled Stonemaul, we had to leave others behind. If we try to rescue them and are recognized, the ogres will know our purpose, and the first thing they will do is kill our friends. The ogres do not know you, which might give you a fighting chance. Enter Stonemaul, find the other gladiators, and release them from their bonds. Do this and you will have our loyalty.", ["objectivesText"] = "Rescue gladiators Bruto , Y'kish, and Pitfighter Vaandaam.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112616, 112617, 112618, 112619 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 79322, ["x"] = 0.428, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 77014, ["x"] = 0.398, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34700] = { ["id"] = 34700, ["name"] = "Nazgrel", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["description"] = "Escaping Stonemaul was the easy part. The ogre filth that rule the pits still have my son. For a while they used him as leverage to ensure I would fight in their arenas. But now that I have escaped they will try to train him to replace me. Please, rescue my son. If they see me they will kill him instantly.", ["objectivesText"] = "Rescue Nazgrel.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 79320, ["x"] = 0.428, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 79320, ["x"] = 0.428, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34702] = { ["id"] = 34702, ["name"] = "Krav'ogra", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["description"] = "Stonemaul has chieftain, and it has slavemaster. Today, we kill both. First, Slavemaster Ok'mok . Me fight in arenas since me your size. Me know cruelty. Slavemaster Ok'mok is cruelty. Want to be true gladiator? Go to Stonemaul Arena, bang challenge gong in center of arena, and face beasts of slavemaster. Maybe you make Ok'mok so mad he jump down himself to kill you. If he do, kill him instead.", ["objectivesText"] = "Slay Slavemaster Ok'mok by using the Challenge Gong in Stonemaul Arena.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 79331, ["x"] = 0.426, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 79331, ["x"] = 0.426, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34703] = { ["id"] = 34703, ["name"] = "The Axe of Kor'gall", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["series"] = { 34699, 34704, 35137 }, ["description"] = "Time for vengeance! We are going to kill Kor'gall and you are going to take his axe. Shatter this feeble barrier, follow the bridge beyond until you reach the chieftain's throne. You freed us, so the honor of first blood is yours. Strike the first blow and we will join you in the cutting.", ["objectivesText"] = "Kill Kor'gall and retrieve his axe, Serathil . Progress: Kor'gall has ruled uncontested for far too long.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 109023, 112884, 112886, 112888 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 77014, ["x"] = 0.398, ["y"] = 0.654 }, { ["mapID"] = 543, ["npcID"] = 79322, ["x"] = 0.428, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 79322, ["x"] = 0.428, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.654 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34704] = { ["id"] = 34704, ["name"] = "A Rediscovered Legend", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["series"] = { 34699, 34703, 35137 }, ["description"] = "This Sparring Arena is a good start, but we will need trainers to help mold your forces into worthy fighters. There has been a reported spotting of a draenei to the west who matches the description of Akaani. This is interesting, as we all believed her dead. She was one of the finest warriors the draenei have ever fielded and a master of nearly any weapon forged or found. Commander, you could not ask for a more skilled trainer. I advise seeking her out, if it is really her...", ["objectivesText"] = "Find Gladiator Akaani near Stonemaul Arena in Gorgrond .", ["rewardGold"] = 42135, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81076, ["x"] = 0.529, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 79322, ["x"] = 0.428, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.529, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34706] = { ["id"] = 34706, ["name"] = "Come Together", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34706 }, ["description"] = "Your work is done here, <name>. I will stay here for now and help clean up any remaining demons. You should return to your outpost and let Dranarus know of our success. He can relay that information to Azeroth.", ["objectivesText"] = "Speak to Knight-Lord Dranarus at Vol'jin's Pride.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 77580, ["x"] = 0.456, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79612, ["x"] = 0.718, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34707] = { ["id"] = 34707, ["name"] = "Come Together", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34707 }, ["description"] = "Gul'dan and his cronies would do well to remember this day. We Auchenai are not to be trifled with. You should inform Vindicator Icia in your outpost of our success. She can reach out to the scattered refugees and their families.", ["objectivesText"] = "Speak to Vindicator Icia at Fort Wrynn.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 77581, ["x"] = 0.456, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79618, ["x"] = 0.696, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34711] = { ["id"] = 34711, ["name"] = "Due Cause to Celebrate", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34909, 34910, 34911, 34912 }, ["description"] = "Shall we return to your outpost? It would be a much better - and safer - place to celebrate. I'll teleport us there.", ["objectivesText"] = "Speak to Magister Serena at Fort Wrynn.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 116395 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80672, ["x"] = 0.696, ["y"] = 0.208 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.208 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 24, ["flags"] = 0 } } },
[34712] = { ["id"] = 34712, ["name"] = "Due Cause to Celebrate", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34887, 34889, 34890 }, ["description"] = "This isn't exactly my idea of the best place to talk. Shall we return to your outpost? It will be a much better place to celebrate. I'll teleport us there.", ["objectivesText"] = "Speak to Magister Krelas at Vol'jin's Pride.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 116395 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80553, ["x"] = 0.712, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 25, ["flags"] = 0 } } },
[34716] = { ["id"] = 34716, ["name"] = "Mo'mor Might Know", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["description"] = "We know the Warsong packleader that attacked the caravan is in Telaar. She has the blueprints. We don't know where she is down there, but there's one who might. Vindicator Mo'mor was last seen alive, but taken prisoner. If he's still alive, he might know where the blueprints are.", ["objectivesText"] = "Find Vindicator Mo'mor in Telaar.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 114691, 114692, 114693, 114694 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79722, ["x"] = 0.658, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79743, ["x"] = 0.666, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34717] = { ["id"] = 34717, ["name"] = "Operation: Just Arrowhead", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34717 }, ["description"] = "It goes without saying that we'll help you kill any of the Warsong out in the open down there. You just start the fight, and we'll end it with extreme prejudice.", ["objectivesText"] = "Kill 15 Warsong forces at Telaar.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79722, ["x"] = 0.658, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34718] = { ["id"] = 34718, ["name"] = "The Others", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["description"] = "There are yet a few survivors. I saw them pile onto Arbiter Khan during the fighting. More importantly, I can hear little Isel's sobs. She's nearby. I hope her mother is still alive. Your dwarf friend, Hansel, came in to try to rescue us. He thought he could take the Warsong on his own. I'm afraid I don't know what happened to him.", ["objectivesText"] = "Rescue Arbiter Khan , Caregiver Felaani & Isel, and Hansel Heavyhands .", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 38534, 38535, 38536, 38537, 198676, 200926 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79743, ["x"] = 0.666, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79743, ["x"] = 0.666, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34719] = { ["id"] = 34719, ["name"] = "... and My Hammer", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["description"] = "When they captured me, the Warsong took my hammer. Will you help me to recover it? I ask only because it's a holy relic. It should be taken from these orc dogs for no other reason than to return it to Auchindoun. Perhaps then, a worthy vindicator of the Light will take it up to smite the enemies of the draenei.", ["objectivesText"] = "Retrieve Mo'mor's Holy Hammer . Progress: I'm having trouble seeing. I may not have long.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 21100, 21398, 21746, 22958, 22959, 22963, 42793, 42806, 42818, 42835, 46017, 52605, 52627, 57290, 57291, 57292, 57293, 63859, 63860, 63861, 87399, 93724, 108439, 111577, 112535, 112536, 112580, 112581, 112585, 121722, 123918, 123919, 124124, 130287, 130288, 130289, 130290, 131280, 136350, 137723, 141007, 141008, 141009, 141010, 146714, 171828, 198606, 211279, 237812, 242241, 246812, 246951 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79743, ["x"] = 0.666, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79743, ["x"] = 0.666, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34737] = { ["id"] = 34737, ["name"] = "Masters of Shadow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 17, ["storyline"] = { 34737, 34739, 34740, 34741 }, ["description"] = "The bad orcs tried to catch me, but I snuck away. I'm good at hiding. All of the bad orcs are bad, but I've remembered the names of the meanest ones, just in case anybody came to save me. < Luuka takes a deep breath.> Ungra , Gurran, and... umm... oh! Ankova. Will you protect me from them?", ["objectivesText"] = "Slay Ungra , Taskmaster Gurran , and Ankova the Fallen . Progress: How goes your mission?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 79675, ["x"] = 0.551, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.551, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34739] = { ["id"] = 34739, ["name"] = "The Shadowmoon Clan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 17, ["storyline"] = { 34737, 34739, 34740, 34741 }, ["description"] = "We will protect the wounded prisoners and make sure Kargath doesn't get through the rubble. You go ahead and clear the cave, <name>.", ["objectivesText"] = "Slay 10 Shadowmoon Orcs or Void Wolves within the Umbral Halls.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 112663, 112664, 112665, 112666 }, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 78553, ["x"] = 0.55, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34740] = { ["id"] = 34740, ["name"] = "Yrel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34737, 34739, 34740, 34741 }, ["description"] = "Forgive me if I'm a bit flustered - I've never killed anyone before. My name is Yrel , and I am a student of Karabor. You say you have an ARMY with you? The Light must truly be watching over me today. I will follow you, then. Lead the way, <name>.", ["objectivesText"] = "Escort Yrel to safety.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34741] = { ["id"] = 34741, ["name"] = "Keli'dan the Breaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 17, ["storyline"] = { 34737, 34739, 34740, 34741 }, ["description"] = "One of Ner'zhul's lieutenants remains, up ahead. The exit to the cave isn't much farther past him. I will go back and tell Khadgar that the cave is clear. We will rendezvous once you've taken care of Keli'dan!", ["objectivesText"] = "Slay Keli'dan the Breaker .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 79675, ["x"] = 0.551, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.551, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 63, ["name"] = "The Shadowmoon", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34746] = { ["id"] = 34746, ["name"] = "Shields Down!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34769 }, ["description"] = "Did you hear that? They got the shield up. There'll be no getting into Telaar now. You must get that shield down. The only way to do it is to destroy the Arkonite crystal . Don't worry about me. You're going to kill two birds with one stone; Packleader Kargora is the one who stole your blueprints.", ["objectivesText"] = "Destroy the Arkonite Crystal and Collect the Garrison Blueprints from Packleader Kargora. Progress: Good news?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 35932, 35933, 35934, 35935, 111619, 114700, 114701, 114702, 114703, 114704, 114705, 114706, 114707 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79743, ["x"] = 0.666, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79674, ["x"] = 0.63, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 6, ["flags"] = 0 } } },
