[34756] = { ["id"] = 34756, ["name"] = "A Charming Deception", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35636, 35668, 35671 }, ["series"] = { 34653, 34655, 34656, 34657, 34658, 34659, 34805, 35537, 35554, 35636, 35668, 35671, 36951, 49548, 49566 }, ["description"] = "Reshad is more than he appears; a mottled old crow with his beak in a book, certainly, but we need him. Shadows gather beneath the lonely spire, in Veil Terokk. Reshad must make it there safely. Along the path you'll find charms primed with illusion spells. You need only touch them to take on Reshad 's image. Adherent assassins are on the prowl for an old outcast with scrolls on his back. They will fall upon you. Oh, but won't they be surprised when the illusion fades?! Kee-hee-hee!", ["objectivesText"] = "Use 5 Illusion Charms to draw out Adherent Harriers.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 111485, 111524, 111575, 111850, 111892, 113282, 114948, 114952, 114953, 119062, 119070 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 79890, ["x"] = 0.516, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 34, ["name"] = "Shadows Gather", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34769] = { ["id"] = 34769, ["name"] = "A Choice to Make", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34746 }, ["description"] = "We're just about ready to go here. All that's needed now is for you to make your choice. Take a look at the blueprints on the drafting table. Are we going to construct a corral or a tankworks?", ["objectivesText"] = "Use the Drafting Table to choose between the construction of a Corral or a Tankworks.", ["rewardGold"] = 292100, ["rewardXP"] = 600, ["rewardItems"] = { 81354, 116395, 118573 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79674, ["x"] = 0.63, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 7, ["flags"] = 0 } } },
