[34775] = { ["id"] = 34775, ["name"] = "Mission Probable", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 590, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34378, 34402, 34461, 34462, 34592, 34765, 34822, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "Despite his recent captures, Olin Umberhide seems to be a tauren of some skill in combat. He certainly has learned how to get an enemy's attention. I have a mission available that might prove ideal for his skill sets. When you are ready, simply issue the order via the command table in front of me and we will dispatch him immediately.", ["objectivesText"] = "Use the Command Table to send Olin Umberhide on a mission. Progress: Commander, I have a mission that might suite your new follower quite well.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 111907 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 13, ["flags"] = 0 } } },
[34778] = { ["id"] = 34778, ["name"] = "Migrant Workers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34779 }, ["description"] = "<name>, more recruits arrive at your garrison every hour. We will soon run out of food. I have made contact with Exarch Akama in hopes of securing rations from Elodor, the breadbasket of this valley. He has agreed, provided we supply labor for the harvest. Everyone wins. If you agree with my plan, speak with Foreman Zipfizzle here in the courtyard - he has gathered together available laborers. Akama and I will escort them and meet you at Elodor, far to the east!", ["objectivesText"] = "Speak with Foreman Zipfizzle in your garrison, then meet with the laborers outside of Elodor. Progress: Where's the rest of the caravan?", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81912, ["x"] = 0.56, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34779] = { ["id"] = 34779, ["name"] = "Circle the Wagon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34778 }, ["description"] = "One of our wagons fell behind, and disappeared somewhere in the woods to the northwest. Vindicator Maraad and several of your workers are stranded out there. Find them and bring them back!", ["objectivesText"] = "Find Maraad and the lost laborers and escort them back to Elodor Fields. Progress: Did you find them? Check the woods to the northwest. If I know Maraad, he probably tried to take the shelter of a hill.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 55121, 63550, 63551, 63552, 63553, 63554, 63555, 63556, 63557, 117497, 117498, 117499, 117500, 131434, 131435 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 81912, ["x"] = 0.56, ["y"] = 0.326 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80078, ["x"] = 0.584, ["y"] = 0.260571 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34780] = { ["id"] = 34780, ["name"] = "Invisible Ramparts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34781 }, ["description"] = "Exarch Akama is too cautious, but we shouldn't ignore a threat from the Shadowmoon clan. It is good you are here! Since we arrived on Draenor I have dedicated myself to recreating the technology we left behind. This large structure here is a defense ward. It should counter a Shadowmoon advance - provided we power it up. I have prepared resonance crystals at my workshop to the south. Carry one crystal at a time to the three pylons that surround the ward, then activate the control panel nearby!", ["objectivesText"] = "Carry charged resonance crystals to the primary, secondary, and tertiary pylons . Progress: <The console thrums with energy. You can't interpret anything on the display, but some of the lights are still blinking needily.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80075, ["x"] = 0.601333, ["y"] = 0.294667 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.294667 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34781] = { ["id"] = 34781, ["name"] = "Defenstrations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34780 }, ["description"] = "No sooner does power rush to the crystal outside than you hear distant war cries and shouts of alarm. Elodor is being attacked! If you want your laborers to come home in one piece, you'd best help with the defense of the town. Defeat the invasion and then return to the control console to reset the defenses.", ["objectivesText"] = "Kill 8 Shadowmoon Raiders or Dark Priestesses. Progress: The sounds of attack still reverberate from outside, which is alarming, given that the console seems awash with angrily blinking warning indicators.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 112995, 112996, 112997, 112998, 112999, 113000, 113001, 113002, 113003, 113004, 113005, 113006, 113007, 113008 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34782] = { ["id"] = 34782, ["name"] = "The Exarch Council", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34783, 34784 }, ["description"] = "Good work at the gates! The Shadowmoon orcs have been seeking prisoners for some reason. Their aggression helps our cause. Come with me. I would like to introduce you to the Exarch Council, \"The Hand of the Prophet.\" I have been trying to convince the Exarchs to support our cause and go on the offensive against the Iron Horde, but they are - as always - too cautious and slow to act. Come with me, I will introduce you to Exarch Othaar up the hill. Perhaps meeting an Alliance hero can sway the council.", ["objectivesText"] = "Speak with Exarch Othaar in Elodor.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 113177, 113178, 113179, 113180, 113181, 113182, 113192, 113256, 118201, 119317 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 82348, ["x"] = 0.582667, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80076, ["x"] = 0.604286, ["y"] = 0.230286 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.582667, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34783] = { ["id"] = 34783, ["name"] = "Naielle, The Rangari", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34782, 34784 }, ["description"] = "I am calling the Exarch Council to order to hear your petition. None of us doubt that this \"Iron Horde\" is a threat, but few can agree on what we should do about it. It is up to you and Vindicator Maraad to gather the Exarchs together. Exarch Naielle is the leader of the Rangari, the \"Eyes of the Prophet.\" They are our scouts who silently stalk the farthest corners of Draenor. Seek her out in the Rangari Enclave northwest of here.", ["objectivesText"] = "Speak to Exarch Naielle in the Rangari Enclave.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 113192, 113256, 119317 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80076, ["x"] = 0.604286, ["y"] = 0.230286 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80079, ["x"] = 0.589667, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.604286, ["y"] = 0.230286 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34784] = { ["id"] = 34784, ["name"] = "Fun with Fungus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34782, 34783 }, ["description"] = "It is our mission as rangari to explore and understand this world. Around you is the Umberfen. Many draenei lost their lives when we first discovered this place. The volatile spores burst whenever anyone approaches. But we watched... and we learned. Around the swamp you'll notice \"Shimmershrooms,\" distinguished by their orange glowcaps. Their dust will make you invisible to the volatile spores. Grab the spores - gently! - and bring them to me. We will forge this savage world into a weapon.", ["objectivesText"] = "Use the Shimmershrooms to safely gather 12 Volatile Spores. Progress: Remember, unless you are covered in shimmershroom dust, the spores will explode as soon as you get near.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 113192, 113256, 119317 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80079, ["x"] = 0.589667, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80079, ["x"] = 0.589667, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.589667, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34785] = { ["id"] = 34785, ["name"] = "Hataaru, the Artificer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 35070 }, ["description"] = "I will also need you to call upon Exarch Hataaru . I understand you were helping him with our defenses at the gate. Hataaru is our Chief Artificer - he understands our technology better than any other and has been working tirelessly to recreate the glory of the civilization we left behind. He has moved to his workstation outside of the Elodor Dig, our crystal mines located just to the Southeast. Look for him at the mine entrance.", ["objectivesText"] = "Speak with Exarch Hataaru outside of the Elodor Dig.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 112738 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80076, ["x"] = 0.604286, ["y"] = 0.230286 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80075, ["x"] = 0.601333, ["y"] = 0.294667 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.604286, ["y"] = 0.230286 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34786] = { ["id"] = 34786, ["name"] = "Engorged Goren", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["description"] = "You must be the <class> that so impressed Exarch Hataaru. Can you help? The Elodor Dig just behind me is overrun by strange stone creatures. These so-called goren actually devour minerals, metabolize them, and grow crystalline structures from their arms and back. Like most of the wildlife on this world, they completely baffle us. Please slay as many as you can and gather their crystal scales for me. You'll be protecting our earthworkers and aiding our research at the same time.", ["objectivesText"] = "Collect $1Oa Crystallized Goren Scales from Crystalmaw goren in the Elodor Dig. Progress: What's the status inside the dig?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 112738, 113155, 113156, 113157 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 81140, ["x"] = 0.618, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81140, ["x"] = 0.618, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 8, ["flags"] = 0 } } },
[34787] = { ["id"] = 34787, ["name"] = "Exarch Maladaar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34789, 34791, 34792, 35552 }, ["description"] = "The council is almost assembled: Othaar, myself, Hataaru and Naielle are ready. Only Exarch Maladaar remains. He has not been himself since he returned from his capture at the hands of the Iron Horde... but Vindicator Maraad was able to track him down. Find Maladaar at the Fey Landing, just south of the town center.", ["objectivesText"] = "Speak with Exarch Maladaar at the Fey Landing south of Elodor.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80078, ["x"] = 0.584, ["y"] = 0.260571 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80073, ["x"] = 0.6184, ["y"] = 0.2784 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.260571 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 9, ["flags"] = 0 } } },
[34788] = { ["id"] = 34788, ["name"] = "Friend of the Exarchs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 35905 }, ["description"] = "Only three members remain of the Exarch Council, but we are all deeply indebted to you. The vote is unanimous: Your Alliance will have our full support on Draenor. We are also going to place a draenei representative under your direct command. Three potential candidates are here in the courtyard. Speak to them and choose who you want - we will dispatch him or her immediately to your garrison!", ["objectivesText"] = "Choose a follower (either Andren, Chel, or Onaala) and then speak with Exarch Naielle . Progress: Who are you going to pick, <name>?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 109644, 119291, 119292, 119296 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80079, ["x"] = 0.589667, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80079, ["x"] = 0.589667, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.589667, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 10, ["flags"] = 0 } } },
[34789] = { ["id"] = 34789, ["name"] = "Speaker for the Dead", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34787, 34791, 34792, 35552 }, ["description"] = "This was a betrayal from within. There's no other explanation for it. None of the Exarchs trust each other now - especially me. But Othaar and Akama can damn their laws. We've got to rout out the traitor and the only way to do it is to speak to the corpse! Join me just outside the Altar of Sha'tar atop the eastern cliffs. Soulbinder Nyami and I will perform an exorcism to save Hataaru's immortal soul... and maybe learn who did this to him. Do you trust me, <name>?", ["objectivesText"] = "Meet Exarch Maladaar at the cliffs east of the Altar of Sha'tar. Complete the ritual to cleanse and interrogate Hataaru's corpse. Progress: Exarch Hataaru didn't deserve to die that way. Not like this.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80073, ["x"] = 0.6184, ["y"] = 0.2784 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80073, ["x"] = 0.6184, ["y"] = 0.2784 }, { ["mapID"] = 539, ["npcID"] = 88972, ["x"] = 0.664, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.6184, ["y"] = 0.2784 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 11, ["flags"] = 0 } } },
[34790] = { ["id"] = 34790, ["name"] = "The Sting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["description"] = "The exarchs seem to trust you, <class>. Are you venturing into the Umbrafen? The Sporebats in this area are usually docile, but something's got them all riled up. When they attack, their stingers wrap around exposed limbs. I've seen them tear through reinforced leather like it was paper. How do they work, I wonder? Could you bring me a pristine sporebat stinger ? I'd love to study it.", ["objectivesText"] = "Acquire a Pristine Sporebat Stinger from a Moonglow Sporebat. Progress: Most draenei avoid the Umbrafen, but we rangari seem drawn to the most dangerous places - that's where you really learn how the world works.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 53362, 53380, 53394, 80713, 80714, 80715, 80716, 80717, 80718, 80719, 80720, 80721, 113159, 113161, 113163, 113192, 113256, 119317, 131853, 172144, 175713, 175728, 175740, 179562, 181398, 181411, 181412, 181413, 181457, 181458, 181459, 181477, 181479, 181541, 182559, 184378, 184381, 184382, 184383, 184384, 184519 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 82537, ["x"] = 0.566, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 82537, ["x"] = 0.566, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 12, ["flags"] = 0 } } },
[34791] = { ["id"] = 34791, ["name"] = "Warning the Exarchs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34787, 34789, 34792, 35552 }, ["description"] = "You set the book ablaze, but not before noting its contents. The demonic tome was dedicated to enchanting weapons with fel energy. It looked as though the goal was to ensnare the victim's soul. The Exarchs must be warned that traitors are among them! The Council should be meeting now just up the hill to the east.", ["objectivesText"] = "Talk to Exarch Maladaar at the Altar of Sha'tar in Shadowmoon Valley .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80073, ["x"] = 0.6184, ["y"] = 0.2784 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.6184, ["y"] = 0.2784 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 13, ["flags"] = 0 } } },
[34792] = { ["id"] = 34792, ["name"] = "The Traitor's True Name", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34787, 34789, 34791, 35552 }, ["description"] = "We must give the traitor no place to hide. I have a focusing lens that will illuminate cloaked fel energy. If it were placed on a high point, it could act like a beacon, lighting up anyone in town who reeks of the fel taint. There is a prayer circle atop the Exarch's Rise to the north that will serve our purpose. Plant the focusing lens, <name>. If you reveal anything, deal with it. Then meet me below.", ["objectivesText"] = "Plant the Focusing Lens atop the Exarch's Rise in Shadowmoon Valley . Progress: What happened up there?", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 113232, 113233, 113234, 113235, 245425, 251330, 251477, 251548, 251549, 251640, 251653, 251654 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 88972, ["x"] = 0.664, ["y"] = 0.262 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80073, ["x"] = 0.6184, ["y"] = 0.2784 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 14, ["flags"] = 0 } } },
[34795] = { ["id"] = 34795, ["name"] = "The Might of the Warsong", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34794, 34808, 34818, 36952, 49549 }, ["description"] = "<The officer is in a great deal of pain. It's clear that he's not long for this world.> The Warsong. Surprise attack. Headed into... the Burning Blade.... <He takes a moment, before continuing.> They took the... blueprints.... <These are his last words.>", ["objectivesText"] = "Speak with Thrall at Wor'var.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80001, ["x"] = 0.864, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.864, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34805] = { ["id"] = 34805, ["name"] = "Echo Hunters", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35636, 35668, 35671 }, ["series"] = { 34653, 34655, 34656, 34657, 34658, 34659, 34756, 35537, 35554, 35636, 35668, 35671, 36951, 49548, 49566 }, ["description"] = "I am no sorcerer, but I've picked up a few spells in my time - enough for me to pass unseen by the naked eye. Unfortunately, the vampire bats in these woods don't use their eyes. They will hear my shuffling robes and Percy's incessant clucking a mile away. Clear them away from the path, would you?", ["objectivesText"] = "Slay 10 Echo Hunters .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 111485, 111524, 111575, 111850, 111892, 113282 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 79519, ["x"] = 0.48, ["y"] = 0.234 }, { ["mapID"] = 542, ["npcID"] = 80265, ["x"] = 0.515, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 34, ["name"] = "Shadows Gather", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34806] = { ["id"] = 34806, ["name"] = "Prune the Podlings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33263, 33271, 33331, 33461, 34806, 34820 }, ["description"] = "The blood soaked body of Ryan is slumped up against the cave wall. Tiny teeth marks cover his body. The podlings clearly are a threat to you and your garrison. It's time to do a little pruning.", ["objectivesText"] = "Take revenge on the podlings.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 74547, ["x"] = 0.47, ["y"] = 0.144 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.144 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 45, ["name"] = "Ending the Gloom", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34808] = { ["id"] = 34808, ["name"] = "More Lazy Peons", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34794, 34795, 34818, 36952, 49549 }, ["description"] = "We have a rare opportunity to strike at the heart of the Warsong. But, we need your wisdom and leadership. The most important decision will be your choice between building a corral or a tankworks. This choice will setup our approach to the fight against the Warsong. Thazz'ril will head up our building efforts. Will you give him a hand? It looks like he's having trouble motivating his peons to work.", ["objectivesText"] = "Motivate 8 Lazy Peons . Progress: If there's one thing the Horde never seems to be short on, it's lazy peons .", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 32680 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80140, ["x"] = 0.828, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34814] = { ["id"] = 34814, ["name"] = "Making Acquaintances", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34632 }, ["description"] = "It's nice to see someone else taking a vested interest in the arcane arts, you know. It's all too rare these days if you ask me! Unfortunately, I must meet Cordana to handle an important matter, but we're in luck! One of my good friends in the Kirin Tor has agreed to help you connect your arcane sanctum to the ley line network. He's waiting at my tower. Let's leave immediately and introduce you to one another.", ["objectivesText"] = "Follow Archmage Khadgar and speak with Magister Krelas in Zangarra. Progress: You are <name>, I presume?", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80142, ["x"] = 0.75, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79393, ["x"] = 0.842, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 14, ["flags"] = 0 } } },
[34815] = { ["id"] = 34815, ["name"] = "Making Acquaintances", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34631 }, ["description"] = "It's nice to see someone else taking a vested interest in the arcane arts, you know. It's all too rare these days if you ask me. Unfortunately, I must meet Cordana to handle an important matter, but we're in luck! One of my good friends in the Kirin Tor has agreed to help you connect your arcane sanctum to the ley line network. She's waiting at my tower. Let's leave immediately and introduce you to one another.", ["objectivesText"] = "Follow Archmage Khadgar and speak with Magister Serena in Zangarra.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 116395 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80142, ["x"] = 0.75, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79392, ["x"] = 0.848, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 13, ["flags"] = 0 } } },
[34818] = { ["id"] = 34818, ["name"] = "They Call Him Lantresor of the Blade", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34794, 34795, 34808, 36952, 49549 }, ["description"] = "The garrison blueprints were taken to the Burning Blade village when the Warsong sacked your caravan. I can't construct this building without those plans. There's been talk of a young blademaster who's been exiled from the clan for many years. They call him Lantresor of the Blade . Our scouts recently saw him return to Hallvalor to challenge the blademaster leadership. Instead, they clapped him in chains. Maybe he's still alive. Maybe he'll help you recover the blueprints?", ["objectivesText"] = "Find Lantresor of the Blade in Hallvalor.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80140, ["x"] = 0.828, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34820] = { ["id"] = 34820, ["name"] = "Lost Lumberjacks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 33263, 33271, 33331, 33461, 34806, 34820 }, ["description"] = "Shelly and her crew haven't returned from Gloomshade Grove. It's been days... I hope everything is okay.", ["objectivesText"] = "Find out what happened to Shelly and the missing lumberjacks.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 79966, ["x"] = 0.3955, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.3955, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 45, ["name"] = "Ending the Gloom", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34822] = { ["id"] = 34822, ["name"] = "What We Need", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34823, 34824, 34844, 34861, 49545 }, ["description"] = "I heard you guys hijacked and wrecked a ship on your way out of Tanaan. It's like my daddy always said: One man's wreck is another goblin's workshop. You should head down to the coast west of the garrison and see if you can't find any materials we might salvage. Oh, and uh... should probably watch yourself. I hear there are ogre raiders in the area.", ["objectivesText"] = "Collect 10 Drudgeboat Salvage . Progress: How's the salvage operation comin'?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 92683, 111907, 163036 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 8, ["flags"] = 0 } } },
[34823] = { ["id"] = 34823, ["name"] = "The Ogron Live?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 590, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34824, 34844, 34861, 49545 }, ["description"] = "Commander, our Frostwolf allies reportin' dat the Bladespire ogres have an outpost to our west led by an ogron. I heard tales of da ogron but never seen one. Dey be brutes, creatures from a time that was best left forgotten. Dey say most were slain during the forming of the original horde. What dey lack in wisdom they make up for in violence, force, and greed. I counsel dispatchin' dis creature as soon as possible.", ["objectivesText"] = "Slay Groog . Progress: Where the ogron goes, death and pain are sure to follow.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 111907 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 10, ["flags"] = 0 } } },
[34824] = { ["id"] = 34824, ["name"] = "What We Got", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34844, 34861, 49545 }, ["description"] = "Every fortress needs three things. One: peons! Find Skaggit and have him get our peons back to work. Two: building materials. I had the peons set up a cache for you where they will store resources they create while you are away. You should check it out. And three: raw experienced muscle! Constructing buildings in a garrison can take some time but I think we can speed up your first building by hiring Skaggit 's recently promoted Senior Peon II . Find him and tell him I sent ya.", ["objectivesText"] = "Have Skaggit get the peons working, investigate your Garrison Cache, and find Senior Peon II . Progress: If buildin' a stronghold were easy, everybody'd be doin' it.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 111907, 111931 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 9, ["flags"] = 0 } } },
[34826] = { ["id"] = 34826, ["name"] = "The Friend of My Enemy", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34826 }, ["description"] = "Hallvalor is the ancestral home of the Burning Blade clan. Since they're such fast friends, the Warsong have allowed the blademasters to remain in Nagrand . We are fierce, but we won't win if the Burning Blade attack us. It would be wise to strike first.", ["objectivesText"] = "Kill 15 Burning Blade forces at Hallvalor.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 38732, 38759, 39030, 39058, 39096, 211279 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34827] = { ["id"] = 34827, ["name"] = "Last of the Talonpriests", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34827, 34828, 34829, 34830, 34838, 34882, 34883, 34884, 34885, 34886, 34942, 36425 }, ["series"] = { 34828, 34829, 34830, 34882, 34883, 34942 }, ["description"] = "Talonpriests live among us in secret, guarding the rites of the Talon King's return. The Adherent proclamation you acquired in Skettis revealed two of them living in the Shadowglade to the north. Orcs have moved into the region, and the Adherent's beam weapon left Veil Akraz a smoking crater. As you can see, my people are beset by enemies on all sides. Talonpriest Ishaal survived and is in hiding. Drink this elixir near his hut to peer into the shadows and make contact with him.", ["objectivesText"] = "Drink the Elixir of Shadow at Ishaal's Hut in the Shadowglade.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 112100 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80153, ["x"] = 0.4636, ["y"] = 0.4612 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80232, ["x"] = 0.48, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.4636, ["y"] = 0.4612 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 37, ["name"] = "Secrets of the Talonpriests", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34828] = { ["id"] = 34828, ["name"] = "Ishaal's Orb", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34827, 34828, 34829, 34830, 34838, 34882, 34883, 34884, 34885, 34886, 34942, 36425 }, ["series"] = { 34827, 34829, 34830, 34882, 34883, 34942 }, ["description"] = "The Adherents came for me, but I was already hiding. I watched from the shadows as they ransacked my hut. Then I watched the Shattered Hand orcs arrive and butcher them like dinner fowl. Seems everyone is after us these days. One of those orc thugs made off with my scrying orb. I will be needing it back if I am to be of any use to Iskar.", ["objectivesText"] = "Retrieve Ishaal's Orb from Camp Thornscar. Progress: Have you found the orb?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 112101 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80232, ["x"] = 0.48, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80232, ["x"] = 0.48, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 37, ["name"] = "Secrets of the Talonpriests", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34829] = { ["id"] = 34829, ["name"] = "New Neighbors", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34827, 34828, 34829, 34830, 34838, 34882, 34883, 34884, 34885, 34886, 34942, 36425 }, ["series"] = { 34827, 34828, 34830, 34882, 34883, 34942 }, ["description"] = "The Shattered Hand clan is made up of orcs who can call no other clan home. They are sadistic warriors who maim their bodies, perhaps in a show of solidarity or perhaps because they simply enjoy the pain. It does not matter. What matters is that they are expanding their territory, butchering anyone in their path. They must be dealt with.", ["objectivesText"] = "Slay 15 Shattered Hand orcs in Camp Thornscar.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 114736, 114737, 114738, 114739 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80232, ["x"] = 0.48, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80232, ["x"] = 0.48, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 37, ["name"] = "Secrets of the Talonpriests", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34830] = { ["id"] = 34830, ["name"] = "Behind the Veil", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34827, 34828, 34829, 34830, 34838, 34882, 34883, 34884, 34885, 34886, 34942, 36425 }, ["series"] = { 34827, 34828, 34829, 34882, 34883, 34942 }, ["description"] = "Soon after the orcs swept in, Veil Akraz was laid to waste by a beam of light from Skyreach. <Ishaal's eyes glass over as he peers into his orb.> It seems they missed their true target. Zellek is still there, hiding in the realm of shadow. And... someone else as well. The orc assassin who used my orb. Take this. Drink it in Veil Akraz and find Zellek. Oh, and be careful. It's a little more potent than the last one. You'll see...", ["objectivesText"] = "Drink the Major Elixir of Shadows at Zellek's hut in Veil Akraz.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 112099 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80232, ["x"] = 0.48, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80508, ["x"] = 0.444, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 37, ["name"] = "Secrets of the Talonpriests", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34837] = { ["id"] = 34837, ["name"] = "Going to the Gordunni", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34579, 34840, 34855, 34858, 34860, 34870, 34971, 34972 }, ["description"] = "We have a good supply of jovite in the arsenal now but there just isn't enough of the material in the mine to keep us in stock for long. Down south of here there's a mountain that's just full of the stuff but there's one problem; Ogres! The Gordunni live on top of that mountain and they have begun trading the jovite to the Iron Horde. We need to go down there and secure the minerals for ourselves. I'll pack some supplies and meet you near their fortress down south.", ["objectivesText"] = "Travel to Gordal Fortress and meet up with Morketh Bladehowl .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79356, ["x"] = 0.708, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80229, ["x"] = 0.622, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34840] = { ["id"] = 34840, ["name"] = "Dropping Bombs", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34579, 34837, 34855, 34858, 34860, 34870, 34971, 34972 }, ["description"] = "The Gordunni have only a single path to their fortress and it is well-defended from a large attack. Thankfully they wont be expecting just the two of us to be attempting to break in. This is a great opportunity to take out their defenses and get some target practice for our artillery gunners back at the arsenal. Take these smoke grenades and use it to call in an artillery strike on their catapults as we head up.", ["objectivesText"] = "Call artillery strikes on the Gordunni Boulderthrower encampments within Gordal Fortress.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 112091 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80229, ["x"] = 0.622, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80339, ["x"] = 0.686, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34849] = { ["id"] = 34849, ["name"] = "The Blade Itself", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["description"] = "When they clapped me in irons, the Burning Blade instructor, Luhk the Keen-Eyed, took my blade. He's an honorable orc, even if his training techniques are counter-productive. I want my blade back, <class>. Then, I'll break myself free.", ["objectivesText"] = "Retrieve Lantresor's Blade from Instructor Luhk. Progress: A blademaster without a blade is no blademaster at all.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 111938 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34850] = { ["id"] = 34850, ["name"] = "Not Without My Honor", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["description"] = "The blade is not the only important item a blademaster carries. Once he has passed his final tests in the Masters' Caverns, the blademaster is given the honor of wearing the Burning Blade's banner. When my petition to reclaim my rightful place with the clan fell upon deaf and craven ears, I was stripped of that honor. No doubt, my banner has been stored away somewhere in Hallvalor. They'll give it to some other aspiring blademaster if they don't burn it first.", ["objectivesText"] = "Find the Blademaster's Banner in a Burning Blade Locker. Progress: Do you have my banner?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 113508, 114687, 114688, 114689, 114690, 114691, 114692, 114693, 114694 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34855] = { ["id"] = 34855, ["name"] = "Punching Through", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34579, 34837, 34840, 34858, 34860, 34870, 34971, 34972 }, ["description"] = "To secure the fortress we need to kill Witch Lord Morkurk, but I don't think we should go straight after him. His three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all powerful mages, and all of them are fiercely loyal to Morkurk. I suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out so that cannot happen.", ["objectivesText"] = "Slay Vizier Vorgorsh , Vizier Zulmork , and Vizier Cromaug . Progress: We need to make sure those Vizier's are taken care of before we can deal with Morkurk.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80339, ["x"] = 0.686, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.686, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 9, ["flags"] = 0 } } },
[34858] = { ["id"] = 34858, ["name"] = "Prized Repossessions", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34579, 34837, 34840, 34855, 34860, 34870, 34971, 34972 }, ["description"] = "The Gordunni were given copies of my blades as a gift from the Iron Horde. But what do they use them for? Toothpicks! Sure the blades are low grade copies but it's still MY design and I can't stand to think of them in those ogre hands for a moment longer! <Sir/Ma'am>, While we are in here can you do me a favor and get those blades out of their hands!", ["objectivesText"] = "Collect 6 Gordunni \"Toothpick's\" from Gordunni Bashers or Gordunni Cleavers within Gordal Fortress. Progress: Were you able to get all of my blades back?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 112006 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80339, ["x"] = 0.686, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.686, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 8, ["flags"] = 0 } } },
[34860] = { ["id"] = 34860, ["name"] = "Supply Recovery", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34579, 34837, 34840, 34855, 34858, 34870, 34971, 34972 }, ["description"] = "We seem to have arrived at just the right time! The Gordunni have been enchanting armaments for the Iron Horde and it looks like they haven't picked up the latest shipment. We could put that gear to far better use! Lets go hunt down their shipping containers. I brought some signal flares that we can use to call in an air pick-up when we've secured the shipment.", ["objectivesText"] = "Recover 6 Iron Horde Shipments . Progress: The goblins said that the flares would surely get their attention. I just hope it doesn't come from the hillside being blown apart.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80339, ["x"] = 0.686, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.686, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34861] = { ["id"] = 34861, ["name"] = "We Need An Army", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 33815, 34364, 34375, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34861 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 49545 }, ["description"] = "So the new warchief decided to send you Warmaster Zog to handle local operations. Zog! I heard that guy was notorious for organizing the Alliance AND the Horde to face off against the silithid at the Gates of Ahn'Qiraj. He was a general back then. Anyway, if you go let him know about the barracks being done I'm sure he'll have some thoughts on how to put it to good use. You can find Zog up at the town hall.", ["objectivesText"] = "Speak with Warmaster Zog .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 111907 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 1, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 11, ["flags"] = 0 } } },
[34866] = { ["id"] = 34866, ["name"] = "Meet Me in the Cavern", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34868, 34899, 35095, 35096 }, ["description"] = "It's time, <class>. Time for you to get your blueprints. Time for us to face the masters.", ["objectivesText"] = "Meet up with Lantresor of the Blade inside the Masters' Cavern.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34868] = { ["id"] = 34868, ["name"] = "Challenge of the Masters", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34866, 34899, 35095, 35096 }, ["description"] = "The time has come to challenge the Burning Blade masters. Go to the back of the cavern. There you will find the challenge ring and the masters watching over it from above. Pull the blade from the middle of the ring to issue your challenge. My clan values honor above all else and will respect your claim to trial by combat. As reward, you will be allowed to walk away with your blueprints and your life. Or, you will be dead.", ["objectivesText"] = "Survive the Burning Blade's trial by combat and retrieve the Garrison Blueprints . Progress: Do you have the garrison blueprints , commander?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 112020, 114700, 114701, 114702, 114703, 114704, 114705, 114706, 114707 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80140, ["x"] = 0.828, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34870] = { ["id"] = 34870, ["name"] = "The Lord of the Gordunni", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34579, 34837, 34840, 34855, 34858, 34860, 34971, 34972 }, ["description"] = "Witch Lord Morkurk is the leader of the Gordunni. He's the one that set up the Iron Horde trade and, even worse, my former boss gave him one of my best maces! We got to get my mace back! I mean... we need to kill him to secure the jovite for your arsenal! Morkurk is an accomplished mage so you better be prepared. Here, take the rocket pack and use it if you need to dodge an attack quickly or something. Also, if you happen to find my mace I'd like to get it back.", ["objectivesText"] = "Defeat Witch Lord Morkurk within Gordal Fortress and obtain \" Fury of the Forge \". Progress: Do you have my mace?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 112307, 112308, 112520, 112521, 112522, 112523 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80342, ["x"] = 0.645, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 10, ["flags"] = 0 } } },
[34874] = { ["id"] = 34874, ["name"] = "Next Steps", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34634, 34635, 34636, 34878, 34879 }, ["description"] = "You are positively on fire! We have everything I need to create the scroll. Your arcane sanctum will be brimming with arcane energy in no time. I will teleport to Vol'jin's Pride to combine the reagents and marshal your forces. Meet me there when you can.", ["objectivesText"] = "Speak to Magister Krelas at Vol'jin's Pride.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80965, ["x"] = 0.712, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 18, ["flags"] = 0 } } },
[34875] = { ["id"] = 34875, ["name"] = "Next Steps", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34609, 34612, 34619, 34908, 34913 }, ["description"] = "We did it! We have all of the reagents for the scroll. Your arcane sanctum will be the talk of Draenor before long. I'll go back to Fort Wrynn to finish it and gather your men. Meet me there.", ["objectivesText"] = "Speak to Magister Serena at Fort Wrynn.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 116395 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80966, ["x"] = 0.695, ["y"] = 0.21 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.21 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 17, ["flags"] = 0 } } },
[34876] = { ["id"] = 34876, ["name"] = "Loola's Lost Love", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34876 }, ["description"] = "Oh it was horrible. My husband and I were fishing in the marsh, I fell asleep and when I woke up he had been turned into a toad! I'm sure it was one of those Shadowmoon orcs I hear so much about. He jumped into the muddy waters before I could catch him. Will you help me find my lost love, <class>?", ["objectivesText"] = "Search Loose Mud for Old Loola 's husband.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 71641, ["x"] = 0.412, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 71641, ["x"] = 0.412, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[34877] = { ["id"] = 34877, ["name"] = "Removing the Reinforcements", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34877 }, ["description"] = "My own investigations have uncovered a permanent arcane portal from here to Highmaul itself. It is guarded but shouldn't be too hard to disrupt once you've gotten some breathing room.", ["objectivesText"] = "Destroy the Portal to Highmaul .", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81144, ["x"] = 0.84, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 }, { ["mapID"] = 550, ["npcID"] = 79674, ["x"] = 0.63, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.84, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34878] = { ["id"] = 34878, ["name"] = "The Foot of the Fortress", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34634, 34635, 34636, 34874, 34879 }, ["description"] = "We've enkindled your forces and the scroll is ready. It's time for phase two - stealing a nexus crystal from a heavily fortified ogre compound. We'll save the scroll to bring in reinforcements in our confrontation with the Gordunni Witch Lord. Let's meet at the base of the Gordal Foothills and take what is more or less rightfully yours!", ["objectivesText"] = "Speak to Magister Krelas at the entrance to Gordal Fortress.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80965, ["x"] = 0.712, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80396, ["x"] = 0.622, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 19, ["flags"] = 0 } } },
[34879] = { ["id"] = 34879, ["name"] = "Dropping In", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34634, 34635, 34636, 34874, 34878 }, ["description"] = "Witch Lord Morkurk is no fool. He has catapults set up throughout the foothills leading into their compound. No matter, I have a way to handle them. Take out the ogres guarding the siege weapons and mark them once they're clear. I'm readying a vortex spell that will handle things from there. We'll meet just outside their gate afterwards.", ["objectivesText"] = "Help Magister Krelas destroy 3 Gordunni Boulderthrowers.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 63859, 63860, 63861, 211279 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80396, ["x"] = 0.622, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80390, ["x"] = 0.682, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 20, ["flags"] = 0 } } },
[34881] = { ["id"] = 34881, ["name"] = "Earth, Wind and Fire...and Water", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34881 }, ["description"] = "The Elemental Plateau has become unstable, and so the cycle of rebirth must begin. It is a natural part of our life cycle that impurities are accumulated in the elemental body over time. When enough contamination has taken place, an elemental will become unstable and in some cases volatile. A necessary part of rebirth is pure, living essence which can be found atop the Elemental Plateau, as well as in the body of an elemental spirit. Return to me with the essence and we shall begin the rebirth.", ["objectivesText"] = "Collect 4 of each living essence from the Elemental Plateau. Progress: Bring to me the living essences of the elements, that I may plant the seeds of rebirth.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 112082, 112083, 112084, 112085, 118151, 118152, 118153, 119066, 119074 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80593, ["x"] = 0.714, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80593, ["x"] = 0.714, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34882] = { ["id"] = 34882, ["name"] = "Blades in the Dark", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34827, 34828, 34829, 34830, 34838, 34882, 34883, 34884, 34885, 34886, 34942, 36425 }, ["series"] = { 34827, 34828, 34829, 34830, 34883, 34942 }, ["description"] = "Those orcs got hold of Ishaal's orb, did they? That would explain the dangerous-looking fellow who crossed into this realm shortly before you. Not everyone handles the transition as... gracefully as you did. The oaf is still grappling with his own mind, stumbling about and muttering nonsense. Soon he will be drawn to the orb again, which would presumably lead him to Veil Terokk. Better to take him out now while he's still befuddled.", ["objectivesText"] = "Slay Malrok Thornscar in Veil Akraz.", ["rewardGold"] = 58650, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80508, ["x"] = 0.444, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80508, ["x"] = 0.444, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 37, ["name"] = "Secrets of the Talonpriests", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34883] = { ["id"] = 34883, ["name"] = "A Feast of Shadows", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34827, 34828, 34829, 34830, 34838, 34882, 34883, 34884, 34885, 34886, 34942, 36425 }, ["series"] = { 34827, 34828, 34829, 34830, 34882, 34942 }, ["description"] = "Many arakkoa died in Veil Akraz. From the outside, all seems still. Empty. But in this place between worlds, death never goes unnoticed. Stray life essence seeps through from the other side; a feast for the beings who prowl here. Slay the shadow creatures here, and gather from their corpses the fine dust they produce. I will need much of it to perform the rites of the Talon King.", ["objectivesText"] = "Gather 10 Shadow Dust . Progress: You know those elixirs you have been so eagerly quaffing? They are made of this stuff.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 112099, 112195, 114723, 114724, 114725, 114726 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80508, ["x"] = 0.444, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80508, ["x"] = 0.444, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 37, ["name"] = "Secrets of the Talonpriests", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34884] = { ["id"] = 34884, ["name"] = "The Kaliri Whisperer", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34827, 34828, 34829, 34830, 34838, 34882, 34883, 34884, 34885, 34886, 34942, 36425 }, ["description"] = "An important contact lives in the nearby Shadowglade. He is meek, but trains kaliri of monstrous size which are quite dangerous. He once claimed they could knock a rylak out of the sky, but I'll believe that when I see it. Skizzik is holding a valuable treasure for me. Seek him out and get him back to Veil Terokk if you can. At the very least, recover the gavel I entrusted to him.", ["objectivesText"] = "Recover the Old Gavel from Skizzik. Progress: Any word on Skizzik?", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 115482 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.470667, ["y"] = 0.455333 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 37, ["name"] = "Secrets of the Talonpriests", ["orderIndex"] = 8, ["flags"] = 0 } } },
[34887] = { ["id"] = 34887, ["name"] = "While We're in the Neighborhood", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34712, 34889, 34890 }, ["description"] = "Ah, the hubris of ogres. It always backfires. Morkurk has been using enchanted bracelets to empower his minions with arcane strength. We can disenchant these bracelets into reagents that will no doubt be useful to your arcane sanctum. What do you think about collecting some while we're here?", ["objectivesText"] = "Collect 8 Gordunni Runebeads . Progress: Most mages discount the use of arcane dust these days, but they're wrong.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 112088, 116395 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80390, ["x"] = 0.682, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 21, ["flags"] = 0 } } },
[34888] = { ["id"] = 34888, ["name"] = "Vicious Viziers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["description"] = "We're after Witch Lord Morkurk, but we shouldn't charge straight at him. His three lieutenants - Vorgorsh, Zulmork, and Cromaug - are the only other capable mages left of the Gordunni, and are fiercely loyal to Morkurk. I suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out first.", ["objectivesText"] = "Slay Vizier Vorgorsh , Vizier Zulmork , and Vizier Cromaug . Progress: I don't take chances.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80390, ["x"] = 0.682, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 22, ["flags"] = 0 } } },
[34889] = { ["id"] = 34889, ["name"] = "Orbs of Power", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34712, 34887, 34890 }, ["description"] = "There's a minor fire we'll need to put out before we can enact my plan. Morkurk has placed powerful wards throughout Gordal Fortress that will prevent any sort of mass summoning - awfully detrimental to our scroll of mass teleportation. Thankfully, no ogre would ever consider that a single enemy or two would have the gall to breach their walls.", ["objectivesText"] = "Destroy 5 Astral Wards .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80390, ["x"] = 0.682, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 23, ["flags"] = 0 } } },
[34890] = { ["id"] = 34890, ["name"] = "The Final Step", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34712, 34887, 34889 }, ["description"] = "It's time to fight fire with fire. We have Morkurk cornered. His protections gone. Use the scroll once you engage Morkurk... ...and enjoy the fireworks.", ["objectivesText"] = "Defeat Witch Lord Morkurk and retrieve the Arcane Nexus in Gordal Fortress. Progress: Ogres. It's always ogres.", ["rewardGold"] = 929400, ["rewardXP"] = 4150, ["rewardItems"] = { 112196, 112520, 112521, 112522, 112523, 112542 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 24, ["flags"] = 0 } } },
[34891] = { ["id"] = 34891, ["name"] = "Elemental Attunement", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34271, 34891, 34894, 34932, 34941, 34943, 34964, 34965, 35144, 35145, 35232, 35265, 35317 }, ["description"] = "Many shaman have sought the favor of the Throne of Elements. Forming an elemental bond with the furies allows a shaman to not only know the will of the elements on Draenor, but also tap into a great font of elemental power. If you are to discover the truth behind Gordawg's disappearance, you will need to succeed where others have failed and undertake the Ritual of Binding. First, you must prepare yourself. Seek out the elemental pillars upon the plateau and attune your spirit with the elements.", ["objectivesText"] = "Seek out the four elemental pillars.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80597, ["x"] = 0.717, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80597, ["x"] = 0.717, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.717, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34893] = { ["id"] = 34893, ["name"] = "Guardians of the Plateau", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34893 }, ["description"] = "The Elemental Plateau is sanctuary to the elemental spirits of Nagrand . The greatest among the elementals on the plateau are the guardians; mighty elemental spirits that stand watch over their domain. The guardians are pure and mighty spirits but a disturbance in the natural balance has caused them to grow unstable, corrupting the lesser elementals around them. In order to restore balance to the plateau, the guardians must be destroyed. Only then will the cycle of rebirth begin.", ["objectivesText"] = "Destroy the corrupted guardians atop the Elemental Plateau.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80593, ["x"] = 0.714, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80593, ["x"] = 0.714, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34894] = { ["id"] = 34894, ["name"] = "A Rare Bloom", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["description"] = "Many years ago I had a life-mate, Dahaka. We were only bound a short time before she was taken from me. I have lived long, but I have never known greater pain than that day. I was young and my grief was great; the earth quaked beneath my rage. I laid her to rest upon this cliff. It is here where I too will rest, but first a favor. A rare bloom grows in a cave within the fiery, molten earth of the plateau. It was her favorite. I would lay the flower upon her grave one last time before I die.", ["objectivesText"] = "Retrieve the Ember Blossom from the Elemental Plateau. Progress: Do you have the Ember Blossom ?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 112089, 113080 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80434, ["x"] = 0.75, ["y"] = 0.228 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80434, ["x"] = 0.75, ["y"] = 0.228 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.228 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34899] = { ["id"] = 34899, ["name"] = "A Choice to Make", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34866, 34868, 35095, 35096 }, ["description"] = "We're ready to start building. All that we need is for you to make a choice. The blueprints are on the drafting table. Take a look. Then, let me know if we're going to construct a corral or a tankworks.", ["objectivesText"] = "Use the Drafting Table to choose between the construction of a Corral or a Tankworks.", ["rewardGold"] = 292100, ["rewardXP"] = 600, ["rewardItems"] = { 116395 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80140, ["x"] = 0.828, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34908] = { ["id"] = 34908, ["name"] = "The Foot of the Fortress", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34609, 34612, 34619, 34875, 34913 }, ["description"] = "Your forces are at the ready and the scroll is prepared. It's time for phase two - stealing a nexus crystal from a fortified ogre compound. We'll save the scroll to bring in reinforcements in our confrontation with the Gordunni Witch Lord. Let's meet at the base of the Gordal Foothills to head into the fortress proper.", ["objectivesText"] = "Speak to Magister Serena at the entrance to Gordal Fortress.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 116395 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80966, ["x"] = 0.695, ["y"] = 0.21 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80607, ["x"] = 0.622, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.21 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 18, ["flags"] = 0 } } },
[34909] = { ["id"] = 34909, ["name"] = "While We're in the Neighborhood", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34711, 34910, 34911, 34912 }, ["description"] = "Ogres from the empire are known for being cold and calculating. We are fortunate that their calculations are rarely spot on. Morkurk has been using enchanted bracelets to empower his minions with arcane strength. Since we're going to have to dispatch them anyways, we might as well get some reagents out of it.", ["objectivesText"] = "Collect 8 Gordunni Runebeads . Progress: Ah, arcane powder. Reminds me of my days as an apprentice.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 112088, 116395 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80608, ["x"] = 0.698, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 20, ["flags"] = 0 } } },
[34910] = { ["id"] = 34910, ["name"] = "Vicious Viziers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34711, 34909, 34911, 34912 }, ["description"] = "We can't just skate in, kill Witch Lord Morkurk, and leave. His three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all fiercely loyal to Morkurk, and are all respectable mages in their own right. I suspect that if we attempt to engage the Witch Lord immediately that they will rush to his aid and overwhelm us. We need to take out his lieutenants first.", ["objectivesText"] = "Slay Vizier Vorgorsh , Vizier Zulmork , and Vizier Cromaug .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 116395 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80608, ["x"] = 0.698, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 21, ["flags"] = 0 } } },
[34911] = { ["id"] = 34911, ["name"] = "Orbs of Power", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34711, 34909, 34910, 34912 }, ["description"] = "Minor issue, I'm afraid. Morkurk has placed powerful wards throughout Gordal Fortress that will prevent any sort of mass summoning - not wonderful considering our plan. Thankfully, no ogre would ever consider that a single enemy or two would attack, so we should be able to slip through their fortress relatively easily.", ["objectivesText"] = "Destroy 5 Astral Wards .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 116395 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80608, ["x"] = 0.698, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 22, ["flags"] = 0 } } },
[34912] = { ["id"] = 34912, ["name"] = "The Final Step", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34711, 34909, 34910, 34911 }, ["description"] = "We have Morkurk cornered. He's all ours now. Use the scroll once you engage Morkurk... ...and enjoy the blizzard of your forces raining down on his head.", ["objectivesText"] = "Defeat Witch Lord Morkurk and retrieve the Arcane Nexus in Gordal Fortress. Progress: It's all come down to this moment.", ["rewardGold"] = 929400, ["rewardXP"] = 4150, ["rewardItems"] = { 112196, 112520, 112521, 112522, 112523, 112543, 116395 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 23, ["flags"] = 0 } } },
[34913] = { ["id"] = 34913, ["name"] = "Dropping In", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34609, 34612, 34619, 34875, 34908 }, ["description"] = "Witch Lord Morkurk, the leader of the fortress, has catapults set up along the road into their compound. That won't be a problem for us. Take out the ogres around the catapults and mark them for me. This vortex spell I have prepared will handle the rest. We'll meet at the gate to the fortress once the catapults are gone.", ["objectivesText"] = "Help Magister Serena destroy 3 Gordunni Boulderthrowers. Progress: I certainly hope they have more than this to stop us.", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["rewardItems"] = { 63859, 63860, 63861, 116395, 211279 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80607, ["x"] = 0.622, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80608, ["x"] = 0.698, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 19, ["flags"] = 0 } } },
[34914] = { ["id"] = 34914, ["name"] = "Target of Opportunity: Telaar", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34915, 34916, 34917, 34918, 35097, 35098, 35150, 35157, 35158, 35171 }, ["description"] = "We've received reports that the draenei enclave at Telaar has fallen to the Warsong. I sent a small group of shadow hunters to check on the situation. Kajassa is their leader. Will you meet her there?", ["objectivesText"] = "Speak with Shadow Hunter Kajassa at Telaar.", ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81189, ["x"] = 0.828, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80429, ["x"] = 0.685333, ["y"] = 0.644667 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 9, ["flags"] = 0 } } },
[34915] = { ["id"] = 34915, ["name"] = "I Help Ya Kill Dem", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34914, 34916, 34917, 34918, 35097, 35098, 35150, 35157, 35158, 35171 }, ["description"] = "Warsong come in an' kill de draenei rangers. No lettin' dem have dis place. You an' me, Commanda. We gonna kill dem all. You be distractin' dem an' I usin' me Loa ta finish dem off. You see.", ["objectivesText"] = "Kill 12 Warsong forces at Telaar.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80429, ["x"] = 0.685333, ["y"] = 0.644667 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80429, ["x"] = 0.685333, ["y"] = 0.644667 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.685333, ["y"] = 0.644667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 11, ["flags"] = 0 } } },
[34916] = { ["id"] = 34916, ["name"] = "The Blessing of Samedi", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34914, 34915, 34917, 34918, 35097, 35098, 35150, 35157, 35158, 35171 }, ["description"] = "Three of mah shadow huntas come here wit' me. De Warsong kill dem. We need ta help dey souls move on. Jus' in case ya find dem first, use dis on dere bodies. It send dere souls ta Samedi, Loa of de Grave.", ["objectivesText"] = "Use the Fetish of Samedi on the corpses of the dead shadow hunters.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 112166, 114687, 114688, 114689, 114690 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80429, ["x"] = 0.685333, ["y"] = 0.644667 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80429, ["x"] = 0.685333, ["y"] = 0.644667 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.685333, ["y"] = 0.644667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 12, ["flags"] = 0 } } },
[34917] = { ["id"] = 34917, ["name"] = "Shields Up!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34914, 34915, 34916, 34918, 35097, 35098, 35150, 35157, 35158, 35171 }, ["description"] = "The Warsong packleader is trying to raise Telaar's shield. If Kargora does that, the Warsong will have an impervious base. So far, they've only managed to initiate the shield. This has the undesirable side effect of protecting the packleader and her shaman at the main crystal. Activate the crystals on the perimeter of Telaar. That will force the shield to fully deploy. Once you do that, Kargora will be exposed.", ["objectivesText"] = "Activate the four Telaari Crystals .", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 35932, 35933, 35934, 35935, 114700, 114701, 114702, 114703, 114704, 114705, 114706, 114707 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80451, ["x"] = 0.685333, ["y"] = 0.644667 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80429, ["x"] = 0.685333, ["y"] = 0.644667 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.685333, ["y"] = 0.644667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 13, ["flags"] = 0 } } },
[34918] = { ["id"] = 34918, ["name"] = "Shields Down!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34914, 34915, 34916, 34917, 35097, 35098, 35150, 35157, 35158, 35171 }, ["description"] = "De time has come, commanda. Packleader Kargora an' de Arkonite Shield no longa protected. We need ta kill her an' destroy de shield crystal.", ["objectivesText"] = "Kill Packleader Kargora and destroy the Arkonite Shield.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 114704, 114705, 114706, 114707 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80429, ["x"] = 0.685333, ["y"] = 0.644667 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.685333, ["y"] = 0.644667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 15, ["flags"] = 0 } } },
[34921] = { ["id"] = 34921, ["name"] = "Cult of the Ravenspeakers", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["series"] = { 34922, 34923, 34938, 34991, 35007, 35010 }, ["description"] = "These outcasts are not the only cursed arakkoa holding their ground in Arak. A curious cult has formed in worship of Ka'alu, my consort and the keeper of my brood. They are considered to be quite... odd. Regardless, the outcasts will need their help. Without the wings of the ravens, Iskar can never take his fight to the spires. Take this feather and place it in the offering basket south of here. The so-called \"Ravenspeakers\" will surely take notice.", ["objectivesText"] = "Place the Plume of Anzu in the Offering Basket in Gnarlwood Pass.", ["rewardGold"] = 30900, ["rewardXP"] = 515, ["rewardItems"] = { 112343 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80648, ["x"] = 0.5865, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80639, ["x"] = 0.49, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.5865, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34922] = { ["id"] = 34922, ["name"] = "Words of the Raven Mother", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["series"] = { 34921, 34923, 34938, 34991, 35007, 35010 }, ["description"] = "We came here to perform the ritual of calling to bring the return of the Raven Mother. We had distributed parts of the scroll to everyone and had just begun when we were attacked by the Bloodmane. Now most of the flock has been killed and fragments lay scattered across our homeland. The ritual was a failure but we will not allow these mongrels to break our faith. We must continue our prayers here but we would be grateful if you can recover the scroll fragments for us.", ["objectivesText"] = "Recover 8 Ravenspeaker Scroll Fragments . Progress: We must have all the sacred texts! We cannot afford to leave even a single one unaccounted for!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 112199 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80740, ["x"] = 0.548, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80740, ["x"] = 0.548, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34923] = { ["id"] = 34923, ["name"] = "The Bloodmane", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["series"] = { 34921, 34922, 34938, 34991, 35007, 35010 }, ["description"] = "We had just arrived and begun the service of the headless fowl when the Bloodmane attacked out of nowhere. Clearly, this means that the Raven Mother wishes to test the worthiness of her children. Fear not, we are steadfast and will fervently continue our prayers regardless of what may come! <Sekara leans in and whispers to you.> Although, if you can get rid of the Bloodmane and their leader that would be a blessing as well.", ["objectivesText"] = "Slay Huntmaster Sorrowfang and 10 Bloodmane Razorclaws .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 114719, 114720, 114721, 114722, 114740, 114741, 114742, 114743 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80740, ["x"] = 0.548, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80740, ["x"] = 0.548, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34924] = { ["id"] = 34924, ["name"] = "The Egg Thieves", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["description"] = "The Bloodclaw are sadistic creatures. They have attacked the Ravenskar before and have stolen the eggs of the sacred ravens. While you are within the Bloodclaw lands keep an eye out for the eggs. I'll be waiting for you at the nest with as many baskets for them as I can gather.", ["objectivesText"] = "Collect 8 Dread Raven Eggs . Progress: Were you able to find the stolen raven eggs?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 112135 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80863, ["x"] = 0.548, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80746, ["x"] = 0.52, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34925] = { ["id"] = 34925, ["name"] = "Polishing the Iron Throne", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34437, 34439, 34442, 34925, 34958, 34987, 35005, 35019 }, ["series"] = { 34437, 34442 }, ["description"] = "These stinking Blackrock cowards think they're humiliating me. They're just making me angrier. Overseer Gotrigg, in the hut over there, carries my shackle key. If I'm going to get out of there, I'm going to need that key. Then... vengeance can begin.", ["objectivesText"] = "Obtain Ga'nar's Shackle Key from Overseer Gotrigg in the nearby building. Progress: You'll have to pry that key out of his cold, ugly hand.", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 64, ["name"] = "The Blackrock", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34932] = { ["id"] = 34932, ["name"] = "Guise of the Deceiver", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["description"] = "In a cave not far from here, there lives an old woman named Challe . I knew Challe many years ago when I was young; though as I have become old and grey, she has kept her youth and beauty. Challe was jealous of my love for Dahaka and I have long suspected that Challe had a part in her death. However, without evidence I could not bring justice against her. Meet with Challe and tell her that I am dying. Tell her that I wish to know the truth of Dahaka's fate before I leave this world.", ["objectivesText"] = "Speak with Challe to discover the truth. Progress: I have not much time left. Please, discover the truth of Dahaka's death before it is too late.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80434, ["x"] = 0.75, ["y"] = 0.228 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80434, ["x"] = 0.75, ["y"] = 0.228 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.228 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34938] = { ["id"] = 34938, ["name"] = "Ralshiara's Demise", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["series"] = { 34921, 34922, 34923, 34991, 35007, 35010 }, ["description"] = "It was said in the Journal of the Rising Sun that eating in the mornings cannot be done without harming a few eggs. The Bloodmane matron, Ralshiara , feasts upon sacred raven eggs for her snacks. How dare she! She must die for her sins! Take the path south over the mountains to reach the accursed home of the Bloodmane. Take this trinket, it fell to us from the heavens as a sign of the Raven Mother's favor and with it you might have a chance.", ["objectivesText"] = "Kill Ralshiara .", ["rewardGold"] = 482040, ["rewardXP"] = 5145, ["rewardItems"] = { 112681 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80481, ["x"] = 0.52, ["y"] = 0.498 }, { ["mapID"] = 542, ["npcID"] = 80740, ["x"] = 0.548, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80481, ["x"] = 0.52, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34939] = { ["id"] = 34939, ["name"] = "Declawing The Bloodmane", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["description"] = "It is written in the Scroll of Sermons to \"Bite the claw that strikes you.\" Take the path south from here that leads over the mountain to the Bloodmane valley in the west. There you will find those of their tribe who can use a primitive form of magic. Slay them and remove their paws. Once you have obtained a few bring them back to me in the nest so that they may be offered to the Raven Mother!", ["objectivesText"] = "Collect 6 Bloodclaw Shaman Paws. Progress: It is written in the Scroll of Sermons that the Raven Mother is not patient, and neither am I. Do you have the paws of the Bloodmane for me?", ["rewardGold"] = 7150, ["rewardXP"] = 4115, ["rewardItems"] = { 112204, 114719, 114720, 114721, 114722 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80481, ["x"] = 0.52, ["y"] = 0.498 }, { ["mapID"] = 542, ["npcID"] = 80860, ["x"] = 0.548, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80481, ["x"] = 0.52, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34941] = { ["id"] = 34941, ["name"] = "The Debt We Share", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["description"] = "These mortal shells that we call bodies are not ours to keep. The body is a gift of earth that must one day be returned from whence it came. The time has come for this body to return to the elements. Know that you have lifted the weight from an old heart, <name>. As I pass on from this realm, I do so without regret. I have fought on behalf of my people and my land, I have served the elements, and I have loved. It would honor me if you would stay during these final moments, <class>.", ["objectivesText"] = "Speak with Gar'rok . Progress: When I face my ancestors in the realm of spirits I will do so without shame or fear, for I have lived an honorable life.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 114883, 114884, 114885, 119052, 119057 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80434, ["x"] = 0.75, ["y"] = 0.228 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80595, ["x"] = 0.726, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.228 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34942] = { ["id"] = 34942, ["name"] = "Back from Beyond", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34827, 34828, 34829, 34830, 34838, 34882, 34883, 34884, 34885, 34886, 34942, 36425 }, ["series"] = { 34827, 34828, 34829, 34830, 34882, 34883 }, ["description"] = "We must begin preparations for the Talon King's return. From within this realm, I can travel quickly to Veil Terokk. You, however, should be returned to the other side. You are powerful, and will attract unwanted attention.", ["objectivesText"] = "Speak with Shadow Sage Iskar in Veil Terokk.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80508, ["x"] = 0.444, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80153, ["x"] = 0.4636, ["y"] = 0.4612 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 37, ["name"] = "Secrets of the Talonpriests", ["orderIndex"] = 11, ["flags"] = 0 } } },
[34943] = { ["id"] = 34943, ["name"] = "An Old Friend", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["description"] = "Since the beginning, a shaman has been called to serve the Throne of Elements as its keeper. It is a lifelong calling and a new keeper is only called after the last has passed on. Gar'rok has been our loyal keeper for many years, cleansing the Elemental Plateau during countless cycles of rebirth. Our keeper is dying, and soon another will be called in his place. When he passes, he should not be alone. Go to him, <name>. Ease his pain.", ["objectivesText"] = "Speak with Gar'rok .", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 25583, 25584, 25585, 69251, 121594, 121595, 121596, 121597, 129986, 129994, 130002, 130013, 237812 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80595, ["x"] = 0.726, ["y"] = 0.196 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80434, ["x"] = 0.75, ["y"] = 0.228 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 3, ["flags"] = 0 } } },
[34949] = { ["id"] = 34949, ["name"] = "Joining the Ranks", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80553, ["x"] = 0.712, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80553, ["x"] = 0.712, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 26, ["flags"] = 0 } } },
[34950] = { ["id"] = 34950, ["name"] = "Dreadpiston", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33722, 33754, 34683, 35226 }, ["description"] = "Nearby, a group of Iron Horde took over a key strategic position with surprising alacrity. They used a machine they call Dreadpiston to terrible effect in the siege, and I believe we need to destroy that machine before moving against the Iron Horde in Tuurem.", ["objectivesText"] = "Defeat Dreadpiston .", ["rewardGold"] = 208560, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75958, ["x"] = 0.59, ["y"] = 0.202 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75959, ["x"] = 0.5485, ["y"] = 0.3875 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 8, ["flags"] = 0 } } },
[34951] = { ["id"] = 34951, ["name"] = "They Call Him Lantresor of the Blade", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34593, 34596, 34954, 34955, 34956, 34957, 35061, 35062, 35148, 35169 }, ["description"] = "The Burning Blade clan at Hallvalor is supplying the Warsong with weapons and warriors. We cannot let this continue. There's a young blademaster who's been exiled from the Burning Blade for many years. They call him Lantresor of the Blade . My rangari recently saw him return to Hallvalor to challenge the blademaster leadership. Instead, they clapped him in chains. Maybe he's still alive. Maybe he'll help you deal with the Burning Blade.", ["objectivesText"] = "Find Lantresor of the Blade in Hallvalor.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80624, ["x"] = 0.634, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 9, ["flags"] = 0 } } },
[34952] = { ["id"] = 34952, ["name"] = "The Friend o' My Enemy", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34952 }, ["description"] = "Hallvalor is the ancestral home o' the Burning Blade clan. Since they be such fast friends, the Warsong allow the blademasters an' their shaman to remain in Nagrand when all o' the other clans are forced out. Blah, blah, blah. I say, if they're the friend o' my enemy, then they're my enemy, and that's all I need to know!", ["objectivesText"] = "Kill 15 Burning Blade forces at Hallvalor.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 38732, 38759, 39030, 39058, 39096, 211279 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79954, ["x"] = 0.635, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79954, ["x"] = 0.635, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34954] = { ["id"] = 34954, ["name"] = "The Blade Itself", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34593, 34596, 34951, 34955, 34956, 34957, 35061, 35062, 35148, 35169 }, ["description"] = "When they clapped me in irons, the Burning Blade instructor, Luhk the Keen-Eyed, took my blade. He's an honorable orc, even if his training techniques are counter-productive. I want my blade back, <class>.", ["objectivesText"] = "Retrieve Lantresor's Blade from Instructor Luhk. Progress: A blademaster without a blade is no blademaster at all.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 111938 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 11, ["flags"] = 0 } } },
[34955] = { ["id"] = 34955, ["name"] = "Not Without My Honor", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34593, 34596, 34951, 34954, 34956, 34957, 35061, 35062, 35148, 35169 }, ["description"] = "The blade is not the only important item a blademaster carries. Once he has passed his final tests in the Masters' Caverns, the blademaster is given the honor of wearing the Burning Blade's banner. When my petition to reclaim my rightful place with the clan fell upon deaf and craven ears, I was stripped of that honor. No doubt, my banner has been stored away somewhere in Hallvalor. They'll give it to some other aspiring blademaster if they don't burn it first.", ["objectivesText"] = "Find the Blademaster's Banner in a Burning Blade Locker. Progress: Do you have my banner?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 77497, 111947, 114687, 114688, 114689, 114690, 114691, 114692, 114693, 114694 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 12, ["flags"] = 0 } } },
[34956] = { ["id"] = 34956, ["name"] = "Meet Me in the Cavern", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34593, 34596, 34951, 34954, 34955, 34957, 35061, 35062, 35148, 35169 }, ["description"] = "It's time, <class>. Time to face the masters.", ["objectivesText"] = "Meet up with Lantresor of the Blade inside the Masters' Cavern.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 14, ["flags"] = 0 } } },
[34957] = { ["id"] = 34957, ["name"] = "Challenge of the Masters", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34593, 34596, 34951, 34954, 34955, 34956, 35061, 35062, 35148, 35169 }, ["description"] = "The time has come to challenge the Burning Blade masters. Go to the back of the cavern. There you will find the challenge ring and the masters watching over it from above. Pull the blade from the middle of the ring to issue your challenge. My clan values honor above all else and will respect your claim to trial by combat. As reward, you will be allowed to walk away with your life. Or, you will be dead.", ["objectivesText"] = "Survive the Burning Blade's trial by combat.", ["rewardGold"] = 1549000, ["rewardXP"] = 4790, ["rewardItems"] = { 114704, 114705, 114706, 114707 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 15, ["flags"] = 0 } } },
[34959] = { ["id"] = 34959, ["name"] = "Dreadpiston", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34087, 34088, 36801 }, ["description"] = "The Iron Horde overtook a peaceful draenei outpost without mercy. They used a machine they call Dreadpiston to level the town in minutes. Destroy it.", ["objectivesText"] = "Defeat Dreadpiston .", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 107843, 107855, 108825, 109161, 110560 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34962] = { ["id"] = 34962, ["name"] = "Khadgar's Plan", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33720, 33721, 33724, 33728, 33729, 33730, 33731, 34948 }, ["description"] = "We have the Iron Horde backed into a corner now, thanks to you. It is almost time to enter the city of Shattrath and repel them. First, we must meet Khadgar and some new allies.", ["objectivesText"] = "Speak with Khadgar near the gates of Shattrath.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75959, ["x"] = 0.5485, ["y"] = 0.3875 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75805, ["x"] = 0.542, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.5485, ["y"] = 0.3875 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 13, ["flags"] = 0 } } },
[34963] = { ["id"] = 34963, ["name"] = "Khadgar's Plan", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34094, 34096, 34097, 34098, 34099, 34947 }, ["description"] = "Shattrath must not fall into the hands of the Iron Horde. It is time again for me to get my hands bloody. We will tell Khadgar we are ready to enter the city and take back what is rightfully ours.", ["objectivesText"] = "Speak with Khadgar near the gates of Shattrath.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75803, ["x"] = 0.586, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75805, ["x"] = 0.542, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 12, ["flags"] = 0 } } },
[34964] = { ["id"] = 34964, ["name"] = "The Farseer Awaits", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34271, 34891, 34894, 34932, 34941, 34943, 34964, 34965, 35144, 35145, 35232, 35265, 35317 }, ["description"] = "Your presence has been requested at the Throne of Elements, <name>. Farseer Drek'Thar heard the call of the furies upon the wind and made the journey to commune with the elements. The Farseer has sent word that you are to join him at the Throne of Elements. Go and see what the elements would have of you.", ["objectivesText"] = "Find Farseer Drek'Thar at the Throne of Elements.", ["rewardGold"] = 5865, ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80597, ["x"] = 0.717, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34965] = { ["id"] = 34965, ["name"] = "Called to the Throne", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34271, 34891, 34894, 34932, 34941, 34943, 34964, 34965, 35144, 35145, 35232, 35265, 35317 }, ["description"] = "It was not long after I arrived in Nagrand that the voice of Kalandrios called out to me upon the wind. It is a great honor to be called to the Throne of Elements, but my heart was heavy sensing the purpose. There is dark malaise in the air, it can be felt all around us. It surrounds all life here...enveloping...smothering... Come, it is time we commune with the furies and lend them our aid. An invisible shadow has been cast upon this valley and it may be up to us to remove it.", ["objectivesText"] = "Commune with the furies at the Throne of Elements. Progress: It is time that we communed with the furies regarding the sickness here.", ["rewardGold"] = 30900, ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80597, ["x"] = 0.717, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80597, ["x"] = 0.717, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.717, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34971] = { ["id"] = 34971, ["name"] = "The Only Way to Travel", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34579, 34837, 34840, 34855, 34858, 34860, 34870, 34972 }, ["description"] = "Call me cautious but I kept a few flares just in case we needed to evac. I'm glad that wasn't needed but we could still use the ride back to the arsenal. Are you ready, <sir/ma'am>?", ["objectivesText"] = "Speak to Morketh Bladehowl in Vol'jin's Pride.", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["rewardItems"] = { 112307, 116395, 237812 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80342, ["x"] = 0.645, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80623, ["x"] = 0.712, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 11, ["flags"] = 0 } } },
[34972] = { ["id"] = 34972, ["name"] = "Armor Up", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34579, 34837, 34840, 34855, 34858, 34860, 34870, 34971 }, ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 112307 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80623, ["x"] = 0.712, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80623, ["x"] = 0.712, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 12, ["flags"] = 0 } } },
[34976] = { ["id"] = 34976, ["name"] = "Dropping Bombs", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34563, 34571, 34573, 34578, 34624, 34977, 34978, 34979, 34980, 34981, 35045 }, ["description"] = "The Gordunni have only a single path to their fortress and it is well-defended from a large attack. Thankfully they wont be expecting just the two of us to be attempting to break in. This is a great opportunity to take out their defenses and get some target practice for our gunners back at the artillery tower. Take these smoke grenades and use it to call in an artillery strike on their catapults as we head up.", ["objectivesText"] = "Call artillery strikes on the Gordunni Boulderthrower encampments within Gordal Fortress.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 112091, 112307, 112504 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80627, ["x"] = 0.625, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80628, ["x"] = 0.696, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34977] = { ["id"] = 34977, ["name"] = "Supply Recovery", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34563, 34571, 34573, 34578, 34624, 34976, 34978, 34979, 34980, 34981, 35045 }, ["description"] = "We seem to have arrived at just the right time! The Gordunni have been enchanting armaments for the Iron Horde and it looks like they haven't picked up the latest shipment. We could put that gear to far better use in our artillery tower! Lets go hunt down their shipping containers. I brought some signal flares that we can use to call in an air pick-up when we've secured the shipment.", ["objectivesText"] = "Recover 6 Iron Horde Shipments .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 112091, 112307, 112504 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80628, ["x"] = 0.696, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34978] = { ["id"] = 34978, ["name"] = "Prized Repossessions", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34563, 34571, 34573, 34578, 34624, 34976, 34977, 34979, 34980, 34981, 35045 }, ["description"] = "The Gordunni have plagued the people of Shattrath ever since the city was founded. Over time they amassed quite a hoard of weapons they captured from our defenders in raids. Getting these weapons in the hands of our soldiers would be practical and I personally would like to get them out of the hands of the ogres. While we are in here can you do me a favor and gather up any of those weapons you come across.", ["objectivesText"] = "Collect 6 Shattrath Guardian Maces from Gordunni Bashers or Gordunni Cleavers within Gordal Fortress. Progress: Were you able to find any weapons?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 112091, 112307, 112504 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80628, ["x"] = 0.696, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 8, ["flags"] = 0 } } },
[34979] = { ["id"] = 34979, ["name"] = "Punching Through", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34563, 34571, 34573, 34578, 34624, 34976, 34977, 34978, 34980, 34981, 35045 }, ["description"] = "To secure the fortress we need to kill Witch Lord Morkurk, but I don't think we should go straight after him. His three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all powerful mages, and all of them are fiercely loyal to Morkurk. I suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out so that cannot happen.", ["objectivesText"] = "Slay Vizier Vorgorsh , Vizier Zulmork , and Vizier Cromaug . Progress: We need to make sure those Vizier's are taken care of before we can deal with Morkurk.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 112091, 112307, 112504 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80628, ["x"] = 0.696, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 9, ["flags"] = 0 } } },
[34980] = { ["id"] = 34980, ["name"] = "The Lord of the Gordunni", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34563, 34571, 34573, 34578, 34624, 34976, 34977, 34978, 34979, 34981, 35045 }, ["description"] = "Witch Lord Morkurk is the leader of the Gordunni. We need to kill him to secure the jovite for use in our artillery tower. Morkurk is an accomplished mage so you better be prepared. Here, take the rocket pack and use it if you need to avoid any of his deadly magic. Archenon poros!", ["objectivesText"] = "Defeat Witch Lord Morkurk within Gordal Fortress.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 112091, 112307, 112504, 112520, 112521, 112522, 112523 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80630, ["x"] = 0.645, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 10, ["flags"] = 0 } } },
[34981] = { ["id"] = 34981, ["name"] = "The Only Way to Travel", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34563, 34571, 34573, 34578, 34624, 34976, 34977, 34978, 34979, 34980, 35045 }, ["description"] = "Call me cautious but I kept a few flares just in case we needed to quickly escape. I'm glad that wasn't needed but we could still use the ride back to the artillery tower. Are you ready <sir/ma'am>?", ["objectivesText"] = "Speak to Miall in Fort Wrynn.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 112091, 112307, 112504, 116395, 237812 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 80630, ["x"] = 0.645, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 80968, ["x"] = 0.696, ["y"] = 0.208 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 11, ["flags"] = 0 } } },
