[34991] = { ["id"] = 34991, ["name"] = "To the... Rescue?", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["series"] = { 34921, 34922, 34923, 34938, 35007, 35010 }, ["description"] = "The Parchment of Dust reads: \"Put the featherless against one another so that our claws remain unsullied!\" How wise the high Ravenspeaker is to foresee this day. There is a great beast on the hillside to the west by the name of Stonescale. It has abducted one of the flock and despite our many attempts we have been unable to defeat it. Go, prove yourself by slaying the beast and rescuing Tillik! Fulfill your destiny in the name of the Raven Mother!", ["objectivesText"] = "Rescue \"Tillik\" from the beast Stonescale in Gnarlwood Pass. Progress: Tillik's disappearance caused great sadness to the Flock.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 9643, 9644, 9645, 9646, 9647, 9648, 23389, 35807, 35808, 35809, 35810, 35811, 35812, 39648, 39649, 39650, 53264, 53300, 53306, 56633, 56634, 56635, 56859, 56860, 56861, 56862, 56863, 56864, 56865, 56866, 61448, 61449, 61450, 63885, 63886, 63887, 65654, 65655, 65656, 112331, 118030, 118031, 118032, 118033, 131294, 131404, 140517, 140922, 141940, 142054, 155466, 155474, 155482, 155490, 158607, 158608, 158609, 158610, 166846, 166970, 166971, 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187328, 187334, 187336, 187466, 205253, 211279, 237812, 246697, 253469 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80639, ["x"] = 0.49, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80639, ["x"] = 0.49, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.49 }, ["mapCandidates"] = 