[34994] = { ["id"] = 34994, ["name"] = "Forever Young", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33788, 34994, 34995, 35006, 35014, 35015 }, ["description"] = "All this sitting around is horrible for business. I have to find a way to recoup some of my lost profits. Those Draenei females are obsessed with the way their horns look. I overheard one of them talking about a root that grows in Blademoon Bloom that supposedly reduces horn shedding or something. I bet I could sell that root to them for a pretty nice profit. I'll give you a cut if you help me get a supply going.", ["objectivesText"] = "Pick Youngroot for Beezil. Progress: Did you find any Youngroot ?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 112328 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80761, ["x"] = 0.535, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80761, ["x"] = 0.535, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 42, ["name"] = "Botani In Bloom", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34995] = { ["id"] = 34995, ["name"] = "Botani Beatdown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33788, 34994, 34995, 35006, 35014, 35015 }, ["description"] = "Gidwin is doing much better. Thank you, <name>. I can't believe the draenei have lived alongside those horrible monsters for so long. Maybe we should show these beasts what happens when you mess with an Azerothian.", ["objectivesText"] = "Kill 5 Botani.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80865, ["x"] = 0.536, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80865, ["x"] = 0.536, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 42, ["name"] = "Botani In Bloom", ["orderIndex"] = 2, ["flags"] = 0 } } },
[34996] = { ["id"] = 34996, ["name"] = "Rotting Riverbeasts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34996 }, ["description"] = "The botani are infecting the local riverbeasts with some kind of strange flesh-eating plant. I fear this infection could spread to our people. If you see any infested riverbeasts, kill the blooming plants that inhabit their bodies... before they kill you.", ["objectivesText"] = "Kill 5 Blooming Mandroga. Progress: We need to stop this infestation.", ["rewardGold"] = 286500, ["rewardXP"] = 1415, ["rewardItems"] = { 113237, 113238, 113239, 113240 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80859, ["x"] = 0.526, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80859, ["x"] = 0.526, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[34997] = { ["id"] = 34997, ["name"] = "Slumberbloom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34997 }, ["description"] = "Huh?... Oh my, I appear to have fallen asleep again. These slumberblooms are nothing but trouble. One second I'm fighting botani and the next I'm dreaming I'm an elekk dancing with riverbeasts. *Yawn* We really should do something about all these slumberbloo *Yawn* ... ZZZZzzzzzzzz <You gather a small handful of pebbles laying by the sleeping draenei.>", ["objectivesText"] = "Use the Gathered Pebbles to pop the Slumberblooms.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 112332, 113405 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80707, ["x"] = 0.53, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.654 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[34998] = { ["id"] = 34998, ["name"] = "Talon Watch", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34998, 34999, 35000, 35001, 35002, 35003, 35004, 35011, 35012, 35013, 35245 }, ["series"] = { 35000, 35001, 35611 }, ["description"] = "By now you must be wondering about all of this curse business. What could distort a majestic arakkoa into... well, into this? < Reshad drags a crooked hand through the mottled feathers about his face.> A raven is prepped and waiting to fly you to Talon Watch. There shall your eyes be opened to the origin of this curse. Present the Eye of Anzu to Talon Guard Kurekk . He will guide you from there.", ["objectivesText"] = "Bring the Eye of Anzu to Talon Guard Kurekk in Talon Watch. Speak with Skytalon Meshaal for a flight. Progress: Reshad sent an outsider here? You must be very important... or very dangerous.", ["rewardGold"] = 5865, ["rewardXP"] = 515, ["rewardItems"] = { 115273 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80758, ["x"] = 0.544, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.470667, ["y"] = 0.455333 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 38, ["name"] = "The Gods of Arak", ["orderIndex"] = 0, ["flags"] = 0 } } },
[34999] = { ["id"] = 34999, ["name"] = "Hatred Undying", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34998, 34999, 35000, 35001, 35002, 35003, 35004, 35011, 35012, 35013, 35245 }, ["description"] = "The blood of the dead god, Sethe, lingers in the pools here. And with it, his hatred of Rukhmar and Anzu. So strong was this hate that it animates the blood even now, eons after he was slain by his fellow gods. I need the congealed blood that holds those spiteful creatures together. There is nothing the Adherents fear more than the power of this curse - what if we could brandish it against them?", ["objectivesText"] = "Gather 15 Congealed Blood of Sethe from Sethekk Holllow. Progress: My attempts to bottle the pooled blood have failed. It breaks down and dissipates when it is taken away from Sethe's bones. But I have high hopes for this congealed form!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 112335, 114715, 114716, 114717, 114718 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81514, ["x"] = 0.618, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81514, ["x"] = 0.618, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 38, ["name"] = "The Gods of Arak", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35000] = { ["id"] = 35000, ["name"] = "Banished From the Sky", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34998, 34999, 35000, 35001, 35002, 35003, 35004, 35011, 35012, 35013, 35245 }, ["series"] = { 34998, 35001, 35611 }, ["description"] = "The Adherents have been casting their enemies into the hollow for generations. The pools carry Sethe's dying curse, crippling arakkoa with visions of darkness and intense pain. The mind reels, the body writhes, and the wings wither. Most arakkoa die or go insane. Only the strongest can resist - seek them out and use the Eye of Anzu to help them to their senses. Beware, for the worshippers of Sethe also prey on these survivors to fill their ranks.", ["objectivesText"] = "Use the Eye of Anzu on 8 Cursed Arakkoa .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 116977 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80758, ["x"] = 0.544, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80758, ["x"] = 0.544, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 38, ["name"] = "The Gods of Arak", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35001] = { ["id"] = 35001, ["name"] = "Gaze of the Raven God", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34998, 34999, 35000, 35001, 35002, 35003, 35004, 35011, 35012, 35013, 35245 }, ["series"] = { 34998, 35000, 35611 }, ["description"] = "The Sethekk are breeding vile wind serpents from Sethe's blood and bones. With these creatures, they will tear apart the sky. The nests are protected by powerful magic, but Anzu's gaze should penetrate them with ease. Let us visit the nests and destroy them!", ["objectivesText"] = "Use the Eye of Anzu at 4 Wind Serpent Nests.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 117396 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80758, ["x"] = 0.544, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 38, ["name"] = "The Gods of Arak", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35002] = { ["id"] = 35002, ["name"] = "Sons of Sethe", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34998, 34999, 35000, 35001, 35002, 35003, 35004, 35011, 35012, 35013, 35245 }, ["description"] = "Many years have passed since anyone has been in contact with Anzu. He faded away, as Terokk did, to take refuge in the shadows. If we are to coax him back, we should make an offering. Sethe took the sky from us all - it seems fitting to take the wings of his children.", ["objectivesText"] = "Collect 6 Wind Serpent Wings . Progress: <A large bowl awaits an offering for the raven god.>", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 112336 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80758, ["x"] = 0.544, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 38, ["name"] = "The Gods of Arak", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35003] = { ["id"] = 35003, ["name"] = "Ritual Severance", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34998, 34999, 35000, 35001, 35002, 35003, 35004, 35011, 35012, 35013, 35245 }, ["series"] = { 35012 }, ["description"] = "I could not defeat this curse, and long ago resigned myself to rest in darkness. But the Sethekk are performing dark rituals to draw me back, slowly binding me to Sethe's will. Should they succeed, Sethe would have me draw a dark cloak across the horizon, and bathe the world in his blood. Disrupt their rituals, so that I may return with my own free will. Then, together, we shall bring an end to Sethe's return.", ["objectivesText"] = "Stomp out the three Sethekk Ritual Circles by running over them.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80648, ["x"] = 0.5865, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 86355, ["x"] = 0.642, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.5865, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 38, ["name"] = "The Gods of Arak", ["orderIndex"] = 5, ["flags"] = 0 } } },
[35004] = { ["id"] = 35004, ["name"] = "Servants of a Dead God", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34998, 34999, 35000, 35001, 35002, 35003, 35004, 35011, 35012, 35013, 35245 }, ["description"] = "Even in death, Sethe exerts influence. The Sethekk cult was born of this influence: led by a false king in service of the dead god. Silence their prophets, for they seek a future of black seas and blighted skies. Defeat their chosen champions, for they have pledged themselves to a lie.", ["objectivesText"] = "Slay 6 Sethekk Prophets and 6 Sethekk Chosen in Sethekk Hollow.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 114949, 114954, 114955, 119053, 119058 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80648, ["x"] = 0.5865, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 86355, ["x"] = 0.642, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.5865, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 38, ["name"] = "The Gods of Arak", ["orderIndex"] = 6, ["flags"] = 0 } } },
[35005] = { ["id"] = 35005, ["name"] = "Prepare for Battle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 17, ["storyline"] = { 34437, 34439, 34442, 34925, 34958, 34987, 35005 }, ["description"] = "There's nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde. It's time to turn this unarmed group of prisoners into an army.", ["objectivesText"] = "Obtain 30 Blackrock Weapons . Progress: These prisoners are no less brave than you or I, <name>. Give them a weapon and an ounce of hope and they will fight like the storm.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 112337, 112668, 112669, 112670, 112671 }, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 78553, ["x"] = 0.55, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 78553, ["x"] = 0.55, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 64, ["name"] = "The Blackrock", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35006] = { ["id"] = 35006, ["name"] = "Poison Paralysis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33788, 34994, 34995, 35006, 35014, 35015 }, ["description"] = "There are others from the caravan that have gone missing. My guess is they have been taken into Blademoon Bloom by the botani. You have to rescue them, <name>. You are our only hope. Here, take some of this elixir I just made, chances are you will need it.", ["objectivesText"] = "Rescue the missing travelers.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 76204, ["x"] = 0.536, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 76204, ["x"] = 0.536, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 42, ["name"] = "Botani In Bloom", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35007] = { ["id"] = 35007, ["name"] = "Rendezvous with the Ritualists", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["series"] = { 34921, 34922, 34923, 34938, 34991, 35010 }, ["description"] = "Our dear brother Sekara went to the Ravenskar with some of the flock to enact the great ritual of purification. No one has been sent back to the nest for supplies in the past day; caught up in prayers I suppose. I would go check on him but I need to make sure the scribe didn't mess up her transcription of my latest sermon. Could you do it? I'll be there in... well, who knows...", ["objectivesText"] = "Speak to Ravenspeaker Sekara in the Ravenskar.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80481, ["x"] = 0.52, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80740, ["x"] = 0.548, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35009] = { ["id"] = 35009, ["name"] = "Call of the Raven Mother", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["description"] = "All is now in its place to begin the ritual of calling that will bring the Raven Mother back to the nest. You have fulfilled all of the tests we have put before you so it is only fitting that you join with us and participate in the ritual. Soon the Raven Mother herself will appear before us! Oh my feathers are tingling in excitement! Speak to me again when you are ready.", ["objectivesText"] = "Help High Ravenspeaker Krikka with the ritual of calling.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 115463 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80481, ["x"] = 0.52, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 77857, ["x"] = 0.512, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35010] = { ["id"] = 35010, ["name"] = "The High Ravenspeaker", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["series"] = { 34921, 34922, 34923, 34938, 34991, 35007 }, ["description"] = "Yes, I knew you were worthy! The Writ of Faith says that great doubt will come in time of crisis but one must put their trust in the Raven Mother and all will be as it should! Come, come, we must go to the High Ravenspeaker!", ["objectivesText"] = "Locate High Ravenspeaker Krikka", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 193373, 199203 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80639, ["x"] = 0.49, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80481, ["x"] = 0.52, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35011] = { ["id"] = 35011, ["name"] = "The False Talon King", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34998, 34999, 35000, 35001, 35002, 35003, 35004, 35011, 35012, 35013, 35245 }, ["series"] = { 35013, 35245 }, ["description"] = "Ikiss was once a respected sage among the Adherents, but his search for the truth of Terokk's fall led to his own banishment. Ikiss became obsessed with Terokk, even claiming to be the old hero reborn. He commands the Sethekk, promising untold power in a new age of darkness. Know this: Ikiss is no Talon King. Slay the delusional fool, and search him for anything useful. He is known to collect powerful trinkets.", ["objectivesText"] = "Retrieve the Scuffed Bangle from Talon King Ikiss. Progress: Have you silenced the false king?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 112444, 119172 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 86475, ["x"] = 0.657333, ["y"] = 0.466667 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 86475, ["x"] = 0.657333, ["y"] = 0.466667 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.657333, ["y"] = 0.466667 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 38, ["name"] = "The Gods of Arak", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35012] = { ["id"] = 35012, ["name"] = "Sethe, the Dead God", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34998, 34999, 35000, 35001, 35002, 35003, 35004, 35011, 35012, 35013, 35245 }, ["series"] = { 35003 }, ["description"] = "The time has come to put an end to Sethe . I killed him before, and with your help I shall do it again. Ready yourself for a fight - the cultists will not stand idly by while we stamp out their god.", ["objectivesText"] = "Help Anzu defeat Sethe in the Broken Spire.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 114712, 114713, 114714, 114731 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 86355, ["x"] = 0.642, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80648, ["x"] = 0.5865, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 38, ["name"] = "The Gods of Arak", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35013] = { ["id"] = 35013, ["name"] = "Lithic's Gift", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34998, 34999, 35000, 35001, 35002, 35003, 35004, 35011, 35012, 35013, 35245 }, ["series"] = { 35011, 35245 }, ["description"] = "<Kurekk squints at the bangle, rotating it slowly in his claws.> There is an inscription on the inside. \"To my father, may Rukhmar illuminate your path. With love, Lithic.\" It cannot be... This is Terokk's bangle! It was a gift from his daughter, he wore it for years until... Well, we had better return it. Terokk built a memorial to Lithic not far from Talon Watch. It should rest there.", ["objectivesText"] = "Bring the Scuffed Bangle to Lithic's Rest. Progress: Who... are you? Why have you stirred me?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 117493 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 86475, ["x"] = 0.657333, ["y"] = 0.466667 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80834, ["x"] = 0.605, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.657333, ["y"] = 0.466667 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 38, ["name"] = "The Gods of Arak", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35014] = { ["id"] = 35014, ["name"] = "Blademoon Bloom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33788, 34994, 34995, 35006, 35014, 35015 }, ["series"] = { 35015 }, ["description"] = "We are out of options. I'm going into the bloom to find out what's going on. I'll meet you inside. Goodluck, <class>.", ["objectivesText"] = "Meet Rangari Arepheon inside Blademoon Bloom.", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80727, ["x"] = 0.536, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80635, ["x"] = 0.556, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 42, ["name"] = "Botani In Bloom", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35015] = { ["id"] = 35015, ["name"] = "Gestating Genesaur", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33788, 34994, 34995, 35006, 35014, 35015 }, ["series"] = { 35014 }, ["description"] = "This is bad. A genesaur is starting to sprout right here in the bloom. This is the first reported case of a genesaur being born in draenor in over three hundred years. No wonder the botani have been acting so crazy. They are bringing back bodies to fertilize that monstrosity. We have to kill it before it gets any larger. Once fully grown there is no stopping that beast.", ["objectivesText"] = "Kill the genesaur. Progress: I never thought I would see a genesaur in my lifetime.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 107303, 107305, 107310, 107861 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80635, ["x"] = 0.556, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80635, ["x"] = 0.556, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 42, ["name"] = "Botani In Bloom", ["orderIndex"] = 5, ["flags"] = 0 } } },
[35019] = { ["id"] = 35019, ["name"] = "Prepare for Battle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 17, ["storyline"] = { 34437, 34439, 34442, 34925, 34958, 34987, 35019 }, ["description"] = "There's nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde. It's time to turn this unarmed group of prisoners into an army.", ["objectivesText"] = "Obtain 30 Blackrock Weapons . Progress: These prisoners are no less brave than you or I, <name>. Give them a weapon and an ounce of hope and they will fight like the storm.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 112243, 112323, 112337, 112668, 112669, 112670, 112671, 117978 }, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 78554, ["x"] = 0.549, ["y"] = 0.504 } }, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 78554, ["x"] = 0.549, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 64, ["name"] = "The Blackrock", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35025] = { ["id"] = 35025, ["name"] = "We Have Company", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 35026, 35035, 35248, 35664, 35665, 35686, 35693, 35730, 35880 }, ["description"] = "Outsider, I've spotted Iron Horde soldiers nearby. It is bold, even for them, to venture into such deadly territory. If you do not deal with their presence, they will surely be a threat to your camp.", ["objectivesText"] = "Investigate the Iron Horde camp in Sulfur Basin.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81202, ["x"] = 0.435, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82832, ["x"] = 0.442, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 19, ["flags"] = 0 } } },
[35032] = { ["id"] = 35032, ["name"] = "Into Anguish", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 33083, 33255, 33256, 33793, 33794, 33795, 33837, 34043, 34054, 35032, 35093 }, ["series"] = { 34054 }, ["description"] = "Rulkan's gift to you, the Fragment of Anguish , will allow you to pass into the fortress unhindered. Go up these stairs to the doorway, then use the fragment to enter the compound. Once you are inside, you will find three altars powering the magical barrier around their stronghold. Destroy these runes, and Yrel and I will be able to join you in finding Ner'zhul.", ["objectivesText"] = "Use the Fragment of Anguish at the main doorway. Then destroy the Mark of Darkness , Mark of Shadows , and Mark of Anguish .", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 112386 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 77282, ["x"] = 0.409, ["y"] = 0.377 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 77282, ["x"] = 0.409, ["y"] = 0.377 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.377 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 44, ["name"] = "The Light of Karabor", ["orderIndex"] = 5, ["flags"] = 0 } } },
[35033] = { ["id"] = 35033, ["name"] = "Welcome to Gorgrond", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35033, 35050, 35055, 35063, 35065, 35828, 35834, 36595 }, ["series"] = { 33255, 33256, 33533, 35050, 35065, 35556, 36632, 49564 }, ["description"] = "Gorgrond is one of the most untamed landscapes in all of Draenor. Only the most skilled of rangari venture this deep into the wilds. It is their camp we are heading for. If you wish to travel ahead, it can be found down this path and to the right. Maraad and I shall follow after you momentarily. We still have some logistics to work out before we leave the landing.", ["objectivesText"] = "Follow the Wildwood Wash to Naielle's Watch. Progress: I am a fan of the temple gardens but this place is just too far gone for my tastes.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 80978, ["x"] = 0.584, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 80921, ["x"] = 0.642, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 52, ["name"] = "We Need An Outpost", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35035] = { ["id"] = 35035, ["name"] = "Seedbearers of Bad News", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 35025, 35026, 35248, 35664, 35665, 35686, 35693, 35730, 35880 }, ["description"] = "When these seedbearers are slain their seeds survive. From them spring new seedbearers, not over years, but hours. Leaving their remains here would soon cause your camp to be overrun. Burn them, outsider, if you wish your camp to endure.", ["objectivesText"] = "Burn 5 Ancient Seedbearer corpses.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 114967 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81202, ["x"] = 0.435, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81202, ["x"] = 0.435, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 21, ["flags"] = 0 } } },
[35036] = { ["id"] = 35036, ["name"] = "Is This One of Yours?", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "I found this one skulking nearby. He claims to be an ally of yours. Is this true? Or does he cook slowly over my fire?", ["objectivesText"] = "Talk to Rexxar and vouch for Bony Xuk .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 83569, ["x"] = 0.46, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 84743, ["x"] = 0.462, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 22, ["flags"] = 0 } } },
[35037] = { ["id"] = 35037, ["name"] = "Bad at Breaking", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35218 }, ["description"] = "Screams and growls echo from the canyon below - even more than usual. I don't dare leave Nisha here alone yet. Will you investigate those noises, <name>?", ["objectivesText"] = "Search the Iron Horde camp at Crushfang's End.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112591, 112592, 112593, 112594 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 80856, ["x"] = 0.46, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 80856, ["x"] = 0.46, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 23, ["flags"] = 0 } } },
[35038] = { ["id"] = 35038, ["name"] = "What the Bony Xuk?", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "Good to see your bones are still intact, <name>. Xuk's too. When you set off into the heart of the canyon, Xuk came to offer my services. Xuk not letting you take all of the skulls! Xuk will share with you powerful spirit magics my clan has passed down for many generations. While Xuk make preparations, you must gather the reagents. First, we'll need crystals from husks of goren corpses. You can find their bodies in the canyon.", ["objectivesText"] = "Collect 25 Goren Crystals from Longtooth Gorgers. Progress: Laughing Skull have some dirty tricks behind our masks.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112863, 112864, 112865, 112911, 119076, 119085 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 84743, ["x"] = 0.462, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 84743, ["x"] = 0.462, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 24, ["flags"] = 0 } } },
[35041] = { ["id"] = 35041, ["name"] = "Xuk It!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "It is done. With this enchantment, not only can you roam amongst the goren freely, but you can move as they do. Your travels through Gorgrond are now made simple. You have safe access to places otherwise impossible to reach. Xuk's ancestors have made it so.", ["objectivesText"] = "Use the goren disguise to explore locations in Gorgrond . Progress: What has that orc done to you?!", ["rewardGold"] = 254700, ["rewardXP"] = 2090, ["rewardItems"] = { 112863, 112864, 112865, 112958, 114963, 118713, 119076, 119085 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 84743, ["x"] = 0.462, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 80856, ["x"] = 0.46, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 25, ["flags"] = 0 } } },
[35045] = { ["id"] = 35045, ["name"] = "In Ared's Memory", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34563, 34571, 34573, 34578, 34609, 34612, 34619, 34624, 34631, 34711, 34815, 34875, 34908, 34909, 34910, 34911, 34912, 34913, 34976, 34977, 34978, 34979, 34980, 34981, 35045 }, ["series"] = { 34563, 34571, 34573, 34578, 34624, 34976, 34977, 34978, 34979, 34980, 34981 }, ["description"] = "My master has gone on to the Light, but I will continue his work. < Miall looks to Ared > Shanai ortar, Ared. I will have his body sent to Auchindoun. For now, show me this artillery tower of yours.", ["objectivesText"] = "Speak to Miall inside of Fort Wrynn in Talador .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 6948, 110898, 111910 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79159, ["x"] = 0.692, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79329, ["x"] = 0.7, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 23, ["name"] = "Establishing your Outpost", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35050] = { ["id"] = 35050, ["name"] = "Rescue Rangari", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35033, 35050, 35055, 35063, 35065, 35828, 35834, 36595 }, ["series"] = { 33255, 33256, 33533, 35033, 35065, 35556, 36632, 49564 }, ["description"] = "Many of our rangari have not been accounted for. It would seem the followers of Iyu have taken captives. We will continue to search the area for survivors. In the meantime, follow the Wildwood Wash west toward Highpass and look for any signs of our rangari comrades. Our people are stout and capable survivors. You may find more than you expect. Have them stay near the road and we will follow as soon as this... dwarf creature... has fixed his mechanical vessel.", ["objectivesText"] = "Find Rangari Rajess , Rangari Kolaan , and Rangari Jonaa . Progress: It is no small thing for us to welcome so many strangers into our camps. Gorgrond is not the sort of place that breeds trust easily.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 118030, 118031, 118032, 118033 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75146, ["x"] = 0.583, ["y"] = 0.561 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75146, ["x"] = 0.583, ["y"] = 0.561 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.561 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 52, ["name"] = "We Need An Outpost", ["orderIndex"] = 5, ["flags"] = 0 } } },
[35055] = { ["id"] = 35055, ["name"] = "Lost Mole Machines", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35033, 35050, 35055, 35063, 35065, 35828, 35834, 36595 }, ["series"] = { 35063, 35208, 35212, 35213, 35215, 35828, 36595 }, ["description"] = "Few people know the Blackrock clan better than Dark Iron dwarves. So after Tanaan, we sent a bunch of mole machines to Gorgrond to build a listenin' post to keep an eye on them. Me own mole machine got way off course an' I got separated. It didn't take long to figure out all the other mole machines got off course as well. Accordin' to the readin's in me tank, a mole machine surfaced somewhere way to the west of here. Mind scoutin' ahead while we get this tank operational?", ["objectivesText"] = "Find the Missing Mole Machine. Progress: I came here to fight the Blackrock clan, not get lost in the jungle.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75136, ["x"] = 0.581, ["y"] = 0.561 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75136, ["x"] = 0.581, ["y"] = 0.561 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.581, ["y"] = 0.561 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 52, ["name"] = "We Need An Outpost", ["orderIndex"] = 6, ["flags"] = 0 } } },
[35059] = { ["id"] = 35059, ["name"] = "Along the Riverside", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 35060 }, ["description"] = "Vindicator Yrel has taken most of our forces north. She's establishing a forward base along the Skysong River. She'll want to know that we're almost ready to move against Grommashar. I'm sure she can also use your help dealing with the Warsong orcs at Lok-rath.", ["objectivesText"] = "Speak with Vindicator Yrel at Yrel's Watch.", ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81039, ["x"] = 0.62, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 16, ["flags"] = 0 } } },
[35060] = { ["id"] = 35060, ["name"] = "Terms of Surrender", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 35059 }, ["description"] = "Believe it or not, I have good news: we've already taken Lok-rath. <The vindicator beams with pride.> Our soldiers have captured most of the Warsong, including their leader, Uruk Foecleaver . I saved the honor of accepting his surrender for you. They're waiting for you inside, commander.", ["objectivesText"] = "Address Uruk Foecleaver at Lok-rath.", ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81039, ["x"] = 0.62, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81086, ["x"] = 0.555, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 17, ["flags"] = 0 } } },
[35061] = { ["id"] = 35061, ["name"] = "The Pride of Lok-rath", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34593, 34596, 34951, 34954, 34955, 34956, 34957, 35062, 35148, 35169 }, ["description"] = "You think the Warsong are so easily defeated? <There's a rasping sound, like rope on metal.> I'm already tired of you Alliance, and you've just invaded my homeland. <The sound becomes more pronounced as Uruk Foecleaver looks you straight in the eye.> There will be no surrender. The Warsong bow to no one!", ["objectivesText"] = "Kill Uruk Foecleaver .", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["rewardItems"] = { 118139, 118140, 118141, 118142 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81086, ["x"] = 0.555, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81039, ["x"] = 0.62, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 18, ["flags"] = 0 } } },
[35062] = { ["id"] = 35062, ["name"] = "Lok-rath is Secured", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34593, 34596, 34951, 34954, 34955, 34956, 34957, 35061, 35148, 35169 }, ["description"] = "With their leader dead, the remaining Warsong will be easier to finish. As soon as that's done, I'll pull our soldiers out of Lok-rath and head for Grommashar. If you're heading back to Telaari Station, would you please inform D'kaan?", ["objectivesText"] = "Speak with Rangari D'kaan at Telaari Station.", ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81039, ["x"] = 0.62, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 19, ["flags"] = 0 } } },
[35063] = { ["id"] = 35063, ["name"] = "We Need An Outpost", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35033, 35050, 35055, 35063, 35065, 35828, 35834, 36595 }, ["series"] = { 35055, 35208, 35212, 35213, 35215, 35828, 36595 }, ["description"] = "Commander, we've gathered enough materials to build an outpost that will support our mission against the Iron Horde. How shall we proceed? A lumber yard would be valuable for gathering resources in the dense overgrowth to the south, and in confronting the plant monstrosities that defend it. On the other hand, a sparring arena would provide us the brutish forces we'd need to push through the magnaron wastelands to the north. When you're ready, make your choice on the table.", ["objectivesText"] = "Use the Drafting Table to craft a Lumber Yard or a Sparring Arena. Progress: Buildin' an outpost out here requires a certain kind o' crazy.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112909, 113136, 119252, 119254, 119256, 119298 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75136, ["x"] = 0.581, ["y"] = 0.561 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75136, ["x"] = 0.581, ["y"] = 0.561 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.581, ["y"] = 0.561 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 52, ["name"] = "We Need An Outpost", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35065] = { ["id"] = 35065, ["name"] = "A Harvester Has Come", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35033, 35050, 35055, 35063, 35065, 35828, 35834, 36595 }, ["series"] = { 33255, 33256, 33533, 35033, 35050, 35556, 36632, 49564 }, ["description"] = "This is what happens when one stands in the path of a genesaur. And where a genesaur walks, the botani follow. I saw one entering our shelter cave along the northern side of the camp. It is commanding the podlings to gather the corpses of our fallen brethren and must be stopped. I must tend to our wounded, and gather supplies for our departure. If you are serious about being a hero, venture into the cave and slay this botani.", ["objectivesText"] = "Slay Harvester Ommru .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 80921, ["x"] = 0.642, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75146, ["x"] = 0.583, ["y"] = 0.561 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 52, ["name"] = "We Need An Outpost", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35067] = { ["id"] = 35067, ["name"] = "Silence the War Machines", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35067 }, ["description"] = "The Iron Horde supplied Lok-rath with war machines from Ironfist Harbor. It won't take long for them to level Yrel's Watch. Someone has to silence those war machines!", ["objectivesText"] = "Destroy the 3 Iron Horde War Machines .", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81097, ["x"] = 0.554, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81123, ["x"] = 0.621, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35068] = { ["id"] = 35068, ["name"] = "If They Won't Surrender...", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35068 }, ["description"] = "This is the backbone of the army we intend to send against Garrosh Hellscream and Grommashar. If they won't surrender, we have no choice but to eliminate the Warsong.", ["objectivesText"] = "Kill 10 enemy forces at Lok-rath.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 118147, 118148, 118149, 118150 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81097, ["x"] = 0.554, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81123, ["x"] = 0.621, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35069] = { ["id"] = 35069, ["name"] = "Terror of Nagrand", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35069 }, ["description"] = "<The body of a fallen soldier lies here. Blood and gore trail back from the corpse to the entrance of the cave just to the north.> <Judging by the howls and the carnage surrounding the den, something truly terrifying must be in there.>", ["objectivesText"] = "Collect Shagor's Collar from Shagor. Progress: Commander. How may I help you?", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["rewardItems"] = { 112620 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81134, ["x"] = 0.56, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81123, ["x"] = 0.621, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35070] = { ["id"] = 35070, ["name"] = "Shut 'er Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34785 }, ["description"] = "Burrowing native creatures known as \"goren\" have tunneled into our crystal mines. Judging from our experience at the gates, I suspect my own experimental resonance crystal is whipping the native wildlife into a frenzy. Enter the Elodor Dig to the north and disable the malfunctioning resonance crystal! Be careful - my earthworkers report that the mine is crawling with those beasts.", ["objectivesText"] = "Disable the Malfunctioning Resonance Crystal in the Elodor Dig.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 30365, 30366, 30377, 30378, 57442, 57443, 112738, 211279 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80075, ["x"] = 0.601333, ["y"] = 0.294667 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 80075, ["x"] = 0.601333, ["y"] = 0.294667 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.294667 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 15, ["flags"] = 0 } } },
[35077] = { ["id"] = 35077, ["name"] = "Defungination", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["series"] = { 35080, 35082, 35619, 35620, 36861, 36862 }, ["description"] = "Have you seen the fungus out there in the water? It's growing faster than a baby ravasaur from Un'goro, and if we don't get it under control, the Gearworks is gonna be ruined like our last village. Uncle Krixel used to tell me to burn away the red fungus because that's what makes it grow so fast. You could help us out by taking a flame blaster and clearing out some of those spores down in the shallows.", ["objectivesText"] = "Use the QR58 Flame Blaster to destroy 20 Spore Pustules .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 46102, 111957, 112634, 112683, 112698, 112906, 115475, 115533, 118071, 118072, 118073, 118074 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81109, ["x"] = 0.614, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81109, ["x"] = 0.614, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35079] = { ["id"] = 35079, ["name"] = "Spore-be-Gone", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["description"] = "We got an emergency! A bunch of spore drifters have infested the shore and tore up our Spore-B-Gone turrets. We're caught with our armor off here! If we don't get those turrets back online then those spores are going to float right in to town and then we'll have another Pinchwhistle Point on our hands! We need to get out there and manually activate them. Well? Are you in?", ["objectivesText"] = "Activate 6 Spore-be-Gone Turrets .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81128, ["x"] = 0.614, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81128, ["x"] = 0.614, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35080] = { ["id"] = 35080, ["name"] = "The Mother Lode", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["series"] = { 35077, 35082, 35619, 35620, 36861, 36862 }, ["description"] = "Hey we got ourselves a crisis here! Our zeppelin \"The Mother Lode\" crashed onto the south mountain range. It was supposed to only be on an observation mission, what could have happened? We got to get down there quick and I'm going to need your help on this. Are you with me?", ["objectivesText"] = "Meet up with Kimzee Pinchwhistle at the Wreck of the Mother Lode.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81109, ["x"] = 0.614, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81773, ["x"] = 0.59, ["y"] = 0.792 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35081] = { ["id"] = 35081, ["name"] = "Clearing Out Before Cleaning Up", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["description"] = "Here's the situation. We need to get this salvage operation moving ASAP, but the ship went down right in the middle of the wasp nests. The ugly bugs are all over the place, and I can't call my team in here to start work until they're taken care of. Go kill as many of 'em as you can and I'll cut you in on some of the haul.", ["objectivesText"] = "Kill 8 Crimsonwing Wasps . Progress: I still see a mess of wasps down there. We need to clear those wasps out before I can get the salvage operation started.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81784, ["x"] = 0.59, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81784, ["x"] = 0.59, ["y"] = 0.792 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35082] = { ["id"] = 35082, ["name"] = "Getting the Crew Back Together", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["series"] = { 35077, 35080, 35619, 35620, 36861, 36862 }, ["description"] = "Oh wow, the debris is all over the mountainside! The survivors won't make it if we don't do something quick. They need healing NOW! Here, take my bandages and go patch them up.", ["objectivesText"] = "Revive 6 Injured Crewmen.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81773, ["x"] = 0.59, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81773, ["x"] = 0.59, ["y"] = 0.792 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35083] = { ["id"] = 35083, ["name"] = "Disrupt the Rituals", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["storyline"] = { 35083 }, ["description"] = "No longer do the Warsong seek to be one with the elements; instead they abuse their power by using it to channel the darkness of the void. I will not tolerate these rituals to continue. Locate the ritual totems the Warsong use to channel the void and destroy them. The gift of the elements was not given to the orcs only to be defiled and used as a plaything.", ["objectivesText"] = "Destroy the Ritual Totems. Progress: Have you destroyed the ritual totems?", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 57329, 57330, 57331 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35084] = { ["id"] = 35084, ["name"] = "Silence the Call", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["storyline"] = { 35084 }, ["description"] = "The Warsong clan, in their lust for dominance, have turned to the darkness of the void for power. Dark shamanism is a loathsome, dangerous practice that abuses the elemental gift I have bestowed upon them. There is one among the Warsong that calls out the loudest to the void, an elder shaman named Kuhlrath. Slay him and the rest of his dark shaman. I will not allow the Warsong to abuse the elements and desecrate tradition.", ["objectivesText"] = "Slay Kuhlrath and 10 Warsong shaman. Progress: Have you put an end to the Warsong ritualists?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 114886, 114889, 114891 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35085] = { ["id"] = 35085, ["name"] = "Through the Nether", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["storyline"] = { 35085 }, ["description"] = "The rituals have been disrupted, yet the nether beacons still glow with power.... This can only mean that the beacons are powered from within the Twisting Nether itself! The connection to the void must be severed! There is but one way to accomplish this; you must slay the void creature that maintains the connection with our world. Lay your hands upon a beacon and travel into the Twisting Nether. When you have arrived on the other side, locate a Shamanstone and use it to contact me.", ["objectivesText"] = "Use a Void Beacon to travel to the Twisting Nether. Progress: The veil between dimensions is thin. Do you hear my words through the shaman stone?", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35086] = { ["id"] = 35086, ["name"] = "The Void March", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["storyline"] = { 35086 }, ["description"] = "Hidden behind the veil of the Twisting Nether, the abominations of the void march upon Oshu'gun. The great void growing deep within the mountain has drawn them like moths to a flame. Wave upon wave, the creatures of the void march upon the mountain and sacrifice themselves to Invalidus. The void lord Invalidus cannot be allowed to feast upon the other void creatures, else it will become too powerful to stop.", ["objectivesText"] = "Destroy 10 Void Terrors and 15 Void Tendrils .", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35087] = { ["id"] = 35087, ["name"] = "The Nether Approaches", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["storyline"] = { 35087 }, ["description"] = "By connecting with the Twisting Nether, the Warsong shaman have created a ripple effect that they could not have anticipated. Look around and you will see countless portals beginning to open, signs that the Twisting Nether seeks to connect to Draenor. Should these portals successfully open, the path will be clear for all manner of demons and void creatures to rampage across this valley.", ["objectivesText"] = "Collapse 6 Void Portals .", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35088] = { ["id"] = 35088, ["name"] = "The Shadow of the Void", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["storyline"] = { 35088 }, ["description"] = "The moment has come to take on the void lord. Invalidus grows more powerful by the minute, so you must move with haste if you are to defeat the monster. At each of the Warsong ritual locations there is a void crystal; these crystals are used to channel the energy of the void from within the Twisting Nether. Disturb the crystal, and Invalidus will sense your presence below. Be ready, as soon as the crystal is disturbed, Invalidus will waste no time hunting you down.", ["objectivesText"] = "Summon and defeat Invalidus . Progress: Have you defeated Invalidus ?", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 118143, 118144, 118145, 118146 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35089] = { ["id"] = 35089, ["name"] = "Skimming Off the Top", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["description"] = "That flying machine is our ticket out of here but its fuel tank is bone dry! We're right next to the oil fields but with the infected out there we don't have time to run a line up here so we need to improvise. The oil creatures moving next to the pumps out there are full of a highly potent mixture that I can drop right into the tank. Grab some of that oil for me and we'll be one step closer to getting out of here.", ["objectivesText"] = "Collect 4 Volatile Oil . Progress: Do ya have that oil for me yet?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81972, ["x"] = 0.584, ["y"] = 0.922 }, { ["mapID"] = 542, ["npcID"] = 81978, ["x"] = 0.588, ["y"] = 0.928 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81978, ["x"] = 0.588, ["y"] = 0.928 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.922 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 5, ["flags"] = 0 } } },
[35090] = { ["id"] = 35090, ["name"] = "The Right Parts for the Job", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["series"] = { 35091, 35285 }, ["description"] = "Uncle Krixel's a tough one but he won't be going anywhere on foot with his leg broken. He has a flying machine he brought from Azeroth that can fly us out of here. Problem is, the engine's busted. I'll need some parts to fix the thing. My car's wasted but those broken shredders just outside of town should have what we need. We don't have time to break them down by hand so just use this rocket launcher and blow 'em apart. Anything that survives the blast should be strong enough to use on the engine.", ["objectivesText"] = "Use the G-14 Buster Rocket near Broken Shredders to retrieve Serviceable Gears . Progress: Got any parts for me?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533, 118075, 118076, 118077, 118078 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81972, ["x"] = 0.584, ["y"] = 0.922 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81978, ["x"] = 0.588, ["y"] = 0.928 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.922 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 6, ["flags"] = 0 } } },
[35091] = { ["id"] = 35091, ["name"] = "Sporicide", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["series"] = { 35090, 35285 }, ["description"] = "It's revolting, absolutely disgusting, infuriating even! I'm talking about seeing those spore creatures walking around Pinchwhistle Point. While I'm working on the machine here how about you go out and kill off some of those spore creatures? I'll feel a bit better knowing there are less of those things moving around.", ["objectivesText"] = "Kill 6 Spore Shamblers in Pinchwhistle Point. Progress: Did you put down those spore creatures yet?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81978, ["x"] = 0.588, ["y"] = 0.928 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81978, ["x"] = 0.588, ["y"] = 0.928 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.928 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35095] = { ["id"] = 35095, ["name"] = "Along the Riverside", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34866, 34868, 34899, 35096 }, ["description"] = "Durotan has taken most of our forces west. He's establishing a forward base along the Skysong River. He'll want to know that we're almost ready to move against Grommashar. I'm sure he'll also appreciate your help dealing with the Warsong orcs at Lok-rath.", ["objectivesText"] = "Speak with Durotan at Riverside Post.", ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81186, ["x"] = 0.486, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 16, ["flags"] = 0 } } },
[35096] = { ["id"] = 35096, ["name"] = "Terms of Surrender", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34866, 34868, 34899, 35095 }, ["description"] = "I have good news, commander: we've already taken Lok-rath. <The warchief grins.> The Horde's soldiers have captured most of the Warsong, including their leader, Uruk Foecleaver . I saved the honor of accepting his surrender for you. They're waiting for you inside, commander.", ["objectivesText"] = "Address Uruk Foecleaver at Lok-rath.", ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81186, ["x"] = 0.486, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81086, ["x"] = 0.555, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 17, ["flags"] = 0 } } },
[35097] = { ["id"] = 35097, ["name"] = "The Pride of Lok-rath", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34914, 34915, 34916, 34917, 34918, 35098, 35150, 35157, 35158, 35171 }, ["description"] = "You think the Warsong are so easily defeated? <There's a rasping sound, like rope on metal.> I'm already tired of you Horde, and you've just invaded my homeland. <The sound becomes more pronounced as Uruk Foecleaver looks you straight in the eye.> There will be no surrender. The Warsong bow to no one!", ["objectivesText"] = "Kill Uruk Foecleaver .", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 118139, 118140, 118141, 118142 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81086, ["x"] = 0.555, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81186, ["x"] = 0.486, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 18, ["flags"] = 0 } } },
[35098] = { ["id"] = 35098, ["name"] = "Lok-rath is Secured", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34914, 34915, 34916, 34917, 34918, 35097, 35150, 35157, 35158, 35171 }, ["description"] = "With their leader dead, the remaining Warsong will be easy pickings. As soon as that's done, I'll pull our soldiers out of Lok-rath and head for Grommashar. If you're heading back to Wor'var, inform Thrall that we'll be ready soon.", ["objectivesText"] = "Speak with Thrall at Wor'var.", ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81186, ["x"] = 0.486, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 19, ["flags"] = 0 } } },
[35099] = { ["id"] = 35099, ["name"] = "Silence the War Machines", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35099 }, ["description"] = "The Iron Horde supplied Lok-rath with war machines from Ironfist Harbor. It won't take long for them to level Riverside Post. Someone has to silence those war machines!", ["objectivesText"] = "Destroy the 3 Iron Horde War Machines .", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81194, ["x"] = 0.554, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81193, ["x"] = 0.494, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35100] = { ["id"] = 35100, ["name"] = "If They Won't Surrender...", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35100 }, ["description"] = "This is the backbone of the army we intend to send against Garrosh Hellscream and Grommashar. If they won't surrender, we have no choice but to eliminate the Warsong.", ["objectivesText"] = "Kill 10 enemy forces at Lok-rath.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 118141, 118147, 118148, 118149, 118150 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81194, ["x"] = 0.554, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81193, ["x"] = 0.494, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35101] = { ["id"] = 35101, ["name"] = "Terror of Nagrand", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35101 }, ["description"] = "<The body of a fallen soldier lies here. Blood and gore trail back from the corpse to the entrance of the cave just to the north.> <Judging by the howls and the carnage surrounding the den, something truly terrifying must be in there.>", ["objectivesText"] = "Collect Shagor's Collar from Shagor. Progress: Commander. How may I help you?", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 112620 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81195, ["x"] = 0.56, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81193, ["x"] = 0.494, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35102] = { ["id"] = 35102, ["name"] = "Unleashed Steel", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34569, 34576, 34577, 34579, 34632, 34634, 34635, 34636, 34712, 34814, 34837, 34840, 34855, 34858, 34860, 34870, 34874, 34878, 34879, 34887, 34888, 34889, 34890, 34949, 34971, 34972, 35102 }, ["series"] = { 34569, 34576, 34577 }, ["description"] = "Thank you... boss. I won't let you down! I didn't even try to sneak one of those low quality blades here that one of your peons placed right next to the cage. Which by the way was a pretty terrible idea and that thing should be moved before you get anyone less honorable in here. Enough talk, lets check this place out!", ["objectivesText"] = "Speak to Morketh Bladehowl inside of Vol'jin's Pride in Talador .", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79210, ["x"] = 0.718, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79356, ["x"] = 0.708, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 33, ["name"] = "Establishing your Outpost", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35128] = { ["id"] = 35128, ["name"] = "Fair Warning", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "The ogron here are far from brilliant, but they are more intelligent than the gronn. They're large, and even stronger than they look. Their leader, Borogahn , is especially formidable. Despite several fights, I have not yet managed to kill him. Heed my words, friend. Take caution as you explore their lair. Nisha is ready to move. Ask her to take you to the mouth of the cave, and I'm sure she would be happy to.", ["objectivesText"] = "Kill 8 Ogron Spinecrushers and Borogahn .", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 23265, 23266, 23267, 118022, 118023, 118024, 118025, 118026, 118027, 118028, 118029, 131252 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 80856, ["x"] = 0.46, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 84131, ["x"] = 0.438, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 32, ["flags"] = 0 }, { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 26, ["flags"] = 0 } } },
[35129] = { ["id"] = 35129, ["name"] = "Leave Every Soldier Behind", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "Hmmm. The ogron possess something of value to the Iron Horde. I'm sure they're unaware, likely just bored and in need of something to torture. I'd be inclined to just let them be, it's a fate they deserve. But we can't afford not to follow up on this clue. With any luck, it will help us stop the Iron Horde from turning Gorgrond 's most fearsome creatures into weapons. Try to find this Corporal Thukmar and his notes. We'll meet you there.", ["objectivesText"] = "Find Corporal Thukmar and recover his intel. Progress: Again you've done well, friend.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 113629 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 80856, ["x"] = 0.46, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 84131, ["x"] = 0.438, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 27, ["flags"] = 0 } } },
[35136] = { ["id"] = 35136, ["name"] = "Chains of Iron", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "The artifact we seek is within our grasp. Be prepared for a fight. If they truly have learned how to control gronn, this may be more difficult than I anticipated. I will join you in this battle as soon as you arrive.", ["objectivesText"] = "Defeat Captain Brak and find the Heart of the Magnaron . Progress: The artifact is yours, and is well earned.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112588, 112589, 112590, 112607, 112680 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 84131, ["x"] = 0.438, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 28, ["flags"] = 0 } } },
[35137] = { ["id"] = 35137, ["name"] = "The Sparring Arena", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["series"] = { 34699, 34703, 34704 }, ["description"] = "We owe you our freedom, and more. I have spoken to the others, we are willing to return with you to your garrison and teach those pitiful creatures you call \"soldiers\" how to properly fight. We will also do our best to impart our knowledge to you, Commander. Should you have need of us when in the wilds of Gorgrond , simply call us. You may wish to warn Rangari Jonaa of our coming.", ["objectivesText"] = "Speak with Rangari Jonaa at Highpass in Gorgrond .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 79322, ["x"] = 0.428, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81076, ["x"] = 0.529, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35139] = { ["id"] = 35139, ["name"] = "Eye in the Sky", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "The notes you recovered tell of a device capable of subjugating even a magnaron. Ancient legends speak of such artifacts, crafted by the worldbuilders to keep these creatures in check. I had discounted them as silly stories, but if they are true... <name>, Draenor is doomed. No army will be able to stop them if they harness this power. We must stop them or die trying. Here, I shall bind our sight to Nisha and hope she can locate this artifact.", ["objectivesText"] = "Speak to Nisha . Progress: We are in luck! The artifact is still within reach.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 155377, 159074 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 84131, ["x"] = 0.438, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 84131, ["x"] = 0.438, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 33, ["flags"] = 0 }, { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 29, ["flags"] = 0 } } },
[35144] = { ["id"] = 35144, ["name"] = "Dark Binding", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34271, 34891, 34894, 34932, 34941, 34943, 34964, 34965, 35144, 35145, 35232, 35265, 35317 }, ["description"] = "Even as we speak, the pale within Shadowfall Canyon are enslaving the elements to their will. Many elemental spirits have already been enthralled, and more will follow. The pale must be stopped and the elementals they enslave set free. Journey into Shadowfall Canyon and set free those elemental spirits which are not fully enthralled by the pale. As for the elementals already enslaved by the pale, the only mercy we can give them now is to release their bonds through death.", ["objectivesText"] = "Free 10 elemental spirits. Progress: Have you freed the elemental spirits of Shadowfall Canyon from the dark bonds of the pale?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81335, ["x"] = 0.555, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 553, ["questLines"] = { { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35145] = { ["id"] = 35145, ["name"] = "The Pale Threat", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34271, 34891, 34894, 34932, 34941, 34943, 34964, 34965, 35144, 35145, 35232, 35265, 35317 }, ["description"] = "The Pale are wretched creatures that hide beneath the ground, ever plotting against those who dwell upon the surface. They stalk the Underpale, a twisted and dark cavern beneath Oshu'gun. If we are to succeed in stopping Cho'gall we must fight our way through their ranks beneath the earth. Make your way into the cavern, slay the vile creatures within and take out the Pale leader... the one known as Greyseer .", ["objectivesText"] = "Kill Greyseer and 6 Pale orcs.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 39563 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81335, ["x"] = 0.555, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 553, ["questLines"] = { { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35148] = { ["id"] = 35148, ["name"] = "Trouble at the Overwatch", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34593, 34596, 34951, 34954, 34955, 34956, 34957, 35061, 35062, 35169 }, ["description"] = "Ya know, we sent a couple o' scouts ta check out those big, smelly, 'civilized' ogres at Mar'gok's Overwatch. Haven't heard from 'em in a bit. Matter o' fact, not since I saved yer bacon up at Telaar. Have some time ta ride over there and check up on 'em, <boyo/girly>?", ["objectivesText"] = "Locate Rangari Eleena at Mar'gok's Overwatch.", ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79954, ["x"] = 0.635, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79282, ["x"] = 0.788, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35150] = { ["id"] = 35150, ["name"] = "Trouble at the Overwatch", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34914, 34915, 34916, 34917, 34918, 35097, 35098, 35157, 35158, 35171 }, ["description"] = "Yesterday, I sent two of my best scouts to spy on the ogres at Mar'gok's Overwatch. I haven't heard back from them. <name>, would you do me the honor of checking on them? I'm sure it's nothing; the Overwatch is a large fortification. I'd feel better knowing they're okay.", ["objectivesText"] = "Find Akrosh at Mar'gok's Overwatch.", ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81319, ["x"] = 0.828, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79281, ["x"] = 0.83, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35151] = { ["id"] = 35151, ["name"] = "Your Base, Your Choice", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 33543, 33544, 33548, 33563, 33593, 35151, 36434, 36460 }, ["series"] = { 33593, 36434, 36460 }, ["description"] = "You have already constructed an impressive garrison in Frostfire. I believe I should defer this next choice to you. One region of Gorgrond is rich in resources. A lumber mill could help us make the most of them. Another region harbors hardened gladiators. A sparring arena would help persuade them to fight for our cause. Either path will strengthen us as we seek to find and weaken the Iron Horde. Which do you choose, Commander?", ["objectivesText"] = "Choose to construct either a Lumber Mill or a Sparring Arena at Beastwatch.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 116394 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.737333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 57, ["name"] = "Establish a Foothold", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35152] = { ["id"] = 35152, ["name"] = "The Sparring Arena", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34697, 34698, 34699, 34700, 34702, 34703, 35152, 35505, 35506, 35508, 35524, 35527, 35707 }, ["description"] = "We owe you our freedom, and more. I have spoken to the others, we are willing to return with you to your garrison and teach those pitiful creatures you call \"soldiers\" how to properly fight. We will also do our best to impart our knowledge to you, Commander. Should you have need of us when in the wilds of Gorgrond , simply call us. You may wish to warn Limbflayer of our coming.", ["objectivesText"] = "Speak with Limbflayer at Beastwatch in Gorgrond .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 79320, ["x"] = 0.428, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 76688, ["x"] = 0.462, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35155] = { ["id"] = 35155, ["name"] = "Obliterating Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35155 }, ["description"] = "We got more of those magic tossing ogres here which is never a good thing. These new ogres are especially bossy and have increased work being done here. Do you know what stops ogres from working hard? Dying. Kill some ogres here and get this camp back to its normal boring self.", ["objectivesText"] = "Kill 15 ogres at Mar'gok's Overwatch.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 114683, 114684, 114685, 114686 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79281, ["x"] = 0.83, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81361, ["x"] = 0.838, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.83, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35156] = { ["id"] = 35156, ["name"] = "Removing the Paper Trail", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35156 }, ["description"] = "This box is filled with writings and diagrams that oddly resemble research into the nullification of magic. It would be best to ruin these efforts by destroying any research found.", ["objectivesText"] = "Destroy 8 Boxes of Ogre Research at Mar'gok's Overwatch. Progress: Hey, do you smell smoke?", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81361, ["x"] = 0.838, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35157] = { ["id"] = 35157, ["name"] = "Obtaining Ogre Offensive Orders", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34914, 34915, 34916, 34917, 34918, 35097, 35098, 35150, 35158, 35171 }, ["description"] = "The upper bluff must be really important to the ogres. Two fancy looking ogre mages came down from there and starting ordering all the others around. Go get those orders and meet up with my scout Dalgorsh on the upper bluff. They will be more useful to him up there.", ["objectivesText"] = "Collect Crulgorosh's Orders and Thulgork's Orders at Mar'gok's Overwatch. Progress: Don't forget! Get the orders and take 'em to Dalgorsh further in.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 111065, 111066 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79281, ["x"] = 0.83, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81361, ["x"] = 0.838, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.83, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35158] = { ["id"] = 35158, ["name"] = "Reglakk's Research", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34914, 34915, 34916, 34917, 34918, 35097, 35098, 35150, 35157, 35171 }, ["description"] = "Okay so these orders say Reglakk is in charge of something called Breaker research, which makes super powerful ogres. I don't know about you but that sounds bad. I'm pretty hurt, do you think you can go up there alone and make Reglakk rethink his research?", ["objectivesText"] = "Stop Grand Magister Reglakk's research.", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["rewardItems"] = { 114911, 114912, 114913, 114914, 114915, 114916, 114917, 114918, 120430 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81361, ["x"] = 0.838, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 14, ["flags"] = 0 } } },
[35159] = { ["id"] = 35159, ["name"] = "Removing the Reinforcements", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35159 }, ["description"] = "Its not good $p, these smart ogres have got a portal working up there and they are bringing in more ogres from somewhere else. It looks like it takes a lot of effort to keep it open though. If you take it down I'm guessing they will be delayed quite a while.", ["objectivesText"] = "Destroy the Portal to Highmaul .", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 81361, ["x"] = 0.838, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 }, { ["mapID"] = 550, ["npcID"] = 80140, ["x"] = 0.828, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35166] = { ["id"] = 35166, ["name"] = "Ship Salvage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 582, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["description"] = "Commander, we are running low on supplies. Maybe we can salvage materials from that ship you arrived on? At the rate folks are coming through the portal we are going to be out of everything by sundown... or moondown? I'm still getting used to this place.", ["objectivesText"] = "Collect 15 crates of Drudgeboat Salvage . Progress: Supplies are getting really low, commander.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 112696 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35169] = { ["id"] = 35169, ["name"] = "And Justice for Thrall", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34593, 34596, 34675, 34678, 34682, 34716, 34718, 34719, 34746, 34769, 34951, 34954, 34955, 34956, 34957, 35059, 35060, 35061, 35062, 35148, 35169 }, ["series"] = { 34593, 34596, 34951, 34954, 34955, 34956, 34957, 35061, 35062, 35148 }, ["description"] = "The time has come, commander. You've dealt with all of the Warsong's allies and holdings. Our troops are massing at the gates of Grommashar. The rangari have reliable intel that Garrosh is holed up inside the Warsong fortress. All of our efforts have led to this moment. Let's take out Garrosh.", ["objectivesText"] = "Speak with Vindicator Yrel at the Gates of Grommashar and lead the assault on the Warsong.", ["rewardGold"] = 679200, ["rewardXP"] = 9580, ["rewardItems"] = { 118154, 118155, 118156, 118157 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81412, ["x"] = 0.668, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 27, ["name"] = "Against the Warsong", ["orderIndex"] = 20, ["flags"] = 0 } } },
[35171] = { ["id"] = 35171, ["name"] = "And Justice for Thrall", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34795, 34808, 34818, 34849, 34850, 34866, 34868, 34899, 34914, 34915, 34916, 34917, 34918, 35095, 35096, 35097, 35098, 35150, 35157, 35158, 35171 }, ["series"] = { 34914, 34915, 34916, 34917, 34918, 35097, 35098, 35150, 35157, 35158 }, ["description"] = "The time has come, commander. You've dealt with all of the Warsong's allies and holdings. Our troops are massing at the gates of Grommashar. The shadow hunters have reliable intel that Garrosh is holed up inside the Warsong fortress. All of our efforts have led to this moment. Let's put an end to this once and for all.", ["objectivesText"] = "Speak with Durotan at the Gates of Grommashar and lead the assault on the Warsong.", ["rewardGold"] = 1239200, ["rewardXP"] = 9580, ["rewardItems"] = { 118154, 118155, 118156, 118157 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80003, ["x"] = 0.828, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81415, ["x"] = 0.668, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 28, ["name"] = "Against the Warsong", ["orderIndex"] = 20, ["flags"] = 0 } } },
[35174] = { ["id"] = 35174, ["name"] = "Pale Moonlight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 582, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["description"] = "We are getting strange reports of an orc attack on a nearby draenei settlement called Eventide Landing. I'm hearing these particular orcs are unlike any we have encountered before. They seem... sickly, and are pale in color. The locals could use our help, commander. This seems like the perfect opportunity to test our garrison's capabilities.", ["objectivesText"] = "Kill Gnaw Bloodseeker and 8 Pale Devourers . Progress: Did you see the pale orcs, commander?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 112696 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35176] = { ["id"] = 35176, ["name"] = "Keeping it Together", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 582, ["storyline"] = { 34582, 34583, 34584, 34585, 34586, 34587, 34616, 34646, 34692, 35166, 35174, 35176 }, ["description"] = "So much work to do... I don't even know where to start. Making sure this garrison is operational is not an easy task. Shelly still hasn't reported back to me, my assistant Brightstone and her crew are who knows where, ugh... I'm so caught up I haven't even had time to check our cache for resources. If I were a mage, do you think I could use mirror images to do all of this at once?", ["objectivesText"] = "Speak with Shelly, find Assistant Brightstone , and check the Garrison Cache. Progress: Can we speak a little later, Sir? I don't really have time to talk at the moment.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 112696, 112730, 248810 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 39, ["name"] = "Foothold in a Savage Land", ["orderIndex"] = 11, ["flags"] = 0 } } },
[35202] = { ["id"] = 35202, ["name"] = "Shells for Xuk", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "The magics Xuk is weaving will let you perform great acts, but preparations must be made before the spirits will bless us with their power. Xuk needs many shells from the pesky goren. To gather them, Xuk will share a secret. Approach their tunnel craters and the goren will pour out. This way, you kill many at once.", ["objectivesText"] = "Collect 9 Goren Shells from Boneyard Gorgers. Progress: Xuk Xuk.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112786 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 84743, ["x"] = 0.462, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 84743, ["x"] = 0.462, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 30, ["flags"] = 0 } } },
[35204] = { ["id"] = 35204, ["name"] = "Pollen Power", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35214 }, ["description"] = "The botani use monstrous insect-like creatures to pollinate their bloom. The pollen they carry has a number of powerful properties that would be of use to your garrison forces. If you bring me a reserve of this pollen I should be able to convert it to something of value.", ["objectivesText"] = "Collect 20 Potent Pollen . Progress: Do you have the pollen?", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112909 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81589, ["x"] = 0.46, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81589, ["x"] = 0.46, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35205] = { ["id"] = 35205, ["name"] = "Burn the Bodies", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35207, 35209, 36523 }, ["description"] = "You don't understand. Anythin' these plant people don't infest they fatten up and then turn inta mulch. I say we take out their food source. These botani got a few corpses lying around that I saw. Might be a good idea to burn those bodies. Let's find out if they can infest ash.", ["objectivesText"] = "Burn 6 Mulching Bodies . Progress: If I survive this, I'm gonna get even by becomin' a vegetarian.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112905 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81601, ["x"] = 0.419222, ["y"] = 0.806 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81601, ["x"] = 0.419222, ["y"] = 0.806 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.419222, ["y"] = 0.806 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35206] = { ["id"] = 35206, ["name"] = "Bushwhacker", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["description"] = "We are continuing the search for Thaelin's people, but these botani, they are a larger threat than we ever realized. To infest their victims... monstrous. Please, commander, if you find yourself in Evermorn Springs to our west, slay as many of those creatures as you can. Stop them from committing such acts of horror. Bring them to justice.", ["objectivesText"] = "Slay 7 Bloom Weavers .", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112858, 112859, 112860, 119060, 119068 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81590, ["x"] = 0.46, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81590, ["x"] = 0.46, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 5, ["flags"] = 0 } } },
[35207] = { ["id"] = 35207, ["name"] = "Coalpart's Revenge", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35205, 35209, 36523 }, ["description"] = "I'm so full I can't swing an axe even if I had one. Tell ya what, we got a mutual interest here. I need yer help to get a little vengeance on the big botani at the back of this bloom. In return, I'll point ya in the right direction fer gettin' a secret weapon the botani keep.", ["objectivesText"] = "Slay 3 Dew Masters . Progress: Me mother always said: \"Burrian! Eat yer veggies!\" Going to make her proud today.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81601, ["x"] = 0.419222, ["y"] = 0.806 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81601, ["x"] = 0.419222, ["y"] = 0.806 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.419222, ["y"] = 0.806 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35208] = { ["id"] = 35208, ["name"] = "Dark Iron Down", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35055, 35063, 35212, 35213, 35215, 35828, 36595 }, ["description"] = "While you were away our rangari here found more clues leadin' to some of me other friends. Burrian Coalpart and Scorchbrow. Problem is, their trail heads right for Evermorn Springs to the west. Please Commander, will ya get in there and save them from mulching?", ["objectivesText"] = "Find Burrian Coalpart in Evermorn Springs.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81588, ["x"] = 0.471, ["y"] = 0.863 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81600, ["x"] = 0.42, ["y"] = 0.834 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.863 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 6, ["flags"] = 0 } } },
[35209] = { ["id"] = 35209, ["name"] = "The Life Spring", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35205, 35207, 36523 }, ["description"] = "So we came here cause we needed a weapon we saw the botani using. Hansel grabbed the artifact an' Scorchbrow an' I were supposed to grab the special water the thing runs on. We didn't know that water so full of life forms an elemental. If ya mosey up to the cauldron at the base of that fancy lookin' ancient artifact in Evermorn Springs, you'll be findin' this beast. If ya can kill it and get its water, we can use it when we get the rest of the artifact.", ["objectivesText"] = "Collect Waters of Utrophis . Progress: Now I see why some become Rangari. This is exciting.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112905, 118009, 118010, 118011, 119081, 119090 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81601, ["x"] = 0.419222, ["y"] = 0.806 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81590, ["x"] = 0.46, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.419222, ["y"] = 0.806 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35211] = { ["id"] = 35211, ["name"] = "Preventing the Worst", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["description"] = "Have you seen all the fungus on the buildings in Pinchwhistle Point? It's only a matter of time 'til it releases enough spores to infest the whole coastline! The remaining infected that are in Pinchwhistle Point will be too far gone for us to save later on, so let's do the right thing and put them out of their misery and prevent an even worse outbreak. I made some firebombs that will burn the fungus down, but I'll need you to place them while I set up the detonator. Are you up for it?", ["objectivesText"] = "Place 5 Firebombs within Pinchwhistle Point. Progress: I'm almost done here. Have you placed all those firebombs yet?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533, 118087, 118088, 118089, 118090 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81443, ["x"] = 0.585, ["y"] = 0.922 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81443, ["x"] = 0.585, ["y"] = 0.922 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.922 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35213] = { ["id"] = 35213, ["name"] = "The Razorbloom", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35055, 35063, 35208, 35212, 35215, 35828, 36595 }, ["description"] = "Kaalya thinks she picked up a trail. Seems a bunch of dwarves went north to Razorbloom by the signs. Problem is that place is filled with plant people. I ain't much use against plant people. Are you willing to investigate?", ["objectivesText"] = "Find clues to the whereabouts of Lera Ashtoes , Nori Sootstache, and Razzlebeard .", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112612, 112613, 112614, 112615 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81588, ["x"] = 0.471, ["y"] = 0.863 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81588, ["x"] = 0.471, ["y"] = 0.863 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.863 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35214] = { ["id"] = 35214, ["name"] = "The Infested", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35204 }, ["description"] = "D'kaan did not say it, but there were more rangari taken by the botani than the ones you found. He believes they were slain. I fear worse. You might dare to venture into the Razorbloom. If you do, you may discover what the botani do to their... \"prisoners.\" Give these poor souls a proper release.", ["objectivesText"] = "Slay 6 Infested. Progress: One truth of Gorgrond : death is not the worst thing that can happen to you.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 219934, 232486, 232883, 233450, 233452, 233453, 233458, 233461, 233466, 233468, 233469, 233474, 233477, 233481, 233485, 233530, 235508, 236096 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81589, ["x"] = 0.46, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81589, ["x"] = 0.46, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35215] = { ["id"] = 35215, ["name"] = "The Voice of Iyu", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35055, 35063, 35208, 35212, 35213, 35828, 36595 }, ["description"] = "Journal Entry 25 - The botani got themselves a leader who calls himself... er... herself... er... itself the Voice of Iyu . Seems the botani see the genesaur as gods and only the most bossy of the botani get to speak on behalf of the genesaur. When we tried askin' it about the artifact we found back at the base it got all angry and sent off Lera and Nori and I ain't seen either of them since. I got a bad feelin' about this thing.", ["objectivesText"] = "Slay the Voice of Iyu .", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81588, ["x"] = 0.471, ["y"] = 0.863 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.863 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35216] = { ["id"] = 35216, ["name"] = "Super Seeds", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["description"] = "These seeds have been shielded with care by the botani. Great power can be felt surging out of these tiny vessels of life. These may prove useful.", ["objectivesText"] = "Collect Enriched Seeds . Progress: What have ya found?", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112970 }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81588, ["x"] = 0.471, ["y"] = 0.863 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.863 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35225] = { ["id"] = 35225, ["name"] = "A Heavy Helping Hand", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35234, 35235, 35255, 36575 }, ["description"] = "Burrian gave us the coordinates of the Dark Iron base. They named it Moira's Reach. But half way through buildin' it the base got infested with goren. If you head south you should come to the structure. Just look for a big ol' cannon. We will follow as soon as we get this bloody tank untangled.", ["objectivesText"] = "Find Dark Iron Dwarf survivors.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 6948, 112993 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81588, ["x"] = 0.471, ["y"] = 0.863 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75710, ["x"] = 0.475, ["y"] = 0.94 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.863 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 11, ["flags"] = 0 } } },
[35226] = { ["id"] = 35226, ["name"] = "Old Friends, New Enemies", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33722, 33754, 34683, 34950 }, ["description"] = "I cannot believe Orgrim would continue to do Blackhand's bidding after all the destruction he has wrought. We must confront him. Join me at the village along Orunai Coast and we will confront my oldest friend.", ["objectivesText"] = "Confront Orgrim Doomhammer at the village along Orunai Coast.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75806, ["x"] = 0.615, ["y"] = 0.109 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75958, ["x"] = 0.59, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.109 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35227] = { ["id"] = 35227, ["name"] = "Ogre Diplomacy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 35227 }, ["description"] = "Ogres are ogres. Spirits or not, the Ango'rosh are not different. Even with their ritual books, they won't relinquish their power to you until you prove yourself. I've fought ogres my entire life, and there's only one way to earn that. Killing them outright. The more Ango'rosh spirits and their pets as you take out while you're there, the more respect you'll command among them.", ["objectivesText"] = "Kill 10 Ango'rosh in the Ango'rosh Ruins. Progress: I hope you've extended our diplomatic hand to our ogre friends.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75392, ["x"] = 0.43, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75392, ["x"] = 0.43, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[35229] = { ["id"] = 35229, ["name"] = "Down the Goren Hole", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["description"] = "These beasts came at us so fast we didn't have time to mount a proper defense. They went right for the metal and chewed through any wall we had. If we don't kill some of them soon they'll bring the whole fortress down on us.", ["objectivesText"] = "Slay 5 goren in Moira's Reach. Progress: All in a day's work, eh Commander?", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112867, 112868, 112869, 112870, 112871, 112872, 112873, 112874 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75710, ["x"] = 0.475, ["y"] = 0.94 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75710, ["x"] = 0.475, ["y"] = 0.94 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.94 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 545, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 12, ["flags"] = 0 } } },
[35232] = { ["id"] = 35232, ["name"] = "The Call of Oshu'gun", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34271, 34891, 34894, 34932, 34941, 34943, 34964, 34965, 35144, 35145, 35232, 35265, 35317 }, ["series"] = { 35231 }, ["description"] = "The elements have spoken and a vision has been revealed, <name>. Together we shall travel to the great mountain Oshu'gun and put an end to the dark disturbance there. If what you saw in the vision is to be believed, then great danger awaits us. I will meet you in the Spirit Woods at the foot of Oshu'gun. When you are ready to depart, speak with Gixmo Moneycash and he will fly you there.", ["objectivesText"] = "Fly to the Spirit Woods.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80597, ["x"] = 0.717, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81335, ["x"] = 0.555, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.717, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35233] = { ["id"] = 35233, ["name"] = "Just In Case", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["description"] = "When we set up shop the first thing we built was the cannon. Seemed like a good place fer it. We started buildin' the base up around it when them chompin' acid spittin' varmints came crawlin' out of the ground. The upside though is the cannon is built, just not loaded. We have to go down to the bottom floor of this thing anyway so may as well grab some Doomshot if you see any on your way down. Better to load the cannon and not need it than to need it and not have it loaded.", ["objectivesText"] = "Collect Doomshot . Progress: Ya got that ammo?", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112990, 267209 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75710, ["x"] = 0.475, ["y"] = 0.94 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75710, ["x"] = 0.475, ["y"] = 0.94 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.94 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 13, ["flags"] = 0 } } },
[35234] = { ["id"] = 35234, ["name"] = "Will of the Genesaur", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35225, 35235, 35255, 36575 }, ["description"] = "When the goren attacked we threw everything we had at them but they just kept comin'. So some of the lads went and stole a fancy artifact from the botani. Problem was we couldn't get it to work. Now the artifact is sitting at the bottom of the bastion. To get to it you got to go all the way to the back of the tunnels past all them goren and find the wee tunnel that takes you farther underground. If you retrieve it, it is yours.", ["objectivesText"] = "Recover the Will of the Genesaur . Progress: Not fond of this place. If the plants ain't tryin' to kill you then the ground is tryin' to swallow ya up.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112993 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75710, ["x"] = 0.475, ["y"] = 0.94 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.94 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 14, ["flags"] = 0 } } },
[35235] = { ["id"] = 35235, ["name"] = "Iyu", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35225, 35234, 35255, 36575 }, ["description"] = "Did ya hear that? Sounds like that genesaur wants its 'will' back. I told ya this place is nuthin' but bad luck. I'll git that shot ya gave me loaded properly and see if I can't weaken that thing up. You better get up there and deal with it though...", ["objectivesText"] = "Defeat Iyu . Progress: How goes your search?", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112588, 112589, 112590, 112607 }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75878, ["x"] = 0.476, ["y"] = 0.932 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.932 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 15, ["flags"] = 0 } } },
[35240] = { ["id"] = 35240, ["name"] = "Bled Dry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34422, 34423, 35240, 35242 }, ["description"] = "<The draenei spits out his last words.> They kept us in cages. They... drain our blood, for... rituals... <He coughs violently.> ...many left -- -- my... people... <The draenei dies.>", ["objectivesText"] = "Free the slaves from the 2 Bleeding Hollow Cages in Heartblood. Progress: You should save those draenei, <name>. It is the right thing to do.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 61, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35241] = { ["id"] = 35241, ["name"] = "Vengeance for the Fallen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 17, ["storyline"] = { 34421, 34422, 34423, 35241 }, ["description"] = "Too many of my people have fallen at the hands of the Bleeding Hollow. Their cruelty cannot be forgiven. <The grieving orc looks up at you.> Make them pay.", ["objectivesText"] = "Slay 6 Bleeding Hollow orcs.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 78553, ["x"] = 0.55, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 61, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35242] = { ["id"] = 35242, ["name"] = "Vengeance for the Fallen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 17, ["storyline"] = { 34422, 34423, 35240, 35242 }, ["description"] = "Too many of my people have fallen at the hands of the Bleeding Hollow. Their cruelty cannot be forgiven. <The grieving draenei looks up at you.> Make them pay.", ["objectivesText"] = "Slay 6 Bleeding Hollow orcs.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 113579 }, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 78554, ["x"] = 0.549, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 61, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35245] = { ["id"] = 35245, ["name"] = "A Sentimental Relic", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34998, 34999, 35000, 35001, 35002, 35003, 35004, 35011, 35012, 35013, 35245 }, ["series"] = { 35011, 35013 }, ["description"] = "My father's bangle sat here for ages before that imposter Ikiss stole it away. I thank you for returning it, but I have no need for keepsakes. Take it, with my blessing. If there are still Talonpriests loyal to the true Talon King, please bring it to them.", ["objectivesText"] = "Bring Lithic's Gift to Reshad in Veil Terokk. Progress: Hm? What's that you have there?", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["rewardItems"] = { 113010 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80834, ["x"] = 0.605, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 38, ["name"] = "The Gods of Arak", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35247] = { ["id"] = 35247, ["name"] = "Zero Xuks Given", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["description"] = "The spirits have spoken to me. They believe the magnaron, Gro the Uncreator, will join our fight and lead his underlings against the Iron Horde. This is an honor beyond any bestowed upon a Laughing Skull, at least in my time. I will commune with the magnaron, and together we shall destroy the Iron Horde.", ["objectivesText"] = "Speak with Bony Xuk to observe him communing with Gro the Uncreator.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 84748, ["x"] = 0.438, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85980, ["x"] = 0.44, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 32, ["flags"] = 0 } } },
[35248] = { ["id"] = 35248, ["name"] = "A Harsh Reminder", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 35025, 35026, 35035, 35664, 35665, 35686, 35693, 35730, 35880 }, ["description"] = "Welcome to the front lines, outsider, where the wastelands and the jungle collide. When their forces forget about the ferocity of the Laughing Skull, this is where we come to make them remember. By fierce and merciless destruction we survive. This is the way of Gorgrond . Join in! Let us see if you can withstand the brutality of our land.", ["objectivesText"] = "Kill 8 denizens of the wasteland in Affliction Ridge.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112612, 112613, 112614, 112615 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81202, ["x"] = 0.435, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81202, ["x"] = 0.435, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 33, ["flags"] = 0 } } },
[35249] = { ["id"] = 35249, ["name"] = "Powering the Defenses", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33917, 33970, 33971, 33972, 33976, 33988, 34013, 34092, 34144, 34163, 34164, 34234, 34242, 34326, 34418, 34451, 34508, 34564, 35249 }, ["series"] = { 34351, 34458 }, ["description"] = "It's good to see a Horde champion joining the fight. Auchindoun's defenses are faltering quickly. The few Auchenai soulpriests not on the front are working fervently to maintain them. Soulbinder Tuulani went inside the nearby Tomb of Lights to retrieve a backup power pylon and hasn't returned. If you can find her and get her and the pylon back here safely it would help greatly.", ["objectivesText"] = "Find Soulbinder Tuulani in the Tomb of Lights.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 78577, ["x"] = 0.555, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 31, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35255] = { ["id"] = 35255, ["name"] = "Power of the Genesaur", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35225, 35234, 35235, 36575 }, ["description"] = "Commander, you now have the Will of the Genesaur along with the genesis water and enough seeds to grow an army. Not to mention the lives of the dwarves you saved. I would call this mission a success. I can help the dwarves mop up their operation here and see what we can salvage. In the meantime, you may want to bring the artifact to Maraad back at the outpost.", ["objectivesText"] = "Speak with Vindicator Maraad at Highpass in Gorgrond .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75878, ["x"] = 0.476, ["y"] = 0.932 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75127, ["x"] = 0.6, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.932 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 16, ["flags"] = 0 } } },
[35257] = { ["id"] = 35257, ["name"] = "Power Unearthed", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35257, 35258, 35259, 35260, 35261, 35273, 35634 }, ["series"] = { 35260 }, ["description"] = "What power could reduce a village to ashes in the blink of an eye? The Adherents claim it is the will of Rukhmar. A lie, obviously. They did nothing to earn such power - in truth, they stumbled upon it rather unwittingly, in a hole in the ground. Come and visit me near the excavation site just west of here. We must understand their technology if we are to defeat it.", ["objectivesText"] = "Speak with Darkscryer Raastok near the Apexis Excavation.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 85598, ["x"] = 0.444, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80157, ["x"] = 0.368, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 46, ["name"] = "Legacy of the Apexis", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35258] = { ["id"] = 35258, ["name"] = "Legacy of the Apexis", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35257, 35258, 35259, 35260, 35261, 35273, 35634 }, ["series"] = { 35634 }, ["description"] = "The Apexis are long gone, but their legacy lies preserved in ancient chambers beneath Arak. Legions of dormant constructs; crystals flush with solar energy; magical techniques lost to the ages - the Apexis left behind caches of immense power, which the Adherents of Rukhmar have begun to unearth. Bring me the cores of the re-activated constructs patrolling the excavation site. Those crystals are the basis of Apexis technology, and the key to our enemy's devastating power.", ["objectivesText"] = "Gather 5 Solar Cores from Apexis Guardians. Progress: The Apexis had every advantage, and yet they vanished. What could have happened?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 113081 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80157, ["x"] = 0.368, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80157, ["x"] = 0.368, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 46, ["name"] = "Legacy of the Apexis", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35259] = { ["id"] = 35259, ["name"] = "Sol Sisters", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35257, 35258, 35259, 35260, 35261, 35273, 35634 }, ["series"] = { 35261, 35273 }, ["description"] = "When I was still a guard in Skyreach, I was tasked with protecting the sisters Veoryx and Krashyx. They were prodigies. At an age when most sun acolytes could barely read, the sisters conjured familiars of pure sunlight to illuminate their textbooks in the small hours. Now they unravel the secrets of Apexis technology, and their excavation has just breached two ancient chambers.", ["objectivesText"] = "Slay Sol-Shaper Veoryx and Sol-Shaper Krashyx . Progress: <The Sol-Shapers are using their power to awaken these ancient Apexis constructs.>", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80155, ["x"] = 0.368, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82123, ["x"] = 0.3225, ["y"] = 0.2715 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 46, ["name"] = "Legacy of the Apexis", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35260] = { ["id"] = 35260, ["name"] = "Hardly Working", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35257, 35258, 35259, 35260, 35261, 35273, 35634 }, ["series"] = { 35257 }, ["description"] = "Those who were not incinerated at Veil Akraz are forced to help the Adherents excavate the very weapons aimed at their heads. Anyone trying to escape is vaporized by the overseer's Apexis turret. With these effigies, they won't know anyone has left! Place one near an enslaved worker and observe as it creates a perfect copy. It even cloaks the subject in shadow, so they can slip away safely!", ["objectivesText"] = "Use Illusion Effigies to create decoys for 10 Enslaved Outcasts .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 113084, 114947, 114950, 114951, 119080, 119089, 193373, 199203 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80157, ["x"] = 0.368, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80157, ["x"] = 0.368, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 46, ["name"] = "Legacy of the Apexis", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35261] = { ["id"] = 35261, ["name"] = "Shot-Caller", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35257, 35258, 35259, 35260, 35261, 35273, 35634 }, ["series"] = { 35259, 35273 }, ["description"] = "<Solar energy courses through the slumbering constructs, their ancient servos whirring to life all around you. It is too late to shut them down now. Outside, an arakkoa overseer bellows commands, each answered by the buzz of an Apexis beam carving away at the mountain. That turret would make short work of the constructs - if you can command it.>", ["objectivesText"] = "Retrieve the Apexis Interface from Overseer Akrath. Progress: <A comfortable-looking chair with a socket in the arm rest.>", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 113121 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82123, ["x"] = 0.3225, ["y"] = 0.2715 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.3225, ["y"] = 0.2715 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 46, ["name"] = "Legacy of the Apexis", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35262] = { ["id"] = 35262, ["name"] = "Service of Rangari Kaalya", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35262 }, ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81772, ["x"] = 0.476, ["y"] = 0.932 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 80987, ["x"] = 0.582, ["y"] = 0.56 }, { ["mapID"] = 543, ["npcID"] = 81589, ["x"] = 0.46, ["y"] = 0.766 }, { ["mapID"] = 543, ["npcID"] = 81772, ["x"] = 0.476, ["y"] = 0.932 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.932 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[35265] = { ["id"] = 35265, ["name"] = "The Ritual of Binding", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34271, 34891, 34894, 34932, 34941, 34943, 34964, 34965, 35144, 35145, 35232, 35265, 35317 }, ["description"] = "The time has come for you to undertake the Ritual of Binding, <name>. This ancient, shamanic rite has been practiced since long before I was born. To be chosen is a great honor. Many shaman see vivid elemental visions during the rite; experiencing this world through the very elemental bonds that hold it together. When you are ready, speak with Kalandrios to begin the rite.", ["objectivesText"] = "Speak with Kalandrios to begin the Ritual of Binding. Progress: Tell me of your vision, <name>. What did the elements reveal?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 114680, 114681, 114682, 114699 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80597, ["x"] = 0.717, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80597, ["x"] = 0.717, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.717, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35271] = { ["id"] = 35271, ["name"] = "The Warsong Threat", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35271 }, ["description"] = "<The attack plans are scrawled onto the parchment in thick, black ink and bound in rough leather.> To all outrider stations: The warlord has commanded that all outriders prepare for a full assault upon the Horde invaders in our land. Plans for the attack have been delivered to several of the remote outrider posts. Blood and glory shall be ours as we trample the Horde invaders beneath our feet! The warlord commands and the Warsong obey! Lok'tar ogar!", ["objectivesText"] = "Steal the Warsong Attack Plans . Progress: What do you have for me?", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 113549, 113550, 113551, 113552 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 81193, ["x"] = 0.494, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35272] = { ["id"] = 35272, ["name"] = "One of Our Own", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35272 }, ["series"] = { 35275 }, ["description"] = "Da bird-men captured me while I was gettin' da lay a da land. We been workin' on an outpost for you just round dis mountain so your will be spreadin' all over da continent. Things not be goin' well. I be needin' your assistance, commander. Can you tell dem that I mean no harm so I can be showin' you da outpost?", ["objectivesText"] = "Speak to Shadow-Sage Iskar and convince him to let Shadow Hunter Ukambe free. Progress: You be savin' my hide, commander.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81890, ["x"] = 0.46, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81890, ["x"] = 0.46, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[35273] = { ["id"] = 35273, ["name"] = "Hot Seat", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35257, 35258, 35259, 35260, 35261, 35273, 35634 }, ["series"] = { 35259, 35261 }, ["description"] = "<Apexis constructs are about to emerge from their ancient chambers on a warpath. The arakkoa are sure to send more sol-shapers to support them. The interface and the turret hum in soft resonance.>", ["objectivesText"] = "Use the Overseer's Chair to take control of the Apexis Turret and slay 20 Apexis Destroyers and 30 Adherent Sol-Shapers .", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 114727, 114728, 114729, 114730, 258748 }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80155, ["x"] = 0.368, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 46, ["name"] = "Legacy of the Apexis", ["orderIndex"] = 5, ["flags"] = 0 } } },
[35274] = { ["id"] = 35274, ["name"] = "One of Our Own", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35274 }, ["series"] = { 35276 }, ["description"] = "These wretched creatures captured me while I was scouting the area. Now that you're here, commander, we could really use your help back at base. Oh, and any way you could convince your... friends... to let me go? They, uh... won't let me leave.", ["objectivesText"] = "Speak to Shadow-Sage Iskar and convince him to let Jasper Fel free. Progress: I had really hoped to have given you a better impression when you came out here.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 111957 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81891, ["x"] = 0.458, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81891, ["x"] = 0.458, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[35276] = { ["id"] = 35276, ["name"] = "Inspecting the Troops", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35276 }, ["series"] = { 35274 }, ["description"] = "Southport lies not far from here to the southwest. No time for chit-chat. I will meet you there, commander.", ["objectivesText"] = "Speak to Jasper Fel at Southport.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 111957 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81891, ["x"] = 0.458, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81915, ["x"] = 0.4, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[35277] = { ["id"] = 35277, ["name"] = "Orders, Commander?", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35277 }, ["description"] = "Commander, our status report is... regrettable. We'll be out of supplies in a few days' time, and that's assuming we have any troops left by then. There's just enough material left to put up an inn or a trading post. The inn would allow us to station fresh troops here, but the trading post would open up potential supply routes with the outcasts nearby. I've left out Gazlowe's blueprints on the drafting table . We await your will.", ["objectivesText"] = "Inspect the Drafting Table and choose which outpost structure to construct. Progress: Have you made a choice, commander? Give the word and it will be done.", ["rewardGold"] = 30900, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81920, ["x"] = 0.402, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81920, ["x"] = 0.402, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
