[35285] = { ["id"] = 35285, ["name"] = "Follow that Hotrod!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["series"] = { 35090, 35091 }, ["description"] = "Miss Kimzee is one tough nugget but Pinchwhistle Point is too dangerous for her to handle alone. It'll be a catastrophe for morale if our boss gets infected. I need to get these crewmen back to the Gearworks so I need you to go and make sure she is alright. Her uncle's place is the tower just on the other side of the oil fields; I think you should look for her around there.", ["objectivesText"] = "Find Kimzee Pinchwhistle in Pinchwhistle Point.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81784, ["x"] = 0.59, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81972, ["x"] = 0.584, ["y"] = 0.922 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35286] = { ["id"] = 35286, ["name"] = "Orders, Commander?", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35286 }, ["description"] = "Commander <name>, it's an honor. We're barely holding on, <sir/madame>. We have a week's supplies at best, assuming we have any troops left to supply in that time. We have just enough material left to put up an inn or a trading post. The inn would allow us to station reinforcements here, while the trading post would allow supply routes with the outcasts nearby. We need your authorization for the project, commander. It's your decision.", ["objectivesText"] = "Inspect the Drafting Table and choose which outpost structure to construct. Progress: Glory to your forces, commander.", ["rewardGold"] = 715, ["rewardXP"] = 515, ["rewardItems"] = { 113094, 113096, 116915 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81929, ["x"] = 0.398, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81929, ["x"] = 0.398, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[35293] = { ["id"] = 35293, ["name"] = "Old Friends", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35293, 35329, 35339, 35353, 35380, 35407, 35408, 35482 }, ["series"] = { 35295, 35322, 35329, 35339, 35353 }, ["description"] = "Admiral Taylor was ordered to establish a garrison inland while we erected yours in Shadowmoon Valley. He settled just a short ways north of here. The two of us could go there and borrow some supplies to tide us over before our next shipment. What do you say, commander? I'm sure the admiral will be thrilled to see you again.", ["objectivesText"] = "Speak to Jasper Fel at Admiral Taylor's Garrison.", ["rewardGold"] = 5865, ["rewardXP"] = 515, ["rewardItems"] = { 113095, 113106, 113122, 113127, 121594, 121595, 121596, 121597, 129986, 129994, 130002, 130013, 237812 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81949, ["x"] = 0.398, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81960, ["x"] = 0.392, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 35, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35295] = { ["id"] = 35295, ["name"] = "What's Theirs is Ours", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35295, 35322, 36183 }, ["series"] = { 35293, 35322, 35329, 35339, 35353 }, ["description"] = "I found somethin' else while I was scoutin', boss. Da Alliance have a garrison just across da way, and der been no movement in or out of da place in a good while. Dis be a golden opportunity to sack da place and bolster your coffers, commander. What do ya say? We do it together.", ["objectivesText"] = "Speak to Shadow Hunter Ukambe at Admiral Taylor's Garrison.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 116837 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81959, ["x"] = 0.402, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81961, ["x"] = 0.392, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 36, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35298] = { ["id"] = 35298, ["name"] = "Flame On", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["description"] = "Alright <name>, we've saved as many as we could but now we need to make sure this disaster doesn't spread any further. The firebombs are wired up and ready to go. Kimzee just finished work on the flying machine so we're ready to ride back to the Gearworks as soon as we're finished. You've done all the hard work so I think you should get the honors of triggering it.", ["objectivesText"] = "Use the Firebomb Plunger then ride on Kimzee's Flying Machine.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81443, ["x"] = 0.585, ["y"] = 0.922 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82468, ["x"] = 0.615, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.922 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35317] = { ["id"] = 35317, ["name"] = "The Dark Heart of Oshu'gun", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34271, 34891, 34894, 34932, 34941, 34943, 34964, 34965, 35144, 35145, 35232, 35265, 35317 }, ["description"] = "We are not far from the inner chamber, <name>. The truth behind the evil here awaits us. I can project my spirit into the chamber to guide you, but it will be up to you to defeat the evil that lays within. May the wind of Kalandrios guide your arm, the wisdom of Aborius enlighten your faculties, and the flame of Incineratus burn your enemies. May the memory of Gordawg be your shield.", ["objectivesText"] = "Enter the Sanctum of the Naaru.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 118124, 118125, 118126, 118127, 118128, 118129, 118130, 118131 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82070, ["x"] = 0.716, ["y"] = 0.195333 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.195333 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 30, ["name"] = "The Throne of the Elements", ["orderIndex"] = 12, ["flags"] = 0 } } },
[35322] = { ["id"] = 35322, ["name"] = "I See Dead People", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35295, 35322, 36183 }, ["series"] = { 35293, 35295, 35329, 35339, 35353 }, ["description"] = "Everybody here be... dead. Dis architect's spirit not be wantin' to fight us. Even in death he only be wantin' to work. Maybe we can break da haze over him and get to da bottom of dis. I bet one of da spectral laborers be havin' one of his schematics we can show to him to clear his mind.", ["objectivesText"] = "Retrieve Bryan Finn's Schematic from Spectral Laborers. Progress: I'd recognize one of my schematics anywhere.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 113095 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81961, ["x"] = 0.392, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82100, ["x"] = 0.39, ["y"] = 0.488 }, { ["mapID"] = 542, ["npcID"] = 82101, ["x"] = 0.39, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 36, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35329] = { ["id"] = 35329, ["name"] = "I See Dead People", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35293, 35329, 35339, 35353, 35380, 35407, 35408, 35482 }, ["series"] = { 35293, 35295, 35322, 35339, 35353 }, ["description"] = "Th... they're ghosts! All of them! Bryan was one of my best friends. Something is clouding his mind; we need to snap him out of it and get to the bottom of this! He was always obsessed with his work. Maybe showing him one of his schematics would help. One of the spectral laborers might have one.", ["objectivesText"] = "Retrieve Bryan Finn's Schematic from Spectral Laborers. Progress: I'd recognize one of my schematics anywhere.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 113095, 113106, 113122, 113127 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81960, ["x"] = 0.392, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82100, ["x"] = 0.39, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 35, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35330] = { ["id"] = 35330, ["name"] = "The Ritual of Binding", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["description"] = "It is time for you to undergo the Ritual of Binding, <name>. I will wait here as you speak with Kalandrios to begin the rite. During the ritual, you will experience the vision of the elements. Return to me when the ritual is complete, and we will speak more.", ["objectivesText"] = "Speak with Kalandrios to begin the Ritual of Binding. Progress: Speak to me of your vision, <name>. What mysteries did you behold?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 114680, 114681, 114682, 114699 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82138, ["x"] = 0.717, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82138, ["x"] = 0.717, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.717, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35331] = { ["id"] = 35331, ["name"] = "Called to the Throne", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["series"] = { 35332 }, ["description"] = "I was far from here in Talador when the voice called out to me. I looked around but found myself alone. Again, I heard the voice as if it were a breeze in my mind. \"You are needed at the throne,\" it whispered. The voice called itself Kalandrios, and it guided me to this place. I had never been here before, nor had I yet beheld these furies with my eyes; yet this feels strangely familiar to me as if it happened long ago in a forgotten dream. We should greet the furies and hear them out.", ["objectivesText"] = "Commune with the furies at the Throne of Elements. Progress: Are you ready to commune with the elemental spirits of the throne?", ["rewardGold"] = 30900, ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82138, ["x"] = 0.717, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82138, ["x"] = 0.717, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.717, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35332] = { ["id"] = 35332, ["name"] = "Nobundo Sends Word", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["series"] = { 35331 }, ["description"] = "Your presence has been requested at the Throne of Elements, <name>. Vindicator Nobundo has heard the call of the furies upon the wind and made the journey to commune with the elements. I know not what the intentions of the furies are, but they are revered as noble and powerful spirits by the orcs.", ["objectivesText"] = "Find Vindicator Nobundo at the Throne of Elements.", ["rewardGold"] = 28090, ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82138, ["x"] = 0.717, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35333] = { ["id"] = 35333, ["name"] = "Elemental Attunement", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["description"] = "Even now, as we speak, the voice of Kalandrios continues to whisper to my mind. \"The Hero of Azeroth must attune to the elements of the plateau.\" Upon the Elemental Plateau are four great pillars carved of living rock. Lay your hands upon the stone pillars and your soul will be attuned with the elements. I will continue to commune with the great furies and attempt to further understand their will while you journey to the plateau.", ["objectivesText"] = "Attune to the four elemental pillars.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82138, ["x"] = 0.717, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82138, ["x"] = 0.717, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.717, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35339] = { ["id"] = 35339, ["name"] = "A Parting Favor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35293, 35329, 35339, 35353, 35380, 35407, 35408, 35482 }, ["series"] = { 35293, 35295, 35322, 35329, 35353 }, ["description"] = "I don't know what happened. My crew and I must have been the first to fall. My wife, the innkeeper, is in the same stupor you found me in. I can feel it... and there are others with her. Please, give the townsfolk peace and show their essences to my wife. That should bring her back from that cold abyss.", ["objectivesText"] = "Gather 6 Spectral Essences from restless spirits inside the garrison and use them to convince Alice Finn of her fate. Progress: Everything is so hazy... what happened? Who are you?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 113095, 113106, 113122, 113127, 114835 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82100, ["x"] = 0.39, ["y"] = 0.488 }, { ["mapID"] = 542, ["npcID"] = 82101, ["x"] = 0.39, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82124, ["x"] = 0.376, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 35, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 36, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35353] = { ["id"] = 35353, ["name"] = "A Piece of the Puzzle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35293, 35329, 35339, 35353, 35380, 35407, 35408, 35482 }, ["series"] = { 35293, 35295, 35322, 35329, 35339 }, ["description"] = "I... I remember now. Watch Commander Branson told us to stay in the inn... he said we would be safe here. Then... Then that THING broke through and slaughtered everyone! The last thing I remember seeing was it descending into the larder.", ["objectivesText"] = "Kill the Horrific Aberration in the basement of the inn. Progress: Is the creature dead?", ["rewardGold"] = 210675, ["rewardXP"] = 3085, ["rewardItems"] = { 113095, 113106, 113122, 113127, 114958, 211279 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82124, ["x"] = 0.376, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82126, ["x"] = 0.375, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 35, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 36, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35372] = { ["id"] = 35372, ["name"] = "The Call of Oshu'gun", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["series"] = { 35393 }, ["description"] = "The elements have spoken and a vision has been revealed, <name>. Together we shall travel to the great mountain Oshu'gun and put an end to the dark disturbance there. If what you saw in the vision is to be believed, then great danger awaits us. I will meet you in the Spirit Woods at the foot of Oshu'gun. When you are ready to depart, speak with Gixmo Moneycash and he will fly you to there.", ["objectivesText"] = "Fly to the Spirit Woods.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82138, ["x"] = 0.717, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82179, ["x"] = 0.555, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.717, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35380] = { ["id"] = 35380, ["name"] = "Second in Command", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35293, 35329, 35339, 35353, 35380, 35407, 35408, 35482 }, ["series"] = { 35407 }, ["description"] = "Wait... I remember something else. Sir Edward ... he was shouting... looking for someone. I... I can't remember who. There were so many screams...", ["objectivesText"] = "Speak to Sir Edward at Admiral Taylor's Garrison.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 113095, 113106, 113122, 113127 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82126, ["x"] = 0.375, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82194, ["x"] = 0.376, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 35, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 36, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35386] = { ["id"] = 35386, ["name"] = "The Warsong Threat", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35386 }, ["description"] = "<The attack plans are scrawled onto the parchment in thick, black ink and bound in rough leather.> To all outrider stations: The warlord has commanded that all outriders prepare for a full assault upon the Alliance invaders in our land. Plans for the attack have been delivered to several of the remote outrider posts. Blood and glory shall be ours as we trample the Alliance invaders beneath our feet! The warlord commands and the Warsong obey! Lok'tar ogar!", ["objectivesText"] = "Steal the Warsong Attack Plans . Progress: What do you have for me?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 113549, 113550, 113551, 113552 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82252, ["x"] = 0.62, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35395] = { ["id"] = 35395, ["name"] = "The Fate of Gordawg", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["description"] = "Looming monstrously between us and the inner chamber is the great fury we have sought to return to the Throne of Elements. Gordawg stands before us enthralled; a slave to Cho'gall. My heart is heavy with grief to see such a great creature mindless and enslaved by evil. There is no going back, in order to push forward you must go through Gordawg. It pains me, but Gordawg must be slain. Slay Gordawg and return the fury's heart to the Throne of Elements where it belongs.", ["objectivesText"] = "Retrieve the Heart of the Fury . Progress: What of Gordawg? Has the great fury been brought to rest?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 113077 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80595, ["x"] = 0.726, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 11, ["flags"] = 0 } } },
[35396] = { ["id"] = 35396, ["name"] = "The Dark Heart of Oshu'gun", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["description"] = "Amongst the timeworn wreckage of the Genedar is the entrance to the vessel's inner chamber. The void energy appears to be most concentrated in that place. You must enter the inner chamber and face whatever evil lurks within. I fear whatever fate may have befallen the great naaru K'ure in that place, but regardless the evil there must be purged. May the Light be with you, <name>.", ["objectivesText"] = "Enter the Sanctum of the Naaru.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 118124, 118125, 118126, 118127, 118128, 118129, 118130, 118131, 245425, 251330, 251477, 251548, 251549, 251640, 251653, 251654 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82214, ["x"] = 0.715, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 12, ["flags"] = 0 } } },
[35397] = { ["id"] = 35397, ["name"] = "The Pale Threat", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["description"] = "If we are to succeed in stopping Cho'gall from destroying the naaru, we will need to fight our way through the Underpale; a dark, winding cavern infested with the Pale. The Pale are fallen orcs that despise all that is good and holy. The longer they are left to their devices beneath the ground, the further their dark plots progress. Make your way into the Underpale, slay the vile creatures within and take out their leader, Greyseer .", ["objectivesText"] = "Kill Greyseer and 6 Pale orcs.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82179, ["x"] = 0.555, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 553, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35398] = { ["id"] = 35398, ["name"] = "Dark Binding", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34894, 34932, 34941, 34943, 35330, 35331, 35332, 35333, 35372, 35395, 35396, 35397, 35398 }, ["description"] = "Even as we speak, the pale are enslaving an army of elementals in Shadowfall Canyon. Many have already been enslaved and if we do not lend our aid, more will follow. Go to Shadowfall Canyon and set free the elemental spirits which are not yet fully enthralled by the pale. As for those already enslaved, the only mercy we can give them now is a swift death.", ["objectivesText"] = "Free 8 elemental spirits.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82179, ["x"] = 0.555, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 553, ["questLines"] = { { ["id"] = 29, ["name"] = "The Throne of the Elements", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35399] = { ["id"] = 35399, ["name"] = "Mossy Fate", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "Your wolf queen will not let me out of her sight. The children of the magnaron may have destroyed my village but it was the children of the genesaur who took my people. The botani and their minions drag our people to the Razorbloom, and if we see them again, it is not as they were in life. You have already helped the Skulls, so I ask your help again. Enter the Razorbloom and search for my people that were recently taken. Perhaps they may even be alive.", ["objectivesText"] = "Search for Torg Earkeeper , Meka the Face Chewer , and Chag the Noseless in Razorbloom.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112612, 112613, 112614, 112615 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74606, ["x"] = 0.448667, ["y"] = 0.723333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74606, ["x"] = 0.448667, ["y"] = 0.723333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.448667, ["y"] = 0.723333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35400] = { ["id"] = 35400, ["name"] = "The Infested", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 36474 }, ["description"] = "I understand Kaz's desire to rescue her people, but her plan is reckless and she is not telling us everything. I came along to make sure she wasn't devising a plan against us and now I see this... this... horror. What did the botani do to these orcs? These infested souls need to be put to rest. Give them peace.", ["objectivesText"] = "Slay 6 Infested Orcs .", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 219934, 232486, 232883, 233450, 233452, 233453, 233458, 233461, 233466, 233468, 233469, 233474, 233477, 233481, 233485, 233530, 235508, 236096 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74593, ["x"] = 0.436857, ["y"] = 0.727429 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74593, ["x"] = 0.436857, ["y"] = 0.727429 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.436857, ["y"] = 0.727429 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35402] = { ["id"] = 35402, ["name"] = "The Voice of Iyu", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "The botani and their wretched minions take and take and take. They want food, they take our land. They want an army, they take our people. It is important to strike fear into the shrubby hearts of these plant people. Look for their leader, the Voice of Iyu . It is a botani who speaks on behalf of their genesaur master. Kill their precious leader in the safety of his precious bloom.", ["objectivesText"] = "Slay the Voice of Iyu .", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74606, ["x"] = 0.448667, ["y"] = 0.723333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74606, ["x"] = 0.448667, ["y"] = 0.723333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.448667, ["y"] = 0.723333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35406] = { ["id"] = 35406, ["name"] = "Super Seeds", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "These seeds have been shielded with care by the botani. Great power can be felt surging out of these tiny vessels of life. These may prove useful.", ["objectivesText"] = "Collect Enriched Seeds . Progress: What have you found?", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112970 }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74606, ["x"] = 0.448667, ["y"] = 0.723333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.448667, ["y"] = 0.723333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35407] = { ["id"] = 35407, ["name"] = "Punishable by Death", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35293, 35329, 35339, 35353, 35380, 35407, 35408, 35482 }, ["series"] = { 35380 }, ["description"] = "Traitors, the lot! You're looking at the last bastion of forces still loyal to Admiral Taylor and the Alliance. I'll be damned if the defectors get away clean. You look like you're ready. Show them how we deal with their kind during times of war.", ["objectivesText"] = "Kill 8 garrison traitors.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82194, ["x"] = 0.376, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82194, ["x"] = 0.376, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 35, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 36, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 5, ["flags"] = 0 } } },
[35408] = { ["id"] = 35408, ["name"] = "Prime the Cannons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35293, 35329, 35339, 35353, 35380, 35407, 35408, 35482 }, ["description"] = "The armory is lost to the traitors. All we have left are these few cannons with no ammunition. Soldier, I need you to recover cannonballs so we can get these things running. Actually, one more cannon wouldn't hurt, either.", ["objectivesText"] = "Recover 10 Ironcoat Cannonballs and 1 Armory Cannon . Progress: I hope you're toting a cannon and some balls, soldier.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 113095, 113106, 113122, 113127, 119348 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82212, ["x"] = 0.376, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82212, ["x"] = 0.376, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 35, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 36, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 6, ["flags"] = 0 } } },
[35416] = { ["id"] = 35416, ["name"] = "Power of the Genesaur", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "Commander, you now have the Will of the Genesaur along with the genesis water and enough seeds to grow an army. Not to mention the Laughing Skulls you helped save. I would call this mission a success. I will investigate this fortress further and see if there are more materials we might glean from it. In the meantime, you may want to bring these artifacts you have obtained to Durotan back at the outpost. I will catch up once we have finished here.", ["objectivesText"] = "Speak with Durotan at Beastwatch in Gorgrond .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82337, ["x"] = 0.476, ["y"] = 0.932 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.932 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35429] = { ["id"] = 35429, ["name"] = "Pollen Power", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["description"] = "Those of us who grew up in Gorgrond have long learned a few secrets of the botani that can be used to grow our own plants. There is no such thing as a hungry Laughing Skull for this reason. The ravagers are the key. Outside of Evermorn Springs you will find ravagers of every type. Slay them and bring me the pollen they carry, and I can cultivate it to be of use to your garrison.", ["objectivesText"] = "Collect 20 Potent Pollen . Progress: Few dare challenge the botani in the field of growing plants.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112909 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74606, ["x"] = 0.448667, ["y"] = 0.723333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82228, ["x"] = 0.42, ["y"] = 0.858 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.448667, ["y"] = 0.723333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 5, ["flags"] = 0 } } },
[35430] = { ["id"] = 35430, ["name"] = "Cutter", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "You found many Laughing Skulls. All friends, all loved, all dead. But you did not find my precious Cutter . They must have taken him to Evermorn Springs. Find him, and rescue him. He is a good boy, and deserves a better death than infesting. I am going to round up some ravagers and take the place by air. Look for me in Evermorn if you find Cutter before I do.", ["objectivesText"] = "Find Cutter .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74606, ["x"] = 0.448667, ["y"] = 0.723333 }, { ["mapID"] = 543, ["npcID"] = 82228, ["x"] = 0.42, ["y"] = 0.858 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82254, ["x"] = 0.436, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.448667, ["y"] = 0.723333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 6, ["flags"] = 0 } } },
[35432] = { ["id"] = 35432, ["name"] = "Bushwhacker", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 35433 }, ["description"] = "Kaz is using us, I am sure of it. She is a Laughing Skull and must NOT be trusted. For now, I am willing to play along until we can learn more. Kaz is going to ask for you to travel to Evermorn Springs. When there, I recommend you slay any botani you encounter. Culling the numbers of these horrific casters will hopefully save future orcs from such a infested fate. I will stay with Kaz and keep a close eye on her.", ["objectivesText"] = "Slay 7 Bloom Weavers .", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112858, 112859, 112860, 119060, 119068 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74593, ["x"] = 0.436857, ["y"] = 0.727429 }, { ["mapID"] = 543, ["npcID"] = 82233, ["x"] = 0.42, ["y"] = 0.858 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82233, ["x"] = 0.42, ["y"] = 0.858 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.436857, ["y"] = 0.727429 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35433] = { ["id"] = 35433, ["name"] = "Cut Them Down", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 35432 }, ["description"] = "They steal children? Children?! Had you not rescued Kaz's child, he would be reduced to mulch just like the others. You should send them a message they will understand. Cut down their great dew casters. Rip them apart. Let them know that it is not okay to take our children.", ["objectivesText"] = "Slay 3 Dew Masters .", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82233, ["x"] = 0.42, ["y"] = 0.858 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82233, ["x"] = 0.42, ["y"] = 0.858 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.858 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35434] = { ["id"] = 35434, ["name"] = "The Life Spring", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "It sounds like these... \"dwarves\"... you found managed to steal a powerful botani artifact. But the fools didn't know they need a special water to power it. To the north is a well along the Evermorn Rise. There you will find a guardian, a creature of water we have named Utrophis. Slay it and take its essence and you will be one step closer to claiming the power of the botani and their genesaur.", ["objectivesText"] = "Collect the Waters of Utrophis . Progress: For years the Laughing Skull would not touch the sacred waters. We feared the wrath of the botani. We should have set them to burn long ago.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112905, 118009, 118010, 118011, 119081, 119090 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82228, ["x"] = 0.42, ["y"] = 0.858 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82228, ["x"] = 0.42, ["y"] = 0.858 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.858 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35444] = { ["id"] = 35444, ["name"] = "The Southern Wilds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 35444 }, ["description"] = "First the Iron Horde, then the Shadowmoon orcs, and now there's trouble brewing to the south! My brother is a feyrider to the south, at the Draakorium. He says that creatures from the swamp are venturing onto our lands. What is this world coming to? Anyway, you look like a seasoned adventurer. If you are heading that way, would you mind checking in over there?", ["objectivesText"] = "Speak to Prelate Reenu at The Draakorium.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 82256, ["x"] = 0.49, ["y"] = 0.380667 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 76200, ["x"] = 0.57, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.380667 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[35482] = { ["id"] = 35482, ["name"] = "Admiral Taylor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35293, 35329, 35339, 35353, 35380, 35407, 35408, 35482 }, ["description"] = "Admiral Taylor had figured out who was behind all this. He told us to save who we could... he wanted to handle matters himself. We never heard from him again, but we have our orders. Please... please find him. He went towards the farm.", ["objectivesText"] = "Find Admiral Taylor at Admiral Taylor 's Farm.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 111957, 113095, 113106, 113122, 113127, 114945, 118079, 118080, 118081, 118082, 118083, 118084, 118085, 118086, 119348 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82278, ["x"] = 0.376, ["y"] = 0.538 }, { ["mapID"] = 542, ["npcID"] = 82293, ["x"] = 0.376, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82375, ["x"] = 0.368, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 35, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35487] = { ["id"] = 35487, ["name"] = "We Burn the Dead", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "I saw lots of bodies here. Kaz always said to burn the bodies. That way they can't come back as the mean greens. We should burn the bodies.", ["objectivesText"] = "Burn 6 Bodies. Progress: Hee hee.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82254, ["x"] = 0.436, ["y"] = 0.84 }, { ["mapID"] = 543, ["npcID"] = 82274, ["x"] = 0.427538, ["y"] = 0.811077 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82274, ["x"] = 0.427538, ["y"] = 0.811077 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35501] = { ["id"] = 35501, ["name"] = "Doomshot", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 545, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["description"] = "This ominously large explosive appears to be ammunition for the primary cannon that the Bastion is built around. The loading assembly must be on a lower floor, but this ammo did not make it that far.", ["objectivesText"] = "Collect 4 Doomshot . Progress: This loader can take a number of rounds of doomshot at a time.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112990 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 545, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 11, ["flags"] = 0 } } },
[35505] = { ["id"] = 35505, ["name"] = "Lost Lumberjack", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34697, 34698, 34699, 34700, 34702, 34703, 35152, 35505, 35506, 35508, 35524, 35527, 35707 }, ["series"] = { 35654 }, ["description"] = "Me friend was in the mole machine wit' me. Good ol' Frenna tried to make the best of it by writin' all o' her observations down in a journal. Penny here wants me to tell ya where she is. I cannae say for sure, but she was followin' me outta here and I don't think she made it.", ["objectivesText"] = "Find Frenna within Tangleheart.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 84811, ["x"] = 0.5465, ["y"] = 0.6935 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82569, ["x"] = 0.57, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.5465, ["y"] = 0.6935 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35506] = { ["id"] = 35506, ["name"] = "Growing Wood", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34697, 34698, 34699, 34700, 34702, 34703, 35152, 35505, 35506, 35508, 35524, 35527, 35707 }, ["description"] = "I found this dwarf, Thuldren, runnin' out of Tangleheart like his boots were on fire. Says his mole machine showed up here and he barely made it out alive. And another called Frenna might still be inside. One useful thing he told me is that the creatures in there have sap that can be used to grow things real fast. By the way, I'm gonna go lookin' for Thuldren's mole machine. Find me in Tangleheart when you're done.", ["objectivesText"] = "Collect 100 Ancient Growth Sap from botani or ancients within Tangleheart. Progress: Don't be such a sap. Get it?!", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112616, 112617, 112618, 112619, 113136 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82574, ["x"] = 0.582, ["y"] = 0.681 }, { ["mapID"] = 543, ["npcID"] = 85077, ["x"] = 0.464, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82574, ["x"] = 0.582, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35507] = { ["id"] = 35507, ["name"] = "Down the Goren Hole", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "Dwarves are dumb. Don't they know that if you dig a deep hole you are going to have goren attack? If you are going to go into that iron fort you better kill a bunch of goren otherwise they are going to chew the walls enough to cause a cave-in. I would do it myself but I'm still stuffed from all that fruit the botani made me eat.", ["objectivesText"] = "Slay 7 goren in Moira's Bastion. Progress: Goren like to chew things. I HATE THAT!", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112867, 112868, 112869, 112870, 112871, 112872, 112873, 112874 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 85601, ["x"] = 0.464, ["y"] = 0.935 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85601, ["x"] = 0.464, ["y"] = 0.935 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.935 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 12, ["flags"] = 0 } } },
[35508] = { ["id"] = 35508, ["name"] = "Chapter I: Plant Food", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34697, 34698, 34699, 34700, 34702, 34703, 35152, 35505, 35506, 35508, 35524, 35527, 35707 }, ["description"] = "There are strange, glowing objects within Tangleheart, seemingly pollinated by a variety of stinging creature. The botani sometimes collect whatever the pods produce. I can't be sure what it is, but it might be dangerous to us. - Frenna", ["objectivesText"] = "Destroy 8 Pollen Pods .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82569, ["x"] = 0.57, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82574, ["x"] = 0.582, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35509] = { ["id"] = 35509, ["name"] = "Will of the Genesaur", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "I am pretty sure those dwarves took the artifact in that iron fort there. Are you going to go get it?", ["objectivesText"] = "Recover the Will of the Genesaur . Progress: Kaz said she wants me to hide for this fight.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112993 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 85601, ["x"] = 0.464, ["y"] = 0.935 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.935 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 545, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 13, ["flags"] = 0 } } },
[35510] = { ["id"] = 35510, ["name"] = "Iyu", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "There is a genesaur here! It wants its artifact back. Kaz and Draka are fighting it now on the surface but they need you. Draka said I could fire the big gun. So I will stay here and do that.", ["objectivesText"] = "Defeat Iyu . Progress: Was the shaman being truthful?", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112588, 112589, 112590, 112607 }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82337, ["x"] = 0.476, ["y"] = 0.932 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.932 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 14, ["flags"] = 0 } } },
[35511] = { ["id"] = 35511, ["name"] = "Kaz the Shrieker", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35511 }, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82338, ["x"] = 0.476, ["y"] = 0.932 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74606, ["x"] = 0.448667, ["y"] = 0.723333 }, { ["mapID"] = 543, ["npcID"] = 82338, ["x"] = 0.476, ["y"] = 0.932 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.932 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[35524] = { ["id"] = 35524, ["name"] = "Chapter III: Ritual of the Charred", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34697, 34698, 34699, 34700, 34702, 34703, 35152, 35505, 35506, 35508, 35524, 35527, 35707 }, ["description"] = "I have seen a strange ritual performed by ancients. They step into fire, burning the leaves from their branches and charring their bark. I call it the Ritual of the Charred. If we want to weaken the ancients, we can get rid of them before they become even stronger. - Frenna", ["objectivesText"] = "Kill 4 Ancients.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82569, ["x"] = 0.57, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82574, ["x"] = 0.582, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 11, ["flags"] = 0 } } },
[35527] = { ["id"] = 35527, ["name"] = "Chapter II: The Harvest", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34697, 34698, 34699, 34700, 34702, 34703, 35152, 35505, 35506, 35508, 35524, 35527, 35707 }, ["description"] = "I have seen a creature working with the ancient saplings, imbuing them with anger and hatred toward creatures unlike them. Perhaps it is this botani who is responsible for the unusually aggressive nature of ancients here in Tangleheart. Would killing this botani do us good? I fear I would be no match for it alone. - Frenna", ["objectivesText"] = "Kill Ontogen the Harvester .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82569, ["x"] = 0.57, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82574, ["x"] = 0.582, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 12, ["flags"] = 0 } } },
[35536] = { ["id"] = 35536, ["name"] = "Secrets of the Botani", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "The botani must have stuck that big ogron there to protect something fancy. And what was that stumpy looking creature that it killed? The botani are mean, but they have some fun toys. Maybe Kaz might know what it was. Can we go find Kaz now? I saw a compost heap up the south hill. If Kaz came looking for me I bet she would start there.", ["objectivesText"] = "Escort Cutter to Kaz the Shrieker at the Compost Heap.", ["rewardGold"] = 46350, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82274, ["x"] = 0.427538, ["y"] = 0.811077 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82228, ["x"] = 0.42, ["y"] = 0.858 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.427538, ["y"] = 0.811077 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 15, ["flags"] = 0 } } },
[35549] = { ["id"] = 35549, ["name"] = "Honoring a Hero", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35549 }, ["description"] = "By the Light... I can't believe this happened to Taylor and his men when they had a full garrison. It's going to take everything we have to keep your outpost safe, commander. We should get out of here. We can honor the fallen when we're safe.", ["objectivesText"] = "Speak to Lieutenant Willem at Southport.", ["rewardGold"] = 5865, ["rewardXP"] = 515, ["rewardItems"] = { 20009, 20010, 116442, 116443, 116444, 116445 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82403, ["x"] = 0.368, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81929, ["x"] = 0.398, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[35550] = { ["id"] = 35550, ["name"] = "Surviving in a Savage Land", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35550 }, ["description"] = "Dey may be Alliance, but Admiral Taylor and his men fought with honor on da battlefield. Dey deserve our respect, warchief be praised. If an entire garrison be fallin' to dark magic, our work be cut out for us, eh commander? We should be goin' back to base. It safe there. Safer, anyway.", ["objectivesText"] = "Speak to Taskmaster Gornek at Axefall.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82402, ["x"] = 0.368, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81920, ["x"] = 0.402, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[35552] = { ["id"] = 35552, ["name"] = "Trust No One", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34787, 34789, 34791, 34792 }, ["description"] = "Nothing is the same since I returned. There is always whispering - everywhere, whispering. Maraad cannot see it, but there are even traces of fel energy here in Elodor. We have been infiltrated! I must attend to the Exarch Council, but I need you to investigate. Follow the traces of fel energy that I will illuminate. If there are truly traitors in our midst, they will have to have some sort of hideout. Find it! I will wait for you with the other Exarchs.", ["objectivesText"] = "Follow Maladaar's trail to verify that Elodor has been infiltrated.", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80073, ["x"] = 0.6184, ["y"] = 0.2784 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.6184, ["y"] = 0.2784 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 16, ["flags"] = 0 } } },
[35611] = { ["id"] = 35611, ["name"] = "Return to Veil Terokk", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35611 }, ["series"] = { 34998, 35000, 35001 }, ["description"] = "<A small note is tied to the kaliri's foot.> \" Percy should have brought with him a basket of goods, assuming he didn't dump it off somewhere along the way. The contents are a token of my gratitude and an apology for the altercation with your scout. I must urge you to return to Veil Terokk so we may press forward with our plans. - Reshad \"", ["objectivesText"] = "Speak with Reshad in Veil Terokk.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 79748, ["x"] = 0.465, ["y"] = 0.4005 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.4005 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
