[35634] = { ["id"] = 35634, ["name"] = "Control is King", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35257, 35258, 35259, 35260, 35261, 35273, 35634 }, ["series"] = { 35258 }, ["description"] = "Apexis technology is fascinating, isn't it? Machines powered by solar energy. Energy which itself has been imbued with magic! Simply brilliant! Ah, but there's always a catch. And I think you may have found it. Bring the interface device back to Veil Terokk, will you? I'll be along shortly with the Apexis cores. If my theory is right, we may be able to turn the Adherents' own weapon against them!", ["objectivesText"] = "Bring the Apexis Interface to Darkscryer Raastok in Veil Terokk. Progress: Did you bring the device?", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 115444 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 80157, ["x"] = 0.368, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82509, ["x"] = 0.47, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 46, ["name"] = "Legacy of the Apexis", ["orderIndex"] = 6, ["flags"] = 0 } } },
[35636] = { ["id"] = 35636, ["name"] = "All Due Respect", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35636, 35668, 35671 }, ["series"] = { 34653, 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35537, 35554, 35668, 35671, 36951, 49548, 49566 }, ["description"] = "A group of Adherents came 'round just before the attack on Skettis. Disguised myself as a mushroom, I did. The fools walked right past me. My neighbor up the road was not so lucky. He had a fondness for texts, if I recall. Might be valuable information in his hut, if you give Reshad a moment to rummage around. Oh, and bring one of his feathers to the shrine near Veil Terokk, would you? He was such a dear, and I know it's what he'd want.", ["objectivesText"] = "Retrieve the Feather of Syth and the Saga of Terokk . Progress: Here, I'll take them both for safekeeping.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 29330, 111485, 111524, 111575, 111850, 111892, 113282, 120050 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 79890, ["x"] = 0.516, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82621, ["x"] = 0.502, ["y"] = 0.366 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 34, ["name"] = "Shadows Gather", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35650] = { ["id"] = 35650, ["name"] = "Chapter III: Ritual of the Charred", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["description"] = "I have seen a strange ritual performed by ancients. They step into fire, burning the leaves from their branches and charring their bark. I call it the Ritual of the Charred. If we want to weaken the ancients, we can get rid of them before they become even stronger. - Frenna", ["objectivesText"] = "Kill 4 Ancients.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82569, ["x"] = 0.57, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85130, ["x"] = 0.606, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35651] = { ["id"] = 35651, ["name"] = "Chapter II: The Harvest", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["description"] = "I have seen a creature working with the ancient saplings, imbuing them with anger and hatred toward creatures unlike them. Perhaps it is this botani who is responsible for the unusually aggressive nature of ancients here in Tangleheart. Would killing this botani do us good? I fear I would be no match for it alone. - Frenna", ["objectivesText"] = "Kill Ontogen the Harvester .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82569, ["x"] = 0.57, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85130, ["x"] = 0.606, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35652] = { ["id"] = 35652, ["name"] = "Growing Wood", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["description"] = "We got the lumber mill good an' built, but we be needin' more wood! The Rangari tol' me there's botani usin' some kinda sap to grow ancients fast as you like. Get yer hands on some o' that sap and I betcha I can put it work. What? Oh, Glyza here? Found 'er crashed here and she knows a thing or two about lumberjackin'. I'll take her back to the outpost later. I'll meet ya inside Tangleheart if I can find it.", ["objectivesText"] = "Collect 100 Ancient Growth Sap from botani or ancients. Progress: Glyza is good with tools.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112616, 112617, 112618, 112619, 113136 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82575, ["x"] = 0.558, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85130, ["x"] = 0.606, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35654] = { ["id"] = 35654, ["name"] = "Chapter I: Plant Food", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["series"] = { 35505 }, ["description"] = "There are strange, glowing objects within Tangleheart, seemingly pollinated by a variety of stinging creature. The botani sometimes collect whatever the pods produce. I can't be sure what it is, but it might be dangerous to us. - Frenna", ["objectivesText"] = "Destroy 8 Pollen Pods .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82569, ["x"] = 0.57, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85130, ["x"] = 0.606, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 11, ["flags"] = 0 } } },
[35664] = { ["id"] = 35664, ["name"] = "Seedbearers of Bad News", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35025, 35026, 35035, 35248, 35665, 35686, 35693, 35730, 35880 }, ["description"] = "When these seedbearers are slain their seeds survive. From them spring new seedbearers, not over years, but hours. Leaving their remains here would soon cause the outpost to be overrun. We have learned that burning their remains prevents this from happening.", ["objectivesText"] = "Burn 5 Ancient Seedbearer corpses. Progress: These creatures employ unusual tactics.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 114967 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 18, ["flags"] = 0 } } },
[35665] = { ["id"] = 35665, ["name"] = "We Have Company", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35025, 35026, 35035, 35248, 35664, 35686, 35693, 35730, 35880 }, ["description"] = "Commander, I've spotted Iron Horde soldiers nearby. It is bold, even for them, to venture into such deadly territory. If we do not deal with their presence, they will surely be a threat to your camp. While I scout deeper into the canyons, may I request your help in investigating the camp?", ["objectivesText"] = "Investigate the Iron Horde camp in Sulfur Basin.", ["rewardGold"] = 87975, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82832, ["x"] = 0.442, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 20, ["flags"] = 0 } } },
[35668] = { ["id"] = 35668, ["name"] = "Syth's Secret", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35636, 35668, 35671 }, ["series"] = { 34653, 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35537, 35554, 35636, 35671, 36951, 49548, 49566 }, ["description"] = "Our deceased friend here was hiding more than a love of old scrolls and erotic sorcery-fiction. He had something truly valuable. If I'm reading his notes correctly, he claims to have found the Eye of Anzu - Terokk's scrying orb from the days after his fall. We need that orb! The notes say he stashed it in a ravager den just up the road.", ["objectivesText"] = "Retrieve the Eye of Anzu . Progress: To hold such a treasure. I wonder if that Sun-Talon had any idea of the significance?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 111485, 111524, 111575, 111850, 111892, 113282 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82621, ["x"] = 0.502, ["y"] = 0.366 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 34, ["name"] = "Shadows Gather", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35671] = { ["id"] = 35671, ["name"] = "A Gathering of Shadows", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35636, 35668, 35671 }, ["series"] = { 34653, 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35537, 35554, 35636, 35668, 36951, 49548, 49566 }, ["description"] = "Veil Terokk is just ahead. Let us hope the others have made the journey safely.", ["objectivesText"] = "Enter Veil Terokk with Reshad .", ["rewardGold"] = 147500, ["rewardXP"] = 2060, ["rewardItems"] = { 111485, 111524, 111575, 111850, 111892, 113282, 258741 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 80153, ["x"] = 0.4636, ["y"] = 0.4612 }, { ["mapID"] = 542, ["npcID"] = 82720, ["x"] = 0.465, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.470667, ["y"] = 0.455333 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 34, ["name"] = "Shadows Gather", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35686] = { ["id"] = 35686, ["name"] = "Rage and Wisdom", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35025, 35026, 35035, 35248, 35664, 35665, 35693, 35730, 35880 }, ["description"] = "An endless war wages between the creatures of the eastern wilds and the beasts of the western wasteland. Should one side overwhelm the other, all of Draenor would fall at the hand of the victor. I sent Rangari Erdanii to the heart of the battle between these two forces. It is likely that she will need your help, commander.", ["objectivesText"] = "Speak to Rangari Erdanii at Affliction Ridge.", ["rewardGold"] = 156420, ["rewardXP"] = 1045, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75127, ["x"] = 0.6, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 17, ["flags"] = 0 } } },
[35693] = { ["id"] = 35693, ["name"] = "A Harsh Reminder", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35025, 35026, 35035, 35248, 35664, 35665, 35686, 35730, 35880 }, ["description"] = "Welcome to the front lines, commander, where the wastelands and the jungle collide. The battle below rages on, but I believe one side is beginning to overwhelm the other. This cannot be allowed to happen. The gronnlings are gaining an upper hand and must be stopped before they pose a threat to Highpass. I will get closer to the battle while you thin their ranks. Meet me within Affliction Ridge when you are done.", ["objectivesText"] = "Kill 8 denizens of the wasteland in Affliction Ridge.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112612, 112613, 112614, 112615 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 19, ["flags"] = 0 } } },
[35697] = { ["id"] = 35697, ["name"] = "Peace Offering", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35699, 37296, 37326, 37327 }, ["description"] = "We need allies amongst these spires, and quickly. Commander, I believe it would be wise if you sought out aid. There is a lone arakkoa outcast southeast of here living near a ravager nest. The ravagers do not attack him - I suspect he has information on the beasts we may be able to use. I have our last crate of cactus apple surprise ready for you. It is our best shot, <sir/madame>.", ["objectivesText"] = "Deliver the Crate of Cactus Apple Surprise to Dusk-Seer Irizzar in the Spires of Arak . Progress: Any luck, commander?", ["rewardGold"] = 154900, ["rewardXP"] = 2060, ["rewardItems"] = { 11584, 113320 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82691, ["x"] = 0.4, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83463, ["x"] = 0.438, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35699] = { ["id"] = 35699, ["name"] = "Peace Offering", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35697, 37296, 37326, 37327 }, ["description"] = "We could really use an ally to trade with, commander. There's an arakkoa outcast living in the middle of a ravager nest northeast of here... do you think he might ally with us? He must have some sort of secret to keeping those ravagers at bay. I have one last crate of my Northshire Port. Maybe that will help convince him that we're friendly.", ["objectivesText"] = "Deliver the Crate of Northshire Port to Dusk-Seer Irizzar . Progress: Welcome back! How did things go with the arakkoa?", ["rewardGold"] = 154900, ["rewardXP"] = 2060, ["rewardItems"] = { 113333 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82709, ["x"] = 0.395, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83463, ["x"] = 0.438, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 7, ["flags"] = 0 } } },
[35702] = { ["id"] = 35702, ["name"] = "Chains of Iron", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 34558, 34676, 36495, 36576, 37183, 49565, 92692 }, ["description"] = "The artifact we seek is within our grasp. Be prepared for a fight. If they truly have learned how to control gronn, this may be more difficult than I anticipated. I will join you in this battle as soon as you arrive.", ["objectivesText"] = "Defeat Captain Brak and find the Heart of the Magnaron . Progress: We have the artifact, and with it we will make the Iron Horde pay.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112588, 112589, 112590, 112607, 112680 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 84131, ["x"] = 0.438, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75127, ["x"] = 0.6, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 34, ["flags"] = 0 } } },
[35704] = { ["id"] = 35704, ["name"] = "When All Is Aligned", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["series"] = { 36085, 36316 }, ["description"] = "The ravenspeaker acolytes have been equipped with Apexis interfaces, they just need to get close enough. Come, let us take to the skies and secure the Terrace of Dawn. When all is aligned, we shall turn the false suns against one another and the spires shall burn like torches! I look forward to penning your actions into history.", ["objectivesText"] = "Fly upon Ka'alu and kill 80 Adherents.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 114903, 114904, 114905, 114906, 114907, 114908, 114909, 114910, 258745 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 84262, ["x"] = 0.465, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35705] = { ["id"] = 35705, ["name"] = "Best Deals Anywhere", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35706, 35718, 35738, 35766, 35797 }, ["description"] = "Commander, two goblin smugglers - Mixxy and Trixxy Weldblast - came through here recently and went off towards the bog to the east. They had drilling equipment but weren't carrying any weapons, <sir/madame>. I'd bet anything that they'll have materials we'd want, and that they could use some protection in return. Commander, I think seeking them out would be a good idea.", ["objectivesText"] = "Speak to Mixxy Weldblast in Murkbog.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82691, ["x"] = 0.4, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82713, ["x"] = 0.56, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35706] = { ["id"] = 35706, ["name"] = "Sticky Situation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35705, 35718, 35738, 35766, 35797 }, ["description"] = "We were hauling batteries to the excavation site and I crashed my freakin' car! My sister didn't even look back. I took the turn a little fast, so what? It happens! Point is, the batteries went flying everywhere and I'm in no condition to lift them out. So what do you say? Wanna help me out?", ["objectivesText"] = "Retrieve 5 Submerged Batteries. Progress: Do you have the batteries?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 113339 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82713, ["x"] = 0.56, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82713, ["x"] = 0.56, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35707] = { ["id"] = 35707, ["name"] = "Tangleheart", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34697, 34698, 34699, 34700, 34702, 34703, 35152, 35505, 35506, 35508, 35524, 35527, 35707 }, ["description"] = "Hey there, peach. We've got the lumber mill good and ready, but we gotta find a way of choppin' wood fast out here. The Laughing Skull talked about Tangleheart, where the botani grow things quick as a quark. I'm headin' there now.", ["objectivesText"] = "Speak to Penny Clobberbottom outside Tangleheart.", ["rewardGold"] = 210675, ["rewardXP"] = 1045, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 85077, ["x"] = 0.464, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82574, ["x"] = 0.582, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 54, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 13, ["flags"] = 0 } } },
[35708] = { ["id"] = 35708, ["name"] = "Tangleheart", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["description"] = "The Rangari have been here for a tick, and they hear tell from the Laughing Skull o' a place called Tangleheart. Seems some really bad ancients come from there, and botani use a kind o' sap to grow them quickly. I think we could use that for yer outpost. Hey, wood is wood, right? I'll meet ya there.", ["objectivesText"] = "Speak to Glirin outside Tangleheart.", ["rewardGold"] = 210675, ["rewardXP"] = 1045, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 85119, ["x"] = 0.53, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82575, ["x"] = 0.558, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 12, ["flags"] = 0 } } },
[35713] = { ["id"] = 35713, ["name"] = "The Tinkertoss Twins", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35716, 35719, 35739, 35782, 35835, 35878, 35879 }, ["description"] = "Commander, two gnomish smugglers passed by while you were out - Filbert and Dilbert Tinkertoss. They were headed towards the bog to the east. They had all sorts of drilling equipment but didn't seem to have any weapons. What do you think of offering them protection in exchange for some of their materials? I'll jot down where they were headed in case you decide to go.", ["objectivesText"] = "Speak to Filbert Tinkertoss in Murkbog.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82709, ["x"] = 0.395, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82759, ["x"] = 0.562, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 8, ["flags"] = 0 } } },
[35716] = { ["id"] = 35716, ["name"] = "Sticky Situation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35713, 35719, 35739, 35782, 35835, 35878, 35879 }, ["description"] = "A squadron of arakkoa spotted us while we were en route to the excavation site and took out our caravan. My brother made it to safety in the chaos. Lucky son of a tinker. I can't leave without the batteries for our drill, but they all fell into the bog and I can't even get them to budge. Any chance you could retrieve them for me?", ["objectivesText"] = "Retrieve 5 Submerged Batteries. Progress: Any luck?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 113339 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82759, ["x"] = 0.562, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82759, ["x"] = 0.562, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 9, ["flags"] = 0 } } },
[35718] = { ["id"] = 35718, ["name"] = "Back on Track", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35705, 35706, 35738, 35766, 35797 }, ["description"] = "You're a lifesaver, I'll tell you what. Say, how about you go on ahead to the excavation site and let my sister know I'm on my way. I'll get everything neat and tidy and go get a new cart to lug these over.", ["objectivesText"] = "Speak to Trixxy Weldblast in Veil Zekk.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82713, ["x"] = 0.56, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82786, ["x"] = 0.601, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 11, ["flags"] = 0 } } },
[35719] = { ["id"] = 35719, ["name"] = "Back on Track", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35713, 35716, 35739, 35782, 35835, 35878, 35879 }, ["description"] = "Now that the batteries are out of the bog I can radio in some more copters to take them to camp. I'll stay here until they arrive, but you should go ahead to my brother Dilbert and let him know what happened. He must be worried sick!", ["objectivesText"] = "Speak to Dilbert Tinkertoss in Veil Zekk.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82759, ["x"] = 0.562, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82788, ["x"] = 0.601, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 10, ["flags"] = 0 } } },
[35730] = { ["id"] = 35730, ["name"] = "Cauterizing Wounds", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35025, 35026, 35035, 35248, 35664, 35665, 35686, 35693, 35880 }, ["description"] = "You have saved my most precious companion, Nisha . I owe you a great debt. The Iron Horde lured me away to separate us. I shall not make the same mistake again. They have inflicted grievous wounds, and I fear we must cause her even more pain before the healing process can begin. Please use a burning log from the nearby fire to cauterize her wounds. I will hold her down.", ["objectivesText"] = "Use a Burning Log to cauterize Nisha 's wounds. Progress: Nisha must make it through this.", ["rewardGold"] = 254700, ["rewardXP"] = 2090, ["rewardItems"] = { 113398 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82832, ["x"] = 0.442, ["y"] = 0.616 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82832, ["x"] = 0.442, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 34, ["flags"] = 0 } } },
[35733] = { ["id"] = 35733, ["name"] = "Rites of the Talonpriests", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35733, 35734, 35895, 35896, 35897, 36059 }, ["series"] = { 35734, 35897 }, ["description"] = "That gavel was once known as Beakbreaker. In his final, darkest days, Terokk used it to perform grim, damnable acts of sacrifice. It is best not to dwell on those days. Terokk was sealed away deep within the shadows to rest, and perhaps to heal. Making contact with him will take a great deal of effort, so in the meantime, allow me to tell you of his more glorious exploits. Before this wretched curse took hold. Please, place the gavel upon the effigy.", ["objectivesText"] = "Place Terokk's Gavel on the Effigy of Terokk .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82813, ["x"] = 0.465, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.470667, ["y"] = 0.455333 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 47, ["name"] = "Terokk's Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35734] = { ["id"] = 35734, ["name"] = "The Talon King", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35733, 35734, 35895, 35896, 35897, 36059 }, ["series"] = { 35733, 35897 }, ["description"] = "<As Reshad begins reciting a tale of Terokk's glory days, your eyes fall to the twin swords at the effigy's belt. They had seemed so plain in Skettis, but now they thrum with power, as if reacting to the scrollkeeper's words.>", ["objectivesText"] = "Use the Effigy of Terokk to re-live Terokk's battle with the Bloodmane. Slay 30 Bloodmane Shortfangs , 20 Mature Bloodmane saberon, and Pridelord Karash .", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 122283 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82813, ["x"] = 0.465, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 47, ["name"] = "Terokk's Legend", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35738] = { ["id"] = 35738, ["name"] = "All Natural", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35705, 35706, 35718, 35766, 35797 }, ["description"] = "So you have a smuggler's den, huh? I'd love to trade with ya, toots, I really would, but my laser cannon isn't even functional right now. I'll tell you what. See all the ancients around here? They got toasted good by the arakkoa's weapon, and they're practically walking piles of charcoal. Bring me some charcoal to power this thing and you've got a deal.", ["objectivesText"] = "Collect 30 Fresh Charcoal from ancients. Progress: If you've got the stuff, let's talk.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 28069, 28070, 28074, 28075, 113404, 211279, 237812 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82786, ["x"] = 0.601, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82786, ["x"] = 0.601, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 12, ["flags"] = 0 } } },
[35739] = { ["id"] = 35739, ["name"] = "All Natural", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35713, 35716, 35719, 35782, 35835, 35878, 35879 }, ["description"] = "Oh, you have a trading post? Fantastic! Let's make a deal. You help me power up my laser cannon, and I'll trade some of this... thermo... ultra... obsidiglass with you for some weapons. The ancients all around here are practically made of charcoal after the arakkoa weapon hit, you should go get some of that!", ["objectivesText"] = "Collect 30 Fresh Charcoal from ancients. Progress: Blasted refurbished goblin tech is always malfunctioning.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 28069, 28070, 28074, 28075, 113404, 211279, 237812 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82788, ["x"] = 0.601, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82788, ["x"] = 0.601, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 11, ["flags"] = 0 } } },
[35747] = { ["id"] = 35747, ["name"] = "Taking a Trip to the Top of the Tank", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34445, 34446, 35747, 35884 }, ["series"] = { 34445 }, ["description"] = "We cannot risk the reactivation of the Dark Portal. Now is the time for the deathblow. Thaelin should have figured out how to get that tank working by now. Take him with you, and turn that tank against the Dark Portal itself. We will follow behind you.", ["objectivesText"] = "Speak with Thaelin Darkanvil , then escort him to the top of the Iron Worldbreaker.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 65, ["name"] = "Escape From Tanaan", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35766] = { ["id"] = 35766, ["name"] = "I See Dead Arakkoa", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35705, 35706, 35718, 35738, 35797 }, ["description"] = "I've got a strange problem and I'm hoping you might be able to help. I don't know who else could help, to be honest. My workers keep saying they're seeing the ghost of the arakkoa that used to head up this place. I know, I know, it's crazy but could you take my Ghostogrifier 12000 to her body and check? If there's a ghost around here, it'll find it. If there's not, then my workers are trying to slack off on the clock.", ["objectivesText"] = "Use the Ghostogrifier 12000 and kill the spirit of Talonpriest Zekk .", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 113438 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82786, ["x"] = 0.601, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82786, ["x"] = 0.601, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 13, ["flags"] = 0 } } },
[35782] = { ["id"] = 35782, ["name"] = "I See Dead Arakkoa", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35713, 35716, 35719, 35739, 35835, 35878, 35879 }, ["description"] = "Say, while you're here would you mind helping me out with a major problem? The workers keep saying that they're seeing the ghost of the head arakkoa that used to be here. I don't believe it for a second but could you take my Ghostogrifier 12000 to her body and check? If they're not crazy, it'll prove it.", ["objectivesText"] = "Use the Ghostogrifier 12000 and kill the spirit of Talonpriest Zekk .", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 113438 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82788, ["x"] = 0.601, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82788, ["x"] = 0.601, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 12, ["flags"] = 0 } } },
[35797] = { ["id"] = 35797, ["name"] = "The Ebon Hunter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35705, 35706, 35718, 35738, 35766 }, ["description"] = "The laser should be good to go once we get it set up, there's just one more thing I need. There's a spore walker that hunts on the delta just southeast from here. It has an apparatus on its face that can fire a powerful laser - way more powerful than what we have hooked up. I want it. We'll be mining faster than you can imagine once we get that bad boy hooked up!", ["objectivesText"] = "Collect an Organic Laser Apparatus from the Ebon Hunter. Progress: I should probably have mentioned that the laser is pretty... potent.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 113441, 116394 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82786, ["x"] = 0.601, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82786, ["x"] = 0.601, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 14, ["flags"] = 0 } } },
[35834] = { ["id"] = 35834, ["name"] = "Wake of the Genesaur", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35033, 35050, 35055, 35063, 35065, 35828, 35834, 36595 }, ["description"] = "One moment we see a great metal beast rolling into our camp, the next a genesaur follows it and sends a wave of pure chaotic life at us. The manifestations left behind by the genesaur must be culled so we have time to salvage what we can before leaving. If you are here to help, then start killing as many of the violent plants that are assailing us as possible.", ["objectivesText"] = "Slay 9 Wild Overgrowth. Progress: This has not been a good day.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112608, 112609, 112610, 112611 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 80922, ["x"] = 0.642, ["y"] = 0.518 }, { ["mapID"] = 543, ["npcID"] = 80987, ["x"] = 0.582, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 80987, ["x"] = 0.582, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 52, ["name"] = "We Need An Outpost", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35835] = { ["id"] = 35835, ["name"] = "The Ebon Hunter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35713, 35716, 35719, 35739, 35782, 35878, 35879 }, ["description"] = "We're ready to set up the laser, but we're going to need more firepower to cut through this stuff. The Ebon Hunter stalks the delta just southeast from here. It has an apparatus on its face that can fire a laser way stronger than what we have hooked up. We need that. You should go get it while we set up the laser.", ["objectivesText"] = "Collect an Organic Laser Apparatus from the Ebon Hunter. Progress: By the way, that laser is very dangerous. Be careful!", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 113441, 116394 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82788, ["x"] = 0.601, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82788, ["x"] = 0.601, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 13, ["flags"] = 0 } } },
[35870] = { ["id"] = 35870, ["name"] = "Basilisk Butcher", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["description"] = "Basilisk is one of Nisha 's favorite meals. This is where she hunts, and that's likely how those Iron Horde bastards were able to capture her. Why would they go to the trouble to subdue her this way? Perhaps together, you and I might learn the answer as we punish them for their transgressions. For now, Nisha 's going to need some food. While I tend to her, will you do her hunting for her?", ["objectivesText"] = "Collect 9 Basilisk Meat from Stoneshamble Basilisks or Decaying Basilisks. Progress: < Nisha sniffs deeply.>", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 113504 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82832, ["x"] = 0.442, ["y"] = 0.616 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81674, ["x"] = 0.458, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 35, ["flags"] = 0 } } },
[35879] = { ["id"] = 35879, ["name"] = "Safety Measures", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35713, 35716, 35719, 35739, 35782, 35835, 35878 }, ["description"] = "The batteries I lost in the bog have really ticked off the wild creatures. It's going to be impossible to remove them without fighting through who knows what. If you're up for it, why don't you 'take care' of any critters you come across? I don't want some giant beast stalking me back to the excavation site. I'll make it worth your while.", ["objectivesText"] = "Kill 15 bog denizens.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82713, ["x"] = 0.56, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82713, ["x"] = 0.56, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 15, ["flags"] = 0 } } },
[35880] = { ["id"] = 35880, ["name"] = "Rage and Wisdom", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 35025, 35026, 35035, 35248, 35664, 35665, 35686, 35693, 35730 }, ["description"] = "Beasts of the western wasteland fight an endless war with the creatures of the eastern wilds. If one side were to overwhelm the other, all of Draenor would be doomed at the hand of the victor. The Laughing Skull seek revenge for their destroyed village. I have directed them to aim their vengeance at the nearby creatures, that our outpost here might be preserved. If you would, commander, oversee their efforts. I have not yet grown to trust the Laughing Skull.", ["objectivesText"] = "Speak to Bony Xuk at Affliction Ridge.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81202, ["x"] = 0.435, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.737333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 36, ["flags"] = 0 } } },
[35882] = { ["id"] = 35882, ["name"] = "The Interest of Bruto", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35882 }, ["description"] = "You have done me a great service. This blade is as much yours as it is mine. I offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces. Will you accept it?", ["objectivesText"] = "Accept the Blood Oath of Blademaster Na'Shra.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 77014, ["x"] = 0.398, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.654 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
