[35884] = { ["id"] = 35884, ["name"] = "The Home Stretch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34445, 35747, 35884 }, ["description"] = "If they weren't angry before, they sure are now. We won't survive a minute up on top o' this tank! Let's join up with the rest and get out of here!!", ["objectivesText"] = "Escape to the docks.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 65, ["name"] = "Escape From Tanaan", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35895] = { ["id"] = 35895, ["name"] = "Terokk's Fall", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35733, 35734, 35895, 35896, 35897, 36059 }, ["description"] = "<Once again, Reshad 's voice envelops you.> Terokk was a powerful and respected king, beloved by his people. His sages, however, were not so loyal. Hungry for control of Skyreach, they conspired against him.", ["objectivesText"] = "Use the Effigy of Terokk to re-live Terokk's fall. Find Lithic , rally 5 Outcast Talon Guards , slay 20 Crazed Outcasts , and use the Eye of Anzu .", ["rewardGold"] = 339600, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82813, ["x"] = 0.465, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 47, ["name"] = "Terokk's Legend", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35896] = { ["id"] = 35896, ["name"] = "The Avatar of Terokk", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35733, 35734, 35895, 35896, 35897, 36059 }, ["series"] = { 36059 }, ["description"] = "My long sleep was disturbed by dreams of the past. I cut down my old enemies again. I watched my daughter die again. You were there. I felt your presence in these dreams. And your past was revealed to me as well. Someone has woven our fates together. My people are yours to protect, and your enemies are mine to destroy. The Shattered Hand are rallied in Bladefist Hold. Left to their own, they would claim this land for the Iron Horde. Take my power, and together we shall break them.", ["objectivesText"] = "Speak with Shade of Terokk to accept his power. Slay 25 Shattered Hand combatants, 4 Shattered Pit-Masters, and confront Kargath Bladefist . Progress: Take what you have earned, <name>.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 118068, 118069, 118070, 119065, 119073, 258749 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 84122, ["x"] = 0.465333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 47, ["name"] = "Terokk's Legend", ["orderIndex"] = 3, ["flags"] = 0 } } },
[35897] = { ["id"] = 35897, ["name"] = "The Missing Piece", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35733, 35734, 35895, 35896, 35897, 36059 }, ["series"] = { 35733, 35734 }, ["description"] = "Terokk's daughter Lithic was a skilled huntress, but found her true passion in goldsmithing. She forged this bangle as a gift for her father, and he wore it for many years. Only after Lithic passed away did he remove the bangle, for her memory was too much for the old king to bear. Place the bangle upon the effigy, and I shall tell you of Terokk's fall.", ["objectivesText"] = "Place Lithic's Gift on the Effigy of Terokk .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82813, ["x"] = 0.465, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.470667, ["y"] = 0.455333 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 47, ["name"] = "Terokk's Legend", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35905] = { ["id"] = 35905, ["name"] = "Supply Drop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34778, 34779, 34780, 34781, 34782, 34783, 34784, 34785, 34786, 34787, 34788, 34789, 34790, 34791, 34792, 35070, 35552, 35905 }, ["series"] = { 34788 }, ["description"] = "Your laborers below have finished with the harvest and are ready to cart supplies back to your garrison. Don't worry about the safety of your caravan this time; I will dispatch a rangari detail to shadow them from the woods and protect them. The Exarchs will always watch over you. Your supplies should be waiting for you when you return to your garrison. Good luck with your campaign, <name>!", ["objectivesText"] = "Speak with Baros Alexston at your garrison in Shadowmoon Valley .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 139879, 147351, 237812 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 80079, ["x"] = 0.589667, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.589667, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 41, ["name"] = "The Exarch Council", ["orderIndex"] = 17, ["flags"] = 0 } } },
[35907] = { ["id"] = 35907, ["name"] = "Attempted Murder", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35924, 35947, 36022, 36028, 36047, 36166 }, ["description"] = "Your bartender Lunzul is dying, commander. She's been poisoned and needs an antidote immediately. One of your scouts reported seeing a Shattered Hand orc nearby recently - that's our best bet. There is a small arakkoa camp to the east that sits near a known Shattered Hand encampment. I suggest we start our search there. I've already spoken to your flight master about securing us a flight; every second counts.", ["objectivesText"] = "Speak to Hutou Featherwind to secure a flight to Shadow's Vigil.", ["rewardGold"] = 30900, ["rewardXP"] = 515, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83529, ["x"] = 0.4, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83608, ["x"] = 0.52, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35915] = { ["id"] = 35915, ["name"] = "Attempted Murder", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35926, 35959, 36023, 36029, 36048, 36165 }, ["description"] = "Kolrigg is dyin', commander. He's been poisoned and needs an antidote before it's too late. One o' yer scouts reported seein' a Shattered Hand orc nearby not long ago - I wager that's our best shot. There's a small arakkoa camp tae the east that sits near a known Shattered Hand encampment. We should start our search there, <sir/madame>. I've already spoken to yer flight master about flyin' us out; every second counts.", ["objectivesText"] = "Speak to Firn Swiftbreeze to secure a flight to Shadow's Vigil.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 113577, 113587, 113630, 113635, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83549, ["x"] = 0.396, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83609, ["x"] = 0.52, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35924] = { ["id"] = 35924, ["name"] = "Assassin's Mark", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35907, 35947, 36022, 36028, 36047, 36166 }, ["description"] = "Their poison is more powerful than I thought. We need to find the orc responsible for making it. Master assassins always leave their mark somewhere on one of their kills. It's a calling card; a claim to fame in their circles. This was definitely the work of such an assassin. We should split up and see if we can find some sign on one of the outcast corpses that will lead us to their creator. Rendezvous at the bottom of the hill, commander.", ["objectivesText"] = "Search Vigilant Outcast corpses for a Craftsman's Mark. Progress: Any luck? I couldn't find anything.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 21877, 107694, 109254, 111968, 111980, 111986, 113573, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83608, ["x"] = 0.52, ["y"] = 0.235 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83772, ["x"] = 0.535, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35925] = { ["id"] = 35925, ["name"] = "The Gronn Strategy", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["description"] = "Raz, Your orders are to capture four additional gronn for weaponization. Of your first group, only one survived the entire process. One attacked our soldiers relentlessly and had to be put down. Another fell victim to a misfire while being fitted. Yet another rolled onto its cannons in its sleep. We're still cleaning up that mess. Rest assured, your efforts are not in vain. - Captain Brak", ["objectivesText"] = "Show the weaponization orders to Rexxar at Breaker's Crown. Progress: Weaponizing gronn? If they succeed...", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 116909 }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 80856, ["x"] = 0.46, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 29, ["flags"] = 0 }, { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 37, ["flags"] = 0 } } },
[35926] = { ["id"] = 35926, ["name"] = "Assassin's Mark", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35915, 35959, 36023, 36029, 36048, 36165 }, ["description"] = "We need tae find the orc responsible fer makin' the poison tae make an antidote. Master assassins always leave their mark somewhere on one o' their kills. It's a claim tae fame o' sorts. An' trust me, this was the work of a master assassin. Let's split up and see if we can find some sign on one o' the outcast corpses that will lead us tae their killer. I'll meet ye at the bottom o' the hill, commander.", ["objectivesText"] = "Search Vigilant Outcast corpses for a Craftsman's Mark. Progress: Did ye find anything?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 113573, 113574, 113577, 113587, 113630, 113635, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83609, ["x"] = 0.52, ["y"] = 0.235 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83773, ["x"] = 0.535, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35933] = { ["id"] = 35933, ["name"] = "Azeroth's Last Stand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34392, 34393, 34398, 34420, 35933, 36881 }, ["series"] = { 34392, 34393, 34398, 34420, 36881 }, ["description"] = "Countless times you have battled against impossible odds and unspeakable evil - and returned the victor. Now, once more, you have answered the call of duty, prepared to risk your life to save the world that you love - our world. You are Azeroth's last hope, <name>. While the challenges that stand before us are daunting, there is no other that I would trust to lead this mission. The enemy at the front may have the information we need to win this war. Seek and destroy! Go now, <name>! For Azeroth!", ["objectivesText"] = "Collect the Iron Horde Missive from one of the Iron Horde at the base of the Dark Portal.", ["rewardXP"] = 1415, ["rewardItems"] = { 110799, 113579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 60, ["name"] = "The Dark Portal", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35934] = { ["id"] = 35934, ["name"] = "Nisha's Vengeance", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["description"] = "Since I left on my last hunt, the Iron Horde have drawn nearer and reinforced their positions. <A grin spreads across Rexxar 's lips.> They've created a target-rich environment. I must continue nursing Nisha to health for now. You go in my stead, friend. Fill them with the fear and pain that they inflicted on her. Make their screams fill the canyon!", ["objectivesText"] = "Kill 10 Grom'kar Grunts .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 80856, ["x"] = 0.46, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 80856, ["x"] = 0.46, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 38, ["flags"] = 0 } } },
[35947] = { ["id"] = 35947, ["name"] = "The Power of Poison", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35907, 35924, 36022, 36028, 36047, 36166 }, ["description"] = "G.V.? We need a name and a location. Not damned initials. <Velonara pulls out a small vial.> This is my last vial of wracking poison . We use it to extract information from prisoners. It is... potent. Coat your weapon with it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care of the rest. I've had enough of these orcs.", ["objectivesText"] = "Interrogate Shattered Hand orcs in the Harvesting Pits to find out the name and location of \"G.V.\".", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 97919, 107694, 109254, 111968, 111980, 111986, 113587, 116394, 116431, 119001, 137663 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83772, ["x"] = 0.535, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83772, ["x"] = 0.535, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35959] = { ["id"] = 35959, ["name"] = "The Power of Poison", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35915, 35926, 36023, 36029, 36048, 36165 }, ["description"] = "G.V.? We need a full name. A location! I have an idea fer how we can find those out. <Hulda pulls out a small vial.> This is my last vial o' wracking poison. We use it when we need tae extract information from prisoners. Coat yer weapon wi' it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care o' the rest.", ["objectivesText"] = "Interrogate Shattered Hand orcs in the Harvesting Pits to find out the name and location of \"G.V.\".", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 46725, 107694, 109254, 111968, 111980, 111986, 113577, 113587, 113630, 113635, 116394, 116431, 119001, 137663 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83773, ["x"] = 0.535, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83773, ["x"] = 0.535, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 2, ["flags"] = 0 } } },
[36022] = { ["id"] = 36022, ["name"] = "Extrinsic Motivation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35907, 35924, 35947, 36028, 36047, 36166 }, ["description"] = "The Shattered Hand aren't strangers to pain. They each cut off their own hand as a sign of their allegiance to Kargath. If you're going to get them to talk, it might take more than my poison. Slaughter them all. We'll see how far they're willing to go for their beloved warlord.", ["objectivesText"] = "Kill 4 Shattered Sightless, 3 Shattered Harvesters, and 1 Shattered Blood-Singer.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83772, ["x"] = 0.535, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83772, ["x"] = 0.535, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 3, ["flags"] = 0 } } },
