[36028] = { ["id"] = 36028, ["name"] = "Gardul Venomshiv", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35907, 35924, 35947, 36022, 36047, 36166 }, ["description"] = "We need to take out Gardul and take his poison recipe while we still have the element of surprise on our side. We need it to craft the antidote. This may be our only opportunity. If what you learned is true, his camp is just south of here. You take him down, and I'll make sure none of his guards interfere. Let's get moving.", ["objectivesText"] = "Defeat Gardul Venomshiv in Shattered Rise.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83772, ["x"] = 0.535, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83899, ["x"] = 0.568, ["y"] = 0.343333 }, { ["mapID"] = 542, ["npcID"] = 83903, ["x"] = 0.571, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 4, ["flags"] = 0 } } },
