[36047] = { ["id"] = 36047, ["name"] = "We Have Him Now", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35907, 35924, 35947, 36022, 36028, 36166 }, ["description"] = "We have Gardul right where we want him, commander. You're far more equipped to face him than I am. Dispose of him, take his formula from his corpse, and grab as many barrels of poison as you can. I'll guard this ramp and make sure no reinforcements come to his aid.", ["objectivesText"] = "Collect Venomshiv's Secret Formula and 6 Poison Barrels . Progress: Do you have everything we need?", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 113630, 113635, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83899, ["x"] = 0.568, ["y"] = 0.343333 }, { ["mapID"] = 542, ["npcID"] = 83903, ["x"] = 0.571, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83903, ["x"] = 0.571, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.343333 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 5, ["flags"] = 0 } } },
[36048] = { ["id"] = 36048, ["name"] = "We Have Him Now", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35915, 35926, 35959, 36023, 36029, 36165 }, ["description"] = "We have Gardul right cornered, commander. Ye have a much better chance against him than me. Take him out, grab the formula from his corpse, and grab as many barrels o' poison as ye can carry. I'll stay here and make sure nae reinforcements come to Gardul's aid.", ["objectivesText"] = "Collect Venomshiv's Secret Formula and 6 Poison Barrels . Progress: I don't want to stick around here any longer than we need to.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 113577, 113587, 113630, 113635, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83900, ["x"] = 0.567333, ["y"] = 0.342667 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 83900, ["x"] = 0.567333, ["y"] = 0.342667 }, { ["mapID"] = 542, ["npcID"] = 83904, ["x"] = 0.571, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.567333, ["y"] = 0.342667 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 5, ["flags"] = 0 } } },
