[36085] = { ["id"] = 36085, ["name"] = "On Ebon Wings", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34921, 34922, 34923, 34924, 34938, 34939, 34991, 35007, 35009, 35010, 35704, 36085, 36790 }, ["series"] = { 35704, 36316 }, ["description"] = "Now we bring our fight to the Adherents. Raastok is certain his new invention will give us control of the Apexis weapons, but we must get close - very close. Ka'alu and her ravens will fly us to the Windswept Terrace. We shall gain a foothold there before pressing on to the Terrace of Dawn.", ["objectivesText"] = "Slay 8 Adherents and Windkeeper Koreyx . Speak with Ka'alu for a ride to Windswept Terrace. Progress: Quickly, we must not let this opportunity pass.", ["rewardGold"] = 331700, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 84276, ["x"] = 0.514, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 84262, ["x"] = 0.465, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 51, ["name"] = "When the Raven Swallows the Day", ["orderIndex"] = 11, ["flags"] = 0 } } },
[36165] = { ["id"] = 36165, ["name"] = "No Time to Waste", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35699, 35713, 35716, 35719, 35739, 35782, 35835, 35878, 35915, 35926, 35959, 36023, 36029, 36048, 36165 }, ["series"] = { 35915, 35926, 35959, 36023, 36029, 36048 }, ["description"] = "We're in luck, commander. The antidote is relatively easy tae make. I've made a small amount with what I had on me. You should take it tae Kolrigg before it's too late. It'll keep him alive long enough for me tae make more.", ["objectivesText"] = "Administer the Spiresalve to Kolrigg Stoktron in Southport. Progress: <Kolrigg grumbles incoherently.>", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 113577, 113587, 113630, 113635, 114820, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83900, ["x"] = 0.567333, ["y"] = 0.342667 }, { ["mapID"] = 542, ["npcID"] = 83904, ["x"] = 0.571, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 84261, ["x"] = 0.396, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.567333, ["y"] = 0.342667 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 49, ["name"] = "Securing Southport", ["orderIndex"] = 6, ["flags"] = 0 } } },
[36166] = { ["id"] = 36166, ["name"] = "No Time to Waste", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35697, 35705, 35706, 35718, 35738, 35766, 35797, 35879, 35907, 35924, 35947, 36022, 36028, 36047, 36166, 36659 }, ["series"] = { 35907, 35924, 35947, 36022, 36028, 36047 }, ["description"] = "Commander, we're in luck. The antidote recipe is fairly simple. I was able to make a small amount with what I had on me. You should take it to Lunzul before it's too late. It should keep her alive long enough for me to make more.", ["objectivesText"] = "Administer the Spiresalve to Lunzul in Axefall. Progress: < Lunzul grumbles incoherently.>", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 107694, 109254, 111968, 111980, 111986, 114820, 116394, 116431, 119001 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 83903, ["x"] = 0.571, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 84259, ["x"] = 0.4, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.571, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 48, ["name"] = "Establishing Axefall", ["orderIndex"] = 6, ["flags"] = 0 } } },
[36179] = { ["id"] = 36179, ["name"] = "Unwanted Pests", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["description"] = "Those creatures out in the shallows keep busting the turrets as fast as we can get them operational. I'm supposed to go clear them out but my blaster is completely busted; the damn thing barely can light a candle like this! Could you do me a favor and go kill a few of those pests while I get my blaster fixed at the shop? Just let Gazwitz know you covered for me so I can get reimbursed for the repair.", ["objectivesText"] = "Kill 10 Spore Drifters or Fungal Hulks in Sporemist Shallows.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 85062, ["x"] = 0.625, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81128, ["x"] = 0.614, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 11, ["flags"] = 0 } } },
[36183] = { ["id"] = 36183, ["name"] = "Admiral Taylor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35295, 35322, 36183 }, ["description"] = "Admiral Taylor had figured out who was behind all this. He told us to save who we could... he wanted to handle matters himself. We never heard from him again, but we have our orders. Please... please find him. He went towards the farm.", ["objectivesText"] = "Find Admiral Taylor at Admiral Taylor 's Farm.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 114945, 118079, 118080, 118081, 118082, 118083, 118084, 118085, 118086, 119348 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 82278, ["x"] = 0.376, ["y"] = 0.538 }, { ["mapID"] = 542, ["npcID"] = 82293, ["x"] = 0.376, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82375, ["x"] = 0.368, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 36, ["name"] = "Admiral Taylor's Garrison", ["orderIndex"] = 7, ["flags"] = 0 } } },
[36208] = { ["id"] = 36208, ["name"] = "The Crystal Shard", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "I'm glad you arrived when you did. The Laughing Skull orcs practice some strange spirit magic, but one of their traditions could be quite useful in our situation. While I make preparations, can you gather the reagents? First, we'll need crystals from the husks of goren corpses. You can find their bodies in the canyon.", ["objectivesText"] = "Collect 25 Goren Crystals from Longtooth Gorgers. Progress: I have learned some of the Laughing Skull traditions. This is less strange than many.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 23985, 23986, 23989, 112863, 112864, 112865, 112911, 119076, 119085 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 27, ["flags"] = 0 } } },
[36209] = { ["id"] = 36209, ["name"] = "What's Under There?", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "It is done. With this enchantment, not only can you roam amongst the goren freely, but you can move as they do. Your travels through the canyon are now made easier. You have safe access to places otherwise impossible to reach. Perhaps these tunnels will lead to more information that could be used against the Iron Horde.", ["objectivesText"] = "Use the goren disguise to explore locations in Gorgrond . Progress: That goren disguise smells awful.", ["rewardGold"] = 254700, ["rewardXP"] = 2090, ["rewardItems"] = { 112958, 114963 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 30, ["flags"] = 0 } } },
[36210] = { ["id"] = 36210, ["name"] = "Hard Shell", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "I have already learned much from watching the Laughing Skull. Traveling through goren tunnels was thought to be impossible due to the acid they leave behind, but the orcs found a way around it. We will need some of the shells of goren within the canyon. If you see any of their tunnel craters ready to burst, approach them and goren will come pouring out. This way, you can kill many at once and find the shells more quickly.", ["objectivesText"] = "Collect 9 Goren Shells from Boneyard Gorgers. Progress: Goren seem willing to eat anything in their path, alive or otherwise.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112786 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 28, ["flags"] = 0 } } },
[36223] = { ["id"] = 36223, ["name"] = "Leave Every Soldier Behind", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36482, 36488, 36494, 36508, 36573, 36574, 36953, 49547 }, ["description"] = "The ogron possess something of value to the Iron Horde. I am sure they're unaware, likely just bored and in need of something to torture. We could simply leave them to their fate, but we should follow up on this clue. With any luck, it will help us stop the Iron Horde from turning Gorgrond 's most fearsome creatures into weapons. Try to find Corporal Thukmar and his notes.", ["objectivesText"] = "Find Corporal Thukmar and recover his intel. Progress: Again you've done well, friend.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 113629 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82610, ["x"] = 0.4525, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 84131, ["x"] = 0.438, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 31, ["flags"] = 0 } } },
[36316] = { ["id"] = 36316, ["name"] = "Victory is Within Reach", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6988, ["mapID"] = 542, ["storyline"] = { 36316 }, ["series"] = { 35704, 36085 }, ["description"] = "We have dealt a crippling blow to the Adherents, but our fight is not yet finished. Gather your allies and prepare for the final siege on Skyreach! \"Shadows gather when the raven swallows the day. Burning sky is extinguished as black wings fold gently about the heavens. Rest, my children, rest. For even the sun must sleep.\" This was Rukhmar's lullaby, sung by her to the first arakkoa. My, how we've lost our way.", ["objectivesText"] = "Slay Ranjit , Araknath , Rukhran and High Sage Viryx in the Skyreach dungeon. Progress: Let us finish what we have started.", ["rewardGold"] = 679200, ["rewardXP"] = 8230, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81770, ["x"] = 0.470667, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.470667, ["y"] = 0.455333 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6988 } }, ["questType"] = "dungeon" },
[36353] = { ["id"] = 36353, ["name"] = "For Old Times' Sake", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 36353 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 85080, ["x"] = 0.4, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 85080, ["x"] = 0.4, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[36368] = { ["id"] = 36368, ["name"] = "Lost Lumberjack", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 34012, 34698, 34699, 34700, 34702, 34703, 34704, 35137, 35650, 35651, 35652, 35654, 35708, 36368 }, ["description"] = "All o' them mole machines got mighty unreliable here in Gorgrond . I hear tell that one of 'em might've crashed here in Tangleheart. See if you can find Frenna . She would've been on the one we tracked to this location. I'll go lookin' for the mole machine to see if it can be repaired.", ["objectivesText"] = "Find Frenna within Tangleheart.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82575, ["x"] = 0.558, ["y"] = 0.715 }, { ["mapID"] = 543, ["npcID"] = 85119, ["x"] = 0.53, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82569, ["x"] = 0.57, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 53, ["name"] = "Supporting Your Garrison", ["orderIndex"] = 13, ["flags"] = 0 } } },
[36384] = { ["id"] = 36384, ["name"] = "Field Trial", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["description"] = "Look, I didn't tell Kimzee about this because I don't want to hurt her feelings, I chose not to leave Pinchwhistle Point. See, I've been working on a serum that I think should be able to cure the infected, but when I tried to test it I got surrounded and I injured my leg during the escape. I know I'm on the right track but I need to test it. Do me a favor and take this vial and go try it out on one of the infected outside.", ["objectivesText"] = "Venture into Pinchwhistle Point and use the Vial of Untested Serum on an Infected Bruiser or Infected Lumberjack. Return to Krixel Pinchwhistle to report the results. Progress: Have you completed the field test, <name>?", ["rewardGold"] = 232300, ["rewardXP"] = 3085, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81443, ["x"] = 0.585, ["y"] = 0.922 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81443, ["x"] = 0.585, ["y"] = 0.922 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.922 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 12, ["flags"] = 0 } } },
[36425] = { ["id"] = 36425, ["name"] = "Egg Punt", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 34827, 34828, 34829, 34830, 34838, 34882, 34883, 34884, 34885, 34886, 34942, 36425 }, ["description"] = "<A sweaty, pulsing egg - no doubt flush with ravager larvae. A swift kick should take care of these.>", ["objectivesText"] = "Kick 10 Ravager Eggs in Camp Thornscar.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 85425, ["x"] = 0.47, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 37, ["name"] = "Secrets of the Talonpriests", ["orderIndex"] = 3, ["flags"] = 0 } } },
[36428] = { ["id"] = 36428, ["name"] = "Curing With Force", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35077, 35079, 35080, 35081, 35082, 35089, 35090, 35091, 35211, 35285, 35298, 36179, 36384, 36428 }, ["description"] = "The infection is getting stronger so I made some adjustments and I'm pretty sure I have the right formula now. It should now work but it needs to have less competition with the infected blood for it to have any effect. This means you will need to weaken them before you apply the serum for it to function properly. The infection is getting more advanced and will soon be untreatable so we have this one shot to save as many as we can.", ["objectivesText"] = "Cure 6 Infected Goblins . Progress: Any progress to report with that cure?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 97919, 111957, 112634, 112683, 112698, 112906, 115475, 115533, 137663, 161218 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81443, ["x"] = 0.585, ["y"] = 0.922 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81443, ["x"] = 0.585, ["y"] = 0.922 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.922 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542, ["questLines"] = { { ["id"] = 50, ["name"] = "Pinchwhistle Gearworks", ["orderIndex"] = 13, ["flags"] = 0 } } },
[36434] = { ["id"] = 36434, ["name"] = "Penny From Heaven", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 33543, 33544, 33548, 33563, 33593, 35151, 36434, 36460 }, ["series"] = { 33593, 35151, 36460 }, ["description"] = "< Durotan looks at you curiously.> Those from your world are not much for subtlety, are they? Go on ahead and greet our new companion. We will join you as soon as we can make ready.", ["objectivesText"] = "Speak to Penny Clobberbottom at Beastwatch.", ["rewardGold"] = 42135, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85147, ["x"] = 0.456, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.737333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 57, ["name"] = "Establish a Foothold", ["orderIndex"] = 5, ["flags"] = 0 } } },
[36460] = { ["id"] = 36460, ["name"] = "Just Another Stick in the Wall", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 33543, 33544, 33548, 33563, 33593, 35151, 36434, 36460 }, ["series"] = { 33593, 35151, 36434 }, ["description"] = "So, get this. As I was flyin' in, I took the opportunity to scope out what might be a defensible position. Just on the other side o' these boulders is an ideal clearing to hole up in. I even brought a set of blueprints to get us all settled in! That's not too presumptuous, is it? Anyway, whenever you're ready just hit this plunger!", ["objectivesText"] = "Use Penny's Plunger to blow up the Rock Wall.", ["rewardGold"] = 232350, ["rewardXP"] = 1045, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 85147, ["x"] = 0.456, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 57, ["name"] = "Establish a Foothold", ["orderIndex"] = 6, ["flags"] = 0 } } },
[36474] = { ["id"] = 36474, ["name"] = "The Razorbloom", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35025, 35026, 35035, 35036, 35037, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35247, 35248, 35399, 35400, 35402, 35406, 35416, 35429, 35430, 35432, 35433, 35434, 35487, 35501, 35507, 35509, 35510, 35536, 35730, 35870, 35880, 35925, 35934, 36474, 36482, 36488 }, ["series"] = { 35400 }, ["description"] = "The Laughing Skull shaman Kaz ran off while we were coming here. She claimed to be looking for more of her people in the jungles to the south. Draka insisted on following her to safeguard us against betrayal. Commander, if Kaz is telling the truth, then she and Draka are going to need all the help they can get. Will you join them? They could not have gotten far. This could prove to be the perfect test for your new shredder and lumber mill resources.", ["objectivesText"] = "Find Draka and Kaz at the Razorbloom.", ["rewardGold"] = 42135, ["rewardXP"] = 260, ["rewardItems"] = { 112612, 112613, 112614, 112615 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74593, ["x"] = 0.436857, ["y"] = 0.727429 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.737333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 56, ["name"] = "In the Land of Giants", ["orderIndex"] = 16, ["flags"] = 0 } } },
