[36523] = { ["id"] = 36523, ["name"] = "A Green Ogron?", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35026, 35037, 35128, 35139, 35204, 35205, 35206, 35207, 35208, 35209, 35213, 35214, 35215, 35216, 35225, 35229, 35233, 35234, 35235, 35255, 35664, 35665, 35686, 35693, 35702, 35730, 35870, 35925, 35934, 36208, 36209, 36210, 36223, 36508, 36523 }, ["series"] = { 35205, 35207, 35209 }, ["description"] = "Them botani got themselves a green ogron. A green ogron! I mean I may not know much about plant people but that canno' be a good thing. Think ya can take it in a fight?", ["objectivesText"] = "Kill the Infested Ogron .", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112591, 112592, 112593, 112594 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 81601, ["x"] = 0.419222, ["y"] = 0.806 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81601, ["x"] = 0.419222, ["y"] = 0.806 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.419222, ["y"] = 0.806 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 55, ["name"] = "In the Land of Giants", ["orderIndex"] = 8, ["flags"] = 0 } } },
[36567] = { ["id"] = 36567, ["name"] = "Bigger is Better", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 36567 }, ["description"] = "Ya know boss, I think I know how we can take this place to the next level. Bigger walls. More buildings. Some space to stretch your arms after a long day of adventuring. Don't get me wrong, it's going to take a lot of resources, but what else are these things for? We can plot it out on the drafting table whenever you're ready. It's going to be GLORIOUS.", ["objectivesText"] = "Use the Architect Table to select your Town Hall and upgrade your garrison to Tier 2. Progress: What ya waitin' for boss? Let's take this thing to the next level!", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["rewardItems"] = { 109576, 111996, 116248, 116249 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36573] = { ["id"] = 36573, ["name"] = "Strike While the Iron is Hot", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36573, 36574 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36574, 36953, 49547 }, ["description"] = "With the Heart of the Mangaron, we wield a powerful weapon against the Iron Horde. They amass far to the north at the Iron Approach. This will not be easy, but we must seize the opportunity to deal a blow to the Iron Horde while we possess the artifact. We are prepared to depart at your command. Speak with Grinslicer when you are ready.", ["objectivesText"] = "Speak to Grinslicer to fly to the Iron Approach and attack the Iron Horde. Progress: The mysteries of this land sometimes bear fruit.", ["rewardGold"] = 25470, ["rewardXP"] = 260, ["rewardItems"] = { 112680, 112885, 112887, 112889, 116394, 118019, 118020, 118021 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.737333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 69, ["name"] = "The Iron Approach", ["orderIndex"] = 0, ["flags"] = 0 } } },
[36574] = { ["id"] = 36574, ["name"] = "Strike While the Iron is Hot", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36573, 36574 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36953, 49547 }, ["description"] = "With the Will of the Genesaur, we wield a powerful weapon. Our scouts have discovered an Iron Horde base, and I believe it is time to seize an opportunity. They amass far to the north at the Iron Approach. This will not be easy, but we must deal a blow to the Iron Horde while we possess the artifact. We are prepared to depart at your command. Speak with Grinslicer when you are ready.", ["objectivesText"] = "Speak to Grinslicer to fly to the Iron Approach and attack the Iron Horde. Progress: The mysteries of this land sometimes bear fruit.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112885, 112887, 112889, 116394 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.737333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 69, ["name"] = "The Iron Approach", ["orderIndex"] = 1, ["flags"] = 0 } } },
