[36576] = { ["id"] = 36576, ["name"] = "Strike While the Iron is Hot", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36575, 36576 }, ["series"] = { 34558, 34676, 35702, 36495, 37183, 49565, 92692 }, ["description"] = "With the Heart of the Magnaron, we wield a powerful weapon against the Iron Horde. They amass far to the north at the Iron Approach. This will not be easy, but we must seize the opportunity to deal a blow to the Iron Horde while we possess the artifact. We are prepared to depart at your command. Speak with Rangari Rajess when you are ready.", ["objectivesText"] = "Speak to Rangari Rajess to fly to the Iron Approach and attack the Iron Horde. Progress: We must eradicate the Iron Horde.", ["rewardGold"] = 46350, ["rewardXP"] = 260, ["rewardItems"] = { 112885, 112887, 112889, 116394 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75127, ["x"] = 0.6, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75127, ["x"] = 0.6, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 68, ["name"] = "The Iron Approach", ["orderIndex"] = 1, ["flags"] = 0 } } },
[36592] = { ["id"] = 36592, ["name"] = "Bigger is Better", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36592 }, ["series"] = { 33059, 33070, 33072, 33075, 33076, 33080, 33081, 33765, 33814, 33905, 34019 }, ["description"] = "Commander, I've been working on schematics that you might be interested in. What do you think about pushing out the walls and making room to get some additional structures in here? Our forces have been growing, and things are getting a little cramped, and I'd really like us to put some of those additional blueprints to use. If you could, take a look at the plans on the table here. As soon as I have your go ahead, I'll get everyone to work immediately.", ["objectivesText"] = "Use the Architect Table to select your Town Hall and upgrade your garrison to Tier 2. Progress: What do you think? Time for an upgrade?", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["rewardItems"] = { 109576, 111996, 116248, 116249, 248661 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36595] = { ["id"] = 36595, ["name"] = "He Drew Aggro...culture", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35033, 35050, 35055, 35063, 35065, 35828, 35834, 36595 }, ["series"] = { 35055, 35063, 35208, 35212, 35213, 35215, 35828 }, ["description"] = "What you saw was the wake of the genesaur, Iyu. It was chasing this mechanical monstrosity and the person who drove it. I believe the pilot of this vessel is still alive and trapped within the ruins of the camp. If you wish them to be recovered, I recommend doing so now.", ["objectivesText"] = "Find the pilot of the Dark Iron tank.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75146, ["x"] = 0.583, ["y"] = 0.561 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75136, ["x"] = 0.581, ["y"] = 0.561 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.561 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 52, ["name"] = "We Need An Outpost", ["orderIndex"] = 3, ["flags"] = 0 } } },
