[37291] = { ["id"] = 37291, ["name"] = "Thunderlord Invasion!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 590, ["storyline"] = { 33010, 34123, 34124, 37291 }, ["series"] = { 33493, 33828 }, ["description"] = "Your timing could not have been better. Your scouts have reported the approach of a large Thunderlord army. My clan can ride out and assist in severing their reinforcements, but you will need to see to the defense of your fort against the bulk of their forces. Sergeant Grimjaw awaits your command.", ["objectivesText"] = "Repel the Thunderlord invasion. Progress: The Frostwolves stand ready.", ["rewardGold"] = 169800, ["rewardXP"] = 2125, ["rewardItems"] = { 120182 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 22, ["name"] = "The Battle of Thunder Pass", ["orderIndex"] = 0, ["flags"] = 0 } } },
