[37687] = { ["id"] = 37687, ["name"] = "Garrison Campaign: In the Shadows", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37687, 38213, 38223, 38267 }, ["series"] = { 38267 }, ["description"] = "I need your help. Iskar has gone missing. I have reason to believe he has followed the remnants of the Sethekk who have been gathering here in Tanaan. I've been investigating and... what was that? < Reshad 's voice drops to a whisper> There is movement in the shadows, we are being watched! Take these vials, they form a gas with a terrible smell when the liquid comes in contact with the air. Smells terrible, they won't be able to resist it. Use them to drive our watchers out of hiding.", ["objectivesText"] = "Kill 3 Council Nightblades within Lion's Watch.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 122463, 124557 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91290, ["x"] = 0.575, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91290, ["x"] = 0.575, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 123, ["name"] = "The Search for Iskar", ["orderIndex"] = 0, ["flags"] = 0 } } },
[37688] = { ["id"] = 37688, ["name"] = "Garrison Campaign: In the Shadows", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37688, 38213, 38223, 38269 }, ["description"] = "I need your help. Iskar has gone missing. I have reason to believe he has followed the remnants of the Sethekk who have been gathering here in Tanaan. I've been investigating and... what was that? < Reshad 's voice drops to a whisper> There is movement in the shadows, we are being watched! Take these vials, they form a gas with a terrible smell when the liquid comes in contact with the air. Smells terrible, they won't be able to resist it. Use them to drive our watchers out of hiding.", ["objectivesText"] = "Kill 3 Council Nightblades within Vol'mar. Progress: Did you take care of our watchers?", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 122463, 124557 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91292, ["x"] = 0.605, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91292, ["x"] = 0.605, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 125, ["name"] = "The Search for Iskar", ["orderIndex"] = 0, ["flags"] = 0 } } },
[37889] = { ["id"] = 37889, ["name"] = "The Invasion of Tanaan", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 539, ["storyline"] = { 37889, 37890, 37934, 37935 }, ["series"] = { 37890, 37934, 37935, 39236, 39241, 39242 }, ["description"] = "It is done! By your command we have built our first ship and can run our naval operations from here. Now that we have our transport, we can let Durotan and that Archmage of yours know that we are ready to kick off an invasion of Tanaan. Speak with them at the docks to embark.", ["objectivesText"] = "Meet with Khadgar and then speak to Draka to start the invasion.", ["rewardGold"] = 42450, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 94429, ["x"] = 0.298, ["y"] = 0.106 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 89822, ["x"] = 0.734, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.106 }, ["mapCandidates"] = { ["npc"] = { 534, 539 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 141, ["name"] = "Tanaan Invasion - Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[37890] = { ["id"] = 37890, ["name"] = "Obstacle Course", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37889, 37890, 37934, 37935 }, ["series"] = { 37889, 37934, 37935, 39236, 39241, 39242 }, ["description"] = "It is strange that these docks were abandoned by the Iron Horde, but up ahead our scouts report trouble. A set of Bleeding Hollow scavengers is busy looting the abandoned buildings to the northwest. Further down the road orc cultists are doing... something... near the Dark Portal. We should try to recover any orders or information as to what is going on here, then meet with our scouts further in...", ["objectivesText"] = "Find any information on the forces deployed in the area and meet with the scouts afterwards.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 97989 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 89822, ["x"] = 0.734, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90238, ["x"] = 0.6496, ["y"] = 0.5144 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.734, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 141, ["name"] = "Tanaan Invasion - Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[37934] = { ["id"] = 37934, ["name"] = "In, Through, and Beyond!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37889, 37890, 37934, 37935 }, ["series"] = { 37889, 37890, 37935, 39236, 39241, 39242 }, ["description"] = "A few of us snuck through before we was spotted, den de cannons started up. De small ones are no trouble, but de big one... we gonna need to take it out if we wanna get anyting through.", ["objectivesText"] = "Destroy the Fel Defense Cannon covering the gate.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90238, ["x"] = 0.6496, ["y"] = 0.5144 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90238, ["x"] = 0.6496, ["y"] = 0.5144 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.6496, ["y"] = 0.5144 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 141, ["name"] = "Tanaan Invasion - Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[37935] = { ["id"] = 37935, ["name"] = "The Assault Base", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37889, 37890, 37934, 37935 }, ["series"] = { 37889, 37890, 37934, 39236, 39241, 39242 }, ["description"] = "Nearby be a good place. Not too close to da enemy, but close enough for us to take some pressure off da boys in the west. Follow me.", ["objectivesText"] = "Establish your assault base in Tanaan Jungle.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90238, ["x"] = 0.6496, ["y"] = 0.5144 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.6496, ["y"] = 0.5144 }, ["mapCandidates"] = { ["npc"] = { 525, 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 141, ["name"] = "Tanaan Invasion - Horde", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38001] = { ["id"] = 38001, ["name"] = "Commander in the Field!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38001 }, ["series"] = { 38577 }, ["description"] = "We have been stopped by these new fel orcs, but we will ultimately prevail. Draka and I did manage to get a full scouting group out into the jungle to gather what else we will have to deal with. You should seek them out, gain a full understanding of what we face here.", ["objectivesText"] = "Get reports from various scouts in Tanaan Jungle .", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90553, ["x"] = 0.096, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.096, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 525, 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[38213] = { ["id"] = 38213, ["name"] = "Get a Clue", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37687, 38213, 38223, 38267 }, ["description"] = "Aktar mentioned that in the ruins he's seen Sethekk, ogres, even demons, but no sign of Iskar. We're going to have to go in there if we're to find any clues and I'd prefer someone strong like yourself to lead the way. Well, what do you say?", ["objectivesText"] = "Search the Ruins of Kra'nak for clues. Progress: The binding is dirty yet the pages are still in good condition. Upon the bottom of the binding is written \"Property of Iskar.\"", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 122463, 124557 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91291, ["x"] = 0.258, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 123, ["name"] = "The Search for Iskar", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 125, ["name"] = "The Search for Iskar", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38223] = { ["id"] = 38223, ["name"] = "Dark Ascension", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 37687, 38213, 38223, 38267 }, ["description"] = "You skim through the pages of the tome, most of them filled with notes on the nature of shadow and illusion. On the last pages you discover a journal: I continue to search for a cure to the curse of Sethe. If Terokk was restored I would not be in this situation. Damn Reshad ! I was contacted by an orc that identified himself as Gul'dan. He has a cure for the curse! I must travel to Tanaan to search for the location of this \"cipher\" of his. Take this information to Reshad .", ["objectivesText"] = "Speak to Reshad in the Ruins of Kra'nak. Progress: I wish it had not come to this...", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 122429, 122463, 124557 }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 89400, ["x"] = 0.16, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.16, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 123, ["name"] = "The Search for Iskar", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 125, ["name"] = "The Search for Iskar", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38253] = { ["id"] = 38253, ["name"] = "Garrison Campaign: War Council", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38254, 38255, 38256, 38257, 38258, 38259, 40418 }, ["description"] = "Your garrison is in an uproar. King Varian Wrynn himself is visiting your fortress to discuss your invasion plan for Tanaan Jungle. The King is ready for you inside your town hall along with his full retinue. It would be wise not to keep him waiting...", ["objectivesText"] = "Speak with King Varian Wrynn inside the Town Hall of your garrison.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 110560, 123867 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 92219, ["x"] = 0.276, ["y"] = 0.102 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.102 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38254] = { ["id"] = 38254, ["name"] = "Derailment", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38255, 38256, 38257, 38258, 38259, 40418 }, ["description"] = "Several orcs have spoken out since Gul'dan assumed control. Some were taken prisoner. Among them is an engineering prodigy: Solog Roark, \"The Iron Shipwright.\" He designed these docks as well as the great dreadnaughts of the orcish fleet. If my scouts are right, he's in that prison train as we speak... And he may be ready to defect! Gather explosives and meet with Yrel at the train to the southeast!", ["objectivesText"] = "Collect Explosive Charges and a Detonator . Progress: Commander, it's you! Naielle promised she would send someone.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 110560, 122515, 122516, 123867 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 90180, ["x"] = 0.525, ["y"] = 0.098 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 90177, ["x"] = 0.276, ["y"] = 0.102 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.098 }, ["mapCandidates"] = { ["npc"] = { 539, 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38255] = { ["id"] = 38255, ["name"] = "The Train Gang", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38254, 38256, 38257, 38258, 38259, 40418 }, ["description"] = "These rangari will surround and cover the train car. Hit the detonator to blow open the doors. I will try to talk Roark into joining our cause. He's a genius around a drydock and our best hope for building a shipyard. If it doesn't work, we must be prepared to kill him. The last thing we need is someone rebuilding another Iron Fleet...", ["objectivesText"] = "Use the detonator to blow open the prison train, and convince Roark to join your cause.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 110560, 123867 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 90177, ["x"] = 0.276, ["y"] = 0.102 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 91242, ["x"] = 0.275, ["y"] = 0.112 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.102 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38256] = { ["id"] = 38256, ["name"] = "Hook, Line, and... Sink Him!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 525, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38254, 38255, 38257, 38258, 38259, 40418 }, ["description"] = "I can build you a shipyard. And not some wasteful piece of over-engineering like this place. But I'm going to need my blueprints. My work was confiscated when Gul'dan turned this harbor over to Admiral Knar. <Roark spits.> Gul'dan's green poison courses through Knar's veins. He's calling the shots from on high. We'll need to grapple up there to take him out.", ["objectivesText"] = "Use a Blackrock Grapple to reach Knar's bunker. Slay him to obtain Roark's Shipyard Blueprints . Progress: I will rebuild.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 110560, 123867 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38257] = { ["id"] = 38257, ["name"] = "We Need a Shipwright", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38254, 38255, 38256, 38258, 38259, 40418 }, ["description"] = "The Iron Horde - or whatever Gul'dan is turning them into - has fallen back and fortified the entrance to Tanaan. A direct assault will take a heavy toll. However, the sea lanes are open. If we attack by both land and sea, Gul'dan's Horde will have no quarter. <name>, it's time to build a shipyard! We'll need to source local resources. Travel to the Iron Docks, where a small Alliance reclamation force is already waiting. Gather what equipment you can, and find us a shipwright capable of building a fleet!", ["objectivesText"] = "Travel to the Iron Docks and speak with Exarch Naielle . Your Garrison Flight Master can provide transport.", ["rewardGold"] = 140450, ["rewardXP"] = 1365, ["rewardItems"] = { 110560, 123867 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 92219, ["x"] = 0.276, ["y"] = 0.102 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 90180, ["x"] = 0.525, ["y"] = 0.098 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.102 }, ["mapCandidates"] = { ["npc"] = { 539, 543 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38258] = { ["id"] = 38258, ["name"] = "Nothing Remains", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 525, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38254, 38255, 38256, 38257, 38259, 40418 }, ["description"] = "Nothing is left for me here. My old clanmates have turned into foes, and Gul'dan is desecrating what remains of my people. You and your allies from Shattrath still have some fight left. If you pledge to depose Gul'dan, I will stand by your side. I will go to this garrison of yours and together we will build a shipyard that will rule the red seas of Draenor! Let your people know I am coming.", ["objectivesText"] = "Report back to King Wrynn at the Town Hall in your garrison.", ["rewardGold"] = 140450, ["rewardXP"] = 1365, ["rewardItems"] = { 110560, 123867 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 92219, ["x"] = 0.276, ["y"] = 0.102 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 525, 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 582, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38259] = { ["id"] = 38259, ["name"] = "All Hands on Deck", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38253, 38254, 38255, 38256, 38257, 38258, 40418 }, ["description"] = "Let's put this \"Iron Shipwright\" of yours to work, commander. If we're to pull off your plan to assault Tanaan from both land and sea, we'll need to get some docks operational as soon as possible. Work with Roark and build the Alliance a shipyard! Last I saw, Roark was northwest of the garrison, near Eventide Landing.", ["objectivesText"] = "Gather materials and construct a Level 1 Shipyard for your garrison. Progress: I'll need building materials, commander. You can't build docks from mud.", ["rewardXP"] = 1365, ["rewardItems"] = { 110560, 119093, 123867 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 92219, ["x"] = 0.276, ["y"] = 0.102 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.102 }, ["mapCandidates"] = { ["npc"] = { 525, 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 6, ["flags"] = 0 } } },
