[38270] = { ["id"] = 38270, ["name"] = "Finding the Killer", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38270, 38271, 38272, 38274, 38453 }, ["series"] = { 38453, 38560 }, ["description"] = "With this map, you have pinpointed the origin of the attacks. It is time to see who or what is behind the attacks, and if they are a possible ally.", ["objectivesText"] = "Locate the slayer of Bleeding Hollow near Zeth'Gol. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 122574, 122575, 123852, 124553, 127709 }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91299, ["x"] = 0.27, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 84, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 85, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 123852 } },
[38271] = { ["id"] = 38271, ["name"] = "Following the Bloody Path", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38270, 38271, 38272, 38274, 38453 }, ["description"] = "The ones I kill... they speak of a cave. Sacred to the Bleeding Hollow. Kilrogg could be there - I am going.", ["objectivesText"] = "Follow Ariok to the cave.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 122574, 122575, 124553, 127709 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91299, ["x"] = 0.27, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91351, ["x"] = 0.324667, ["y"] = 0.374667 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 84, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 85, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38272] = { ["id"] = 38272, ["name"] = "The Bleeding Hollow", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38270, 38271, 38272, 38274, 38453 }, ["description"] = "The cave pulls me. It keeps angry spirits near. Kilrogg has done magic here. You help me understand...", ["objectivesText"] = "Reach the bottom of the Bleeding Hollow.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 25628, 25629, 25630, 122574, 122575, 123852, 124553, 127709 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91351, ["x"] = 0.324667, ["y"] = 0.374667 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91324, ["x"] = 0.334, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.324667, ["y"] = 0.374667 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 84, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 85, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38273] = { ["id"] = 38273, ["name"] = "Spirits of the Bleeding Hollow", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["storyline"] = { 38273 }, ["description"] = "It is clear the cave is protected by powerful ghosts, ancestors of the Bleeding Hollow. Whatever is down there, it will be easier to deal with if many of the spirits were dealt with first.", ["objectivesText"] = "Slay 6 Enraged Blood Spirits .", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 122574, 122575, 124553, 127669, 127709 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[38274] = { ["id"] = 38274, ["name"] = "The Eye of Kilrogg", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38270, 38271, 38272, 38274, 38453 }, ["description"] = "If you wish to know what Kilrogg and his new master intend, you will need his eye. After the ritual all chieftains place their eye under the protection of the ghosts of the Bleeding Hollow in the next chamber. Go and locate the Eye of Kilrogg in the vault. The other chieftains will not stand with us, and will fight you for it. Then place it on the ritual mark nearby to get your answers.", ["objectivesText"] = "Find the Eye of Kilrogg and perform the scrying ritual. Progress: What have you learned?", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 122574, 122575, 124553, 127709 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91324, ["x"] = 0.334, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 92317, ["x"] = 0.328, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 84, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 85, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38415] = { ["id"] = 38415, ["name"] = "Garrison Campaign: Onslaught at Auchindoun", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 525, ["storyline"] = { 38415, 38416 }, ["description"] = "Your ally, Liadrin, has sent a missive requesting aid near Auchindoun. The Sargerei have made a new assault there and breached something important. It is no coincidence this happened after Gul'dan's ascendancy. We will watch the front here, commander.", ["objectivesText"] = "Meet Liadrin at Auchindoun in Talador.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 122, ["name"] = "Gorefiend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38416] = { ["id"] = 38416, ["name"] = "Secrets of the Sargerei", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 38415, 38416 }, ["description"] = "The Auchenai have been reporting for some time that something was... wrong... with Auchindoun. They were never able to find a reason. Suddenly the Sargerei attacked and blew open a hole into a subchamber. Corruption leaks from that hole, we need to stop it.", ["objectivesText"] = "Locate and stop the source of corruption underneath Auchindoun.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 124552 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 122, ["name"] = "Gorefiend", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38417] = { ["id"] = 38417, ["name"] = "The Sargerei Menace", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["storyline"] = { 38417 }, ["description"] = "An attack such as this was unexpected. They have deployed heavily and it will take me some time to marshal enough forces to root them out. Any Sargerei you can slay will make retaking this area much easier commander.", ["objectivesText"] = "Slay 12 Sargerei.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[38421] = { ["id"] = 38421, ["name"] = "Garrison Campaign: Onslaught at Auchindoun", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38421, 38562 }, ["description"] = "The Auchenai have sent me an urgent missive - Auchindoun is in jeopardy again! The Sargerei have renewed their assault and breached the underhalls. I sense the hand of Gul'dan is behind this. Gather your things and meet me in the Court of Souls West of Auchindoun at once!", ["objectivesText"] = "Meet Yrel at Auchindoun in Talador.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 124552 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90309, ["x"] = 0.585, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 121, ["name"] = "Gorefiend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38435] = { ["id"] = 38435, ["name"] = "The Invasion of Tanaan", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38435, 38436, 38444, 38445 }, ["series"] = { 38436, 38444, 38445, 39054, 39055, 39082, 39276 }, ["description"] = "It is done! By your command we have built our first ship and can run our naval operations from here. Now that we have our transport, we can let Yrel and Archmage Khadgar know that we are ready to kick off an invasion of Tanaan. Speak with them at the docks to embark.", ["objectivesText"] = "Meet with Khadgar at your shipyard and then speak to Yrel to begin the invasion.", ["rewardGold"] = 42450, ["rewardXP"] = 1365, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 95002, ["x"] = 0.298, ["y"] = 0.106 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 91913, ["x"] = 0.75, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.106 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 142, ["name"] = "Tanaan Invasion - Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38436] = { ["id"] = 38436, ["name"] = "Obstacle Course", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38435, 38436, 38444, 38445 }, ["series"] = { 38435, 38444, 38445, 39054, 39055, 39082, 39276 }, ["description"] = "Our landing was unopposed. Why are these docks all but abandoned? The rangari scouts up ahead report trouble. Bleeding Hollow scavengers are looting some abandoned buildings to the northwest, and an encampment of warlock cultists lurk near the Dark Portal. Let's find out what we can and meet up with our scouts.", ["objectivesText"] = "Find any information on the forces deployed in the area and meet with the scouts afterwards.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91913, ["x"] = 0.734, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91923, ["x"] = 0.6475, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.734, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 142, ["name"] = "Tanaan Invasion - Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38444] = { ["id"] = 38444, ["name"] = "In, Through, and Beyond!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38435, 38436, 38444, 38445 }, ["series"] = { 38435, 38436, 38445, 39054, 39055, 39082, 39276 }, ["description"] = "Gul'dan seems to have concentrated his defenses on this chokepoint. The guns up ahead are unlike anything we've seen before - they're empowered with fel energy. Our enemies think this pass is impregnable. Let's prove them wrong, commander! If we can break through, the terrain ahead will make an excellent stronghold. Destroy that cannon!", ["objectivesText"] = "Destroy the Fel Defense Cannon covering the gate.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91923, ["x"] = 0.6475, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91923, ["x"] = 0.6475, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.6475, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 142, ["name"] = "Tanaan Invasion - Alliance", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38445] = { ["id"] = 38445, ["name"] = "The Assault Base", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38435, 38436, 38444, 38445 }, ["series"] = { 38435, 38436, 38444, 39054, 39055, 39082, 39276 }, ["description"] = "While you were playing with fel fire, I've located the perfect position for an assault outpost. Follow me and we can get this base started!", ["objectivesText"] = "Establish your assault base in Tanaan Jungle.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91923, ["x"] = 0.6475, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90309, ["x"] = 0.585, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.6475, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 142, ["name"] = "Tanaan Invasion - Alliance", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38446] = { ["id"] = 38446, ["name"] = "Commander in the Field!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38446 }, ["series"] = { 38581 }, ["description"] = "This battle will be won, but it will be hard fought. Our rangari did manage to get a few scouts out to the rest of the jungle though. Perhaps it is best you collect this intelligence yourself and see what this jungle holds for us all.", ["objectivesText"] = "Get reports from various scouts in Tanaan Jungle . Progress: There's a lot to see here isn't there?", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 91935, ["x"] = 0.098, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90309, ["x"] = 0.585, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.098, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[38453] = { ["id"] = 38453, ["name"] = "Garrison Campaign: The Bane of the Bleeding Hollow", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 525, ["storyline"] = { 38270, 38271, 38272, 38274, 38453 }, ["series"] = { 38270, 38560 }, ["description"] = "Commander, now that we've had time to get scouts all over the jungle we have heard some news near Zeth'Gol. It appears that somebody else has a vendetta against the Bleeding Hollow and has been... hunting... them. Their hunters are closing in on the assassin. You know what they say about \"the enemy of my enemy...\" We should collect their tracking maps and try to find the killer first!", ["objectivesText"] = "Collect tracking maps to find the location of the killer.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 123852, 124553, 127006, 127709 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 84, ["name"] = "The Bleeding Hollow", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38458] = { ["id"] = 38458, ["name"] = "Garrison Campaign: The Warlock", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 525, ["storyline"] = { 38458, 38462, 38463 }, ["series"] = { 38462, 38463, 38561 }, ["description"] = "Commander, you have a visitor. One of Gul'dan 's warlocks just walked up to the base and surrendered. He says he has information of a terrible event that is about to occur. I suggest you speak with him immediately.", ["objectivesText"] = "Speak with the warlock at Vol'mar in Tanaan Jungle.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 124551, 128225, 128309, 128320 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 92055, ["x"] = 0.472, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525, 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 126, ["name"] = "Gul'dan Finale", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38462] = { ["id"] = 38462, ["name"] = "Breaching the Barrier", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38462, 38561, 39394 }, ["series"] = { 38458, 38463, 38561 }, ["description"] = "The ritual site is already prepared, and it is protected by a barrier... one that I created. I can destroy the barrier, but I will need three items currently in use at Forge Camp Vengeance. If you can get those ritual items, I will meet you at the Corrupted Refuge and remove the barrier. Even if it kills me.", ["objectivesText"] = "Collect the Black Candle , the Tome of Protection , and the Shadowblade at the Fel Forge and bring them to Oronok.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 124551, 128225, 128309, 128320 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 92055, ["x"] = 0.472, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 92120, ["x"] = 0.625, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 124, ["name"] = "Gul'dan Finale", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 126, ["name"] = "Gul'dan Finale", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38463] = { ["id"] = 38463, ["name"] = "The Cipher of Damnation", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38458, 38462, 38463 }, ["series"] = { 38458, 38462, 38561 }, ["description"] = "Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy. Gul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.", ["objectivesText"] = "Get Oronok and your ally to destroy the barrier, then stop Gul'dan.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["rewardItems"] = { 124551, 128225, 128309, 128320 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 92120, ["x"] = 0.625, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 93659, ["x"] = 0.628, ["y"] = 0.278 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 126, ["name"] = "Gul'dan Finale", ["orderIndex"] = 2, ["flags"] = 0 } } },
