[38561] = { ["id"] = 38561, ["name"] = "Garrison Campaign: The Warlock", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38462, 38561, 39394 }, ["series"] = { 38458, 38462, 38463 }, ["description"] = "Commander, you have a visitor. One of Gul'dan 's warlocks just walked up to the base and surrendered. He says he has information of a terrible event that is about to occur. I suggest you speak with him immediately.", ["objectivesText"] = "Speak with the warlock at Lion's Watch in Tanaan Jungle.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 124551, 128225, 128309, 128320 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90309, ["x"] = 0.585, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 92055, ["x"] = 0.472, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 124, ["name"] = "Gul'dan Finale", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38562] = { ["id"] = 38562, ["name"] = "Secrets of the Sargerei", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 38421, 38562 }, ["description"] = "The Auchenai have been reporting for some time that something was... wrong... with Auchindoun since Teron'gor's original assault. Now suddenly the Sargerei attacked and blew open a hole into one of the underhalls. Corruption leaks from that breach. We must investigate!", ["objectivesText"] = "Locate and stop the source of corruption underneath Auchindoun.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 124552 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 121, ["name"] = "Gorefiend", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38565] = { ["id"] = 38565, ["name"] = "The Sargerei Menace", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["storyline"] = { 38565 }, ["description"] = "This attack surprised our defenders. Forces are marshalling to push them out, but it will take some time for them to arrive. Any Sargerei you can slay will make retaking this area much easier commander.", ["objectivesText"] = "Slay 12 Sargerei.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[38567] = { ["id"] = 38567, ["name"] = "Garrison Campaign: War Council", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 590, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 38568, 38570, 38571, 38572, 38573, 38574 }, ["description"] = "Your garrison is in an uproar. Warchief Vol'jin himself is visiting your fortress to discuss your invasion plan for Tanaan Jungle. The Warchief is ready for you inside your Town Hall. It would be wise not to keep him waiting...", ["objectivesText"] = "Speak with Warchief Vol'jin inside the Town Hall of your garrison.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38568] = { ["id"] = 38568, ["name"] = "We Need a Shipwright", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 543, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 38567, 38570, 38571, 38572, 38573, 38574 }, ["description"] = "Whatever be left of da Iron Horde be fallin' back ta Tanaan Jungle, where Gul'dan is turnin' them into sumthun' even worse. A frontal assault be suicide. But da seas be open. If we attack by both land an' sea, Gul'dan got ta fall back somewhere. <name>, it be time ta build a shipyard! We need local resources. Go to da Iron Docks. Gazlowe's boys are already there. Gather any equipment ya find, and see if ya can recruit us a proper Horde Shipwright!", ["objectivesText"] = "Travel to the Iron Docks and speak with Sammy Fivefingers . Your Garrison Flight Master can provide transport.", ["rewardGold"] = 140450, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 89937, ["x"] = 0.56, ["y"] = 0.066 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.066 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38570] = { ["id"] = 38570, ["name"] = "Derailment", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 38567, 38568, 38571, 38572, 38573, 38574 }, ["description"] = "Some orcs have spoken out against Gul'dan, and they've been taken prisoner. One of them is what you'd call an engineering prodigy: Solog Roark, \"The Iron Shipwright.\" This guy's good. Designed all these docks, as well as the big dreadnaughts you fought around Shattrath. If my scouts are right, he's in a prison train as we speak... And I betcha he'd be willing to defect! Gather up some explosives and meet Durotan next to the train to the south.", ["objectivesText"] = "Collect Explosive Charges and a Detonator . Progress: Commander, it's you! Good, I need someone steady at my back.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 122515, 122516 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 89937, ["x"] = 0.56, ["y"] = 0.066 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 92401, ["x"] = 0.568, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.066 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38571] = { ["id"] = 38571, ["name"] = "The Train Gang", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 38567, 38568, 38570, 38572, 38573, 38574 }, ["description"] = "My warriors will surround and cover the train car. Hit the detonator to blow open the doors. I will speak to Roark and convince him to defect to our cause. He built all of this - he's our best hope for building a shipyard of our own. If this doesn't work, execute him on the spot. The last thing we need is someone rebuilding the Iron Fleet.", ["objectivesText"] = "Use the detonator to blow open the prison train, and convince Roark to join your cause.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 92401, ["x"] = 0.568, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 525, 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38572] = { ["id"] = 38572, ["name"] = "Hook, Line, and... Sink Him!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 38567, 38568, 38570, 38571, 38573, 38574 }, ["description"] = "I can build you a shipyard. And not some wasteful piece of over-engineering like this place. But I'm going to need my blueprints. My work was confiscated when Gul'dan turned this harbor over to Admiral Knar. <Roark spits.> Gul'dan's green poison courses through Knar's veins. He's calling the shots from on high. We'll need to grapple up there to take him out.", ["objectivesText"] = "Use a Blackrock Grapple to reach Knar's bunker. Slay him to obtain Roark's Shipyard Blueprints . Progress: I will rebuild.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 123867 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38573] = { ["id"] = 38573, ["name"] = "Nothing Remains", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 38567, 38568, 38570, 38571, 38572, 38574 }, ["description"] = "Nothing is left for me here. My old clanmates have turned into foes, and Gul'dan is desecrating what remains of my people. You and your Frostwolf allies still have some fight left. If you pledge to depose Gul'dan, I will stand by your side. I will go to this garrison of yours and together we will build a shipyard that will rule the red seas of Draenor! Let your people know I am coming.", ["objectivesText"] = "Report back to Vol'jin at your garrison.", ["rewardGold"] = 140450, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38574] = { ["id"] = 38574, ["name"] = "All Hands on Deck", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 38567, 38568, 38570, 38571, 38572, 38573 }, ["description"] = "Let's put dis \"Iron Shipwright\" ta work, commander. If we ta take Tanaan from both land an' sea, we gonna need a shipyard. Work wit' Roark an' make it happen! He be surveyin' tha land along tha road west of Frostwall.", ["objectivesText"] = "Construct a Level 1 Shipyard for your garrison. Progress: I'll need building supplies, commander. Can't build docks of ice and snow.", ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 91242, ["x"] = 0.415, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39054] = { ["id"] = 39054, ["name"] = "Shipbuilding", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38435, 38436, 38444, 38445, 39055, 39082, 39276 }, ["description"] = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there. Let's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, <class>, and then destroy the evidence. Let me know when you are done.", ["objectivesText"] = "Learn the blueprints and destroy the evidence. Progress: You memorize those blueprints yet?", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 8, ["flags"] = 0 } } },
