[39180] = { ["id"] = 39180, ["name"] = "Warchief's Command: Zangarmarsh!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3521, ["mapID"] = 102, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["series"] = { 9716, 9718, 9720, 39181 }, ["description"] = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition. Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body. The expedition's leader, Ysiel Windsinger , has asked us to direct volunteers to her outpost. Report to her at the Cenarion Refuge in eastern Zangarmarsh . Take the main path to the west and it will lead you directly there.", ["objectivesText"] = "Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh .", ["rewardGold"] = 200, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 102, ["npcID"] = 17841, ["x"] = 0.784, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 102, ["source"] = "quest_giver", ["x"] = 0.784, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 102 }, ["zone"] = { 3521 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 102, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 3, ["flags"] = 0 } } },
