[39204] = { ["id"] = 39204, ["name"] = "Hero's Call: Dragonblight!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["series"] = { 11995, 12000, 12004, 12439, 12440 }, ["description"] = "Volunteers are needed to aid the Silver Covenant forces in the Dragonblight as they attempt to counter the chaotic arcane energies that threaten to rip the land apart. Those skilled in fighting dragons and undead are greatly welcome. Those willing to answer the call should report to Archmage Modera at Stars' Rest in Dragonblight .", ["objectivesText"] = "Speak with the Image of Archmage Modera at Stars' Rest.", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 26673, ["x"] = 0.29, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39206] = { ["id"] = 39206, ["name"] = "Warchief's Command: Grizzly Hills!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 28711, 39203, 39206, 49533, 49534, 49535, 49536, 49537, 60097, 60963 }, ["series"] = { 12257, 12468, 12487, 12488 }, ["description"] = "We've received a request for help from our base in the Grizzly Hills . Go to see Conqueror Krenna . She's attempting to secure all of the natural resources. Just watch your back around her. The word is that she's aggressive even for an orc. You can reach her by traveling east from Dragonblight.", ["objectivesText"] = "Present yourself to Conqueror Krenna at Conquest Hold in the Grizzly Hills .", ["rewardGold"] = 2775, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 26860, ["x"] = 0.206, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.206, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets", ["questLines"] = { { ["id"] = 5578, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39207] = { ["id"] = 39207, ["name"] = "Hero's Call: Grizzly Hills!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["series"] = { 12292, 12293, 12294, 12295, 12511 }, ["description"] = "While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills . All in hopes of finding an alternate route into Icecrown. Lieutenant Dumont , stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?", ["objectivesText"] = "Report to Lieutenant Dumont at Amberpine Lodge in western Grizzly Hills .", ["rewardGold"] = 2775, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 26875, ["x"] = 0.318, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets", ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39208] = { ["id"] = 39208, ["name"] = "Zul'Drak", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 66, ["mapID"] = 121, ["storyline"] = { 39208 }, ["series"] = { 12630, 12883, 12884, 12902, 49534, 49552 }, ["description"] = "Our death knight allies in Zul'Drak are in need of heroes to aid them in securing the troll lands from the Scourge. Those willing to aid should travel to the southwestern camp of Ebon Watch and speak with Stefan Vadu there.", ["objectivesText"] = "Report to Stefan Vadu at Ebon Watch in Zul'Drak . Progress: What have you got there, <race>?", ["rewardGold"] = 5350, ["rewardXP"] = 690, ["ends"] = { { ["mapID"] = 121, ["npcID"] = 28518, ["x"] = 0.232, ["y"] = 0.574667 } }, ["coords"] = { ["mapID"] = 121, ["source"] = "quest_giver", ["x"] = 0.232, ["y"] = 0.574667 }, ["mapCandidates"] = { ["npc"] = { 121 }, ["zone"] = { 66 } }, ["questType"] = "standard" },
[39209] = { ["id"] = 39209, ["name"] = "Sholazar Basin", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3711, ["mapID"] = 119, ["storyline"] = { 39209 }, ["series"] = { 12489, 12521, 39212, 49535, 49553 }, ["description"] = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin . His expedition has not been heard from since. Monte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either. Volunteers are needed to mount an expedition to find the missing expedition. Monte's flying machine was last seen in the Wildgrowth Mangal south of the Suntouched Pillar in Sholazar Basin .", ["objectivesText"] = "Speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin .", ["rewardGold"] = 140450, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 119, ["npcID"] = 27987, ["x"] = 0.396, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 119, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 119 }, ["zone"] = { 3711 } }, ["questType"] = "standard" },
[39212] = { ["id"] = 39212, ["name"] = "Sholazar Basin", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 3711, ["mapID"] = 119, ["storyline"] = { 39212 }, ["series"] = { 12489, 12521, 39209, 49535, 49553 }, ["description"] = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin . His expedition has not been heard from since. Monte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either. Archmage Pentarus in Dalaran is standing by with a flying machine to take you to the last known location of Monte Muzzleshot .", ["objectivesText"] = "Talk to Archmage Pentarus when you're ready to leave for Sholazar Basin . When you arrive, speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin .", ["rewardGold"] = 140450, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 119, ["npcID"] = 27987, ["x"] = 0.396, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 119, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 119 }, ["zone"] = { 3711 } }, ["questType"] = "standard" },
[39236] = { ["id"] = 39236, ["name"] = "Let's Get To Work", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 37889, 37890, 37934, 37935, 39241, 39242 }, ["description"] = "Now that the shipyard is complete, we need to get busy making ships! Solog ran off to the dry docks, why don't you meet him down there? He said he had a plan.", ["objectivesText"] = "Meet Solog at the dry docks.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 }, { ["mapID"] = 525, ["npcID"] = 97096, ["x"] = 0.415, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39241] = { ["id"] = 39241, ["name"] = "Shipbuilding", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 37889, 37890, 37934, 37935, 39236, 39242 }, ["description"] = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there. Let's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, <class>, and then destroy the evidence. Let me know when you are done.", ["objectivesText"] = "Learn the blueprints and destroy the evidence. Progress: You memorize those blueprints yet?", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39242] = { ["id"] = 39242, ["name"] = "Ship Shape", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 37889, 37890, 37934, 37935, 39236, 39241 }, ["description"] = "You want to take the fight to Gul'dan? You need a transport! Speak to me when you are ready to begin construction.", ["objectivesText"] = "Speak with Solog to begin construction on a transport ship. Once complete, add it to your collection of ships. Progress: Get that ship started yet?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 9, ["flags"] = 0 } } },
[39243] = { ["id"] = 39243, ["name"] = "Naval Commander", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39401 }, ["description"] = "You're a natural at this, <name>. You've got the salt in your veins. Now it's time to run our first naval mission and control the seas of Draenor! You will want a high vantage point to plan out these seafaring missions. I know a good spot just up the path behind us. Meet me near the shipyard entrance and we can get started on our first mission.", ["objectivesText"] = "Find Rolash Wavechaser at your shipyard and complete a Naval Mission. Progress: Finish a naval mission yet?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 128373 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 10, ["flags"] = 0 } } },
[39245] = { ["id"] = 39245, ["name"] = "Upgrading The Fleet", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39246 }, ["description"] = "You have been doing a great job out there commander. However, we are going to need more experience and resources to upgrade this shipyard. Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!", ["objectivesText"] = "Collect 1000 garrison resources , 1000 gold and combat 15 naval missions. Progress: Finding success on these new naval missions?", ["rewardXP"] = 685, ["rewardItems"] = { 127270 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 16, ["flags"] = 0 } } },
[39246] = { ["id"] = 39246, ["name"] = "Naval Domination", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39245 }, ["description"] = "Our naval domination continues! However, we are going to need even more experience and resources to take this shipyard to the next level. Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!", ["objectivesText"] = "Collect 2500 garrison resources , 2500 gold and complete 25 naval treasure missions. Progress: Gather those resources yet? I am ready to get this upgrade started!", ["rewardXP"] = 685, ["rewardItems"] = { 127267 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 17, ["flags"] = 0 } } },
[39394] = { ["id"] = 39394, ["name"] = "The Cipher of Damnation", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38462, 38561, 39394 }, ["description"] = "Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy. Gul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.", ["objectivesText"] = "Get Oronok and your ally to destroy the barrier, then stop Gul'dan.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["rewardItems"] = { 124551, 128225, 128309, 128320 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 92120, ["x"] = 0.625, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 93658, ["x"] = 0.626, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534, ["questLines"] = { { ["id"] = 124, ["name"] = "Gul'dan Finale", ["orderIndex"] = 2, ["flags"] = 0 } } },
